#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_PACKET_SIZE 1024
#define MAX_PACKETS 1000

typedef struct {
    int id;
    char data[MAX_PACKET_SIZE];
} Packet;

Packet* packet_pool[MAX_PACKETS];
int pool_index = 0;
sem_t pool_semaphore;
pthread_mutex_t pool_mutex;

void init_packet_pool() {
    sem_init(&pool_semaphore, 0, MAX_PACKETS);
    pthread_mutex_init(&pool_mutex, NULL);
    for (int i = 0; i < MAX_PACKETS; i++) {
        packet_pool[i] = malloc(sizeof(Packet));
    }
}

Packet* allocate_packet(int id) {
    Packet* packet;
    sem_wait(&pool_semaphore);
    pthread_mutex_lock(&pool_mutex);
    if (pool_index >= MAX_PACKETS) {
        pthread_mutex_unlock(&pool_mutex);
        sem_post(&pool_semaphore);
        return NULL; // Pool is full
    }
    packet = packet_pool[pool_index++];
    packet->id = id;
    pthread_mutex_unlock(&pool_mutex);
    return packet;
}

void free_packet(Packet* packet) {
    pthread_mutex_lock(&pool_mutex);
    packet_pool[--pool_index] = packet;
    pthread_mutex_unlock(&pool_mutex);
    sem_post(&pool_semaphore);
}

void process_packets(int max_packets) {
    for (int i = 0; i < max_packets; i++) {
        int id = generate_packet_id(); // Assume this function generates a valid ID
        Packet* packet = allocate_packet(id);
        if (packet != NULL) {
            // Process packet data
            read_packet_data(packet); // Assume this function reads the actual packet data
            free_packet(packet);
        } else {
            // Handle pool full scenario, e.g., log error or drop packet
        }
    }
}

void* packet_processor_thread(void* arg) {
    int max_packets = *(int*)arg;
    process_packets(max_packets);
    return NULL;
}

int main() {
    init_packet_pool();

    pthread_t threads[10];
    int thread_args[10] = {500, 400, 300, 200, 100, 50, 40, 30, 20, 10};

    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, packet_processor_thread, &thread_args[i]);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

This code provides a basic structure for processing network packets with a focus on memory management and concurrency. It includes functions for initializing the packet pool, allocating and freeing packets, and processing a specified number of packets. The main function demonstrates how to create multiple threads to process packets concurrently. This example uses semaphores and mutexes to manage access to the packet pool and ensure thread safety during allocation and deallocation operations.']

