            exit(EXIT_FAILURE);
        }
        keys[i] = rand() % range;
        offsets[i] = time(NULL); // Example of external data source
    }
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    int num_records = 1000; // Example size
    int range = 100; // Range for random values

    Record **records = (Record **)malloc(num_records * sizeof(Record *));
    long *offsets = (long *)malloc(num_records * sizeof(long));
    int *keys = (int *)malloc(num_records * sizeof(int));

    if (records == NULL || offsets == NULL || keys == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    populate_records(records, offsets, keys, num_records, range);

    // Example usage
    for (int i = 0; i < num_records; ++i) {
        printf("Record %d: Value = %d, Key = %d, Offset = %ld\n", i, records[i]->value, keys[i], offsets[i]);
        free(records[i]); // Free each record when done
    }

    free(offsets);
    free(keys);

    return 0;
}
