int count_characters(const char* filename) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        return -1;
    }

    off_t size = lseek(fd, 0, SEEK_END);
    if (size == -1) {
        close(fd);
        perror("Error seeking file size");
        return -1;
    }

    char* buffer = malloc(size);
    if (!buffer) {
        close(fd);
        perror("Memory allocation failed");
        return -1;
    }

    ssize_t bytes_read = read(fd, buffer, size);
    if (bytes_read == -1) {
        free(buffer);
        close(fd);
        perror("Error reading file");
        return -1;
    }
    close(fd);

    int total_chars = 0;
    for (ssize_t i = 0; i < bytes_read; i++) {
        if (buffer[i] != '\n') {
            total_chars++;
        }
    }

    free(buffer);
    printf("Total characters: %d\n", total_chars);
    return 0;
}

int main(int argc, char* argv[]) {
    int opt;
    const char* output_file = NULL;
    ssize_t buffer_size = DEFAULT_BUFFER_SIZE;
    while ((opt = getopt(argc, argv, "mcs:o:b:")) != -1) {
        switch (opt) {
            case 'm':
                generate_manpage();
                return 0;
            case 'c':
                count_characters("input.txt");
                return 0;
            case 's':
                buffer_size = atoi(optarg);
                if (buffer_size <= 0) {
                    fprintf(stderr, "Invalid buffer size\n");
                    return 1;
                }
                break;
            case 'o':
                output_file = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-m] [-c] [-s buffer_size] [-o output_file]\n", argv[0]);
                return 1;
        }
    }

    // Code to process input files using the specified buffer size and other options

    return 0;
}
