#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

#define MAX_LINE_LENGTH 2048

int resolve_hostname(const char *hostname, u_char **ip_address) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return -1;
    }

    *ip_address = (u_char *)malloc(INET6_ADDRSTRLEN);
    if (*ip_address == NULL) {
        perror("Failed to allocate memory for IP address");
        freeaddrinfo(res);
        return -2;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    inet_ntop(AF_INET, &(ipv4->sin_addr), (char *)*ip_address, INET6_ADDRSTRLEN);

    freeaddrinfo(res);
    return 0;
}

int read_and_process_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    u_char ip_address[INET6_ADDRSTRLEN];
    char *line = NULL;
    size_t len = 0;

    while ((len = getline(&line, &len, file)) != -1) {
        line[len - 1] = '\0'; // Remove newline character

        int status = resolve_hostname(line, &ip_address);
        if (status < 0) {
            fprintf(stderr, "Failed to resolve hostname: %s\n", line);
            continue;
        }

        printf("Resolved IP for %s: %s\n", line, ip_address);

        // Process other fields as needed
    }

    free(line);
    fclose(file);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return -1;
    }

    return read_and_process_file(argv[1]);
}
```

