#define MAX_INPUT_SIZE 1024

void log_error(const char *message) {
    FILE *log_file = getenv("LOG_FILE") ? fopen(getenv("LOG_FILE"), "a") : stderr;
    if (log_file) {
        fprintf(log_file, "Error: %s\n", message);
        fclose(log_file);
    } else {
        fprintf(stderr, "Error: %s\n", message);
    }
}

int* read_integers(int *count) {
    int limit = 1000; // Predefined limit
    char input[MAX_INPUT_SIZE];
    int *array = NULL;
    int array_size = 0;

    while (fgets(input, sizeof(input), stdin)) {
        if (array_size >= limit) {
            log_error("Input exceeds predefined limit");
            free(array);
            return NULL;
        }
        int number;
        if (sscanf(input, "%d", &number) != 1) {
            continue; // Skip invalid input
        }
        array = realloc(array, (array_size + 1) * sizeof(int));
        if (!array) {
            log_error("Memory allocation failed");
            return NULL;
        }
        array[array_size++] = number;
    }

    *count = array_size;
    return array;
}

void find_and_print_largest(int *array, int count) {
    if (count == 0) {
        printf("No integers provided.\n");
        return;
    }
    int largest = INT_MIN;
    for (int i = 0; i < count; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    printf("Largest integer: %d\n", largest);
}

int main() {
    int count;
    int *array = read_integers(&count);
    if (array) {
        find_and_print_largest(array, count);
        free(array);
    }
    return 0;
}
