#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <semaphore.h>
#include <dirent.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct {
    sem_t *mutex;
    char *temp_dir;
} TemporaryFileManager;

TemporaryFileManager* create_temp_file_manager(int initial_value, const char* temp_dir) {
    TemporaryFileManager *manager = (TemporaryFileManager*)malloc(sizeof(TemporaryFileManager));
    manager->mutex = sem_open("/temp_file_manager_mutex", O_CREAT, 0644, initial_value);
    if (manager->mutex == SEM_FAILED) {
        perror("Failed to create semaphore");
        free(manager);
        return NULL;
    }
    manager->temp_dir = strdup(temp_dir);
    return manager;
}

void destroy_temp_file_manager(TemporaryFileManager *manager) {
    sem_close(manager->mutex);
    sem_unlink("/temp_file_manager_mutex");
    free(manager->temp_dir);
    free(manager);
}

int create_secure_temp_file(TemporaryFileManager *manager, char **file_path) {
    sem_wait(manager->mutex);
    DIR *dir = opendir(manager->temp_dir);
    if (!dir) {
        perror("Failed to open temporary directory");
        sem_post(manager->mutex);
        return -1;
    }
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;
        sem_post(manager->mutex);
        snprintf(*file_path, PATH_MAX, "%s/%s", manager->temp_dir, entry->d_name);
        return 0; // Simulate successful creation of a secure temp file
    }
    closedir(dir);
    sem_post(manager->mutex);
    *file_path = NULL;
    return -1; // No available temporary files
}

void cleanup_temp_files(TemporaryFileManager *manager) {
    sem_wait(manager->mutex);
    DIR *dir = opendir(manager->temp_dir);
    if (!dir) {
        perror("Failed to open temporary directory");
        sem_post(manager->mutex);
        return;
    }
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;
        char path[PATH_MAX];
        snprintf(path, PATH_MAX, "%s/%s", manager->temp_dir, entry->d_name);
        unlink(path);
    }
    closedir(dir);
    sem_post(manager->mutex);
}
