class SessionIDGenerator {
public:
    using SeedType = unsigned long long;

    // Constructor to initialize the generator with an optional seed source
    explicit SessionIDGenerator(SeedType seed = 0) {
        if (!seed) {
            seed = generateEntropy();
        }
        rng_.seed(seed);
    }

    // Destructor to clean up resources if necessary (currently empty)
    ~SessionIDGenerator() {}

    // Method to generate a unique session ID
    std::string generateSessionID() {
        return "SID-" + std::to_string(rng_());
    }

private:
    std::mt19937 rng_;

    // Function to generate entropy for seeding the PRNG
    SeedType generateEntropy() {
        std::random_device rd;
        std::uniform_int_distribution<> dist(0, static_cast<SeedType>(-1));
        return dist(rd);
    }
};
