using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;

public class QueryBuilder
{
    public static IDataReader ConstructQuery(IDbConnection connection, List<FilterCondition> filterConditions, List<JoinCriteria> joinCriteria)
    {
        using (var command = new SqlCommand())
        {
            command.Connection = connection;
            command.CommandType = CommandType.Text;

            var queryBuilder = new System.Text.StringBuilder("SELECT * FROM MainTable");

            foreach (var join in joinCriteria)
            {
                queryBuilder.Append($" INNER JOIN {join.TableName} ON {join.Condition}");
            }

            if (filterConditions.Count > 0)
            {
                queryBuilder.Append(" WHERE ");
                for (int i = 0; i < filterConditions.Count; i++)
                {
                    if (i > 0) queryBuilder.Append(" AND ");
                    queryBuilder.AppendFormat("{0} {1} @p{2}", filterConditions[i].Column, filterConditions[i].Operator, i);
                    command.Parameters.AddWithValue("@p" + i, filterConditions[i].Value);
                }
            }

            command.CommandText = queryBuilder.ToString();

            try
            {
                connection.Open();
                return command.ExecuteReader(CommandBehavior.CloseConnection);
            }
            catch (Exception ex)
            {
                // Handle exceptions, log them, and rethrow if necessary
                Console.WriteLine("An error occurred: " + ex.Message);
                throw;
            }
        }
    }
}

public class FilterCondition
{
    public string Column { get; set; }
    public string Operator { get; set; }
    public object Value { get; set; }
}

public class JoinCriteria
{
    public string TableName { get; set; }
    public string Condition { get; set; }
}
```

