public class AuthenticationManager
{
    private static readonly object _lock = new object();
    private static XmlDocument _configXml;

    public static void Initialize()
    {
        lock (_lock)
        {
            if (_configXml == null)
            {
                string configPath = ConfigurationManager.AppSettings["ConfigFilePath"];
                _configXml = LoadConfiguration(configPath);
            }
        }
    }

    private static XmlDocument LoadConfiguration(string filePath)
    {
        XmlDocument doc = new XmlDocument();
        doc.XmlResolver = null; // Disable external entity resolution for security
        doc.Load(filePath);
        return doc;
    }

    public static void UpdateConfiguration(string key, string value)
    {
        lock (_lock)
        {
            XmlNode node = _configXml.SelectSingleNode($"//configuration/{key}");
            if (node != null)
            {
                node.InnerText = value;
                SaveConfiguration(_configXml, ConfigurationManager.AppSettings["ConfigFilePath"]);
            }
        }
    }

    private static void SaveConfiguration(XmlDocument doc, string filePath)
    {
        using (StreamWriter writer = new StreamWriter(filePath))
        {
            doc.Save(writer);
        }
    }

    public static string GetConfiguration(string key)
    {
        XmlNode node = _configXml.SelectSingleNode($"//configuration/{key}");
        return node?.InnerText ?? string.Empty;
    }
}

public class SessionManager
{
    private Dictionary<string, object> _sessionCache;

    public SessionManager()
    {
        _sessionCache = new Dictionary<string, object>();
    }

    public void SetSession(string sessionId, object data)
    {
        lock (_sessionCache)
        {
            _sessionCache[sessionId] = data;
        }
    }

    public object GetSession(string sessionId)
    {
        lock (_sessionCache)
        {
            if (_sessionCache.ContainsKey(sessionId))
            {
                return _sessionCache[sessionId];
            }
        }
        return null;
    }

    public void RemoveSession(string sessionId)
    {
        lock (_sessionCache)
        {
            _sessionCache.Remove(sessionId);
        }
    }
}

