using Microsoft.AspNetCore.Mvc;
using System.Threading.Tasks;

[ApiController]
[Route("api/[controller]")]
public class ResourceController : ControllerBase
{
    private readonly IResourceService _resourceService;
    private readonly ICacheProvider _cacheProvider;
    private readonly ILogger<ResourceController> _logger;

    public ResourceController(IResourceService resourceService, ICacheProvider cacheProvider, ILogger<ResourceController> logger)
    {
        _resourceService = resourceService;
        _cacheProvider = cacheProvider;
        _logger = logger;
    }

    [HttpPut("{id}")]
    public async Task<IActionResult> UpdateResource(int id, [FromBody] Resource updatedResource)
    {
        try
        {
            var resourceToUpdate = await _cacheProvider.GetCachedResourceAsync(id);
            if (resourceToUpdate == null)
            {
                _logger.LogWarning("Resource not found for ID: {Id}", id);
                return NotFound();
            }

            if (!ModelState.IsValid || !updatedResource.Version.Equals(resourceToUpdate.Version))
            {
                _logger.LogWarning("Invalid resource data or version mismatch for ID: {Id}", id);
                return BadRequest();
            }

            var updated = await _resourceService.UpdateResourceAsync(id, updatedResource);
            await _cacheProvider.SetCachedResourceAsync(updated.Id, updated);

            return Ok(updated);
        }
        catch (ConcurrencyException ex)
        {
            _logger.LogError(ex, "Concurrent update conflict for ID: {Id}", id);
            return Conflict();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to update resource for ID: {Id}", id);
            return StatusCode(500, "Internal server error");
        }
    }

    [HttpDelete("{id}")]
    public async Task<IActionResult> DeleteResource(int id)
    {
        try
        {
            var deleted = await _resourceService.DeleteResourceAsync(id);
            if (deleted != null)
            {
                await _cacheProvider.RemoveCachedResourceAsync(id);

                return Ok(new Resource { Id = deleted.Id, Version = default });
            }

            _logger.LogWarning("Resource not found for ID: {Id}", id);
            return NotFound();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to delete resource for ID: {Id}", id);
            return StatusCode(500, "Internal server error");
        }
    }
}
