use std::env;
use std::fs;
use std::sync::{Once, ONCE_INIT};
use std::path::PathBuf;

static SET_ENV_VAR: Once = ONCE_INIT;

fn create_directory_with_env_var(directory_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let mut directory_path = PathBuf::new();
    directory_path.push(env::var("DIRECTORY_PATH")?); // Check if environment variable exists

    if !directory_path.exists() || !directory_path.is_dir() {
        SET_ENV_VAR.call_once(|| {
            env::set_var("DIRECTORY_PATH", &directory_path);
        });
        fs::create_dir_all(&directory_path)?;
    }

    Ok(())
}
