import java.io.*;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;

public class ThemeCacheManager {

    private static final String THEME_DIR = "/path/to/theme/directory";
    private static final String Fallback_PATH = "/fallback/path/to/theme/directory";

    public MoSTState loadThemeState(String filePath) {
        File file = new File(filePath);
        if (!file.exists()) {
            initializeDefaultThemeDirectory();
        }

        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
            Object obj = ois.readObject();
            if (obj instanceof MoSTState) {
                return (MoSTState) obj;
            }
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
        return null;
    }

    private void initializeDefaultThemeDirectory() {
        File dir = new File(THEME_DIR);
        if (!dir.exists()) {
            String fallbackPath = Fallback_PATH + "/theme/directory";
            new File(fallbackPath).mkdirs();
        }
    }

    public Bitmap parsePNG(String filePath) {
        try (InputStream is = new FileInputStream(filePath)) {
            return BitmapFactory.decodeStream(is);
        } catch (IOException e) {
            e.printStackTrace();
            return null;
        }
    }

    public void recycleBitmap(Bitmap bitmap) {
        if (bitmap != null && !bitmap.isRecycled()) {
            bitmap.recycle();
            bitmap = null;
        }
    }

    // Add synchronization to handle concurrent access
    public synchronized MoSTState loadThemeStateConcurrently(String filePath) {
        return loadThemeState(filePath);
    }
}
