["```javascript
function extractFrameworkMentions(documents, frameworks) {
  const frameworkRegex = createFrameworkRegex(frameworks);
  const results = {};

  documents.forEach(document => {
    const cleanedDocument = removeCodeSnippetsAndComments(document);
    const matches = cleanedDocument.match(frameworkRegex);
    if (matches) {
      matches.forEach(match => {
        match = match.toLowerCase();
        if (!results[match]) results[match] = [];
        results[match].push({
          document: document,
          frequency: 1
        });
      });
    }
  });

  return results;
}

function createFrameworkRegex(frameworks) {
  const escapedFrameworks = frameworks.map(escapeRegExp);
  return new RegExp(`\\b(${escapedFrameworks.join('|')})\\b`, 'gi');
}

function removeCodeSnippetsAndComments(document) {
  // Remove code snippets and comments
  return document.replace(/<code>[\s\S]*?<\/code>/g, '').replace(/\/\/.*|\/\*[\s\S]*?\*\//g, '');
}

function escapeRegExp(string) {
  return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}
```

This function `extractFrameworkMentions` processes a large collection of technical documents to extract and categorize specific software development frameworks. It uses configurable regular expressions to define matches for the frameworks, ignoring case differences and matching only whole words. The function efficiently handles datasets of varying sizes by using efficient string manipulation methods and avoiding unnecessary operations."]

