function generateFooterScripts(scripts) {
    const sanitizedCode = (code) => {
        // Simple sanitization: escape special characters for HTML content
        return code.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    };

    const isValidScript = (script) => script && typeof script === 'object' && script.id;

    let footerHTML = '<footer><div id="scripts">';

    scripts.forEach(script => {
        if (!isValidScript(script)) {
            console.warn('Invalid script object:', script);
            return;
        }

        const { id, type, code } = script;
        const safeCode = sanitizedCode(code);

        footerHTML += `<script id="${id}" type="${type || 'text/javascript'}">${safeCode}</script>`;
    });

    footerHTML += '</div></footer>';

    return footerHTML;
}

