#include <iostream>
#include <forward_list>

void insertAfterString(std::forward_list<std::string>& lst, const std::string& target, const std::string& toInsert) {
    if (lst.empty()) return;

    auto it = lst.begin();
    while (it != lst.end()) {
        if (*it == target) {
            lst.insert_after(it, toInsert);
            break;
        }
        ++it;
    }
    if (it == lst.end()) {
        lst.push_back(toInsert);
    }
}
