public class StreamingDataCollector {
    private final AtomicBoolean isRunning = new AtomicBoolean(false);
    private final int storageSizeLimit;
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private int dataCounter;

    public StreamingDataCollector(int storageSizeLimit) {
        this.storageSizeLimit = storageSizeLimit;
        this.dataCounter = 0;
    }

    public void start() {
        if (isRunning.compareAndSet(false, true)) {
            scheduler.scheduleAtFixedRate(this::collectData, randomDelay(), randomDelay(), TimeUnit.MILLISECONDS);
        }
    }

    public void stop() {
        isRunning.set(false);
        scheduler.shutdown();
        notifyMessagingSystem("Service stopped");
    }

    private void collectData() {
        if (dataCounter < storageSizeLimit) {
            // Simulate data collection
            System.out.println("Collecting data...");
            dataCounter++;
        } else {
            stop();
        }
    }

    private int randomDelay() {
        return 100 + (int) (Math.random() * 900); // Random delay between 100ms and 1 second
    }

    private void notifyMessagingSystem(String message) {
        // Implement messaging system notification logic here
        System.out.println("Notification: " + message);
    }
}
