["```javascript
class DOMTraverser {
    constructor() {
        this.cache = new Map();
    }

    traverse(selector) {
        if (this.cache.has(selector)) {
            return this.cache.get(selector);
        }

        const elements = [];
        const walker = document.createTreeWalker(
            document.body,
            NodeFilter.SHOW_ELEMENT,
            null,
            false
        );

        while (walker.nextNode()) {
            if (walker.currentNode.matches(selector)) {
                elements.push(walker.currentNode);
            }
        }

        this.cache.set(selector, elements);
        return elements;
    }

    clearCache() {
        this.cache.clear();
    }
}

// Usage example:
const traverser = new DOMTraverser();
const buttons = traverser.traverse('button');
console.log(buttons);

// Clear cache if necessary
traverser.clearCache();
```

