// Define the FileLoader class
class FileLoader {
  constructor(apiUrl) {
    this.apiUrl = apiUrl;
    this.files = [];
    this.dependencies = {};
  }

  // Method to add a file with its dependencies
  addFile(name, url, deps = []) {
    this.files.push({ name, url, deps });
    this.dependencies[name] = deps;
  }

  // Recursive method to load files in the correct order
  async loadFiles() {
    for (const file of this.files) {
      if (!this.isLoaded(file.name)) {
        await this.loadFile(file.name);
      }
    }
  }

  // Method to load a single file
  async loadFile(name) {
    const file = this.findFileByName(name);
    if (!file) return;

    try {
      const metadata = await fetch(`${this.apiUrl}/metadata?name=${file.name}`).then(res => res.json());
      if (!metadata.valid || metadata.integrity !== file.url) {
        throw new Error('Invalid or corrupted file');
      }

      const code = await this.fetchFileContent(file.url);
      eval(code); // Execute the JavaScript code

      for (const dep of file.deps) {
        if (!this.isLoaded(dep)) {
          await this.loadDependency(dep, name);
        }
      }
    } catch (error) {
      console.error(`Failed to load file ${name}:`, error);
    }
  }

  // Method to fetch file content
  async fetchFileContent(url) {
    const response = await fetch(url);
    if (!response.ok) throw new Error('File not found');
    return response.text();
  }

  // Helper method to find a file by name
  findFileByName(name) {
    return this.files.find(f => f.name === name);
  }

  // Method to check if a file is loaded
  isLoaded(name) {
    return !!eval(`typeof ${name} !== 'undefined'`);
  }

  // Method to handle dependencies
  async loadDependency(dep, parent) {
    const file = this.findFileByName(dep);
    if (!file) return;

    try {
      await this.loadFile(dep);
      console.log(`${dep} loaded successfully by ${parent}`);
    } catch (error) {
      console.error(`Failed to load dependency ${dep} for file ${parent}:`, error);
    }
  }

  // Method to clear all files and dependencies
  clear() {
    this.files = [];
    this.dependencies = {};
  }
}

// Usage example
const loader = new FileLoader('https://api.example.com');
loader.addFile('main', 'https://example.com/main.js', ['helper']);
loader.addFile('helper', 'https://example.com/helper.js');

(async () => {
  try {
    await loader.loadFiles();
    console.log('All files loaded successfully.');
  } catch (error) {
    console.error('Failed to load all files:', error);
  }
})();
```

This code defines a `FileLoader` class that can dynamically load and execute JavaScript files from an external API. It handles file metadata validation, dependency management, and robust error handling. The example usage demonstrates how to add files with dependencies and load them asynchronously."]

