<?php

function updateUserProfile($userId, $newEmail, $newPhone, $currentIp) {
    // Assuming $db is a PDO instance connected to your database
    global $db;

    try {
        // Begin transaction for atomicity
        $db->beginTransaction();

        // Fetch user's current IP address from the database
        $stmt = $db->prepare("SELECT ip_address FROM users WHERE id = :userId");
        $stmt->execute(['userId' => $userId]);
        $userIp = $stmt->fetchColumn();

        if ($userIp !== $currentIp) {
            // Log discrepancy to an external service
            logDiscrepancy($userId, $userIp, $currentIp);
            throw new Exception("IP address mismatch");
        }

        // Update user's email, phone number, and last login details
        $stmt = $db->prepare("UPDATE users SET email = :email, phone_number = :phone, last_login = NOW() WHERE id = :userId");
        $stmt->execute(['email' => $newEmail, 'phone' => $newPhone, 'userId' => $userId]);

        // Commit transaction
        $db->commit();

        return "Profile updated successfully";
    } catch (Exception $e) {
        // Rollback transaction on error
        $db->rollBack();
        return "Error updating profile: " . $e->getMessage();
    }
}

function logDiscrepancy($userId, $storedIp, $currentIp) {
    // Simulate logging to an external service
    file_put_contents('discrepancies.log', date('Y-m-d H:i:s') . " - UserID: $userId, Stored IP: $storedIp, Current IP: $currentIp\n", FILE_APPEND);
}

// Example usage:
$result = updateUserProfile(1, 'newemail@example.com', '1234567890', $_SERVER['REMOTE_ADDR']);
echo $result;
?>
