async function fetchAndSaveCertificate(oauthRequest) {
  const configDir = getEnvConfigDirectory(oauthRequest.environment);

  try {
    const privateKeyPath = path.join(configDir, 'private_key.pem');
    const certificatePath = path.join(configDir, 'certificate.pem');

    if (!fs.existsSync(privateKeyPath)) throw new Error('Private key file not found');
    if (!fs.existsSync(certificatePath)) throw new Error('Certificate file not found');

    const privateKey = fs.readFileSync(privateKeyPath);
    const certificate = await fetchCertificateFromRemoteService(oauthRequest);

    const pemFileContent = Buffer.concat([privateKey, certificate]);

    fs.writeFileSync(path.join(configDir, 'concatenated.pem'), pemFileContent);

    logProgress('Certificate fetched and saved successfully');

  } catch (error) {
    handleError(error);
  }
}

function getEnvConfigDirectory(environment) {
  // Implement logic to determine the environment-specific configuration directory
  return path.join(__dirname, 'config', environment);
}

async function fetchCertificateFromRemoteService(oauthRequest) {
  // Implement logic to fetch certificate from remote service using OAuth request
  const response = await fetch('https://api.example.com/certificate', {
    headers: oauthRequest.headers,
  });

  if (!response.ok) throw new Error(`Failed to fetch certificate: ${response.statusText}`);

  return Buffer.from(await response.arrayBuffer());
}

