class UserService {
    private $dbConnection;
    private $authServices;

    public function __construct($dbConnection, array $authServices) {
        $this->dbConnection = $dbConnection;
        $this->authServices = $authServices;
    }

    public function updatePassword($userId, $newPassword): bool {
        // Authenticate the operation
        if (!$this->isAuthenticated()) {
            error_log("Unauthorized attempt to update password for user {$userId}");
            return false;
        }

        // Start a transaction
        $this->dbConnection->beginTransaction();

        try {
            // Update user's password in the database
            $stmt = $this->dbConnection->prepare('UPDATE users SET password = ? WHERE id = ?');
            $stmt->execute([$newPassword, $userId]);

            // Notify external authentication services
            foreach ($this->authServices as $service) {
                if (!$service->updateUserPassword($userId, $newPassword)) {
                    throw new Exception("Failed to update user password with {$service->getName()}");
                }
            }

            // Commit the transaction
            $this->dbConnection->commit();

            // Log successful password update
            error_log("Password updated for user {$userId}");

            return true;
        } catch (Exception $e) {
            // Rollback on failure
            $this->dbConnection->rollBack();
            error_log("Failed to update password for user {$userId}: " . $e->getMessage());

            return false;
        }
    }

