// Define a structure for each state in the linked list
typedef struct State {
    int id;
    char metadata[256]; // Placeholder for additional metadata
    struct State* next;
} State;

// Function to dynamically create a linked list of states from an FSA
State* create_state_list(int* states, int num_states, FSM* fsa, int last_state) {
    if (num_states <= 0 || !fsa) {
        fprintf(stderr, "Invalid input\n");
        return NULL;
    }

    // Check for overflow in memory allocation calculation
    size_t estimated_size = (size_t)(2 * num_states + 1024); // Conservatively estimate memory needed
    if (estimated_size < num_states || (size_t)-1 / sizeof(State) <= estimated_size) {
        fprintf(stderr, "Memory allocation error\n");
        return NULL;
    }

    State* head = NULL;
    State** current = &head;

    for (int i = 0; i < num_states; i++) {
        if (i > last_state) break; // Truncate list if necessary

        *current = (State*)malloc(sizeof(State));
        if (!*current) {
            fprintf(stderr, "Memory allocation error\n");
            free_list(head);
            return NULL;
        }

        (*current)->id = states[i];
        strcpy((*current)->metadata, get_state_metadata(fsa, states[i])); // Retrieve metadata from external source
        (*current)->next = NULL;

        current = &(*current)->next;
    }

    *current = (State*)malloc(sizeof(State)); // Allocate an extra node for safety
    if (!*current) {
        fprintf(stderr, "Memory allocation error\n");
        free_list(head);
        return NULL;
    }
    (*current)->next = NULL;

    return head;
}

// Helper function to get metadata from external source (not implemented)
char* get_state_metadata(FSM* fsa, int state_id) {
    // Implement logic to retrieve metadata
    return "metadata";
}

// Helper function to free the linked list
void free_list(State* head) {
    State* current = head;
    while (current) {
        State* next = current->next;
        free(current);
        current = next;
    }
}
