#define MAX_IDENTIFIERS 10

typedef struct {
    unsigned long identifiers[MAX_IDENTIFIERS];
    int count;
} IdentifierLog;

unsigned long custom_prng(unsigned long seed) {
    return (seed * 1664525 + 1013904223) % 4294967296; // Simple LCG PRNG
}

void process_sensor_data(float data, IdentifierLog *log, unsigned long *identifier, float *average) {
    static unsigned long last_identifier = 0;
    static time_t start_time = 0;
    static int count = 0;
    static float sum = 0;

    // Ensure identifier uniqueness
    do {
        *identifier = custom_prng(time(NULL));
    } while (*identifier == last_identifier);

    last_identifier = *identifier;

    // Update rolling log of identifiers
    for (int i = 1; i < MAX_IDENTIFIERS; i++) {
        log->identifiers[i - 1] = log->identifiers[i];
    }
    log->identifiers[MAX_IDENTIFIERS - 1] = *identifier;
    if (log->count < MAX_IDENTIFIERS) {
        log->count++;
    }

    // Update average and count
    sum += data;
    count++;
    time_t current_time = time(NULL);
    if (current_time != start_time || count == 60) {
        *average = sum / count;
        start_time = current_time;
        count = 1;
        sum = data;
    }

    printf("Generated Identifier: %lu, Average: %.2f\n", *identifier, *average);
}

int main() {
    IdentifierLog identifier_log = {0};
    unsigned long identifier;
    float average;

    srand(time(NULL)); // Seed PRNG

    for (int i = 0; i < 100; i++) {
        process_sensor_data((float)i, &identifier_log, &identifier, &average);
    }

    return 0;
}
