async function asyncReduce(numbers, initialValue, callback, seed = 0) {
    if (!Array.isArray(numbers)) throw new Error('Input must be an array');
    if (typeof initialValue !== 'number') throw new Error('Initial value must be a number');
    if (typeof callback !== 'function') throw new Error('Callback must be a function');

    let accumulator = initialValue;
    for (const num of numbers) {
        if (typeof num !== 'number') continue; // Ignore non-numeric elements
        try {
            const result = await callback(accumulator, num, seed);
            accumulator = result;
        } catch (error) {
            console.error('Error during reduction:', error);
            return Promise.reject(error);
        }
    }
    return accumulator;
}

// Example usage:
const numbers = [1, 2, 3, 4, 5];
const initialValue = 0;
const callback = async (acc, num, seed) => {
    // Simulate some asynchronous operation using the PRNG
    const randomValue = Math.sin(seed + acc * num) * 1000; // Simple example of PRNG usage
    await new Promise(resolve => setTimeout(resolve, 1)); // Simulate async behavior
    return acc + num + randomValue;
};

asyncReduce(numbers, initialValue, callback, Math.random())
    .then(result => console.log('Reduced result:', result))
    .catch(error => console.error('Reduction failed:', error));
```

