#include <pthread.h>

typedef struct {
    char *buffer;
    size_t size;
} LogEntry;

LogEntry *read_log_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return NULL;

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    LogEntry *entry = malloc(sizeof(LogEntry));
    entry->buffer = malloc(file_size + 1);
    if (fread(entry->buffer, 1, file_size, file) != file_size) {
        free(entry->buffer);
        free(entry);
        fclose(file);
        return NULL;
    }

    entry->buffer[file_size] = '\0';
    entry->size = file_size;

    fclose(file);
    return entry;
}

void *process_log_file(void *arg) {
    const char *filename = (const char *) arg;
    LogEntry *entry = read_log_file(filename);
    if (!entry) return NULL;

    // Process the log entry
    printf("Processing log file: %s\n", filename);

    free(entry->buffer);
    free(entry);
    return NULL;
}

int main() {
    const char *log_files[] = {"file1.log", "file2.log", "file3.log"};
    pthread_t threads[3];

    for (size_t i = 0; i < sizeof(log_files) / sizeof(log_files[0]); ++i) {
        if (pthread_create(&threads[i], NULL, process_log_file, log_files[i])) {
            fprintf(stderr, "Failed to create thread\n");
            return 1;
        }
    }

    for (size_t i = 0; i < sizeof(log_files) / sizeof(log_files[0]); ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

