function enhanceDOMElements(inputText, sizeLimit, testElement, startNode) {
  if (inputText.length <= sizeLimit) {
    return inputText + '/';
  }

  const result = [];
  const queue = [startNode];

  while (queue.length > 0) {
    const node = queue.shift();

    if (node.nodeType === Node.ELEMENT_NODE && testElement(node)) {
      result.push(node);
    }

    for (let i = 0; i < node.childNodes.length; i++) {
      queue.push(node.childNodes[i]);
    }
  }

  return result;
}
