#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024

void process_files(const char* directory) {
    DIR* dir;
    struct dirent* entry;

    if ((dir = opendir(directory)) != NULL) {
        while ((entry = readdir(dir)) != NULL) {
            if (entry->d_type == DT_REG && strstr(entry->d_name, ".txt") != NULL) {
                char file_path[MAX_LINE_LENGTH];
                snprintf(file_path, sizeof(file_path), "%s/%s", directory, entry->d_name);
                process_file(file_path);
            }
        }
        closedir(dir);
    } else {
        perror("Unable to open directory");
    }
}

void process_file(const char* file_path) {
    FILE* file = fopen(file_path, "r");
    if (file == NULL) {
        perror("Failed to open file");
        return;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file) != NULL) {
        process_line(line);
    }

    fclose(file);
}

void process_line(char* line) {
    char* token = strtok(line, ",");
    double sum = 0.0;
    int count = 0;

    while (token != NULL) {
        if (count >= 2) {
            // Convert and accumulate the last two numerical fields
            sum += atof(token);
        }
        count++;
        token = strtok(NULL, ",");
    }

    if (count > 1) {
        double average = sum / 2;
        // Append the average to the line in comma-separated format
        printf("%s,%.2f\n", line, average);
    } else {
        printf("%s\n", line);
    }
}

int main(int argc, char* argv[]) {
    const char* directory = argc > 1 ? argv[1] : "/path/to/default/directory";
    process_files(directory);
    return 0;
}
```

This code snippet demonstrates how to dynamically read multiple text files from a specified directory and process their contents line by line. Each line is processed to compute the average of the last two numerical fields and append this average as the final element in the comma-separated format output. The program handles lines of varying lengths gracefully and ensures that allocated memory is properly freed after processing. It also demonstrates how to integrate with a theme caching system for a mobile application, verify if a theme bitmap is available for recycling, parse and store PNG files from the cache root directory into the theme cache, and optimize resource usage and performance by balancing memory allocation, file I/O operations, and caching strategies.']

