        return;
    }

    // Calculate the number of digits to append based on numeric characters in the filename
    int digit_count = 0;
    for (int i = 0; filename[i] != '\0'; i++) {
        if (filename[i] >= '0' && filename[i] <= '9') {
            digit_count++;
        }
    }

    // Append ".txt" to the modified filename
    char extension[] = ".txt";
    int extension_len = strlen(extension);

    // Ensure there is enough space in the buffer for the modified filename, file type, and digits
    if (digit_count + extension_len + 1 > buffer_size) {
        return;
    }

    // Construct the modified filename with a sequence of digits and file type
    snprintf(buffer, buffer_size, "%s%d%s", filename, digit_count, extension);
}
