void aes_cbc_init(const char *password, unsigned char **key, unsigned char **iv) {
    const int key_len = 32;
    const int iv_len = 16;

    // Derive the encryption key using SHA-1
    unsigned char sha1_digest[SHA_DIGEST_LENGTH];
    SHA1((unsigned char*)password, strlen(password), sha1_digest);

    *key = (unsigned char *)malloc(key_len);
    memcpy(*key, sha1_digest, key_len);

    // Generate a random IV
    *iv = (unsigned char *)malloc(iv_len);
    if (!RAND_bytes(*iv, iv_len)) {
        fprintf(stderr, "Failed to generate IV\n");
        exit(EXIT_FAILURE);
    }
}

void aes_cbc_cleanup(unsigned char *key, unsigned char *iv) {
    free(key);
    free(iv);
}
