        exit(EXIT_FAILURE);
    }
    theme_cache[cache_index].bitmap = NULL;
    theme_cache[cache_index].is_cached = 0;
}

unsigned char* get_theme_bitmap(const char *filename) {
    for (int i = 0; i < THEME_CACHE_SIZE; i++) {
        if (theme_cache[i].is_cached && strcmp(theme_cache[i].bitmap, filename) == 0) {
            return theme_cache[i].bitmap;
        }
    }

    unsigned char *bitmap = (unsigned char *)malloc(strlen(filename));
    strcpy(bitmap, filename);
    theme_cache[cache_index].bitmap = bitmap;
    theme_cache[cache_index].is_cached = 1;

    // Load the PNG file into the bitmap
    // This part is not implemented as it depends on the specific library used to handle PNG files

    cache_index++;
    return bitmap;
}

void recycle_theme_bitmap(unsigned char *bitmap) {
    for (int i = 0; i < THEME_CACHE_SIZE; i++) {
        if (theme_cache[i].is_cached && theme_cache[i].bitmap == bitmap) {
            free(theme_cache[i].bitmap);
            theme_cache[i].bitmap = NULL;
            theme_cache[i].is_cached = 0;
            return;
        }
    }
}
