    struct jpeg_error_mgr jerr;
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);
    jpeg_stdio_src(&cinfo, inFile);
    jpeg_read_header(&cinfo, TRUE);
    jpeg_start_decompress(&cinfo);

    SerializedPDF* serializedPDF = malloc(sizeof(SerializedPDF));
    if (!serializedPDF) {
        fclose(inFile);
        jpeg_destroy_decompress(&cinfo);
        return NULL; // Handle error
    }
    serializedPDF->length = cinfo.output_width * cinfo.output_height * 3;
    serializedPDF->data = malloc(serializedPDF->length);
    if (!serializedPDF->data) {
        free(serializedPDF);
        fclose(inFile);
        jpeg_destroy_decompress(&cinfo);
        return NULL; // Handle error
    }

    JSAMPROW row_pointer[1];
    while (cinfo.output_scanline < cinfo.output_height) {
        row_pointer[0] = serializedPDF->data + cinfo.output_scanline * cinfo.output_width * 3;
        jpeg_read_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);
    fclose(inFile);

    // Apply processing parameters to serializedPDF->data here

    return serializedPDF;
}
