#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

#define MAX_COMMAND_LENGTH 256

int execute_command_in_background(const char *command, const char **args) {
    pid_t pid;
    int status;

    // Validate command and arguments length
    size_t total_length = strlen(command);
    for (const char *arg = args[0]; arg != NULL; arg++) {
        if (strlen(arg) > MAX_COMMAND_LENGTH - total_length - 1) {
            fprintf(stderr, "Error: Argument too long.\n");
            return -1;
        }
        total_length += strlen(arg) + 1;
    }

    // Fork a new process
    pid = fork();
    if (pid == -1) {
        perror("fork");
        return -1;
    } else if (pid == 0) {
        // Child process
        execvp(command, (char *const *)args);
        perror("execvp"); // This should never be reached if execvp succeeds
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        printf("Command started in background with PID %d\n", pid);
        return 0;
    }
}

int main() {
    const char *command = "ls";
    const char *args[] = {"-l", "/home/user", NULL};

    if (execute_command_in_background(command, args) == -1) {
        fprintf(stderr, "Failed to start command.\n");
        return EXIT_FAILURE;
    }

    // Parent continues with other tasks
    waitpid(-1, &status, 0);
    printf("Command completed with status %d\n", WEXITSTATUS(status));

    return EXIT_SUCCESS;
}
