public class WebsiteManager
{
    private readonly string _monitoringServiceUrl;
    private readonly int _maxRetries;
    private readonly TimeSpan _retryInterval;

    public WebsiteManager(string monitoringServiceUrl, int maxRetries, TimeSpan retryInterval)
    {
        _monitoringServiceUrl = monitoringServiceUrl;
        _maxRetries = maxRetries;
        _retryInterval = retryInterval;
