            throw new DirectoryNotFoundException($"The directory '{directoryPath}' does not exist.");
        }

        string configFilePath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(configFilePath))
        {
            throw new FileNotFoundException($"The web.config file is missing in the directory '{directoryPath}'.");
        }

        for (int retryCount = 0; retryCount <= _maxRetries; retryCount++)
        {
            try
            {
                // Log action to monitoring service
                await LogActionAsync("StartSite", directoryPath);

                // Start website logic here
                Console.WriteLine($"Starting site in directory: {directoryPath}");

                // Simulate starting the website
                await Task.Delay(1000);

                // Log success
                await LogActionAsync("SiteStarted", directoryPath);
                return;
            }
            catch (Exception ex)
            {
                if (retryCount == _maxRetries)
                {
                    throw new Exception($"Failed to start site in directory '{directoryPath}' after {_maxRetries} retries.", ex);
                }

                // Log error
                await LogActionAsync("SiteStartFailed", directoryPath, ex.Message);

                // Retry logic
                await Task.Delay(_retryInterval);
            }
        }
    }

    private async Task LogActionAsync(string action, string directoryPath, string errorMessage = null)
    {
        // Simulate logging to monitoring service
        Console.WriteLine($"[{DateTime.UtcNow}] {action} in {directoryPath}: {(errorMessage != null ? $"ERROR: {errorMessage}" : "SUCCESS")}");
    }
}

// Usage example
class Program
{
    static async Task Main(string[] args)
    {
        WebsiteManager manager = new WebsiteManager("http://monitoring.service/log", 3, TimeSpan.FromSeconds(5));
        await manager.AddAndStartSiteAsync("C:\\Sites\\MyNewSite");
    }
}
```

