import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class DirectorySizeCalculator {

    private String commandLineUtility = "du -sh"; // Default utility for Unix/Linux

    public void setCommandLineUtility(String utility) {
        this.commandLineUtility = utility;
    }

    public long calculateDirectorySize(String directoryPath) throws IOException {
        Path path = Paths.get(directoryPath);

        if (!Files.exists(path)) {
            throw new IOException("Directory does not exist: " + directoryPath);
        }

        String command = commandLineUtility + " " + directoryPath;
        Process process = Runtime.getRuntime().exec(command);

        try (var reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            return Long.parseLong(reader.readLine().split("\\s+")[0].replaceAll("[^\\d]", ""));
        } catch (NumberFormatException e) {
            throw new IOException("Failed to parse directory size output", e);
        }
    }

    public static void main(String[] args) {
        DirectorySizeCalculator calculator = new DirectorySizeCalculator();

        try {
            String[] directories = {"./path/to/directory1", "/absolute/path/to/directory2"};

            for (String dir : directories) {
                long size = calculator.calculateDirectorySize(dir);
                System.out.println("Size of " + dir + ": " + size + " bytes");
            }
        } catch (IOException e) {
            System.err.println("Error calculating directory size: " + e.getMessage());
        }
    }
}
