public class MessageDecryptor
{
    private readonly byte[] _key;
    private readonly byte[] _iv;
    private readonly ILogger<MessageDecryptor> _logger;

    public MessageDecryptor(byte[] key, byte[] iv, ILogger<MessageDecryptor> logger)
    {
        _key = key;
        _iv = iv;
        _logger = logger;
    }

    public async Task<List<string>> DecryptMessagesAsync(List<string> base64EncodedMessages, int batchSize = 10)
    {
        var decryptedMessages = new List<string>();
        for (int i = 0; i < base64EncodedMessages.Count; i += batchSize)
        {
            var batch = base64EncodedMessages.Skip(i).Take(batchSize);
            var decryptedBatch = await Task.WhenAll(batch.Select(DecryptMessageAsync));
            decryptedMessages.AddRange(decryptedBatch);
        }
        return decryptedMessages;
    }

    private async Task<string> DecryptMessageAsync(string base64EncodedMessage)
    {
        try
        {
            using (var decryptor = Aes.Create())
            {
                decryptor.Key = _key;
                decryptor.IV = _iv;
                decryptor.Mode = CipherMode.CBC;
                decryptor.Padding = PaddingMode.PKCS7;

                var encryptedData = Convert.FromBase64String(base64EncodedMessage);
                using (var msDecrypt = new MemoryStream(encryptedData))
                {
                    using (var csDecrypt = new CryptoStream(msDecrypt, decryptor.CreateDecryptor(), CryptoStreamMode.Read))
                    {
                        using (var srDecrypt = new StreamReader(csDecrypt))
                        {
                            var decryptedMessage = await srDecrypt.ReadToEndAsync();
                            var hmac = CreateHmac(decryptedMessage);
                            if (VerifyHmac(hmac))
