                                _logger.LogInformation($"Decryption successful for message: {decryptedMessage}");
                                return decryptedMessage;
                            }
                            else
                            {
                                _logger.LogError($"Integrity check failed for message: {decryptedMessage}");
                                throw new SecurityException("Integrity check failed");
                            }
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Decryption failed");
            throw;
        }
    }

    private byte[] CreateHmac(string decryptedMessage)
    {
        using (var hmac = new HMACSHA256(_key))
        {
            return hmac.ComputeHash(System.Text.Encoding.UTF8.GetBytes(decryptedMessage));
        }
    }

