using System;
using System.Security.Cryptography;
using System.Text;

public class HashGenerator
{
    public static (string MD5Hash, string SHA256Hash) GenerateHashes(string input)
    {
        if (string.IsNullOrEmpty(input))
            throw new ArgumentException("Input cannot be null or empty.");

        using (MD5 md5 = MD5.Create())
        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] inputBytes = Encoding.UTF8.GetBytes(input);
            byte[] md5HashBytes = md5.ComputeHash(inputBytes);
            byte[] sha256HashBytes = sha256.ComputeHash(inputBytes);

            string md5Hash = BitConverter.ToString(md5HashBytes).Replace("-", "").ToLower();
            string sha256Hash = BitConverter.ToString(sha256HashBytes).Replace("-", "").ToLower();

            return (md5Hash, sha256Hash);
        }
    }

    public static void Main(string[] args)
    {
        try
        {
            var result = GenerateHashes("Hello, World!");
            Console.WriteLine($"MD5: {result.MD5Hash}");
            Console.WriteLine($"SHA-256: {result.SHA256Hash}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
