using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class AesCbcDecryptor
{
    private readonly ICryptoTransform _cryptoTransform;
    private readonly PaddingMode _paddingMode;
    private readonly HMACSHA256 _hmac;

    public AesCbcDecryptor(byte[] key, byte[] iv, PaddingMode paddingMode)
    {
        if (key == null || key.Length < 16 || key.Length > 32)
            throw new ArgumentException("Invalid AES key length.");

        if (iv == null || iv.Length != 16)
            throw new ArgumentException("Invalid IV length.");

        _cryptoTransform = Aes.Create().CreateDecryptor(key, iv);
        _paddingMode = paddingMode;
        _hmac = new HMACSHA256(key);
    }

    public byte[] Decrypt(byte[] ciphertext, string macAlgorithm)
    {
        if (ciphertext == null || ciphertext.Length < 32) // Assuming MAC length is 32 bytes
            throw new ArgumentException("Invalid ciphertext length.");

        var macBytes = new byte[32];
        Array.Copy(ciphertext, ciphertext.Length - 32, macBytes, 0, 32);
        ciphertext = ciphertext.Take(ciphertext.Length - 32).ToArray();

        using (var hmac = HMAC.Create(macAlgorithm))
        {
            hmac.Key = _cryptoTransform.Key;
            var computedMac = hmac.ComputeHash(ciphertext);

            if (!computedMac.SequenceEqual(macBytes))
                throw new CryptographicException("MAC verification failed.");
        }

        using (var msDecrypt = new MemoryStream(ciphertext))
        using (var csDecrypt = new CryptoStream(msDecrypt, _cryptoTransform, CryptoStreamMode.Read))
        {
            return csDecrypt.ToArray();
        }
    }
}
```

