import java.io.*;
import java.net.Socket;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ObjectStreamDeserializer {

    private final ExecutorService executorService = Executors.newCachedThreadPool();
    private final Socket socket;

    public ObjectStreamDeserializer(Socket socket) {
        this.socket = socket;
    }

    public void startDeserialization() {
        try (InputStream inputStream = socket.getInputStream()) {
            while (!Thread.currentThread().isInterrupted()) {
                byte[] buffer = new byte[1024];
                int bytesRead = inputStream.read(buffer);
                if (bytesRead == -1) {
                    break;
                }
                Object obj = deserializeObject(new ByteArrayInputStream(buffer, 0, bytesRead));
                handleDeserializedObject(obj);
            }
        } catch (IOException e) {
            Thread.currentThread().interrupt();
        } finally {
            executorService.shutdown();
        }
    }

    private Object deserializeObject(InputStream inputStream) throws IOException {
        try (ObjectInputStream ois = new ObjectInputStream(inputStream)) {
            return ois.readObject();
        } catch (ClassNotFoundException e) {
            throw new IOException("Class not found during deserialization", e);
        }
    }

    private void handleDeserializedObject(Object obj) {
        // Implement object validation and processing logic here
        if (obj instanceof CustomDataStructure) {
            CustomDataStructure data = (CustomDataStructure) obj;
            validateAndProcess(data);
        } else {
            throw new IllegalArgumentException("Unsupported object type");
        }
    }

    private void validateAndProcess(CustomDataStructure data) {
        // Implement data integrity checks and processing logic here
        if (!data.isValid()) {
            throw new IllegalArgumentException("Invalid data structure received");
        }
        processObject(data);
    }

    private void processObject(CustomDataStructure data) {
        // Implement object processing logic here
        executorService.submit(() -> {
            // Perform operations with the data in a separate thread to avoid blocking the main loop
        });
    }

    public static void main(String[] args) throws IOException, InterruptedException {
        Socket socket = new Socket("localhost", 12345);
        ObjectStreamDeserializer deserializer = new ObjectStreamDeserializer(socket);
        deserializer.startDeserialization();
    }
}
