import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class SerializationUtils {

    public static <T> T deserializeObject(byte[] data, Class<T> expectedClass) throws DeserializationException {
        try {
            // Calculate the checksum of the data
            byte[] calculatedChecksum = calculateChecksum(data);
            if (!Arrays.equals(calculatedChecksum, new byte[]{/* Expected checksum */})) {
                logWarning("Checksum does not match. Manual inspection required.");
                throw new DeserializationException("Checksum verification failed.");
            }

            // Deserialize the object
            ByteArrayInputStream bais = new ByteArrayInputStream(data);
            ObjectInputStream ois = new ObjectInputStream(bais);
            T deserializedObject = expectedClass.cast(ois.readObject());
            ois.close();
            return deserializedObject;
        } catch (IOException | ClassNotFoundException e) {
            logError("Failed to deserialize object: " + e.getMessage(), e);
            throw new DeserializationException("Deserialization failed.", e);
        }
    }

    private static byte[] calculateChecksum(byte[] data) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        return md.digest(data);
    }

    private static void logWarning(String message) {
        System.out.println("WARNING: " + message);
    }

    private static void logError(String message, Throwable e) {
        System.err.println("ERROR: " + message);
        e.printStackTrace();
    }

    public static class DeserializationException extends Exception {
        public DeserializationException(String message) {
            super(message);
        }

        public DeserializationException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
