const express = require('express');
const multer = require('multer');
const AWS = require('aws-sdk');
const crypto = require('crypto');

const app = express();
const upload = multer({ storage: multer.memoryStorage() });
const s3 = new AWS.S3({
  accessKeyId: 'YOUR_ACCESS_KEY_ID',
  secretAccessKey: 'YOUR_SECRET_ACCESS_KEY'
});

app.use(express.json());

const fileUploads = {};

app.post('/upload', upload.array('files'), async (req, res) => {
  const batchId = crypto.randomBytes(16).toString('hex');
  fileUploads[batchId] = [];

  for (let i = 0; i < req.files.length; i++) {
    const file = req.files[i];
    const params = {
      Bucket: 'your-bucket-name',
      Key: `uploads/${file.originalname}`,
      Body: file.buffer,
      Metadata: {
        uploadTimestamp: new Date().toISOString(),
        status: 'pending'
      }
    };

    try {
      const data = await s3.upload(params).promise();
      params.Metadata.status = 'success';
      params.Metadata.location = data.Location;
    } catch (error) {
      params.Metadata.status = 'failure';
      params.Metadata.error = error.message;
    }

    fileUploads[batchId].push(params);
  }

  res.json({ batchId, status: 'uploading' });
});

app.get('/status/:batchId', (req, res) => {
  const batchId = req.params.batchId;

  if (!fileUploads[batchId]) {
    return res.status(404).json({ error: 'Batch not found' });
  }

  const status = fileUploads[batchId].reduce((acc, curr) => {
    acc[curr.Metadata.status] = (acc[curr.Metadata.status] || 0) + 1;
    return acc;
  }, {});

  res.json(status);
});

app.listen(3000, () => {
  console.log('File upload service running on port 3000');
});
```"]

["```javascript
const fs = require('fs').promises;
const axios = require('axios');
const { LRUCache } = require('lru-cache');

class ConfigManager {
  constructor(configFilePath) {
    this.configFilePath = configFilePath;
    this.cache = new LRUCache({ max: 100 });
    this.apiCache = new LRUCache({ max: 50 });
  }

  async loadConfig() {
    try {
      const data = await fs.readFile(this.configFilePath, 'utf8');
      return JSON.parse(data);
    } catch (error) {
      if (error.code === 'ENOENT') {
        return {};
      }
      throw error;
    }
  }

  async saveConfig(config) {
    await fs.writeFile(this.configFilePath, JSON.stringify(config, null, 2), 'utf8');
  }

  async get(key) {
    const fromCache = this.cache.get(key);
    if (fromCache) {
      return fromCache;
    }

    const config = await this.loadConfig();
    const value = config[key];
    if (value !== undefined) {
      this.cache.set(key, value);
      return value;
    }

    throw new Error(`Key ${key} not found in configuration.`);
  }

  async set(key, value) {
    const config = await this.loadConfig();
    config[key] = value;
    await this.saveConfig(config);
    this.cache.set(key, value);
  }

  async delete(key) {
    const config = await this.loadConfig();
    if (config.hasOwnProperty(key)) {
      delete config[key];
      await this.saveConfig(config);
      this.cache.del(key);
    }
  }

  async updateApiData(apiKey, endpoint, data) {
    try {
      const response = await axios.post(`https://api.example.com/${apiKey}/${endpoint}`, data);
      this.apiCache.set(`${apiKey}-${endpoint}`, response.data);
      return response.data;
    } catch (error) {
      if (error.response) {
        throw new Error(`API error: ${error.response.status} - ${error.response.statusText}`);
      }
      throw new Error('Network error or invalid API key.');
    }
  }

  async getApiData(apiKey, endpoint) {
    const fromCache = this.apiCache.get(`${apiKey}-${endpoint}`);
    if (fromCache) {
      return fromCache;
    }

    try {
      const data = await this.updateApiData(apiKey, endpoint);
      this.apiCache.set(`${apiKey}-${endpoint}`, data);
      return data;
    } catch (error) {
      console.error(`Failed to fetch API data for ${apiKey} / ${endpoint}:`, error);
      throw error;
    }
  }
}

// Example usage:
const configManager = new ConfigManager('config.json');

(async () => {
  try {
    await configManager.set('theme', 'dark');
    const theme = await configManager.get('theme');
    console.log(`Current theme: ${theme}`);

    await configManager.delete('theme');
    try {
      await configManager.get('theme');
    } catch (error) {
      console.log('Theme key not found:', error.message);
    }

    const apiData = await configManager.getApiData('myApiKey', 'status');
    console.log('API data:', apiData);
  } catch (error) {
    console.error('Error:', error);
  }
