import uuid
from random import randint
from typing import Dict, List, Optional

class GraphNode:
    def __init__(self, identifier: str):
        self.identifier = identifier
        self.properties = {}
        self.edges = {}

class Edge:
    def __init__(self, weight: int, direction: str):
        self.weight = weight
        self.direction = direction

class DynamicGraphDatabase:
    def __init__(self, max_size: int):
        self.max_size = max_size
        self.vertices: Dict[str, GraphNode] = {}

    def add_vertex(self) -> None:
        if len(self.vertices) >= self.max_size:
            raise Exception("Graph size limit reached")

        identifier = str(uuid.uuid4())
        while identifier in self.vertices:
            identifier = str(uuid.uuid4())

        random_property = f"property_{randint(1, 100)}"
        new_vertex = GraphNode(identifier)
        new_vertex.properties[random_property] = True
        self.vertices[identifier] = new_vertex

    def add_edge(self, source: str, destination: str, weight: int, direction: str) -> None:
        if source not in self.vertices or destination not in self.vertices:
            raise Exception("One or both vertices do not exist")

        if len(self.vertices) >= self.max_size:
            raise Exception("Graph size limit reached")

        new_edge = Edge(weight, direction)
        self.vertices[source].edges[destination] = new_edge
        if direction == "bidirectional":
            self.vertices[destination].edges[source] = new_edge

    def get_edges_for_vertex(self, vertex_id: str) -> List[Edge]:
        return list(self.vertices[vertex_id].edges.values())

# Example usage:
graph_db = DynamicGraphDatabase(max_size=1000)
graph_db.add_vertex()
graph_db.add_vertex()
graph_db.add_edge("vertex1", "vertex2", weight=5, direction="unidirectional")
edges = graph_db.get_edges_for_vertex("vertex1")
print(edges)
