use tokio::sync::{mpsc, Mutex};
use tokio::task;
use std::error::Error;
use std::time::Duration;

#[derive(Debug)]
enum Task {
    FileIO,
    NetworkRequest,
    DatabaseQuery,
}

async fn file_io_task() -> Result<(), Box<dyn Error>> {
    // Simulate file I/O operation
    println!("Executing file I/O task");
    Ok(())
}

async fn network_request_task() -> Result<(), Box<dyn Error>> {
    // Simulate network request operation with potential retries
    for attempt in 1..=3 {
        match reqwest::get("https://api.example.com/data").await {
            Ok(response) if response.status().is_success() => {
                println!("Network request successful");
                return Ok(());
            }
            _ => {
                if attempt == 3 {
                    println!("Network request failed after {} attempts", attempt);
                    return Err("Network request failed".into());
                } else {
                    println!("Retrying network request...");
                    tokio::time::sleep(Duration::from_secs(1)).await;
                }
            }
        }
    }
}

async fn database_query_task() -> Result<(), Box<dyn Error>> {
    // Simulate database query operation with caching
    let cache = Mutex::new(None);
    if let Some(data) = *cache.lock().await {
        println!("Using cached data");
        return Ok(());
    }

    // Simulate database query
    println!("Executing database query");
    let data = "Cached data".to_string();
    *cache.lock().await = Some(data.clone());

    println!("Database query result: {}", data);
    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    let (tx, mut rx) = mpsc::channel(10);

    for task in vec![Task::FileIO, Task::NetworkRequest, Task::DatabaseQuery] {
        tx.send(task).await?;
    }

    while let Some(task) = rx.recv().await {
        match task {
            Task::FileIO => task::spawn(async move {
                if let Err(e) = file_io_task().await {
                    error!("Error executing file I/O task: {}", e);
                }
            }),
            Task::NetworkRequest => task::spawn(async move {
                if let Err(e) = network_request_task().await {
                    error!("Error executing network request task: {}", e);
                }
            }),
            Task::DatabaseQuery => task::spawn(async move {
                if let Err(e) = database_query_task().await {
                    error!("Error executing database query task: {}", e);
                }
            }),
        };
    }

    Ok(())
}
