use std::fs;
use std::env;
use std::path::{Path, PathBuf};
use std::thread;
use std::time::{Duration, Instant};
use log::{info, error};

const MAX_RETRIES: u8 = 3;

fn create_directory_and_set_env_var(directory_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let config_service_url = "http://config-service/checksum";

    for attempt in 1..=MAX_RETRIES {
        if let Some(valid_path) = verify_env_var_checksum(config_service_url, directory_name)? {
            env::set_var("MY_DIRECTORY", valid_path);
            info!("Directory path verified: {}", valid_path.display());
            return Ok(());
        }

        if attempt == MAX_RETRIES {
            error!("Failed to verify environment variable after {} attempts", MAX_RETRIES);
            return Err("Environment variable verification failed".into());
        } else {
            let delay = Duration::from_secs(attempt as u64);
            info!("Retrying in {:?}...", delay);
            thread::sleep(delay);
        }
    }

    let new_dir_path = create_new_directory(directory_name)?;
    env::set_var("MY_DIRECTORY", &new_dir_path);
    info!("New directory created and environment variable set: {}", new_dir_path.display());
    Ok(())
}

fn verify_env_var_checksum(config_service_url: &str, expected_variable: &str) -> Result<Option<PathBuf>, Box<dyn std::error::Error>> {
    // Simulate fetching checksum from config service
    let response = reqwest::blocking::get(config_service_url)?;
    let expected_checksum = response.text()?;

    if env::var(expected_variable).map_or(false, |path| {
        match Path::new(&path).metadata() {
            Ok(metadata) => metadata.is_dir(),
            Err(_) => false,
        }
    }) {
        // Simulate checksum validation
        if "expected_hash" == expected_checksum {
            return Ok(Some(PathBuf::from(env::var(expected_variable)?)));
        } else {
            error!("Checksum mismatch for environment variable: {}", expected_variable);
        }
    }

    Ok(None)
}

fn create_new_directory(directory_name: &str) -> Result<PathBuf, Box<dyn std::error::Error>> {
    let mut new_dir_path = env::temp_dir();
    new_dir_path.push(&directory_name);

    fs::create_dir_all(&new_dir_path)?;
    info!("Created new directory at: {}", new_dir_path.display());
    Ok(new_dir_path)
}
