#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

long *allocate_long_array(size_t size) {
    return (long *)malloc(size * sizeof(long));
}

int *allocate_int_array(size_t size) {
    return (int *)malloc(size * sizeof(int));
}

record *allocate_record_array(size_t size) {
    return (record *)malloc(size * sizeof(record));
}

void initialize_lcg(unsigned long *seed, unsigned long a, unsigned long c, unsigned long m) {
    *seed = time(NULL);
    *a = 1664525;
    *c = 1013904223;
    *m = 4294967296ULL; // 2^32
}

int pseudo_random_number(unsigned long *seed, unsigned long a, unsigned long c, unsigned long m) {
    *seed = (*a * (*seed) + *c) % *m;
    return (int)(*seed / (double)*m * (1 << 30)); // Scale to int range
}

int initialize_arrays(long **long_arr, int **int_arr, record **record_arr, size_t size, unsigned long a, unsigned long c, unsigned long m) {
    *long_arr = allocate_long_array(size);
    *int_arr = allocate_int_array(size);
    *record_arr = allocate_record_array(size);

    if (*long_arr == NULL || *int_arr == NULL || *record_arr == NULL) {
        return -1; // Memory allocation failed
    }

    unsigned long seed;
    initialize_lcg(&seed, a, c, m);

    for (size_t i = 0; i < size; i++) {
        (*long_arr)[i] = pseudo_random_number(&seed, a, c, m);
        (*int_arr)[i] = pseudo_random_number(&seed, a, c, m);
        (*record_arr)[i].value = pseudo_random_number(&seed, a, c, m);
    }

    return 0; // Success
}

// Example usage
int main() {
    size_t size = 100;
    long *long_arr;
    int *int_arr;
    record *record_arr;

    if (initialize_arrays(&long_arr, &int_arr, &record_arr, size, 0, 0, 0) == -1) {
        // Handle memory allocation failure
        return 1;
    }

    // Use the arrays as needed...

    free(long_arr);
    free(int_arr);
    free(record_arr);

    return 0;
}
```

