#include <random>
#include <memory>

struct record {
    int value;
};

class RandomRecordManager {
public:
    RandomRecordManager(size_t size) : data_size(size), records(new record[size]) {
        if (!records) {
            throw std::bad_alloc();
        }
        initialize_random_engine();
        populate_records();
    }

    ~RandomRecordManager() {
        delete[] records;
    }

    const record* getRecords() const {
        return records;
    }

private:
    size_t data_size;
    record* records;

    void initialize_random_engine() {
        std::random_device rd;  // Seed from random device
        if (!rd()) {  // Check for failure in seed initialization
            throw std::runtime_error("Failed to initialize random number generator seed.");
        }
        gen.seed(rd());
    }

    void populate_records() {
        std::uniform_int_distribution<> dis(1, 100);  // Range for the random numbers
        for (size_t i = 0; i < data_size; ++i) {
            records[i].value = dis(gen);
        }
    }

    std::mt19937 gen;  // Mersenne Twister engine
};

int main() {
    try {
        size_t num_records = 10;
        RandomRecordManager manager(num_records);

        const record* data = manager.getRecords();
        for (size_t i = 0; i < num_records; ++i) {
            std::cout << "Record " << i << ": " << data[i].value << std::endl;
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
