        fprintf(stderr, "Error: Maximum number of images reached.\n");
        return;
    }
    Image *new_image = malloc(sizeof(Image));
    new_image->filename = strdup(filename);
    new_image->width = width;
    new_image->height = height;
    new_image->resolution = resolution;
    // Initialize additional metadata fields if needed
    images[image_count++] = new_image;
}

// Function to calculate total memory requirements
size_t calculate_memory_requirements() {
    size_t total_memory = 0;
    for (int i = 0; i < image_count; i++) {
        Image *image = images[i];
        total_memory += sizeof(Image) + strlen(image->filename);
        // Add memory for additional metadata fields if needed
    }
    return total_memory;
}

// Function to free all allocated memory
void free_images() {
    for (int i = 0; i < image_count; i++) {
        Image *image = images[i];
        free(image->filename);
        free(image);
    }
    image_count = 0;
}

