    while ((numRead < outputArraySize) && scanf("%d", &inputArray[numRead++]) == 1);

    int maxVal = recordArray[0].value > inputArray[0] ? recordArray[0].value : inputArray[0];
    // Find the largest integer in both arrays
    for (int i = 1; i < maxValue; i++) {
        if (recordArray[i].value > maxVal) maxVal = recordArray[i].value;
    }
    for (int i = 1; i < numRead; i++) {
