int populate_records(int start, int end) {
    if (end < start) return 0; // Empty range
    for (int i = start; i <= end; i++) {
        records[i].value = rand() % ((i - start + 1) * 10); // Pseudo-random number generation
    }
    return end - start + 1;
}

void read_input(int* inputArray, int* inputSize) {
