    if (!logFile) {
        perror("Failed to open log file");
        return;
    }

    // Memory pool implementation
    const size_t poolSize = 1024 * 1024; // 1MB for demonstration
    char *memoryPool = (char *)malloc(poolSize);
    if (!memoryPool) {
        perror("Failed to allocate memory pool");
        fclose(logFile);
        return;
    }

    size_t nextFree = 0;

    int *inputArray = (int *)memoryPool; // Using part of the pool for input data
    size_t inputSize = poolSize / sizeof(int);

    // Simulate reading from standard input and processing
    printf("Enter integers, enter -1 to stop:\n");
    while (nextFree < inputSize) {
        int value;
        if (scanf("%d", &value) != 1) break;
        if (value == -1) break;
        inputArray[nextFree++] = value;
    }

    // Find max in records
    int maxInRecords = records[0].value;
    for (long i = 1; i < max_records; ++i) {
        if (records[i].value > maxInRecords) {
