#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000000

typedef struct {
    int key;
    long offset;
    int uniqueValue;
} record;

// Non-cryptographic PRNG for speed
int fastPRNG() {
    static unsigned int seed = time(NULL);
    return (seed = seed * 214013 + 2531011) >> 16;
}

// Non-cryptographic PRNG for accuracy and repeatability
int accuratePRNG(int range, int start, int end) {
    static unsigned int seed = time(NULL);
    return (rand_r(&seed) % range) + start;
}

record* createRecordsArray(int count, int (*prngFunc)(int), int minValue, int maxValue) {
    if (count > MAX_RECORDS) {
        fprintf(stderr, "Error: Maximum records limit exceeded.\n");
        return NULL;
    }

    record* records = (record*)malloc(count * sizeof(record));
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        records[i].key = i;
        records[i].offset = prngFunc();
        records[i].uniqueValue = accuratePRNG(maxValue - minValue + 1, minValue, maxValue);
    }

    return records;
}

void freeRecordsArray(record* records) {
    free(records);
}

int main() {
    int count = 500000;
    record* myRecords = createRecordsArray(count, fastPRNG, 100, 200);

    if (myRecords) {
        // Use the records array...

        freeRecordsArray(myRecords);
    }

    return 0;
