int allocate_and_initialize_records(int num_records, int semaphore_value, unsigned int prng_seed) {
    if (num_records <= 0 || semaphore_value <= 0) {
        fprintf(stderr, "Invalid input values.\n");
        return -1;
    }

    record *records = (record *)malloc(num_records * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records.");
        return -1;
    }

    sem_t *sem = sem_open("/my_semaphore", O_CREAT, 0644, semaphore_value);
    if (sem == SEM_FAILED) {
        perror("Failed to create semaphore.");
        free(records);
        return -1;
    }

    srand(prng_seed);
    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand();
    }

    sem_close(sem);
    sem_unlink("/my_semaphore");
    free(records);

    return 0;
}

