#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>

#define MAX_HOSTNAME_LEN 256
#define MAX_IP_LEN 16
#define MAX_CONCURRENT_QUERIES 10
#define MAX_THREADS 5
#define MEMORY_THRESHOLD 500000 // in bytes

typedef struct {
    char *hostname;
    u_char ip[MAX_IP_LEN];
    int status_code;
} HostInfo;

HostInfo *host_info_array;
int host_count = 0;
int max_hosts;
pthread_mutex_t info_lock;
pthread_cond_t info_ready;
int query_in_progress = 0;

void* dns_resolution(void* arg) {
    HostInfo *info = (HostInfo*)arg;
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(info->hostname, NULL, &hints, &res)) != 0) {
        info->status_code = status;
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        if (inet_ntop(p->ai_family, &(ipv4->sin_addr), info->ip, MAX_IP_LEN)) {
            break;
        }
    }

    freeaddrinfo(res);
    info->status_code = 0;

    return NULL;
}

void* process_line(void* arg) {
    char *line = (char*)arg;
    HostInfo info;
    pthread_t dns_thread;

    strncpy(info.hostname, line, MAX_HOSTNAME_LEN);

    if (pthread_create(&dns_thread, NULL, dns_resolution, &info) != 0) {
        fprintf(stderr, "Error creating DNS thread\n");
        return NULL;
    }

    pthread_join(dns_thread, NULL);
    pthread_mutex_lock(&info_lock);
    host_info_array[host_count++] = info;
    pthread_cond_signal(&info_ready);
    pthread_mutex_unlock(&info_lock);

    free(line); // Ensure line memory is freed correctly

    return NULL;
}

void monitor_resources() {
    // Implement monitoring mechanism here
}

int main() {
    FILE *file;
    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    max_hosts = MAX_THREADS; // Assuming each thread can process one line
    host_info_array = (HostInfo*)calloc(max_hosts, sizeof(HostInfo));
    if (!host_info_array) {
        fprintf(stderr, "Failed to allocate memory\n");
        return EXIT_FAILURE;
    }

    pthread_mutex_init(&info_lock, NULL);
    pthread_cond_init(&info_ready, NULL);

    file = fopen("hosts.txt", "r");
    if (file == NULL) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    while ((read = getline(&line, &len, file)) != -1) {
        line[strcspn(line, "\n")] = '\0'; // Remove newline character
        pthread_t thread;

        if (pthread_create(&thread, NULL, process_line, strdup(line)) != 0) {
            fprintf(stderr, "Error creating processing thread\n");
            free(line);
            break;
        }
    }

    free(line);
    fclose(file);

    while (host_count < host_info_array->status_code) {
        pthread_cond_wait(&info_ready, &info_lock);
    }

    // Free dynamically allocated memory and perform other cleanup
    for (int i = 0; i < host_count; i++) {
        free(host_info_array[i].hostname);
        if (host_info_array[i].ip[0] != '\0') { // Assuming IP is valid if not empty string
            free((void*)host_info_array[i].ip);
        }
    }

    pthread_mutex_destroy(&info_lock);
    pthread_cond_destroy(&info_ready);
    free(host_info_array);

    return EXIT_SUCCESS;
}
