// Function to process a stream of integers from a network socket
int processStream(int connectionLimit, int allowNegative) {
    char line[MAX_LINE_LENGTH];
    int *array = NULL;
    int length = 0, capacity = DEFAULT_BUFFER_SIZE;

    // Dynamically allocate memory for the array
    if ((array = (int *)malloc(capacity * sizeof(int))) == NULL) {
        return -1; // Memory allocation failed
    }

    while (fgets(line, MAX_LINE_LENGTH, stdin)) {
        int num = atoi(line);
        if ((allowNegative && num < 0) || (!allowNegative && num >= 0)) {
            if (length == capacity) {
                // Double the array size to accommodate more elements
                capacity *= 2;
                if ((array = realloc(array, capacity * sizeof(int))) == NULL) {
                    free(array);
                    return -1; // Memory reallocation failed
                }
            }
            array[length++] = num;

            if (length >= connectionLimit) {
                break; // Stop processing when the limit is reached
            }
        }
    }

    sortArray(array, length, "ascending", 0); // Sort the array in ascending order without duplicates

    printSmallest(array, length); // Print the smallest number in the array

    free(array); // Free allocated memory

    return 0; // Success
}

