Transaction* generateTransactions(int size, unsigned int seed, long ts_min, long ts_max, int id_min, int id_max) {
    srand(seed);
    Transaction* transactions = (Transaction*)malloc(size * sizeof(Transaction));

    if (transactions == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        transactions[i].timestamp = (rand() % (ts_max - ts_min + 1)) + ts_min;
        transactions[i].transactionID = (rand() % (id_max - id_min + 1)) + id_min;
        transactions[i].amount = ((double)rand()) / RAND_MAX; // Uniform distribution between 0 and 1
    }

    return transactions;
}

void freeTransactions(Transaction* transactions, int size) {
    free(transactions);
}

int main() {
    unsigned int seed = time(NULL);
    long ts_min = 1609459200L; // Example timestamp for January 1, 2021
    long ts_max = 1672531199L; // Example timestamp for December 31, 2022
    int id_min = 100;
    int id_max = 999;

    int size = 10; // Number of transactions
    Transaction* transactions = generateTransactions(size, seed, ts_min, ts_max, id_min, id_max);

    if (transactions != NULL) {
        for (int i = 0; i < size; i++) {
            printf("Transaction %d: Timestamp=%ld, ID=%d, Amount=%.2f\n", 
                   i + 1, transactions[i].timestamp, transactions[i].transactionID, transactions[i].amount);
        }
        freeTransactions(transactions, size);
    }

    return 0;
}
