        float num;
        sscanf(line, "%f", &num);

        if (!include_negatives && num < 0) continue;

        bool is_duplicate = false;
        for (size_t i = 0; i < array->count; i++) {
            if (array->data[i] == num) {
                is_duplicate = true;
                break;
            }
        }

        if (!ignore_duplicates || !is_duplicate) {
            array->data[array->count++] = num;
        }
    }

    fclose(file);
    return array;
}

