import java.io.BufferedReader;
import java.io.File;
import java.io.InputStreamReader;
import java.util.concurrent.TimeUnit;

public class CommandExecutor {

    private static final String CONFIG_FILE_PATH = "/path/to/config/file";
    private static final String BACKUP_DIR = "/path/to/backup/directory";

    public static void main(String[] args) {
        File configFile = new File(CONFIG_FILE_PATH);
        File backupDir = new File(BACKUP_DIR);

        if (configFile.exists()) {
            try {
                moveConfigToBackup(configFile, backupDir);
            } catch (Exception e) {
                System.err.println("Error moving config file to backup: " + e.getMessage());
            }
        }

        try {
            executeCommand("your_command_here");
        } catch (Exception e) {
            System.err.println("Error executing command: " + e.getMessage());
        }
    }

    private static void moveConfigToBackup(File configFile, File backupDir) throws Exception {
        // Ensure the backup directory exists
        if (!backupDir.exists()) {
            backupDir.mkdirs();
        }

        // Create a backup file name with timestamp
        String backupFileName = "config_backup_" + System.currentTimeMillis() + ".txt";
        File backupFile = new File(backupDir, backupFileName);

        // Rename the original config file to the backup location
        if (!configFile.renameTo(backupFile)) {
            throw new Exception("Failed to move config file to backup");
        }

        System.out.println("Config file moved to: " + backupFile.getAbsolutePath());
    }

    private static void executeCommand(String command) throws Exception {
        long startTime = System.nanoTime();

        Process process = Runtime.getRuntime().exec(command, null, new File("/path/to/command/directory"));
        BufferedReader outputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

        String line;
        while ((line = outputReader.readLine()) != null) {
            System.out.println("Output: " + line);
        }
        while ((line = errorReader.readLine()) != null) {
            System.err.println("Error: " + line);
        }

        int exitCode = process.waitFor();
        long endTime = System.nanoTime();

        System.out.println("Command executed with exit code: " + exitCode);
        System.out.println("Execution time: " + TimeUnit.NANOSECONDS.toMillis(endTime - startTime) + " ms");
    }
}

