unsigned long xorshift128plus(unsigned long *state) {
    unsigned long x = state[0];
    unsigned long y = state[1];
    unsigned long result = x + y;

    x ^= y; 
    y = (y << 24) | (y >> 8);  
    state[0] = x ^ (x << 9);
    state[1] = y ^ (y >> 5);

    return result;
}

int processAndInitializeData(long *offsets, int *keys, record **records, unsigned long prngSeed) {
    // Validate input parameters
    if (!offsets || !keys || !records || prngSeed == 0) {
        return -1; // Invalid parameters
    }

    size_t length = sizeof(offsets) / sizeof(offsets[0]); // Assuming offsets is non-empty

    // Allocate memory for records array
    *records = (record *)malloc(length * sizeof(record));
    if (!*records) {
        return -2; // Memory allocation failed
    }

    // Initialize PRNG state
    unsigned long prngState[] = {prngSeed, 0};

    // Populate records with random values using XORShift128+
    for (size_t i = 0; i < length; ++i) {
        (*records)[i].value = xorshift128plus(prngState);
    }

    return 0; // Success
}

void findAndPrintLargest(record *records, size_t length) {
    if (!records || length == 0) {
        printf("No records available.\n");
        return;
    }

    clock_t start = clock();
    int largest = records[0].value;
    for (size_t i = 1; i < length; ++i) {
        if (records[i].value > largest) {
            largest = records[i].value;
        }
    }
    clock_t end = clock();

    printf("Largest value: %d\n", largest);
    printf("Time taken to find largest: %f seconds\n", ((double)(end - start)) / CLOCKS_PER_SEC);
}

int main() {
