    if (result != 0) {
        printf("Initialization failed with code: %d\n", result);
        return 1;
    }

    findAndPrintLargest(records, sizeof(offsets) / sizeof(offsets[0]));

    // Clean up allocated memory
    free(records);

    return 0;
}
