#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

// Define record structure
typedef struct Record {
    int value;
} Record;

// Define linked list node
typedef struct Node {
    Record rec;
    struct Node* next;
} Node;

// Define PRNG state
uint64_t prng_state = 0;

// PRNG function using SplitMix64 algorithm
uint64_t splitmix64(uint64_t *state) {
    uint64_t z = (*state += UINT64_C(0x9E3779B97F4A7C15));
    z = (z ^ (z >> 30)) * UINT64_C(0xBF58476D1CE4E5B9);
    z = (z ^ (z >> 27)) * UINT64_C(0x94D049BB133111EB);
    return z ^ (z >> 31);
}

// Initialize PRNG with an external seed
void init_prng(uint64_t seed) {
    prng_state = seed;
}

// Generate pseudo-random number within a specified range
int prng_range(int min, int max) {
    uint64_t rand_val = splitmix64(&prng_state);
    return (int)((rand_val % (max - min + 1)) + min);
}

// Function to dynamically allocate memory and initialize arrays/linked list
int allocate_and_initialize_arrays(long* offsets, int* keys, Record** records, Node** head) {
    // Validate input parameters and handle memory allocation failures
    if (!offsets || !keys || !records || !head) return -1;

    *head = NULL;
    for (int i = 0; i < 3; i++) { // Assuming a fixed size for demonstration
        offsets[i] = prng_range(1, 100); // Example offset range
        keys[i] = prng_range(1, 100);   // Example key range

        // Allocate memory for records and linked list nodes
        *records = (Record*)malloc(sizeof(Record) * 3);
        if (!*records) return -1;

        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            free(*records);
            return -1;
        }

        // Initialize record and linked list node
        (*records)[i].value = prng_range(0, 100); // Example value range for records

        new_node->rec = (*records)[i];
        new_node->next = *head;
        *head = new_node;
    }
    return 0;
}

// Function to insert a record by key
void insert_record(Node** head, Record rec) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    new_node->rec = rec;
    new_node->next = *head;
    *head = new_node;
}

// Function to delete a record by key
void delete_record(Node** head, int key) {
    Node* current = *head;
    Node* previous = NULL;

    while (current != NULL && current->rec.value != key) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return; // Record not found

    if (previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
}

// Function to search for a record by key
Record* search_record(Node** head, int key) {
    Node* current = *head;

    while (current != NULL) {
        if (current->rec.value == key) {
            return &current->rec;
        }
        current = current->next;
    }

    return NULL; // Record not found
}

// Function to free all allocated memory
void free_memory(Node** head, Record** records, long* offsets, int* keys) {
    Node* current = *head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    free(*records);
    // Free offsets and keys if dynamically allocated
}

// Thread-safe function to ensure data integrity in multi-threaded applications
void thread_safe_function(Node** head, Record rec, int key) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&mutex);
    insert_record(head, rec);
    delete_record(head, key);
    Record* found_rec = search_record(head, key);
    if (found_rec != NULL) printf("Found record with value: %d\n", found_rec->value);
    pthread_mutex_unlock(&mutex);

    // Clean up mutex after operations
    pthread_mutex_destroy(&mutex);
}

int main() {
    long offsets[3];
    int keys[3];
    Record* records;
    Node* head;

    // Initialize PRNG with an external seed (e.g., using time or other sources)
    init_prng(time(NULL));

    if (allocate_and_initialize_arrays(offsets, keys, &records, &head) != 0) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    // Example usage of thread-safe function
    Record new_record = { prng_range(0, 100) };
    thread_safe_function(&head, new_record, keys[1]);

    free_memory(&head, &records, offsets, keys);
    return 0;
}
```

This code snippet demonstrates a basic implementation of the described functionality. It includes memory allocation for arrays and linked list nodes, initialization with pseudo-random numbers, and operations for inserting, deleting, and searching records. The code also handles memory freeing and ensures thread safety using mutexes. Note that this is a simplified version and may need to be adapted to your specific requirements, including handling external data sources for seeding the PRNG and assessing the impact of different PRNG algorithms on performance and randomness quality.']

