#define MAX_PAYLOAD_SIZE 1024

typedef struct {
    int timestamp;
    char status_flag;
    unsigned char payload[MAX_PAYLOAD_SIZE];
} packet;

int create_packets(long *offsets, int *keys, unsigned char **data_bytes, packet **packets, int num_packets) {
    if (num_packets <= 0 || offsets == NULL || keys == NULL || data_bytes == NULL || packets == NULL) {
        return -1; // Invalid input
    }

    *packets = (packet *)malloc(num_packets * sizeof(packet));
    if (*packets == NULL) {
        return -2; // Memory allocation failed
    }

    unsigned char *temp_payload = (unsigned char *)malloc(MAX_PAYLOAD_SIZE * num_packets);
    if (temp_payload == NULL) {
        free(*packets);
        return -2; // Memory allocation failed
    }

    srand(time(NULL)); // Seed the PRNG

    for (int i = 0; i < num_packets; ++i) {
        (*packets)[i].timestamp = rand();
        (*packets)[i].status_flag = (rand() % 2 == 0) ? 'A' : 'B';

        int payload_size = rand() % MAX_PAYLOAD_SIZE;
        for (int j = 0; j < payload_size; ++j) {
            temp_payload[i * MAX_PAYLOAD_SIZE + j] = rand();
        }
        (*packets)[i].payload = &temp_payload[i * MAX_PAYLOAD_SIZE];
    }

    *offsets = (long *)malloc(num_packets * sizeof(long));
    if (*offsets == NULL) {
        free(*packets);
        free(temp_payload);
        return -2; // Memory allocation failed
    }

    for (int i = 0; i < num_packets; ++i) {
        offsets[i] = i;
    }

    *keys = (int *)malloc(num_packets * sizeof(int));
    if (*keys == NULL) {
        free(*packets);
        free(temp_payload);
        free(offsets);
        return -2; // Memory allocation failed
    }

    for (int i = 0; i < num_packets; ++i) {
        keys[i] = rand() % num_packets;
    }

    *data_bytes = temp_payload;

    return 0; // Success
}
