    if (!src) {
        perror("Error opening source file");
        return -1;
    }

    long offset_values[MAX_RECORDS];
    record records[MAX_RECORDS];

    for (int i = 0; i < MAX_RECORDS; i++) {
        size_t bytes_read = fread(&offset_values[i], sizeof(long), 1, src);
        if (bytes_read != 1) {
            perror("Error reading offset value");
            fclose(src);
            return -1;
        }
        records[i].value = custom_prng(key_range[0], key_range[1]);
