    fclose(src);

    char pdf_cmd[256];
    snprintf(pdf_cmd, sizeof(pdf_cmd), "convert %s %s", src_file, tgt_file);
    int cmd_result = system(pdf_cmd);
    if (cmd_result != 0) {
        perror("Error converting to PDF");
        return -1;
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        printf("Record %d: Value = %d\n", i, records[i].value);
    }

    return 0;
