#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>

typedef enum {
    ENCRYPT,
    DECRYPT,
    SIGN,
    VERIFY
} CipherOperation;

EVP_CIPHER_CTX* create_cipher_context(const char* operation, const char* cipher_name, const unsigned char* key, size_t key_length, const unsigned char* iv) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return NULL;
    }

    int encrypt_flag = (operation == ENCRYPT);
    const EVP_CIPHER* cipher = EVP_get_cipherbyname(cipher_name);
    if (!cipher) {
        fprintf(stderr, "Unknown cipher name: %s\n", cipher_name);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (!EVP_Init_ex(ctx, cipher, NULL, key, iv, encrypt_flag)) {
        fprintf(stderr, "Failed to initialize cipher context\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

int perform_cipher_operation(EVP_CIPHER_CTX* ctx, const unsigned char* input, size_t input_length, unsigned char* output) {
    int output_length = 0;
    if (!EVP_EncryptUpdate(ctx, output, &output_length, input, input_length)) {
        fprintf(stderr, "Failed to encrypt data\n");
        return -1;
    }

    int final_output_length = 0;
    if (!EVP_EncryptFinal_ex(ctx, output + output_length, &final_output_length)) {
        fprintf(stderr, "Failed to finalize encryption\n");
        return -1;
    }

    return output_length + final_output_length;
}

int main(int argc, char* argv[]) {
    if (argc < 5) {
        fprintf(stderr, "Usage: %s operation cipher_name key iv\n", argv[0]);
        return 1;
    }

    CipherOperation operation = ENCRYPT;
    if (strcmp(argv[1], "decrypt") == 0) {
        operation = DECRYPT;
    } else if (strcmp(argv[1], "sign") == 0) {
        operation = SIGN;
    } else if (strcmp(argv[1], "verify") == 0) {
        operation = VERIFY;
    }

    const char* cipher_name = argv[2];
    unsigned char key[32]; // Example: AES-256
    size_t key_length = 32;
    unsigned char iv[16]; // Example: AES block size

    if (strlen(argv[3]) != key_length * 2 || strlen(argv[4]) != sizeof(iv) * 2) {
        fprintf(stderr, "Invalid key or IV length\n");
        return 1;
    }

    for (size_t i = 0; i < key_length * 2; i += 2) {
        sscanf(&argv[3][i], "%2hhx", &key[i / 2]);
    }
    for (size_t i = 0; i < sizeof(iv) * 2; i += 2) {
        sscanf(&argv[4][i], "%2hhx", &iv[i / 2]);
    }

    EVP_CIPHER_CTX* ctx = create_cipher_context(operation, cipher_name, key, key_length, iv);
    if (!ctx) {
        return 1;
    }

    unsigned char input[] = "Hello, OpenSSL!";
    size_t input_length = strlen(input);
    unsigned char output[128];

    int result_length = perform_cipher_operation(ctx, (unsigned char*)input, input_length, output);
    if (result_length < 0) {
        EVP_CIPHER_CTX_free(ctx);
        return 1;
    }

    printf("Cipher operation result: %.*s\n", result_length, output);

    EVP_CIPHER_CTX_free(ctx);
    return 0;
}
