#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define METADATA_SIZE sizeof(metadata)
#define RECORD_SIZE sizeof(record)

typedef struct {
    int value;
    char *buffer;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    size_t size;
} metadata;

void custom_prng_init(void) {
    unsigned seed = time(NULL) ^ ((unsigned)rand() << 16);
    srand(seed);
}

long generate_offset(void) {
    // Simple pseudo-random offset generator
    return (long)(rand() * rand());
}

int generate_key(void) {
    // Simple pseudo-random key generator
    return rand();
}

record* create_record(int value, size_t buffer_size) {
    record *rec = malloc(RECORD_SIZE);
    if (!rec) return NULL;

    rec->value = value;
    rec->buffer = malloc(buffer_size);
    if (!rec->buffer) {
        free(rec);
        return NULL;
    }

    for (size_t i = 0; i < buffer_size; ++i) {
        rec->buffer[i] = rand() & 0xFF;
    }

    return rec;
}

metadata* init_metadata(size_t size, int min_buffer_size, int max_buffer_size) {
    metadata *meta = malloc(METADATA_SIZE);
    if (!meta) return NULL;

    meta->size = size;
    meta->offsets = malloc(sizeof(long) * size);
    if (!meta->offsets) {
        free(meta);
        return NULL;
    }

    meta->keys = malloc(sizeof(int) * size);
    if (!meta->keys) {
        free(meta->offsets);
        free(meta);
        return NULL;
    }

    meta->records = malloc(sizeof(record*) * size);
    if (!meta->records) {
        free(meta->keys);
        free(meta->offsets);
        free(meta);
        return NULL;
    }

    custom_prng_init();

    for (size_t i = 0; i < size; ++i) {
        meta->offsets[i] = generate_offset();
        meta->keys[i] = generate_key();
        size_t buffer_size = min_buffer_size + rand() % (max_buffer_size - min_buffer_size);
        meta->records[i] = create_record(meta->keys[i], buffer_size);
        if (!meta->records[i]) {
            for (size_t j = 0; j < i; ++j) {
                free(meta->records[j]->buffer);
                free(meta->records[j]);
            }
            free(meta->records);
            free(meta->keys);
            free(meta->offsets);
            free(meta);
            return NULL;
        }
    }

    return meta;
}

void free_metadata(metadata *meta) {
    if (meta) {
        for (size_t i = 0; i < meta->size; ++i) {
            if (meta->records[i]) {
                free(meta->records[i]->buffer);
                free(meta->records[i]);
            }
        }
        free(meta->records);
        free(meta->keys);
        free(meta->offsets);
        free(meta);
    }
}

int main() {
    size_t dataset_size = 1000;
    metadata *data = init_metadata(dataset_size, 32, 64);

    if (data) {
        // Process the data
        printf("Metadata initialized successfully.\n");
        free_metadata(data);
    } else {
        printf("Failed to initialize metadata.\n");
    }

    return 0;
}
