#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a structure for log entry
typedef struct LogEntry {
    time_t timestamp;
    char* message;
    struct LogEntry* next;
} LogEntry;

// Function to create a new log entry
LogEntry* create_log_entry(time_t ts, const char* msg) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!entry) return NULL;
    entry->timestamp = ts;
    entry->message = strdup(msg);
    entry->next = NULL;
    return entry;
}

// Function to add a log entry to the linked list
void add_log_entry(LogEntry** head, time_t ts, const char* msg) {
    LogEntry* new_entry = create_log_entry(ts, msg);
    if (!new_entry) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    if (*head == NULL) {
        *head = new_entry;
    } else {
        LogEntry* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_entry;
    }
}

// Helper function to calculate and display the average time interval
void print_average_interval(LogEntry* head) {
    if (head == NULL || head->next == NULL) {
        printf("Not enough entries for an average interval.\n");
        return;
    }
    time_t total_seconds = 0;
    LogEntry* current = head;
    while (current && current->next != NULL) {
        time_t diff = difftime(current->next->timestamp, current->timestamp);
        total_seconds += diff;
        current = current->next;
    }
    printf("Average interval between events: %.2f seconds\n", (double)total_seconds / (current - head));
}

// Function to process the log file
void process_log_file(const char* filename, int max_entries, time_t cutoff_timestamp, int exclude_older, int ignore_duplicates) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    LogEntry* head = NULL;
    char buffer[1024];
    int entry_count = 0;
    int duplicate_count = 0;

    while (fgets(buffer, sizeof(buffer), file)) {
        // Simulate parsing logic
        time_t ts;
        char msg[1024];
        if (sscanf(buffer, "%ld %s", &ts, msg) != 2) {
            fprintf(stderr, "Malformed line: %s\n", buffer);
            continue;
        }

        // Filter based on timestamp
        if ((exclude_older && ts < cutoff_timestamp) || (!exclude_older && ts > cutoff_timestamp)) {
            continue;
        }

        // Check for duplicates and ignore if required
        LogEntry* current = head;
        while (current != NULL) {
            if (strcmp(current->message, msg) == 0) {
                duplicate_count++;
                if (ignore_duplicates) break;
            }
            current = current->next;
        }
        if (current != NULL) continue;

        // Add to list and increment entry count
        add_log_entry(&head, ts, msg);
        entry_count++;
        if (entry_count >= max_entries) {
            fprintf(stderr, "Maximum entries reached. Processing stopped.\n");
            break;
        }
    }

    fclose(file);

    // Display results
    printf("Entries processed: %d\n", entry_count);
    printf("Duplicates ignored: %d\n", duplicate_count);
    print_average_interval(head);

    // Free allocated memory
    LogEntry* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp->message);
        free(temp);
    }
}

int main() {
    process_log_file("events.log", 100, time(NULL), 1, 1);
    return 0;
}
