#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    short value;
    int index;
    char* buffer;
} record;

unsigned long hash(char* str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash;
}

record* create_records(int N, int seed, int max_buffer_len) {
    record* records = (record*)malloc(N * sizeof(record));
    if (!records)
        return NULL;

    for (int i = 0; i < N; ++i) {
        records[i].value = 0;
        records[i].index = rand_r(&seed);
        records[i].buffer = (char*)malloc(max_buffer_len * sizeof(char));
        if (!records[i].buffer) {
            // Free previously allocated memory on error
            for (int j = 0; j < i; ++j)
                free(records[j].buffer);
            free(records);
            return NULL;
        }
        for (int j = 0; j < max_buffer_len - 1; ++j)
            records[i].buffer[j] = 'A' + rand_r(&seed) % 26;
        records[i].buffer[max_buffer_len - 1] = '\0';
    }

    return records;
}

void free_records(record* records, int N) {
    for (int i = 0; i < N; ++i)
        free(records[i].buffer);
    free(records);
}

void process_records(record* records, int N, unsigned long (*hash_func)(char*)) {
    srand(time(NULL));
    int seed = rand();

    for (int i = 0; i < N; ++i) {
        records[i].value = records[i].index + hash_func(records[i].buffer);
    }
}

void* thread_function(void* arg) {
    // Example function that could be used with pthreads
    record** records_ptr = (record**)arg;
    record* records = *records_ptr;

    for (int i = 0; i < 1000; ++i)
        process_records(records, 100, hash);

    return NULL;
}

// Example usage:
int main() {
    const int N = 1000;
    record* records = create_records(N, time(NULL), 128);
    if (records) {
        pthread_t threads[4];
        for (int i = 0; i < 4; ++i)
