}

fn generateAndProcessRecords(seed: i64, recordCount: u32, url: String, enableSecureHttp: bool, maxRetryAttempts: u32) -> Result<(), i32> {
    let mut rng = thread_rng();
    rng.seed(seed);

    let records: Vec<Record> = (0..recordCount).map(|_| Record { value: rng.gen_range(-1000..=1000) }).collect();

