    println!("Average Value: {}", avg_value);

    let mut channel = establish_channel()?;

    for record in records {
        send_record(&mut client, &record)?;
        receive_and_process_response(&mut channel)?;
    }

    shutdown_connection(&mut client, &mut channel)?;

    Ok(())
}

fn create_client(url: &str, enableSecureHttp: bool) -> Result<TcpStream, i32> {
    let mut stream = TcpStream::connect(url).map_err(|_| -1)?;
    if !enableSecureHttp {
        unsafe {
            stream.set_read_timeout(Some(Duration::from_secs(0)));
            stream.set_write_timeout(Some(Duration::from_secs(0)));
        }
    }
    Ok(stream)
}

fn calculate_average(numbers: &Vec<i32>) -> f64 {
    numbers.iter().sum::<i32>() as f64 / numbers.len() as f64
}

