    Ok(JavaChannel)
}

fn shutdown_connection(client: &mut TcpStream, channel: &mut JavaChannel) -> Result<(), i32> {
    client.shutdown(Shutdown::Both).map_err(|_| -1)?;
    channel.close().map_err(|_| -1)?;
    Ok(())
}
