    if (count == 0 || min_timestamp >= max_timestamp) {
        return -1; // Invalid input
    }

    offsets = malloc(count * sizeof(long));
    keys = malloc(count * sizeof(int));
    records = malloc(count * sizeof(record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return -2; // Memory allocation failed
