    for (size_t i = 0; i < count; ++i) {
        offsets[i] = rand() % count; // Example offset logic
        keys[i] = rand() % 100; // Example key logic

        records[i].timestamp = min_timestamp + ((long long)(max_timestamp - min_timestamp) * rand()) / RAND_MAX;
        records[i].key = keys[i];
    }

    return 0; // Success
}

