#include <string.h>
#include <time.h>

#define MAX_LOG_ENTRIES 1000
#define MIN_EVENT_ID 100
#define MAX_EVENT_ID 999

typedef struct {
    time_t timestamp;
    int event_id;
    char description[256];
} LogEntry;

typedef struct {
    LogEntry *entries;
    size_t count;
    size_t capacity;
} LogModule;

LogModule* log_init() {
    LogModule *module = (LogModule*)malloc(sizeof(LogModule));
    if (!module) return NULL;
    module->entries = (LogEntry*)malloc(MAX_LOG_ENTRIES * sizeof(LogEntry));
    if (!module->entries) {
        free(module);
        return NULL;
    }
    module->count = 0;
    module->capacity = MAX_LOG_ENTRIES;
    srand(time(NULL)); // Seed the PRNG
    return module;
}

void log_free(LogModule *module) {
    if (module->entries) free(module->entries);
    free(module);
}

int log_add_entry(LogModule *module, char *description) {
    if (module->count >= module->capacity) {
        LogEntry *new_entries = (LogEntry*)realloc(module->entries, module->capacity * 2 * sizeof(LogEntry));
        if (!new_entries) return -1;
        module->entries = new_entries;
        module->capacity *= 2;
    }
    module->entries[module->count].timestamp = time(NULL);
    module->entries[module->count].event_id = MIN_EVENT_ID + rand() % (MAX_EVENT_ID - MIN_EVENT_ID + 1);
    snprintf(module->entries[module->count].description, sizeof(module->entries[module->count].description), "%s", description);
    module->count++;
    return 0;
}

void log_print_all(LogModule *module) {
    for (size_t i = 0; i < module->count; i++) {
        printf("Timestamp: %ld, Event ID: %d, Description: %s\n", 
               (long)module->entries[i].timestamp, module->entries[i].event_id, module->entries[i].description);
    }
}

int main() {
    LogModule *log_module = log_init();
    if (!log_module) {
        fprintf(stderr, "Failed to initialize log module.\n");
        return 1;
    }

    for (int i = 0; i < 5; i++) {
        char description[256];
        snprintf(description, sizeof(description), "Log entry %d", i);
        if (log_add_entry(log_module, description) != 0) {
            fprintf(stderr, "Failed to add log entry.\n");
        }
    }

    log_print_all(log_module);

    log_free(log_module);
    return 0;
}
