#include <stdlib.h>
#include <stdio.h>

// Define the structure for each record
typedef struct {
    int key;
    long offset;
} Record;

// Custom PRNG state
typedef struct {
    unsigned long seed;
} PRNGState;

// Initialize the PRNG with a seed
void initPRNG(PRNGState *state, unsigned long seed) {
    state->seed = seed;
}

// Generate a random number using a custom non-cryptographic PRNG
unsigned long generateRandom(PRNGState *state) {
    state->seed = state->seed * 1664525 + 1013904223; // LCG parameters for uniform distribution
    return state->seed;
}

// Memory-efficient data structure using linked list
typedef struct Node {
    Record data;
    struct Node *next;
} Node;

// Function to insert a new record into the data structure
void insertRecord(Node **head, PRNGState *prng) {
    Node *newNode = (Node *)malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Memory allocation failed\n");
        return; // Handle memory allocation failure gracefully
    }

    newNode->data.key = generateRandom(prng);
    newNode->data.offset = generateRandom(prng);
    newNode->next = *head;
    *head = newNode;
}

// Function to update a record in the data structure
void updateRecord(Node **head, int key, long newOffset) {
    Node *current = *head;
    while (current != NULL) {
        if (current->data.key == key) {
            current->data.offset = newOffset;
            return; // Record updated successfully
        }
        current = current->next;
    }
    printf("Record with key %d not found\n", key);
}

// Function to verify the integrity of the data structure
void verifyDataStructure(Node *head) {
    Node *current = head;
    while (current != NULL) {
        // Perform checks for consistency or corruption
        if (current->data.key < 0 || current->data.offset < 0) {
            printf("Corruption detected in record with key %d\n", current->data.key);
        }
        current = current->next;
    }
}

// Function to free the memory allocated for the data structure
void freeDataStructure(Node **head) {
    Node *current = *head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }
    *head = NULL;
}
```

This code provides a basic implementation of the required functionality. It includes a custom PRNG, a linked list data structure for managing records, and functions to insert, update, verify, and free memory. The solution is designed with resource efficiency and concurrent access in mind, ensuring that it can handle frequent updates and scale gracefully under increasing load.']

