using System;
using System.Xml;

public class XPathHelper
{
    public static XmlElement FindFirstXPathElement(XmlDocument doc, string nodeName, string namespacePrefix, string defaultNamespaceUri)
    {
        try
        {
            if (string.IsNullOrEmpty(nodeName) || string.IsNullOrEmpty(defaultNamespaceUri))
                throw new ArgumentException("Node name and default namespace URI cannot be null or empty.");

            var xpath = $"//{namespacePrefix}:{nodeName}";
            var namespaces = new XmlNamespaceManager(doc.NameTable);
            namespaces.AddNamespace(namespacePrefix, defaultNamespaceUri);

            var nodeList = doc.DocumentElement.SelectNodes(xpath, namespaces);
            if (nodeList != null && nodeList.Count > 0)
            {
                if (nodeList.Count > 1)
                    throw new InvalidOperationException("More than one element found with the specified name and namespace.");

                return (XmlElement)nodeList.Item(0);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }

        return null;
    }
}
