// Define structures
typedef struct {
    long offset;
} OffsetStruct;

typedef struct {
    int key;
} KeyStruct;

typedef struct {
    int value;
} Record;

// Function prototypes
OffsetStruct* allocate_offset_struct();
KeyStruct* allocate_key_struct(int value);
Record* allocate_record_array(int size);
void initialize_records(Record* records, int size, int range_start, int range_end);
int process_network_data(char* input, int limit, bool allow_negative);
void print_smallest_integer(Record* records, int size);
void sort_records(Record* records, int size, bool ascending);

// Main function
int main() {
    // Example usage
    OffsetStruct *offset = allocate_offset_struct();
    KeyStruct *key = allocate_key_struct(42);
    Record *records = allocate_record_array(10);
    initialize_records(records, 10, -50, 50);
    process_network_data("123\n-456\n789", 15, true);
    print_smallest_integer(records, 10);
    sort_records(records, 10, true);

    // Free allocated memory
    free(offset);
    free(key);
    free(records);

    return 0;
}

// Function implementations
OffsetStruct* allocate_offset_struct() {
    return (OffsetStruct*)malloc(sizeof(OffsetStruct));
}

KeyStruct* allocate_key_struct(int value) {
    KeyStruct *key = (KeyStruct*)malloc(sizeof(KeyStruct));
    key->key = value;
    return key;
}

Record* allocate_record_array(int size) {
    return (Record*)calloc(size, sizeof(Record));
}

void initialize_records(Record* records, int size, int range_start, int range_end) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % (range_end - range_start + 1) + range_start;
    }
}

int process_network_data(char* input, int limit, bool allow_negative) {
    char line[256];
    int count = 0;

    while (fgets(line, sizeof(line), stdin)) {
        if (count >= limit) {
            fprintf(stderr, "Buffer overflow detected. Dropping data.\n");
            continue;
        }

        // Parse and validate input
        char *endptr;
        long value = strtol(line, &endptr, 10);
        if (*endptr != '\n' || (value == 0 && endptr == line) || (!allow_negative && value < 0)) {
            fprintf(stderr, "Malformed data detected. Ignoring.\n");
            continue;
        }

        // Process valid data
        printf("Processed: %ld\n", value);
        count++;
    }

    return count;
}

void print_smallest_integer(Record* records, int size) {
    if (size == 0) {
        printf("No data to process.\n");
        return;
    }

    qsort(records, size, sizeof(Record), (int (*)(const void *, const void *))strcmp);
    printf("Smallest integer: %d\n", records[0].value);
}

void sort_records(Record* records, int size, bool ascending) {
    if (size == 0) {
        return;
    }

    qsort(records, size, sizeof(Record), (int (*)(const void *, const void *))strcmp);
    if (!ascending) {
        for (int i = 0; i < size / 2; i++) {
            Record temp = records[i];
            records[i] = records[size - i - 1];
            records[size - i - 1] = temp;
        }
    }
}
