    private static Dictionary<int, Resource> resources = new Dictionary<int, Resource>();
    private static int nextId = 1;

    [HttpPut("{id}")]
    public IActionResult UpdateResource(int id, [FromBody] Resource updatedResource)
    {
        if (!resources.ContainsKey(id))
        {
            return NotFound();
        }

        if (!ModelState.IsValid || !IsValidResource(updatedResource))
        {
            return BadRequest(ModelState);
        }

        resources[id] = new Resource
        {
            Id = id,
            Name = updatedResource.Name,
            Description = updatedResource.Description
        };

        return Ok(resources[id]);
    }

    [HttpDelete("{id}")]
    public IActionResult DeleteResource(int id)
    {
        if (!resources.ContainsKey(id))
        {
            return NotFound();
        }

        resources[id] = new Resource { Id = id, Name = "Deleted", Description = "This resource has been deleted." };

        return NoContent();
    }

    private bool IsValidResource(Resource resource)
    {
        // Implement validation logic here
        return !string.IsNullOrEmpty(resource.Name) && !string.IsNullOrEmpty(resource.Description);
    }
}

public class Resource
{
    public int Id { get; set; }
    public string Name { get; set; }
    public string Description { get; set; }
