#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define TABLE_SIZE 1024

typedef struct record {
    int key;
    long offset;
    char *metadata;
    struct record *next;
} Record;

typedef struct hash_table {
    Record *buckets[TABLE_SIZE];
    pthread_mutex_t mutex;
} HashTable;

typedef struct session_context {
    HashTable *table;
    pthread_mutex_t alloc_lock;
    size_t allocated_memory;
} SessionContext;

HashTable* create_hash_table() {
    HashTable *table = malloc(sizeof(HashTable));
    pthread_mutex_init(&table->mutex, NULL);
    for (int i = 0; i < TABLE_SIZE; i++) {
        table->buckets[i] = NULL;
    }
    return table;
}

SessionContext* create_session_context() {
    SessionContext *ctx = malloc(sizeof(SessionContext));
    ctx->table = create_hash_table();
    pthread_mutex_init(&ctx->alloc_lock, NULL);
    ctx->allocated_memory = 0;
    return ctx;
}

void destroy_record(Record *record) {
    free(record->metadata);
    free(record);
}

void destroy_session_context(SessionContext *ctx) {
    pthread_mutex_lock(&ctx->table->mutex);
    for (int i = 0; i < TABLE_SIZE; i++) {
        Record *current = ctx->table->buckets[i];
        while (current != NULL) {
            Record *next = current->next;
            destroy_record(current);
            current = next;
        }
    }
    pthread_mutex_unlock(&ctx->table->mutex);
    pthread_mutex_destroy(&ctx->table->mutex);
    free(ctx->table);
    pthread_mutex_lock(&ctx->alloc_lock);
    ctx->allocated_memory = 0;
    pthread_mutex_unlock(&ctx->alloc_lock);
    pthread_mutex_destroy(&ctx->alloc_lock);
    free(ctx);
}

Record* create_record(int key, long offset, char *metadata) {
    Record *record = malloc(sizeof(Record));
    record->key = key;
    record->offset = offset;
    record->metadata = strdup(metadata);
    record->next = NULL;
    return record;
}

void add_record(SessionContext *ctx, int key, long offset, char *metadata) {
    pthread_mutex_lock(&ctx->table->mutex);
    Record **bucket = &ctx->table->buckets[key % TABLE_SIZE];
    while (*bucket != NULL && (*bucket)->key != key) {
        bucket = &(*bucket)->next;
    }
    if (*bucket == NULL) {
        *bucket = create_record(key, offset, metadata);
    } else {
        (*bucket)->offset = offset;
        free((*bucket)->metadata);
        (*bucket)->metadata = strdup(metadata);
    }
    pthread_mutex_unlock(&ctx->table->mutex);
}

void update_record(SessionContext *ctx, int key, long offset, char *metadata) {
    pthread_mutex_lock(&ctx->table->mutex);
    Record **bucket = &ctx->table->buckets[key % TABLE_SIZE];
    while (*bucket != NULL && (*bucket)->key != key) {
        bucket = &(*bucket)->next;
    }
    if (*bucket != NULL) {
        (*bucket)->offset = offset;
        free((*bucket)->metadata);
        (*bucket)->metadata = strdup(metadata);
    }
    pthread_mutex_unlock(&ctx->table->mutex);
}

void delete_record(SessionContext *ctx, int key) {
    pthread_mutex_lock(&ctx->table->mutex);
    Record **bucket = &ctx->table->buckets[key % TABLE_SIZE];
    while (*bucket != NULL && (*bucket)->key != key) {
        bucket = &(*bucket)->next;
    }
    if (*bucket != NULL) {
        Record *record_to_delete = *bucket;
        *bucket = record_to_delete->next;
        free(record_to_delete);
        pthread_mutex_unlock(&ctx->table->mutex);

        // Set environment variable
        char env_var[256];
        snprintf(env_var, sizeof(env_var), "DELETED_RECORD_PATH_%d", key);
        const char *current_path = getenv(env_var);
        if (current_path != NULL) {
            setenv(env_var, current_path, 1);
        } else {
            char new_dir[256];
            snprintf(new_dir, sizeof(new_dir), "/path/to/new/dir/%d", key);
            mkdir(new_dir, 0755);
            setenv(env_var, new_dir, 1);
        }
    } else {
        pthread_mutex_unlock(&ctx->table->mutex);
    }
}
