#include <string.h>

#define MAX_STRING_LENGTH 256
#define TERMINATION_STRING "END"

typedef void (*StringCallback)(const char*);

char** readStringsFromFile(FILE* file, StringCallback callback) {
    char buffer[MAX_STRING_LENGTH];
    char** strings = NULL;
    size_t capacity = 10;
    size_t count = 0;

    strings = (char**)malloc(capacity * sizeof(char*));
    if (strings == NULL) {
        return NULL;
    }

    while (fgets(buffer, MAX_STRING_LENGTH, file)) {
        buffer[strcspn(buffer, "\n")] = '\0'; // Remove newline character

        if (callback != NULL) {
            callback(buffer);
        }

        if (strcmp(buffer, TERMINATION_STRING) == 0) {
            break;
        }

        strings[count] = strdup(buffer);
        if (strings[count] == NULL) {
            for (size_t i = 0; i < count; ++i) {
                free(strings[i]);
            }
            free(strings);
            return NULL;
        }

        ++count;

        if (count >= capacity) {
            capacity *= 2;
            strings = realloc(strings, capacity * sizeof(char*));
            if (strings == NULL) {
                for (size_t i = 0; i < count; ++i) {
                    free(strings[i]);
                }
                return NULL;
            }
        }
    }

    // Resize array to fit exactly
    char** resizedStrings = realloc(strings, count * sizeof(char*));
    if (resizedStrings != NULL) {
        strings = resizedStrings;
    }

    return strings;
}

void logString(const char* str) {
    printf("Logging: %s\n", str);
}

int main() {
    FILE* file = fopen("strings.txt", "r");
    if (file == NULL) {
        perror("Failed to open file");
        return 1;
    }

    char** strings = readStringsFromFile(file, logString);
    if (strings != NULL) {
        for (size_t i = 0; strings[i] != NULL; ++i) {
            free(strings[i]);
        }
        free(strings);
    }

    fclose(file);
    return 0;
}
