struct AttackRecord {
    long offset;
    int key;
    struct {
        int value;
    } data;
};

class AttackManager {
private:
    std::vector<AttackRecord*> cache;
    std::priority_queue<long> cooldownQueue;
    std::mutex cacheMutex;
    std::condition_variable cv;
    size_t maxCacheSize;

public:
    AttackManager(size_t size) : maxCacheSize(size) {}

    ~AttackManager() {
        for (auto record : cache) {
            delete record;
        }
    }

    void selectAndExecuteAttack(int keyRangeStart, int keyRangeEnd) {
        std::lock_guard<std::mutex> lock(cacheMutex);

        // Remove expired cooldowns
        while (!cooldownQueue.empty() && cooldownQueue.top() < time(nullptr)) {
            cache.erase(findIf(cache.begin(), cache.end(), [this](const AttackRecord* record) { return record->offset == cooldownQueue.top(); }));
            cooldownQueue.pop();
        }

        // Select an attack if available or evict to make space
        if (cache.size() >= maxCacheSize) {
            delete cache.front();
            cache.erase(cache.begin());
        }

        // Generate a new attack record and add it to the cache
        AttackRecord* newAttack = new AttackRecord;
        newAttack->offset = time(nullptr);
        newAttack->key = rand() % (keyRangeEnd - keyRangeStart + 1) + keyRangeStart;
        newAttack->data.value = rand();
        cache.push_back(newAttack);
        cooldownQueue.push(time(nullptr) + 9);

        // Log the attack
        std::cout << "Attack executed at " << time(nullptr) << " with key: " << newAttack->key << std::endl;
    }
};
