    return ctx;
}

void init_crypto_context(CryptoContext *ctx, const unsigned char *key, const unsigned char *iv) {
    memcpy(ctx->key, key, 32);
    memcpy(ctx->iv, iv, 16);
}

void encrypt_data(CryptoContext *ctx, const unsigned char *in, unsigned char *out, int length) {
    EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv);
    EVP_EncryptUpdate(ctx->ctx, out, &length, in, strlen(in));
    EVP_EncryptFinal_ex(ctx->ctx, out + length, &length);
}

void decrypt_data(CryptoContext *ctx, const unsigned char *in, unsigned char *out, int length) {
    EVP_DecryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv);
    EVP_DecryptUpdate(ctx->ctx, out, &length, in, strlen(in));
    EVP_DecryptFinal_ex(ctx->ctx, out + length, &length);
}

void free_crypto_context(CryptoContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}
