public class ServiceManager {

    private ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);

    public void startService() {
        scheduler.scheduleAtFixedRate(() -> {
            // Perform service logic here
            System.out.println("Service started");
            try {
                Thread.sleep(500); // Simulate service operation
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
            System.out.println("Service stopped");
            sendMessageToMessagingSystem("Service terminated");
        }, 0, 10, TimeUnit.SECONDS);
    }

    private void sendMessageToMessagingSystem(String message) {
        // Send message to messaging system implementation here
        System.out.println("Message sent: " + message);
    }

    public void stopService() {
        scheduler.shutdownNow();
    }
}
