    for (int i = 0; i < count; ++i) {
        records[i].value = rand() % 1000 + 1;
    }
}

record* read_network_data(int *num_records, int connection_limit) {
    char buffer[256];
    record *records = (record *)malloc(sizeof(record) * MAX_RECORDS);
    if (!records) return NULL;

    *num_records = 0;
    while (*num_records < connection_limit && fgets(buffer, sizeof(buffer), stdin)) {
        records[*num_records].value = atoi(buffer);
        ++(*num_records);
    }

    // Resize array to actual number of records
    record *resized_records = (record *)realloc(records, (*num_records) * sizeof(record));
    if (!resized_records) {
        free(records);
        return NULL;
    }
    records = resized_records;

    return records;
}

void sort_records(record *records, int count, int ascending) {
    // Simple bubble sort for demonstration; replace with a more efficient algorithm
    for (int i = 0; i < count - 1; ++i) {
        for (int j = 0; j < count - i - 1; ++j) {
            if ((ascending && records[j].value > records[j + 1].value) ||
                (!ascending && records[j].value < records[j + 1].value)) {
                record temp = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp;
            }
        }
    }
}

