    for (size_t i = 0; i < numElements; ++i) {
        offsets[i] = i * 2; // Example offset initialization
        keys[i] = i + 1;   // Example key initialization

        unsigned char randomByte = generateRandomByte(prng);
        data[i] = (randomByte << 4) | (randomByte >> 4); // Example bitwise operation
    }
}

