int customPRNG(int seed) {
    // Simple linear congruential generator for demonstration purposes
    return (seed * 1664525 + 1013904223) % 0xFFFFFFFF;
}

int initializeAndSortRecords(long* offsets, int* keys, record** records, int size, int seed) {
    // Allocate memory for arrays and records
    if ((offsets = (long*)malloc(size * sizeof(long))) == NULL) return -1;
    if ((keys = (int*)malloc(size * sizeof(int))) == NULL) return -2;
    if ((*records = (record*)malloc(size * sizeof(record))) == NULL) return -3;

    // Initialize arrays and records
    for (int i = 0; i < size; i++) {
        offsets[i] = i * 10L; // Example offset initialization
        keys[i] = customPRNG(seed + i); // Initialize with PRNG values
        (*records)[i].value = keys[i]; // Populate record structure
    }

    // Sort records based on their int values
    qsort(*records, size, sizeof(record), (int(*)(const void*, const void*))compareRecords);

    return 0; // Success
}

int compareRecords(const void* a, const void* b) {
    return ((record*)a)->value - ((record*)b)->value;
}
