    if (tx == NULL) return NULL;
    tx->data = data;
    tx->status = status;
    return tx;
}

void initialize_arrays(long** offset_array, int** key_array, unsigned char*** data_buffers, int num_transactions) {
    *offset_array = (long*)malloc(num_transactions * sizeof(long));
    *key_array = (int*)malloc(num_transactions * sizeof(int));
    *data_buffers = (unsigned char**)malloc(num_transactions * sizeof(unsigned char*));

    if (*offset_array == NULL || *key_array == NULL || *data_buffers == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_transactions; i++) {
        (*data_buffers)[i] = allocate_buffer();
        if ((*data_buffers)[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for buffer %d\n", i);
            exit(EXIT_FAILURE);
        }
    }

    // Initialize with some values
    for (int i = 0; i < num_transactions; i++) {
        (*offset_array)[i] = i * 10;
        (*key_array)[i] = i * 5;
        Transaction* tx = create_transaction((*data_buffers)[i], i % 2);
        if (tx == NULL) {
            fprintf(stderr, "Failed to create transaction for buffer %d\n", i);
            exit(EXIT_FAILURE);
        }
    }
}

void free_resources(long* offset_array, int* key_array, unsigned char** data_buffers, Transaction* transactions[], int num_transactions) {
    for (int i = 0; i < num_transactions; i++) {
        if (data_buffers[i] != NULL) free(data_buffers[i]);
        if (transactions[i] != NULL) free(transactions[i]);
    }
    free(offset_array);
    free(key_array);
    free(data_buffers);
}

int main() {
    int num_transactions = 5000;
    long* offset_array;
    int* key_array;
    unsigned char** data_buffers;
    Transaction* transactions[MAX_TRANSACTIONS] = {NULL};

    initialize_arrays(&offset_array, &key_array, &data_buffers, num_transactions);

    for (int i = 0; i < num_transactions; i++) {
        transactions[i] = create_transaction(data_buffers[i], i % 2);
    }

    // Use the arrays and transactions...

    free_resources(offset_array, key_array, data_buffers, transactions, num_transactions);

    return 0;
}
