#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef enum {
    INIT_SUCCESS,
    DUPLICATE_KEY,
    MAX_RETRIES_EXCEEDED
} status;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    status *status_indicators;
    time_t *timestamps;
    size_t array_size;
} arrays_struct;

arrays_struct* initialize_arrays(size_t array_size, int key_range_start, int key_range_end) {
    arrays_struct *result = malloc(sizeof(arrays_struct));
    if (!result) {
        perror("Failed to allocate memory for result structure");
        return NULL;
    }

    result->array_size = array_size;

    result->offsets = malloc(array_size * sizeof(long));
    if (!result->offsets) {
        perror("Failed to allocate memory for offsets array");
        free(result);
        return NULL;
    }

    result->keys = malloc(array_size * sizeof(int));
    if (!result->keys) {
        perror("Failed to allocate memory for keys array");
        free(result->offsets);
        free(result);
        return NULL;
    }

    result->records = malloc(array_size * sizeof(record *));
    if (!result->records) {
        perror("Failed to allocate memory for records array");
        free(result->keys);
        free(result->offsets);
        free(result);
        return NULL;
    }

    result->status_indicators = malloc(array_size * sizeof(status));
    if (!result->status_indicators) {
        perror("Failed to allocate memory for status indicators array");
        free(result->records);
        free(result->keys);
        free(result->offsets);
        free(result);
        return NULL;
    }

    result->timestamps = malloc(array_size * sizeof(time_t));
    if (!result->timestamps) {
        perror("Failed to allocate memory for timestamps array");
        free(result->status_indicators);
        free(result->records);
        free(result->keys);
        free(result->offsets);
        free(result);
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG

    for (size_t i = 0; i < array_size; ++i) {
        result->status_indicators[i] = MAX_RETRIES_EXCEEDED;
        while (result->status_indicators[i] != INIT_SUCCESS) {
            int new_key = rand() % (key_range_end - key_range_start + 1) + key_range_start;

            // Check for duplicate key
            bool is_duplicate = false;
            for (size_t j = 0; j < i; ++j) {
                if (result->keys[j] == new_key) {
                    is_duplicate = true;
                    break;
                }
            }

            if (!is_duplicate) {
                result->offsets[i] = i * sizeof(long);
                result->keys[i] = new_key;
                result->records[i] = malloc(sizeof(record));
                if (!result->records[i]) {
                    perror("Failed to allocate memory for record");
                    free(result->timestamps);
                    free(result->status_indicators);
                    free(result->records);
                    free(result->keys);
                    free(result->offsets);
                    return NULL;
                }
                result->records[i]->value = rand() % (key_range_end - key_range_start + 1) + key_range_start;
                result->status_indicators[i] = INIT_SUCCESS;
                result->timestamps[i] = time(NULL);
            } else if (i >= 100) {
                break; // Max retries exceeded
            }
        }

        if (result->status_indicators[i] != INIT_SUCCESS) {
            free(result->records[i]);
            break; // Break on failure to initialize any record
        }
    }

    if (result->status_indicators[0] == MAX_RETRIES_EXCEEDED) {
        for (size_t i = 0; i < array_size; ++i) {
            free(result->records[i]);
        }
        free(result);
        return NULL;
    }

    return result;
}

void free_arrays(arrays_struct *arrays) {
    if (!arrays) return;

    for (size_t i = 0; i < arrays->array_size; ++i) {
        free(arrays->records[i]);
    }

    free(arrays->timestamps);
    free(arrays->status_indicators);
    free(arrays->records);
    free(arrays->keys);
    free(arrays->offsets);
    free(arrays);
}
