#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
} record;

// Function to generate a random UUID string
void generate_uuid(char *uuid, size_t uuid_size) {
    static const char characters[] = "0123456789abcdef";
    for (size_t i = 0; i < uuid_size - 1; ++i) {
        uuid[i] = characters[rand() % sizeof(characters)];
    }
    uuid[uuid_size - 1] = '\0';
}

// Function to check if a UUID is unique
int is_uuid_unique(const char *uuid, const char **existing_uuids, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (strcmp(uuid, existing_uuids[i]) == 0) {
            return 0;
        }
    }
    return 1;
}

// Function to initialize arrays
long* init_offset_array(size_t size) {
    long *offsets = (long *)malloc(size * sizeof(long));
    if (!offsets) return NULL;
    // Initialize offsets with some values
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = i * 1024L;
    }
    return offsets;
}

int* init_key_array(size_t size, int max_retries) {
    int *keys = (int *)malloc(size * sizeof(int));
    if (!keys) return NULL;

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < size; ++i) {
        int key;
        int retries = 0;
        do {
            key = rand();
            retries++;
        } while (!is_key_unique(key, keys, i) && retries < max_retries);
        if (retries >= max_retries) {
            free(keys);
            return NULL; // Failed to generate unique keys
        }
        keys[i] = key;
    }

    return keys;
}

record* init_record_array(size_t size, int max_retries) {
    record *records = (record *)malloc(size * sizeof(record));
    if (!records) return NULL;

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < size; ++i) {
        int value;
        int retries = 0;
        do {
            value = rand();
            retries++;
        } while (!is_value_unique(value, records, i) && retries < max_retries);
        if (retries >= max_retries) {
            free(records);
            return NULL; // Failed to generate unique values
        }
        records[i].value = value;
    }

    return records;
}

char** init_session_array(size_t size, int max_retries) {
    char **sessions = (char **)malloc(size * sizeof(char *));
    if (!sessions) return NULL;

    for (size_t i = 0; i < size; ++i) {
        sessions[i] = (char *)malloc(37); // UUID length + null terminator
        if (!sessions[i]) {
            // Free previously allocated memory on failure
            for (size_t j = 0; j < i; ++j) {
                free(sessions[j]);
            }
            free(sessions);
            return NULL;
        }

        int retries = 0;
        do {
            generate_uuid(sessions[i], 37);
            retries++;
        } while (!is_uuid_unique(sessions[i], sessions, i) && retries < max_retries);
        if (retries >= max_retries) {
            // Free previously allocated memory on failure
            for (size_t j = 0; j <= i; ++j) {
                free(sessions[j]);
            }
            free(sessions);
            return NULL; // Failed to generate unique UUIDs
        }
    }

    return sessions;
}

// Example usage
int main() {
    size_t array_size = 4;
    int max_retries = 10;

    long *offsets = init_offset_array(array_size);
    int *keys = init_key_array(array_size, max_retries);
    record *records = init_record_array(array_size, max_retries);
    char **sessions = init_session_array(array_size, max_retries);

    if (offsets && keys && records && sessions) {
        // Use the arrays here
        // ...

        // Free allocated memory
        for (size_t i = 0; i < array_size; ++i) {
            free(sessions[i]);
        }
        free(offsets);
        free(keys);
        free(records);
        free(sessions);
    }

    return 0;
}
