#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int logLevel;
} logRecord;

int generatePRNG(int seed) {
    return seed * 1103515245 + 12345 % 65536; // Simple linear congruential generator
}

void sortRecords(logRecord* records, int size) {
    for (int i = 0; i < size - 1; i++) {
        for (int j = 0; j < size - i - 1; j++) {
            if (records[j].logLevel > records[j + 1].logLevel) {
                logRecord temp = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp;
            }
        }
    }
}

int allocateAndSort(long** timestamps, int** ids, logRecord** logs, int size, int seed) {
    *timestamps = (long*)malloc(size * sizeof(long));
    *ids = (int*)malloc(size * sizeof(int));
    *logs = (logRecord*)malloc(size * sizeof(logRecord));

    if (*timestamps == NULL || *ids == NULL || *logs == NULL) {
        return -1; // Memory allocation failed
    }

    srand(seed);
    for (int i = 0; i < size; i++) {
        (*timestamps)[i] = time(NULL); // Example timestamp generation
        (*ids)[i] = generatePRNG(i + seed);
        (*logs)[i].logLevel = generatePRNG((*ids)[i]);
    }

    sortRecords(*logs, size);

    return 0; // Success
}

int main() {
    int size = 10;
    long* timestamps;
    int* ids;
