#define MAX_STREAMS 10
#define MAX_INPUT_SIZE 256

typedef struct {
    int *array;
    size_t length;
    size_t capacity;
} IntegerArray;

typedef enum {
    INCLUDE_NEGATIVES,
    EXCLUDE_NEGATIVES
} NegativeHandlingOption;

typedef enum {
    INCLUDE_DUPLICATES,
    EXCLUDE_DUPLICATES
} DuplicateHandlingOption;

typedef struct {
    pthread_mutex_t lock;
    IntegerArray *arrays[MAX_STREAMS];
    size_t count;
} DataProcessingSystem;

void initializeDataProcessingSystem(DataProcessingSystem *system) {
    pthread_mutex_init(&system->lock, NULL);
    memset(system->arrays, 0, sizeof(IntegerArray *) * MAX_STREAMS);
    system->count = 0;
}

void cleanupDataProcessingSystem(DataProcessingSystem *system) {
    for (size_t i = 0; i < system->count; ++i) {
        free(system->arrays[i]->array);
        free(system->arrays[i]);
    }
    pthread_mutex_destroy(&system->lock);
}

int readInput(char *buffer, size_t size) {
    if (!fgets(buffer, size, stdin)) {
        return -1;
    }
    buffer[strcspn(buffer, "\n")] = '\0';
    return 0;
}

void *processStream(void *arg) {
    DataProcessingSystem *system = (DataProcessingSystem *)arg;
    IntegerArray *array = malloc(sizeof(IntegerArray));
    if (!array) {
        perror("Failed to allocate memory for stream array");
        pthread_exit(NULL);
    }
    array->length = 0;
    array->capacity = 16; // Initial capacity
    array->array = malloc(array->capacity * sizeof(int));
    if (!array->array) {
        free(array);
        perror("Failed to allocate memory for stream data");
        pthread_exit(NULL);
    }

    char buffer[MAX_INPUT_SIZE];
    while (readInput(buffer, MAX_INPUT_SIZE) == 0 && strcmp(buffer, "") != 0) {
        int number = atoi(buffer);
        if (number != 0 || NegativeHandlingOption == INCLUDE_NEGATIVES) { // Placeholder for user-specified negative handling
            if (array->length == array->capacity) {
                array->capacity *= 2;
                array->array = realloc(array->array, array->capacity * sizeof(int));
                if (!array->array) {
                    perror("Failed to reallocate memory for stream data");
                    free(array);
                    pthread_exit(NULL);
                }
            }
            array->array[array->length++] = number;
        }
    }

    pthread_mutex_lock(&system->lock);
    system->arrays[system->count++] = array;
    pthread_mutex_unlock(&system->lock);

    return NULL;
}

void sortAndDeduplicate(IntegerArray *array, DuplicateHandlingOption duplicateOption) {
    // Placeholder for sorting and deduplication logic
    // Sort in descending order
    qsort(array->array, array->length, sizeof(int), (int (*)(const void *, const void *))descending);
    if (duplicateOption == EXCLUDE_DUPLICATES) {
        // Remove duplicates
        size_t i = 1;
        while (i < array->length) {
            if (array->array[i] == array->array[i - 1]) {
                memmove(&array->array[i], &array->array[i + 1], sizeof(int) * (array->length - i));
                --array->length;
            } else {
                ++i;
            }
        }
    }
}

int descending(const void *a, const void *b) {
    return (*(int *)b - *(int *)a);
}

int main() {
    DataProcessingSystem system;
    initializeDataProcessingSystem(&system);

    pthread_t threads[MAX_STREAMS];
    size_t thread_count = 0;

    printf("Enter data for up to %zu streams (type 'exit' to finish):\n", MAX_STREAMS);
    while (thread_count < MAX_STREAMS) {
        if (pthread_create(&threads[thread_count], NULL, processStream, &system) != 0) {
            perror("Failed to create thread");
            break;
        }
        ++thread_count;
        pthread_join(threads[thread_count - 1], NULL);
    }

    for (size_t i = 0; i < system.count; ++i) {
        sortAndDeduplicate(system.arrays[i], EXCLUDE_DUPLICATES); // Placeholder for user-specified duplicate handling
        printf("Stream %zu: ", i + 1);
        for (size_t j = 0; j < system.arrays[i]->length; ++j) {
            printf("%d ", system.arrays[i]->array[j]);
        }
        printf("\n");
    }

    cleanupDataProcessingSystem(&system);

    return 0;
}
