// Function to generate random numbers using a pseudo-random number generator
unsigned long generateRandomNumber(unsigned long seed) {
    return rand_r(&seed);
}

// Function to check if the value is within the specified range
int isValidValue(int value, int minValue, int maxValue) {
    return (value >= minValue && value <= maxValue);
}

// Main function to generate and analyze data
int generateAndAnalyzeData(unsigned long seed, size_t dataSize, int valueRange, const char* outputFile, char integrationType) {
    unsigned long* randomNumbers = (unsigned long*)malloc(dataSize * sizeof(unsigned long));
    int* fileValues = NULL;
    size_t fileSize = 0;

    if (!randomNumbers) {
        return -1; // Memory allocation failed
    }

    srand(seed);
    for (size_t i = 0; i < dataSize; ++i) {
        randomNumbers[i] = generateRandomNumber(seed) % (valueRange + 1);
    }

    FILE* file = fopen(outputFile, "r");
    if (!file) {
        free(randomNumbers);
        return -2; // Failed to open file
    }

    int currentValue;
    while (fscanf(file, "%d", &currentValue) == 1) {
        ++fileSize;
    }
    fseek(file, 0, SEEK_SET);

    if (integrationType == 'A') {
        fileValues = (int*)malloc(fileSize * sizeof(int));
        if (!fileValues) {
            fclose(file);
            free(randomNumbers);
            return -3; // Memory allocation failed
        }
        size_t i = 0;
        while (fscanf(file, "%d", &currentValue) == 1) {
            if (isValidValue(currentValue, 0, valueRange)) {
                fileValues[i++] = currentValue;
            }
        }
    } else {
        fileValues = (int*)malloc((fileSize + dataSize) * sizeof(int));
        if (!fileValues) {
            fclose(file);
            free(randomNumbers);
            return -4; // Memory allocation failed
        }
        size_t i = 0;
        while (fscanf(file, "%d", &currentValue) == 1) {
            fileValues[i++] = currentValue;
        }
        for (size_t j = 0; j < dataSize; ++j) {
            fileValues[i++] = randomNumbers[j];
        }
    }

    int maxValue = randomNumbers[0];
    if (integrationType == 'A') {
        for (size_t i = 0; i < fileSize; ++i) {
            if (fileValues[i] > maxValue) {
                maxValue = fileValues[i];
            }
        }
    } else {
        size_t totalSize = fileSize + dataSize;
        for (size_t i = fileSize; i < totalSize; ++i) {
            if (fileValues[i] > maxValue) {
                maxValue = fileValues[i];
            }
        }
    }

    printf("Maximum value: %d\n", maxValue);

    free(randomNumbers);
    if (integrationType == 'A') {
        free(fileValues);
    }
    fclose(file);

    return 0;
}
