['```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t max_size;
    pthread_mutex_t lock;
} dataset;

dataset* create_dataset(size_t max_size) {
    if (max_size == 0) return NULL;

    dataset* ds = malloc(sizeof(dataset));
    if (!ds) return NULL;

    ds->offsets = malloc(max_size * sizeof(long));
    ds->keys = malloc(max_size * sizeof(int));
    ds->records = malloc(max_size * sizeof(record*));

    if (!ds->offsets || !ds->keys || !ds->records) {
        free(ds);
        return NULL;
    }

    pthread_mutex_init(&ds->lock, NULL);

    for (size_t i = 0; i < max_size; ++i) {
        ds->records[i] = malloc(sizeof(record));
        if (!ds->records[i]) {
            for (size_t j = 0; j < i; ++j) free(ds->records[j]);
            free(ds);
            return NULL;
        }
    }

    srand(time(NULL)); // Seed PRNG
    for (size_t i = 0; i < max_size; ++i) {
        ds->offsets[i] = rand() % (long)(max_size * sizeof(long));
        ds->keys[i] = rand();
        ds->records[i]->value = rand();
    }

    ds->max_size = max_size;
    return ds;
}

void free_dataset(dataset* ds) {
    if (!ds) return;

    for (size_t i = 0; i < ds->max_size; ++i) free(ds->records[i]);
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

// Example usage
int main() {
    dataset* ds = create_dataset(1000);
    if (ds) {
        // Use the dataset...
        free_dataset(ds);
    }
    return 0;
}
