// Controlled abstraction layer for running tests
async function runTest(label, f) {
    const start = process.hrtime();
    let result;
    try {
        result = await f();
    } catch (error) {
        console.error(`Test ${label} failed:`, error);
        return { passed: false, duration: 0 };
    }
    const end = process.hrtime(start);
    return { passed: true, duration: (end[1] / 1e6).toFixed(2) };
}

