    blueslip.reset();
}

// Detailed logging function
function logTestResult(moduleName, label, outcome, duration) {
    console.log({
        moduleName,
        testLabel: label,
        outcome,
        executionTime: `${duration} ms`
    });
}

// Secure credential management for external logging
async function getExternalLoggerCredentials() {
    const encryptedCredentials = process.env.EXTERNAL_LOGGER_CREDENTIALS;
    if (!encryptedCredentials) throw new Error('Missing external logger credentials');
    const decryptedCredentials = crypto.createDecipheriv(
        'aes-256-cbc',
        Buffer.from(process.env.ENCRYPTION_KEY, 'hex'),
        Buffer.from(process.env.INIT_VECTOR, 'hex')
    ).update(encryptedCredentials, 'hex', 'utf8') + crypto.createDecipheriv('aes-256-cbc', Buffer.from(process.env.ENCRYPTION_KEY, 'hex'), Buffer.from(process.env.INIT_VECTOR, 'hex')).final('utf8');
    return JSON.parse(decryptedCredentials);
}

// Function to log test results securely
async function secureLogTestResult(moduleName, label, outcome, duration) {
    const credentials = await getExternalLoggerCredentials();
    externalLogger.log(credentials, { moduleName, testLabel: label, outcome, executionTime: `${duration} ms` });
}

