        const worker = new workerPool.Worker(__filename, { workerData });
        worker.on('message', result => {
            logTestResult(workerData.moduleName, workerData.label, result.passed ? 'pass' : 'fail', result.duration);
            secureLogTestResult(workerData.moduleName, workerData.label, result.passed ? 'pass' : 'fail', result.duration);
