int generateRandomOffset() {
    return rand();
}

Record* initializeRecords(int numKeys, int maxSize, int* offsetValues) {
    if (numKeys <= 0 || maxSize <= 0) {
        return NULL; // Handle invalid inputs
    }

    Record** records = (Record**)malloc(numKeys * sizeof(Record*));
    if (!records) {
        return NULL; // Memory allocation failure
    }

    for (int i = 0; i < numKeys; i++) {
        int offset = generateRandomOffset() % maxSize;
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            // Handle memory allocation failure
            for (int j = 0; j < i; j++) {
                free(records[j]);
            }
            free(records);
            return NULL;
        }
        records[i]->value = offset;
    }

    *offsetValues = generateRandomOffset() % maxSize;

    return (Record*)records;
}

void freeRecords(Record* records, int numKeys) {
    for (int i = 0; i < numKeys; i++) {
        if (records[i]) {
            free(records[i]);
        }
    }
    free(records);
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    int offsetValues;
    Record* records = initializeRecords(10, 100, &offsetValues);

    if (records) {
        printf("Offset values: %d\n", offsetValues);
        for (int i = 0; i < 10; i++) {
            printf("Record %d value: %d\n", i, records[i]->value);
        }
        freeRecords(records, 10);
    } else {
        printf("Failed to initialize records.\n");
    }

    return 0;
}
