// Define constants
#define MAX_INPUT_SIZE 1024

// Function to initialize PRNG with a seed array
void initPRNG(unsigned long *keyArray, size_t keySize) {
    for (size_t i = 0; i < keySize; ++i) {
        srand(keyArray[i]);
    }
}

// Function to generate data using PRNG
void generateData(int **data, int *dataSize, unsigned long *keyArray, size_t keySize) {
    initPRNG(keyArray, keySize);
    *data = (int *)malloc((*dataSize + 1) * sizeof(int));
    if (*data == NULL) {
        perror("Failed to allocate memory for data");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < *dataSize; ++i) {
        (*data)[i] = rand();
    }
}

// Function to read input from standard input
void readInput(char *inputBuffer, int max_input_size) {
    if (!fgets(inputBuffer, max_input_size, stdin)) {
        perror("Failed to read input");
        exit(EXIT_FAILURE);
    }
    // Remove newline character if present
    size_t len = strlen(inputBuffer);
    if (len > 0 && inputBuffer[len - 1] == '\n') {
        inputBuffer[len - 1] = '\0';
    }
}

// Function to log memory allocation/deallocation
void logMemoryEvent(int *ptr, const char *operation) {
    printf("%s: %p\n", operation, (void *)ptr);
}

// Function to analyze and print maximum values
void analyzeData(int *data, int dataSize, char *inputBuffer) {
    int maxData = data[0];
    for (int i = 1; i < dataSize; ++i) {
        if (data[i] > maxData) {
            maxData = data[i];
        }
    }

    int maxInput = inputBuffer[0];
    for (size_t i = 1; i < strlen(inputBuffer); ++i) {
        if (inputBuffer[i] > maxInput) {
            maxInput = inputBuffer[i];
        }
    }

    printf("Max in data: %d\n", maxData);
    printf("Max in input buffer: %c\n", maxInput);
}

// Main function
void generateAndAnalyzeData(int dataSize, unsigned long *keyArray, char *inputBuffer, int max_input_size, FILE *logFile, void *memoryPool) {
    int *data;
    generateData(&data, &dataSize, keyArray, 10); // Assuming key size is always 10 for simplicity

    logMemoryEvent(data, "Allocated");

    readInput(inputBuffer, max_input_size);

    analyzeData(data, dataSize, inputBuffer);

    free(data);
    logMemoryEvent(NULL, "Deallocated");
}
