    newUser->id = rand() % 10000; // Using a non-cryptographic PRNG
    strcpy(newUser->name, name);
    strcpy(newUser->email, email);
    strcpy(newUser->password, password);
    return newUser;
}

void manageUserAccounts(char* data[]) {
    int id = atoi(data[0]);
    char* name = data[1];
    char* email = data[2];
    char* password = data[3];
    char* sub_action = data[4];

    if (id == 0) {
        // Create new user account
        User* newUser = createUserAccount(name, email, password);
        userAccounts[accountCount++] = newUser;
    } else if (sub_action != NULL && strcmp(sub_action, "delete") == 0) {
        // Delete user account
        for (int i = 0; i < accountCount; i++) {
            if (userAccounts[i]->id == id) {
                free(userAccounts[i]);
                memmove(&userAccounts[i], &userAccounts[i + 1], (accountCount - i - 1) * sizeof(User*));
                accountCount--;
                break;
            }
        }
    } else {
        // Update user account
        for (int i = 0; i < accountCount; i++) {
            if (userAccounts[i]->id == id) {
                strcpy(userAccounts[i]->name, name);
                strcpy(userAccounts[i]->email, email);
                strcpy(userAccounts[i]->password, password);
                break;
            }
        }
    }

    // Return JSON response
