    for (int i = 1; i < accountCount; i++) {
        if (userAccounts[i]->id > max) {
            max = userAccounts[i]->id;
        }
    }
    printf("Largest integer: %d\n", max);
}

void unionFind(int* records, int n) {
    int* parent = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        parent[i] = i;
    }

    clock_t start = clock();
    for (int i = 1; i < n; i++) {
        while (parent[i] != i) {
            i = parent[i];
        }
    }
    clock_t end = clock();

    double time_taken = ((double)(end - start)) / CLOCKS_PER_SEC;
    printf("Time taken for Union-Find: %f seconds\n", time_taken);

    free(parent);
}

int main() {
    srand(time(0)); // Seed the PRNG

    initializeUserSystem();
    manageUserAccounts((char*[]){"0", "John Doe", "john@example.com", "password123", NULL});
    manageUserAccounts((char*[]){"1", "Jane Smith", "jane@example.com", "password456", NULL});
    findAndPrintLargest();
    unionFind((int[]){1, 2, 3, 4, 5}, 5);

    freeUserSystem();

    return 0;
}
