    if (*records == NULL) {
        return -2; // Error code for memory allocation failure
    }

    // Initialize records array with random integer values using a non-cryptographic PRNG
    srand(time(NULL)); // Seed the PRNG
    int range_min = 100;
    int range_max = 999;
    for (int i = 0; i < maxRecords; i++) {
        (*records)[i].value = rand() % (range_max - range_min + 1) + range_min;
    }

    // Read integers from standard input up to readCount times, storing them in a separate array
    int* inputArray = malloc(readCount * sizeof(int));
    if (inputArray == NULL) {
        free(*records);
        return -3; // Error code for memory allocation failure
    }
    printf("Enter %d integers:\n", readCount);
    for (int i = 0; i < readCount; i++) {
        scanf("%d", &inputArray[i]);
    }

    // Find and print the largest integer in the input array
    findAndPrintMax(inputArray, readCount);

    free(*records);
    free(inputArray);
    return 0; // Success code
}
