import java.io.*;
import java.net.*;
import java.util.concurrent.*;

public class ConcurrentServer {
    private ServerSocket serverSocket;
    private ExecutorService threadPool;
    private volatile boolean isAcceptingConnections = true;
    private ScheduledExecutorService scheduler;

    public void start(int port, int poolSize) throws IOException {
        serverSocket = new ServerSocket(port);
        threadPool = Executors.newFixedThreadPool(poolSize);
        scheduler = Executors.newScheduledThreadPool(1);

        // Schedule server restart
        scheduler.scheduleAtFixedRate(this::restartServer, 0, 5, TimeUnit.MINUTES);

        System.out.println("Server started on port " + port);
    }

    public void stop() {
        isAcceptingConnections = false;
        try {
            serverSocket.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
        threadPool.shutdown();
        scheduler.shutdown();
    }

    private void restartServer() {
        if (!isAcceptingConnections) return;

        try {
            System.out.println("Restarting server...");
            stop();
            start(serverSocket.getLocalPort(), threadPool.getCorePoolSize());
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void pauseConnectionAcceptance() {
        isAcceptingConnections = false;
    }

    public void resumeConnectionAcceptance() {
        isAcceptingConnections = true;
    }

    public static void main(String[] args) {
        try {
            ConcurrentServer server = new ConcurrentServer();
            server.start(8080, 10);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
