typedef struct {
    double value;
} record;

long* allocateOffsets(int size) {
    return (long*)malloc(size * sizeof(long));
}

int* allocateIdentifiers(int size) {
    return (int*)malloc(size * sizeof(int));
}

record* allocateRecords(int size) {
    return (record*)malloc(size * sizeof(record));
}

double generatePRNG() {
    static double seed = 1234.5678;
    seed = (seed * 1103515245 + 12345) / 65536.0; // Simple LCG
    return seed;
}

int initializeData(int size, long** offsets, int** identifiers, record** records) {
    if (size <= 0) return -1; // Validate input

    *offsets = allocateOffsets(size);
    *identifiers = allocateIdentifiers(size);
    *records = allocateRecords(size);

    if (!*offsets || !*identifiers || !*records) {
        free(*offsets); // Clean up on failure
        free(*identifiers);
        free(*records);
        return -2; // Memory allocation failed
    }

    for (int i = 0; i < size; i++) {
        (*offsets)[i] = rand() % size; // Populate offsets with random values
        (*identifiers)[i] = i; // Populate identifiers sequentially
        (*records)[i].value = generatePRNG(); // Populate records with PRNG values
    }

    return 0; // Success
}

void freeData(long* offsets, int* identifiers, record* records) {
    free(offsets);
    free(identifiers);
    free(records);
}

int main() {
    srand(time(0)); // Seed for the PRNG

    int size = 1000;
    long* offsets;
    int* identifiers;
    record* records;

    int result = initializeData(size, &offsets, &identifiers, &records);

    if (result == 0) {
        printf("Data initialized successfully.\n");
        freeData(offsets, identifiers, records);
    } else {
        printf("Failed to initialize data. Error code: %d\n", result);
    }

    return 0;
}
