    offsets: Vec<i64>,
    keys: Vec<i32>,
    records: Arc<Mutex<Vec<Record>>>,
    url: String,
    javaChannel: JavaChannel,
    maxConcurrentConnections: usize,
) -> Result<(), i32> {
