#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    uint64_t value;
} record;

typedef struct {
    size_t allocation_count;
    pthread_mutex_t lock;
    unsigned int seed;
} RandomGeneratorState;

static RandomGeneratorState rng_state = {0, PTHREAD_MUTEX_INITIALIZER, 0};

record* create_records(size_t count, long offset_min, long offset_max, int key_min, int key_max) {
    record *records = malloc(count * sizeof(record));
    if (!records) return NULL;

    pthread_mutex_lock(&rng_state.lock);
    rng_state.allocation_count++;
    pthread_mutex_unlock(&rng_state.lock);

    if (rng_state.seed == 0) {
        pthread_mutex_lock(&rng_state.lock);
        if (rng_state.seed == 0) {
            srand(time(NULL));
            rng_state.seed = rand();
        }
        pthread_mutex_unlock(&rng_state.lock);
    }

    for (size_t i = 0; i < count; ++i) {
        records[i].offset = offset_min + (rand_r(&rng_state.seed) % (offset_max - offset_min + 1));
        records[i].key = key_min + (rand_r(&rng_state.seed) % (key_max - key_min + 1));
        records[i].value = (uint64_t(rand_r(&rng_state.seed))) | 
                          ((uint64_t(rand_r(&rng_state.seed))) << 32);
    }

    return records;
}

void free_records(record *records, size_t count) {
    free(records);
}

void reset_random_generator(unsigned int new_seed) {
    pthread_mutex_lock(&rng_state.lock);
    rng_state.seed = new_seed;
    pthread_mutex_unlock(&rng_state.lock);
}

size_t get_total_allocations() {
    return rng_state.allocation_count;
}
