    if (network_entry_validate(address, port)) {
        if (config->count >= config->max_count) {
            fprintf(stderr, "Network configuration limit reached. Entry added to secondary storage.\n");
            // Implement secondary storage logic here
        } else {
            NetworkEntry *entry = (NetworkEntry *)malloc(sizeof(NetworkEntry));
            entry->address = strdup(address);
            entry->port = port;
            entry->score = score;

            config->entries[config->count++] = entry;
        }
    } else {
        fprintf(stderr, "Invalid network address or port. Entry not added.\n");
    }
}

int network_config_get_best(NetworkConfig *config) {
    if (config->count == 0) return -1; // No entries

    int best_index = 0;
    for (size_t i = 1; i < config->count; ++i) {
        if (config->entries[i]->score > config->entries[best_index]->score) {
            best_index = i;
        }
    }

    return best_index;
}

