        return 1;
    }

    // Example usage
    network_config_add(config, "192.168.1.1", 80, 5);
    network_config_add(config, "10.0.0.1", 443, 7);

    int best_index = network_config_get_best(config);
    if (best_index != -1) {
        printf("Best entry: %s:%d\n", config->entries[best_index]->address, config->entries[best_index]->port);
    }

    network_config_free(config);
    return 0;
}
