#define NUM_RECORDS 1000

typedef struct {
    int value;
} record;

unsigned long xorshift32(unsigned long *state) {
    unsigned long x = *state;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    return (*state = x);
}

void initialize_arrays(long **offsets, int **keys, short **ids, record **records) {
    time_t now = time(NULL);
    pid_t pid = getpid();
    unsigned long seed = (unsigned long)(now ^ pid);

    *offsets = malloc(NUM_RECORDS * sizeof(long));
    *keys = malloc(NUM_RECORDS * sizeof(int));
    *ids = malloc(NUM_RECORDS * sizeof(short));
    *records = malloc(NUM_RECORDS * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *ids == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    unsigned long state = seed;
    for (int i = 0; i < NUM_RECORDS; i++) {
        (*offsets)[i] = xorshift32(&state) % 1000000L; // Example range
        (*keys)[i] = xorshift32(&state);
        (*ids)[i] = xorshift32(&state) % 65536; // Example range for short int

        record *r = &(*records)[i];
        r->value = xorshift32(&state); // Initialize with PRNG
    }
}

void free_arrays(long *offsets, int *keys, short *ids, record *records) {
    free(offsets);
    free(keys);
    free(ids);
    free(records);
}
