        free(logger);
        return NULL;
    }

    return logger;
}

void destroy_event_logger(EventLogger *logger) {
    if (logger) {
        free(logger->timestamps);
        free(logger->event_types);
        free(logger->priorities);
        free(logger);
    }
}

void log_event(EventLogger *logger, long timestamp, int event_type) {
    if (logger->count >= MAX_EVENTS) return;

    logger->timestamps[logger->count] = timestamp;
    logger->event_types[logger->count] = event_type;
    logger->priorities[logger->count] = rand() % 10; // Simplified priority generation

    logger->count++;
}

void flush_event_logger(EventLogger *logger) {
    logger->count = 0;
