#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    char* data;
} record;

typedef struct {
    record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} pipeline;

pipeline* create_pipeline(size_t initial_capacity) {
    pipeline* pipe = malloc(sizeof(pipeline));
    if (pipe == NULL) return NULL;

    pipe->records = calloc(initial_capacity, sizeof(record*));
    if (pipe->records == NULL) {
        free(pipe);
        return NULL;
    }

    pipe->capacity = initial_capacity;
    pipe->size = 0;
    pthread_mutex_init(&pipe->mutex, NULL);

    return pipe;
}

void destroy_pipeline(pipeline* pipe) {
    for (size_t i = 0; i < pipe->size; ++i) {
        free(pipe->records[i]->data);
        free(pipe->records[i]);
    }
    free(pipe->records);
    pthread_mutex_destroy(&pipe->mutex);
    free(pipe);
}

void add_record(pipeline* pipe, time_t timestamp) {
    if (pipe->size >= pipe->capacity) {
        size_t new_capacity = pipe->capacity * 2;
        record** new_records = realloc(pipe->records, new_capacity * sizeof(record*));
        if (new_records == NULL) return;

        pipe->records = new_records;
        pipe->capacity = new_capacity;
    }

    pipe->records[pipe->size] = malloc(sizeof(record));
    if (pipe->records[pipe->size] == NULL) return;

    record* rec = pipe->records[pipe->size];
    rec->timestamp = timestamp;
    rec->data = malloc(1024 * sizeof(char)); // Example buffer size
    if (rec->data == NULL) {
        free(rec);
        return;
    }

    // Initialize data with PRNG
    srand(time(NULL));
    for (size_t i = 0; i < 1024; ++i) {
        rec->data[i] = rand() % 256;
    }

    pthread_mutex_lock(&pipe->mutex);
    pipe->size++;
    pthread_mutex_unlock(&pipe->mutex);
}

// Example usage
int main() {
    pipeline* my_pipeline = create_pipeline(1000);
    if (my_pipeline == NULL) return -1;

    add_record(my_pipeline, time(NULL));

    // Clean up
    destroy_pipeline(my_pipeline);

    return 0;
}
```

