#include <time.h>

typedef struct {
    long id;
} transactionRecord;

float* processAndAnalyzeTransactions(long numRecords) {
    float* amounts = (float*)malloc(numRecords * sizeof(float));
    if (!amounts) return NULL; // Handle memory allocation failure

    long* ids = (long*)malloc(numRecords * sizeof(long));
    if (!ids) {
        free(amounts);
        return NULL; // Handle memory allocation failure
    }

    transactionRecord* records = (transactionRecord*)malloc(numRecords * sizeof(transactionRecord));
    if (!records) {
        free(ids);
        free(amounts);
        return NULL; // Handle memory allocation failure
    }

    srand(time(NULL)); // Seed PRNG for better randomness

    for (long i = 0; i < numRecords; i++) {
        records[i].id = ids[i] = rand(); // Populate with random transaction IDs
        amounts[i] = ((float)rand() / RAND_MAX) * 1000.0f; // Random amount between 0 and 1000
    }

    long* validIds = (long*)malloc(numRecords * sizeof(long));
    if (!validIds) {
        free(records);
        free(ids);
        free(amounts);
        return NULL; // Handle memory allocation failure
    }

    int validCount = 0;
    while (1) {
        printf("Enter transaction ID (-1 to finish): ");
        long inputId;
        scanf("%ld", &inputId);
        if (inputId == -1) break;
        for (long i = 0; i < numRecords; i++) {
            if (records[i].id == inputId) {
                validIds[validCount++] = inputId;
                break;
            }
        }
    }

    float average = 0.0f;
    float variance = 0.0f;
    for (int i = 0; i < validCount; i++) {
        average += amounts[i];
    }
    average /= validCount;

    for (int i = 0; i < validCount; i++) {
        variance += pow(amounts[i] - average, 2);
    }
    variance /= validCount;

    printf("Average transaction amount: %.2f\n", average);
    printf("Variance of transaction amounts: %.2f\n", variance);

    free(validIds);
    free(records);
    free(ids);
    free(amounts);

    return amounts;
}
