    while (token != NULL && *count < MAX_INTS) {
        (*array)[(*count)++] = atoi(token);
        token = strtok(NULL, " \n");
    }

    if (*count == MAX_INTS) {
        log_error("Too many integers. Maximum allowed is 1000.");
        free(*array);
        return -1;
    }

    return 0;
}

void print_largest_integer(int* array, size_t count) {
    if (count == 0) {
        printf("No integers found.\n");
        return;
    }

    int max = array[0];
    for (size_t i = 1; i < count; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }

    printf("Largest integer: %d\n", max);
}

