```c
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
    long *offsets;
} record;

int generate_unique_offsets(int size, int min, int max, long *offsets) {
    if (size > (max - min + 1)) {
        return -1; // Not enough unique values in the range
    }

    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % (max - min + 1) + min;
    }

    // Sort and remove duplicates using bubble sort (not efficient but simple)
    for (int i = 0; i < size - 1; i++) {
        for (int j = 0; j < size - i - 1; j++) {
            if (offsets[j] == offsets[j + 1]) {
                // Shift elements to the right
                for (int k = size - 2; k > j; k--) {
                    offsets[k] = offsets[k - 1];
                }
                offsets[j] = rand() % (max - min + 1) + min;
                i--;
                break;
            }
        }
    }

    return 0;
}

int initialize_records(int num_records, int offset_range_min, int offset_range_max, record **records) {
    if (num_records <= 0 || offset_range_min > offset_range_max) {
        return -1; // Invalid input
    }

    *records = malloc(num_records * sizeof(record));
    if (*records == NULL) {
        return -2; // Memory allocation failed
    }

    srand(time(NULL)); // Seed the PRNG

    for (int i = 0; i < num_records; i++) {
        (*records)[i].key = i + 1;
        int size = rand() % (offset_range_max - offset_range_min + 1) + offset_range_min;
        long *offsets = malloc(size * sizeof(long));
        if (offsets == NULL) {
            // Free previously allocated memory
            for (int j = 0; j < i; j++) {
                free((*records)[j].offsets);
            }
            free(*records);
            return -2; // Memory allocation failed
        }

        if (generate_unique_offsets(size, offset_range_min, offset_range_max, offsets) != 0) {
            free(offsets);
            for (int j = 0; j < i; j++) {
                free((*records)[j].offsets);
            }
            free(*records);
            return -3; // Failed to generate unique offsets
        }

        (*records)[i].offsets = offsets;
    }

    return 0; // Success
}
```

