```csharp
using System;

public class SecureRandomValueGenerator
{
    private readonly Random _random = new Random();

    public SecureRandomValueGenerator(int minValue, int maxValue)
    {
        if (minValue >= maxValue)
        {
            throw new ArgumentException("minValue must be less than maxValue");
        }

        MinValue = minValue;
        MaxValue = maxValue;
    }

    public int MinValue { get; }
    public int MaxValue { get; }

    public int GetRandomInt()
    {
        // Generate a random integer within the specified range
        return _random.Next(MinValue, MaxValue + 1);
    }

    public float GetRandomFloat()
    {
        // Generate a random float within the specified range
        return (float)_random.NextDouble() * (MaxValue - MinValue) + MinValue;
    }
}
