using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Xml.Linq;

public class XPathRetriever
{
    private static Dictionary<string, XDocument> cache = new Dictionary<string, XDocument>();
    private static readonly Stopwatch stopwatch = new Stopwatch();

    public static XElement RetrieveFirstXPathElement(XDocument xmlDoc, string nodeName, string namespacePrefix)
    {
        if (xmlDoc == null) throw new ArgumentNullException(nameof(xmlDoc));
        if (string.IsNullOrEmpty(nodeName)) throw new ArgumentException("Node name cannot be empty.", nameof(nodeName));
        if (string.IsNullOrEmpty(namespacePrefix)) throw new ArgumentException("Namespace prefix cannot be empty.", nameof(namespacePrefix));

        string key = $"{namespacePrefix}_{nodeName}";
        if (!cache.TryGetValue(key, out XDocument cachedDoc))
        {
            stopwatch.Restart();
            var ns = new XNamespace($"http://schemas.xmlsoap.org/wsdl/{namespacePrefix}");
            var element = xmlDoc.Descendants(ns + nodeName).FirstOrDefault();
            stopwatch.Stop();

            if (element == null) return null;
            if (xmlDoc.Descendants(ns + nodeName).Count() > 1) throw new InvalidOperationException("Multiple elements found.");

            cache[key] = xmlDoc;
        }
        else
        {
            stopwatch.Restart();
            var ns = new XNamespace($"http://schemas.xmlsoap.org/wsdl/{namespacePrefix}");
            var element = cachedDoc.Descendants(ns + nodeName).FirstOrDefault();
            stopwatch.Stop();

            if (element == null) return null;
            if (cachedDoc.Descendants(ns + nodeName).Count() > 1) throw new InvalidOperationException("Multiple elements found.");
        }

        Debug.WriteLine($"Retrieved {nodeName} in {stopwatch.ElapsedMilliseconds} ms");
        return element;
    }
}
