use std::collections::{HashMap, HashSet};
use std::env;
use std::fs::{self, DirEntry};
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::thread;

type DirCache = Arc<Mutex<HashMap<String, PathBuf>>>;

fn manage_directory_with_env_var(directory_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    if directory_name.is_empty() || directory_name.contains(&['/', '\\', ':', '*', '?', '"', '<', '>', '|']) {
        return Err("Invalid directory name".into());
    }

    let dir_path = PathBuf::from(directory_name);
    if !dir_path.exists() {
        fs::create_dir_all(&dir_path)?;
    }

    let mut cache: DirCache = Arc::new(Mutex::new(HashMap::new()));
    let cache_clone = Arc::clone(&cache);

    thread::spawn(move || {
        let mut guard = cache_clone.lock().unwrap();
        guard.insert("DIRECTORY_PATH".to_string(), dir_path.clone());
    }).join()?;

    env::set_var("DIRECTORY_PATH", cache.lock().unwrap().get("DIRECTORY_PATH").unwrap().as_os_str());

    Ok(())
}
