use std::collections::LinkedList;
use serde_json::{Value, from_str};
use chrono::{Local, Duration};

struct DistributedList {
    list: LinkedList<String>,
    lock: Mutex<()>, // Mutex for thread safety when modifying the list
}

impl DistributedList {
    fn new() -> Self {
        DistributedList {
            list: LinkedList::new(),
            lock: Mutex::new(()),
        }
    }

    fn insert_string_after_match(
        &self,
        forward_list: &std::forward_list<std::string>,
        target_string: std::string,
        insert_string: std::string,
        log_level: LogLevel,
    ) {
        let mut list = self.list.lock().unwrap();
        for item in forward_list.iter() {
            if *item == target_string {
                list.push_back(insert_string.clone());
                break;
            }
        }
        if list.back() != Some(&insert_string) {
            list.push_back(insert_string);
        }

        log_operation(log_level, "Inserted string", insert_string);
    }
}

fn parse_target_string(json_data: &str) -> Result<std::string, String> {
    match from_str::<Value>(json_data) {
        Ok(val) => match val.get("target") {
            Some(target) => target.to_string(),
            None => Err("Target string not found in JSON data".to_string()),
        },
        Err(_) => Err("Failed to parse JSON data".to_string()),
    }
}

fn log_operation(log_level: LogLevel, operation: &str, details: std::string) {
    match log_level {
        LogLevel::Info => println!("{} - {}: {}", Local::now(), operation, details),
        LogLevel::Error => eprintln!("{} - Error: {}", Local::now(), details),
    }
}

enum LogLevel {
    Info,
    Error,
}
