#include <arpa/inet.h>

#define MAX_CONCURRENT_UPLOADS 100
#define MAX_FILE_SIZE 1024 * 1024 * 1024 // 1GB

typedef enum {
    UNENCRYPTED,
    CBC,
    GCM,
    CTR
} EncryptionMode;

typedef struct {
    int fd;
    char* file_path;
   EncryptionMode mode;
    char* key;
    char* iv;
    pthread_t thread_id;
    int progress;
    int status; // 0: Pending, 1: Success, -1: Failure
} UploadTask;

UploadTask tasks[MAX_CONCURRENT_UPLOADS];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* handle_upload(void* arg) {
    UploadTask* task = (UploadTask*)arg;
    FILE* file = fopen(task->file_path, "rb");
    if (!file) {
        task->status = -1;
        return NULL;
    }

    // Simulate encryption and decryption
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx || !EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, (unsigned char*)task->key, (unsigned char*)task->iv)) {
        task->status = -1;
        fclose(file);
        return NULL;
    }

    unsigned char* buffer = malloc(MAX_FILE_SIZE);
    size_t bytes_read;
    while ((bytes_read = fread(buffer, 1, MAX_FILE_SIZE, file)) > 0) {
        if (!EVP_EncryptUpdate(ctx, buffer, &bytes_read, buffer, bytes_read)) {
            task->status = -1;
            break;
        }
        // Send encrypted data to server
    }

    free(buffer);
    EVP_CIPHER_CTX_free(ctx);
    fclose(file);

    task->status = 1;
    return NULL;
}

int start_upload(const char* file_path, EncryptionMode mode) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < MAX_CONCURRENT_UPLOADS; i++) {
        if (!tasks[i].fd) {
            tasks[i].file_path = strdup(file_path);
            tasks[i].mode = mode;
            tasks[i].progress = 0;
            tasks[i].status = 0;

            if (mode != UNENCRYPTED) {
                // Generate key and IV
                RAND_bytes((unsigned char*)tasks[i].key, 32);
                RAND_bytes((unsigned char*)tasks[i].iv, EVP_CIPHER_block_size(EVP_aes_256_cbc()));
            }

            if (pthread_create(&tasks[i].thread_id, NULL, handle_upload, &tasks[i]) != 0) {
                free(tasks[i].file_path);
                tasks[i].fd = -1;
                pthread_mutex_unlock(&lock);
                return -1;
            }
            pthread_detach(tasks[i].thread_id);
            pthread_mutex_unlock(&lock);
            return i + 1; // Return task ID
        }
    }
    pthread_mutex_unlock(&lock);
    return -2; // No available slots
}

void* check_upload_status(void* arg) {
    int task_id = *(int*)arg;
    if (task_id < 1 || task_id > MAX_CONCURRENT_UPLOADS) {
        return NULL;
    }

    pthread_mutex_lock(&lock);
    UploadTask* task = &tasks[task_id - 1];
    if (!task->fd) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }
    pthread_mutex_unlock(&lock);

    // Simulate checking upload status
    sleep(1); // Simulate time taken to check status

    pthread_mutex_lock(&lock);
    int current_status = task->status;
    pthread_mutex_unlock(&lock);

    if (current_status == 0) {
        printf("Upload %d: Pending\n", task_id);
    } else if (current_status == 1) {
        printf("Upload %d: Success\n", task_id);
    } else if (current_status == -1) {
        printf("Upload %d: Failure\n", task_id);
    }

    return NULL;
}

int main() {
    int task_id = start_upload("/path/to/file.txt", CBC);
    if (task_id < 0) {
        printf("Failed to start upload\n");
        return -1;
    }

    pthread_t status_thread;
    if (pthread_create(&status_thread, NULL, check_upload_status, &task_id) != 0) {
        printf("Failed to create status thread\n");
        return -1;
    }
    pthread_detach(status_thread);

    // Simulate long running process
    sleep(5);
    return 0;
}
