long seed;
int minValue;
int maxValue;
int numRecords;

void initializePRNG(long seed) {
    srand(seed);
}

int generateRandomValue(int minValue, int maxValue) {
    return rand() % (maxValue - minValue + 1) + minValue;
}

void populateRecords(record* records, long maxRecords, int seed, int minValue, int maxValue) {
    initializePRNG(seed);
    for (long i = 0; i < maxRecords; i++) {
        records[i].value = generateRandomValue(minValue, maxValue);
    }
}

int readInput(int* inputArray, int* size) {
    *size = 0;
    while (scanf("%d", &inputArray[*size]) != EOF) {
        (*size)++;
        if (*size >= MAX_RECORD_SIZE) {
            return -1; // Error: Input exceeds maximum record size
        }
    }
    return 0;
}

void findAndPrintMax(int* inputArray, int inputSize) {
    long maxRecordValue = INT_MIN;
    for (long i = 0; i < numRecords; i++) {
        if (records[i].value > maxRecordValue) {
            maxRecordValue = records[i].value;
        }
    }

    int maxInputValue = INT_MIN;
    for (int i = 0; i < inputSize; i++) {
        if (inputArray[i] > maxInputValue) {
            maxInputValue = inputArray[i];
        }
    }

    printf("Max Record Value: %ld\n", maxRecordValue);
    printf("Max Input Value: %d\n", maxInputValue);
}

int processAndFindMax(long* offsets, int* keys, record* records, long maxRecords, long seed, int minValue, int maxValue) {
    numRecords = maxRecords;
    this->offsets = offsets;
    this->keys = keys;
    this->records = records;
    this->maxRecords = maxRecords;
    this->seed = seed;
    this->minValue = minValue;
    this->maxValue = maxValue;

    populateRecords(records, maxRecords, seed, minValue, maxValue);

    int inputArray[MAX_RECORD_SIZE];
    int inputSize;
    if (readInput(inputArray, &inputSize) != 0) {
        return -1; // Error: Input exceeds maximum record size
    }

    findAndPrintMax(inputArray, inputSize);
    return 0;
}

int main() {
    long offsets[1];
    int keys[1];
    record records[50];

    processAndFindMax(offsets, keys, records, 50, time(0), 0, 100);
    return 0;
}
