// C++ Library: SessionIDGenerator.cpp
#include "SessionIDGenerator.h"
#include <string>
#include <iomanip>

SessionIDGenerator::SessionIDGenerator() : mt(std::random_device{}()) {}

std::string SessionIDGenerator::generateSessionID() {
    std::lock_guard<std::mutex> lock(mtx);
    std::uniform_int_distribution<> dist(0, 255);
    std::stringstream ss;
    for (int i = 0; i < 32; ++i) {
        ss << std::hex << std::setw(2) << std::setfill('0') << dist(mt);
    }
    return ss.str();
}
