public class CommandExecutor {

    public static void main(String[] args) {
        String configFilePath = "path/to/config/file";
        String storedHash = "pre-stored-hash-value";

        try {
            if (!verifyConfigFileIntegrity(configFilePath, storedHash)) {
                System.out.println("Configuration file integrity check failed. Please manually verify and update the file.");
                return;
            }

            ProcessBuilder processBuilder = new ProcessBuilder("command-to-execute");
            processBuilder.redirectErrorStream(true);

            Process process = processBuilder.start();
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));

            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }

            int exitCode = process.waitFor();
            System.out.println("Process exited with code: " + exitCode);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static boolean verifyConfigFileIntegrity(String configFilePath, String storedHash) throws Exception {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] fileBytes = Files.readAllBytes(Paths.get(configFilePath));
        byte[] fileHash = digest.digest(fileBytes);

        String calculatedHash = bytesToHex(fileHash);
        return calculatedHash.equals(storedHash);
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static native void manageMemory(int numRecords, long[] offsets, int[] keys, short[] counters, record[] records);

    static {
        System.loadLibrary("memory_management");
    }

    public static class record {
        int value;
        short counter;
        double timestamp;

        public record(int value, short counter, double timestamp) {
            this.value = value;
            this.counter = counter;
            this.timestamp = timestamp;
        }
    }
}
