typedef struct Record {
    int key;
    long offset;
} Record;

Record* initializeDataset(int numRecords, int keyRangeStart, int keyRangeEnd) {
    if (numRecords <= 0 || keyRangeStart >= keyRangeEnd) {
        return NULL;
    }

    Record* dataset = (Record*)malloc(numRecords * sizeof(Record));
    if (dataset == NULL) {
        return NULL; // Memory allocation failed
    }

    int* usedKeys = (int*)calloc(keyRangeEnd - keyRangeStart + 1, sizeof(int));
    if (usedKeys == NULL) {
        free(dataset);
        return NULL; // Memory allocation for keys failed
    }

    srand(time(NULL)); // Seed the PRNG

    for (int i = 0; i < numRecords; ) {
        int key;
        do {
            key = rand() % (keyRangeEnd - keyRangeStart + 1) + keyRangeStart;
        } while (usedKeys[key - keyRangeStart]);

        dataset[i].key = key;
        usedKeys[key - keyRangeStart] = 1;
        i++;
    }

    free(usedKeys);
    return dataset;
}

void freeDataset(Record* dataset, int numRecords) {
    if (dataset != NULL) {
        free(dataset);
    }
}
