} Transaction;

void initializeStructures(int offsetSize, int keySize, int numTransactions) {
    if (numTransactions > 10000) {
        printf("Error: Number of transactions exceeds the maximum limit.\n");
        return;
    }

    long *offsets = malloc(offsetSize * sizeof(long));
    if (!offsets) {
        printf("Error: Memory allocation failed for offsets.\n");
        return;
    }

    int *keys = malloc(keySize * sizeof(int));
    if (!keys) {
        printf("Error: Memory allocation failed for keys.\n");
        free(offsets);
        return;
    }

    Transaction *transactions = malloc(numTransactions * sizeof(Transaction));
    if (!transactions) {
        printf("Error: Memory allocation failed for transactions.\n");
        free(offsets);
        free(keys);
        return;
    }

    srand(time(NULL)); // Seed the PRNG with the current time

    for (int i = 0; i < numTransactions; ++i) {
        do {
            transactions[i].id = rand(); // Generate a random transaction ID
        } while (!isUnique(transactions, numTransactions, transactions[i].id));

        int dataSize = rand() % 128 + 1; // Random data size between 1 and 128 bytes
        for (int j = 0; j < dataSize; ++j) {
            transactions[i].data[j] = (char)(rand() % 256); // Fill data buffer with random bytes
        }
    }

    // Use offsets, keys, and transactions as needed

    free(offsets);
    free(keys);
    free(transactions);
}

int isUnique(Transaction *transactions, int numTransactions, int id) {
    for (int i = 0; i < numTransactions; ++i) {
        if (transactions[i].id == id && i != numTransactions - 1) {
            return 0; // Not unique
        }
    }
    return 1; // Unique
}

int main() {
    initializeStructures(100, 200, 5000);
    return 0;
}
