#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_TRANSACTIONS 50000
#define BUFFER_SIZE 128

typedef struct {
    int key;
    long data_buffer[BUFFER_SIZE];
} Transaction;

typedef struct {
    Transaction *transactions;
    int offset[MAX_TRANSACTIONS];
    int status[MAX_TRANSACTIONS];
    time_t timestamps[MAX_TRANSACTIONS];
    size_t metadata_size;
} Metadata;

Metadata* initialize_transactions(int num_transactions, unsigned seed) {
    if (num_transactions > MAX_TRANSACTIONS) {
        fprintf(stderr, "Error: Too many transactions requested.\n");
        return NULL;
    }

    Metadata *metadata = malloc(sizeof(Metadata));
    if (!metadata) {
        perror("Memory allocation failed");
        return NULL;
    }

    metadata->transactions = calloc(num_transactions, sizeof(Transaction));
    if (!metadata->transactions) {
        fprintf(stderr, "Error: Failed to allocate memory for transactions.\n");
        free(metadata);
        return NULL;
    }

    srand(seed);

    for (int i = 0; i < num_transactions; ++i) {
        metadata->offset[i] = rand() % BUFFER_SIZE;
        int key = rand();
        metadata->transactions[i].key = key;

        // Generate random data buffer
        for (int j = 0; j < BUFFER_SIZE; ++j) {
            metadata->transactions[i].data_buffer[j] = rand();
        }

        metadata->status[i] = rand() % 2; // Randomly set status to 0 or 1
        metadata->timestamps[i] = time(NULL);
    }

    metadata->metadata_size = sizeof(Metadata) + (num_transactions * sizeof(Transaction));
    return metadata;
}

void free_metadata(Metadata *metadata) {
    if (metadata) {
        free(metadata->transactions);
        free(metadata);
    }
}

int main() {
    int num_transactions = 1000; // Example input
    unsigned seed = time(NULL);

    Metadata *metadata = initialize_transactions(num_transactions, seed);
    if (!metadata) {
        fprintf(stderr, "Failed to initialize transactions.\n");
        return EXIT_FAILURE;
    }

    // Use metadata for further processing...

    free_metadata(metadata);
    return EXIT_SUCCESS;
}
