struct record* processAndFindMax(int limit, int range_start, int range_end) {
    struct record* records = malloc(limit * sizeof(struct record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < limit; ++i) {
        records[i].value = rand() % (range_end - range_start + 1) + range_start;
    }

    int max_index = 0;
    for (int i = 1; i < limit; ++i) {
        if (records[i].value > records[max_index].value) {
            max_index = i;
        }
    }

    return &records[max_index];
}

