    struct transaction transactions[MAX_TRANSACTIONS];
    int limit = 10000;

    init_transactions(10, 100, transactions, limit);

    struct record* max_record = processAndFindMax(limit, 0, 100000);
    if (max_record) {
        printf("Maximum value: %d\n", max_record->value);
    }

    for (int i = 0; i < limit; ++i) {
        free(transactions[i].data_buffer);
        free(transactions[i].metadata);
    }

    return 0;
}
