} ResourceBundle;

ResourceBundle* loadResourceBundle(const char* filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return NULL;

    // Read number of items from file
    int count;
    if (fscanf(file, "%d", &count) != 1) {
        fclose(file);
        return NULL;
    }

    ResourceBundle *bundle = malloc(sizeof(ResourceBundle));
    if (!bundle) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(file);
        return NULL;
    }

    bundle->ids = malloc(count * sizeof(long));
    bundle->usernames = malloc(count * sizeof(char*));
    bundle->status = malloc(count * sizeof(int));
    bundle->timestamps = malloc(count * sizeof(time_t));

    if (!bundle->ids || !bundle->usernames || !bundle->status || !bundle->timestamps) {
        fprintf(stderr, "Memory allocation failed\n");
        free(bundle->ids);
        free(bundle->usernames);
        free(bundle->status);
        free(bundle->timestamps);
        free(bundle);
        fclose(file);
        return NULL;
    }

    for (int i = 0; i < count; ++i) {
        if (fscanf(file, "%ld %s", &bundle->ids[i], bundle->usernames[i]) != 2) {
            fprintf(stderr, "Error reading file\n");
            free(bundle->ids);
            free(bundle->usernames);
            free(bundle->status);
            free(bundle->timestamps);
            free(bundle);
            fclose(file);
            return NULL;
        }
        bundle->status[i] = 0; // Initialize status
        time(&bundle->timestamps[i]);
    }

    fclose(file);
    return bundle;
}
