// Helper function to process and find maximum
int* processAndFindMax(int limit, int min_val, int max_val, size_t* out_size) {
    if (limit <= 0 || min_val > max_val) {
        return NULL; // Invalid input
    }

    *out_size = limit;
    int* records = (int*)malloc(limit * sizeof(int));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < limit; ++i) {
        records[i] = rand() % (max_val - min_val + 1) + min_val;
    }

    return records;
}

// Main function to manage memory and populate structures
void manageMemory(int offset, int key, size_t num_transactions) {
    if (num_transactions > 50000) {
        printf("Error: Number of transactions exceeds limit.\n");
        return;
    }

    // Allocate memory for arrays
    int* offsets = (int*)malloc(offset * sizeof(int));
    int* keys = (int*)malloc(key * sizeof(int));
    Transaction* transactions = (Transaction*)malloc(num_transactions * sizeof(Transaction));
    Metadata* metadata = (Metadata*)malloc(num_transactions * sizeof(Metadata));

    if (!offsets || !keys || !transactions || !metadata) {
        printf("Error: Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(transactions);
        free(metadata);
        return;
    }

    // Initialize and populate structures with random values
    srand(time(NULL));
    for (size_t i = 0; i < num_transactions; ++i) {
        transactions[i].data_buffer = (int*)malloc(128 * sizeof(int));
        if (!transactions[i].data_buffer) {
            printf("Error: Memory allocation failed for transaction data buffer.\n");
            return;
        }

        // Populate data_buffer with random values
        for (size_t j = 0; j < 128; ++j) {
            transactions[i].data_buffer[j] = rand() % 256;
        }

        metadata[i].status = rand() % 3; // Example status: 0, 1, or 2
        metadata[i].timestamp = time(NULL);
    }

    // Free allocated memory
    for (size_t i = 0; i < num_transactions; ++i) {
        free(transactions[i].data_buffer);
    }
    free(offsets);
    free(keys);
    free(transactions);
    free(metadata);
}

int main() {
    size_t num_transactions = 1000;
    manageMemory(10, 5, num_transactions);

    size_t record_size;
    int* records = processAndFindMax(num_transactions, -100, 100, &record_size);
    if (records) {
        // Process the records array
        free(records);
    }

    return 0;
}
```

