    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        records[i].value = rand() % (range_max - range_min + 1) + range_min;
    }
}

int allocate_memory(size_t size, long** offsets, int** keys, record** records, int* error_code) {
    *offsets = allocate_offset_array(size);
    if (!*offsets) {
        *error_code = -1;
        return -1; // Allocation failed
    }

    *keys = allocate_key_array(size);
    if (!*keys) {
        free(*offsets);
        *error_code = -2;
        return -1; // Allocation failed
    }

    *records = allocate_record_array(size);
    if (!*records) {
        free(*offsets);
        free(*keys);
        *error_code = -3;
        return -1; // Allocation failed
    }

    init_random_records(*records, size, 0, 100); // Initialize records with random values between 0 and 100

    *error_code = 0;
    return 0; // Success
}

void free_memory(long* offsets, int* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
}

