#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_STRING_LENGTH 64

typedef struct {
    int value;
    char string[MAX_STRING_LENGTH];
} record;

unsigned long xorshift128plus() {
    static unsigned long x = 123456789, y = 362436069, z = 521288629, w = 88675123;
    unsigned long t;

    t = x ^ (x << 11);
    x = y; y = z; z = w;
    return w = (w ^ (w >> 19)) + (t ^ (t >> 8));
}

void populate_records(record* records, int* keys, long* offsets, int size) {
    for (int i = 0; i < size; ++i) {
        keys[i] = xorshift128plus();
        sprintf(records[i].string, "String%04d", i);
        records[i].value = keys[i];
    }
}

void sort_records(record* records, int size) {
    for (int i = 0; i < size - 1; ++i) {
        for (int j = i + 1; j < size; ++j) {
            if (records[i].value < records[j].value || 
                (records[i].value == records[j].value && strcmp(records[i].string, records[j].string) > 0)) {
                record temp = records[i];
                records[i] = records[j];
                records[j] = temp;
            }
        }
    }
}

void manage_dataset(int size) {
    long* offsets = (long*)malloc(size * sizeof(long));
    int* keys = (int*)malloc(size * sizeof(int));
    record* records = (record*)malloc(size * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    populate_records(records, keys, offsets, size);
    sort_records(records, size);

    // Output sorted records
    for (int i = 0; i < size; ++i) {
        printf("Value: %d, String: %s\n", records[i].value, records[i].string);
    }

    free(offsets);
    free(keys);
    free(records);
}

int main() {
    srand(time(NULL));
    int dataset_size = 10000; // Configurable dataset size
    manage_dataset(dataset_size);
    return 0;
}
