    retain_duplicates: bool,
) -> Result<(), Box<dyn Error>> {
    let mut stream_count = 0;
    let records = Arc::new(Mutex::new(Vec::new()));

    for stream in listener.incoming() {
        if stream_count >= connection_limit {
            break;
        }

        match stream {
            Ok(mut stream) => {
                stream.set_read_timeout(Some(Duration::from_secs(5)))?;
                process_stream(&mut stream, allow_negative, log_level)?;
                stream_count += 1;
            }
            Err(e) => {
                eprintln!("Connection error: {}", e);
            }
        }

        if stream_count >= connection_limit {
            break;
        }
    }

    let mut records = records.lock().unwrap();
    if sort_ascending {
        records.sort_by(|a, b| a.value.cmp(&b.value));
    } else {
        records.sort_by(|a, b| b.value.cmp(&a.value));
    }

    if retain_duplicates {
        // Retain duplicates
    } else {
        let mut seen = HashMap::new();
        records.retain(|record| {
            if seen.contains_key(&record.value) {
                false
            } else {
                seen.insert(record.value, true);
                true
            }
        });
    }

    Ok(())
}

fn process_stream(
    stream: &mut TcpStream,
    allow_negative: bool,
    log_level: u8,
) -> Result<(), Box<dyn Error>> {
    let mut buffer = [0; 1024];
    while let Ok(n) = stream.read(&mut buffer) {
        if n == 0 {
            break;
        }

        for chunk in buffer[..n].chunks(4) {
            if chunk.len() != 4 {
                eprintln!("Malformed input");
                continue;
            }

            let value = i32::from_le_bytes(chunk.try_into().unwrap());
            if allow_negative || value >= 0 {
                records.lock().unwrap().push(Record { value });
            }
        }
    }

    Ok(())
}
```']

