import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class CryptoWalletTransactionSystem {
    private static final int SEED_VALUE = 123456789;
    private static final int RECORD_COUNT = 100000;
    private static final int MAX_CONCURRENT_REQUESTS = 10;

    private long[] offsets;
    private int[] keys;
    private Record[] records;
    private Set<Long> uniqueIds;
    private Lock lock;

    public CryptoWalletTransactionSystem() {
        offsets = new long[RECORD_COUNT];
        keys = new int[RECORD_COUNT];
        records = new Record[RECORD_COUNT];
        uniqueIds = new HashSet<>();
        lock = new ReentrantLock();

        initializeRecordStructures();
        generateRandomTransactions(SEED_VALUE);
    }

    private void initializeRecordStructures() {
        for (int i = 0; i < RECORD_COUNT; i++) {
            records[i] = new Record(0, 0);
        }
    }

    private void generateRandomTransactions(int seed) {
        java.util.Random random = new java.util.Random(seed);

        for (int i = 0; i < RECORD_COUNT; i++) {
            offsets[i] = random.nextLong();
            keys[i] = random.nextInt(Integer.MAX_VALUE);
            records[i].offset = offsets[i];
            records[i].key = keys[i];

            uniqueIds.add(offsets[i]);
        }
    }

    public boolean validateTransactions(int[] transactionIds) {
        long startTime = System.nanoTime();

        lock.lock();
        try {
            Set<Long> seenIds = new HashSet<>();
            for (int id : transactionIds) {
                if (!uniqueIds.contains(id)) {
                    return false;
                }
                if (seenIds.contains(id)) {
                    return false;
                }
                seenIds.add(id);
            }
        } finally {
            lock.unlock();
        }

        long endTime = System.nanoTime();
        System.out.println("Validation time: " + (endTime - startTime) / 1e6 + " ms");

        return true;
    }

    public static void main(String[] args) {
        CryptoWalletTransactionSystem system = new CryptoWalletTransactionSystem();

        int[] transactionIds = {1, 2, 3, 4, 5};
        boolean isValid = system.validateTransactions(transactionIds);
        System.out.println("Transactions are " + (isValid ? "valid" : "invalid"));
    }

    static class Record {
        long offset;
        int key;

        public Record(long offset, int key) {
            this.offset = offset;
            this.key = key;
        }
    }
}
