#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long accountID;
    double transactionAmount;
} transaction;

unsigned long xorshift128plus() {
    static unsigned long s[4];
    if (s[3] == 0) {
        srand(time(NULL));
        for (int i = 0; i < 4; ++i) {
            s[i] = rand();
        }
    }
    unsigned long t = s[3];
    s[3] = s[2];
    s[2] = s[1];
    s[1] = s[0];
    s[0] = s[0] ^ (s[0] << 23);
    s[0] ^= s[3] ^ (s[3] >> 18) ^ (t ^ (t << 5));
    return s[0] + t;
}

double generateUniqueRandom(double min, double max) {
    static unsigned long lastGenerated = 0;
    unsigned long current = xorshift128plus();
    while (current == lastGenerated) {
        current = xorshift128plus();
    }
    lastGenerated = current;
    return min + ((double)current / RAND_MAX) * (max - min);
}

transaction* allocateTransactions(long numAccounts, double minAmount, double maxAmount, int* errorCode) {
    if (numAccounts <= 0 || minAmount >= maxAmount) {
        *errorCode = -1; // Invalid input parameters
        return NULL;
    }

    transaction* transactions = malloc(numAccounts * sizeof(transaction));
    if (transactions == NULL) {
        *errorCode = -2; // Memory allocation failed
        return NULL;
    }

    int retries = 0;
    while (retries < numAccounts) {
        for (long i = 0; i < numAccounts; ++i) {
            double amount = generateUniqueRandom(minAmount, maxAmount);
            int foundDuplicate = 0;
            for (long j = 0; j < i; ++j) {
                if (transactions[j].transactionAmount == amount) {
                    foundDuplicate = 1;
                    break;
                }
            }
            if (foundDuplicate) {
                retries++;
                continue;
            }

            transactions[i].accountID = i + 1;
            transactions[i].transactionAmount = amount;
        }
        if (retries < numAccounts) {
            free(transactions);
            transactions = NULL;
            retries = 0;
        } else {
            break;
        }
    }

    *errorCode = retries == numAccounts ? -3 : 0; // Retry limit reached or success
    return transactions;
}

int main() {
    int errorCode;
    transaction* transactions = allocateTransactions(100, 0.0, 1000.0, &errorCode);
    if (transactions != NULL) {
        for (long i = 0; i < 100; ++i) {
            printf("Account ID: %ld, Transaction Amount: %.2f\n", transactions[i].accountID, transactions[i].transactionAmount);
        }
        free(transactions);
    } else {
        switch (errorCode) {
            case -1:
                printf("Error: Invalid input parameters.\n");
                break;
            case -2:
                printf("Error: Memory allocation failed.\n");
                break;
            case -3:
                printf("Error: Retry limit reached for unique random generation.\n");
                break;
        }
    }
    return 0;
}
