#include <stdlib.h>
#include <time.h>

#define SEED 12345

typedef struct {
    int value;
} Record;

Record* create_records(int num_records, int min_value, int max_value) {
    if (num_records <= 0 || min_value > max_value) {
        return NULL; // Invalid input
    }

    srand(SEED);
    time_t now = time(NULL);
    if (now == -1) {
        return NULL; // Time function failed
    }
    srand(now);

    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_records; ++i) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
    }

    return records;
}

void free_records(Record* records, int num_records) {
    if (records) {
        free(records);
    }
}
