typedef struct {
    int value;
} record;

void* initialize_data_structure(void* arg) {
    long* offset_array = (long*)malloc(1000 * sizeof(long));
    int* key_array = (int*)malloc(1000 * sizeof(int));
    record* record_array = (record*)malloc(1000 * sizeof(record));

    if (!offset_array || !key_array || !record_array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    srand(time(NULL));

    for (int i = 0; i < 1000; i++) {
        pthread_mutex_lock(&mutex);
        key_array[i] = i;
        record_array[i].value = rand() % 1000; // Random value between 0 and 999
        offset_array[i] = (long)i * sizeof(record);
        pthread_mutex_unlock(&mutex);
    }

    free(offset_array);
    free(key_array);
    free(record_array);

    return NULL;
}

int main() {
    pthread_t thread_id;

    if (pthread_create(&thread_id, NULL, initialize_data_structure, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    pthread_join(thread_id, NULL);

    return 0;
}
