int processAndFindMax(int *records, int limit, int range_start, int range_end, int **max_record) {
    // Allocate memory for records
    *max_record = (int *)malloc(limit * sizeof(int));
    if (!*max_record) {
        return -1; // Memory allocation failure
    }

    // Populate records with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < limit; i++) {
        (*max_record)[i] = rand() % (range_end - range_start + 1) + range_start;
    }

    // Find and return the maximum record value
    int max_value = *max_record[0];
    for (int i = 1; i < limit; i++) {
        if ((*max_record)[i] > max_value) {
            max_value = (*max_record)[i];
        }
    }

    free(*max_record);
    return max_value;
