#define MAX_THREADS 10

typedef struct {
    double amount;
} Transaction;

struct ArrayManager {
    long *offsets;
    int *identifiers;
    Transaction *transactions;
    size_t size;
    FILE *log_file;
    pthread_mutex_t lock;
};

void initialize_array_manager(struct ArrayManager *manager, size_t size, const char *log_filename) {
    manager->size = size;
    manager->log_file = fopen(log_filename, "a");
    if (!manager->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&manager->lock, NULL);

    manager->offsets = malloc(size * sizeof(long));
    manager->identifiers = malloc(size * sizeof(int));
    manager->transactions = malloc(size * sizeof(Transaction));

    if (!manager->offsets || !manager->identifiers || !manager->transactions) {
        perror("Memory allocation failed");
        fclose(manager->log_file);
        pthread_mutex_destroy(&manager->lock);
        exit(EXIT_FAILURE);
    }
}

void populate_transactions(struct ArrayManager *manager, double min_value, double max_value) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        // Pseudo-random number generation
        double random_amount = min_value + (max_value - min_value) * rand() / RAND_MAX;
        manager->transactions[i].amount = random_amount;

        // Log the transaction for debugging and performance analysis
        fprintf(manager->log_file, "Transaction %zu: Amount=%.2f\n", i, random_amount);
    }
    pthread_mutex_unlock(&manager->lock);
}

void free_array_manager(struct ArrayManager *manager) {
    pthread_mutex_lock(&manager->lock);
    fclose(manager->log_file);
    free(manager->offsets);
    free(manager->identifiers);
    free(manager->transactions);
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    struct ArrayManager manager;
    initialize_array_manager(&manager, 1000, "transaction_log.txt");

    populate_transactions(&manager, 10.0, 500.0);

    free_array_manager(&manager);

    return 0;
}
