import subprocess
from datetime import datetime

def modify_kickstart_config(file_path, placeholders):
    with open(file_path, 'r') as file:
        content = file.read()

    for placeholder, value in placeholders.items():
        content = content.replace(placeholder, str(value))

    encrypted_password = "encryptedPassword123"
    new_line = f"PASSWD {encrypted_password}\n"
    updated_content = content + new_line

    new_file_path = f"{file_path}.updated"
    with open(new_file_path, 'w') as file:
        file.write(updated_content)

    subprocess.run(['sed', '-i', f's/TEMP_PASSWORD/{encrypted_password}/g', new_file_path])

def validate_transaction_ids(transaction_ids, seed_values):
    from random import seed, randint

    seed(seed_values)

    offset = [0] * 1000
    key = [0] * 1000
    record = [{'offset': 0, 'key': 0}] * 1000

    start_time = datetime.now()

    for i in range(len(transaction_ids)):
        if transaction_ids[i] in transaction_ids[:i]:
            print(f"Transaction ID {transaction_ids[i]} is not unique.")
            return False

        offset[i] = randint(0, 999)
        key[i] = randint(0, 999)

        record[i]['offset'] = offset[i]
        record[i]['key'] = key[i]

    end_time = datetime.now()
    print(f"Validation time: {end_time - start_time}")

    return True

