import java.util.HashSet;
import java.util.Random;

public class TransactionValidator {
    private static final int NUM_SEEDS = 3;
    private static final int MAX_TRANSACTION_IDS = 1000;

    public static void main(String[] args) {
        HashSet<String> transactionIds = new HashSet<>();
        Random random = new Random();

        for (int i = 0; i < NUM_SEEDS; i++) {
            String transactionId = "TXN" + random.nextInt(MAX_TRANSACTION_IDS);
            while (!transactionIds.add(transactionId)) {
                transactionId = "TXN" + random.nextInt(MAX_TRANSACTION_IDS);
            }
            System.out.println("Transaction ID: " + transactionId);
        }
    }
}
