}

// Function to perform DNS resolution and return the IP address
int dns_resolution(const char *hostname, u_char **ip_address) {
    struct in_addr addr;
    int result;

    // Initialize resolver library
    if ((result = res_init()) != 0) {
        // Handle resolver initialization error
        return -1;
    }

    // Perform DNS resolution
    if ((result = gethostbyname_r(hostname, (struct hostent *)malloc(sizeof(struct hostent)), NULL, sizeof(struct hostent), (char *)&addr, sizeof(addr))) == 0) {
        *ip_address = (u_char *)&addr.s_addr;
    } else {
        // Handle DNS resolution error
        freeaddrinfo((struct addrinfo *)result);
        return -1;
    }

    return 0;
}
