    // Fill offsets and keys arrays with random values
    for (long i = 0; i < num_records; i++) {
        offsets[i] = rand();
        keys[i] = rand();

        // Generate random values within the specified range
        (*records)[i].value = min_value + rand() % (max_value - min_value + 1);
    }
