#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
    long timestamp;
    int purpose_code;
} record;

typedef struct {
    long offset_values[MAX_RECORDS];
    pthread_mutex_t offset_lock;
} offset_store;

typedef struct {
    int keys[MAX_RECORDS];
    pthread_mutex_t key_lock;
} key_store;

typedef struct {
    record records[MAX_RECORDS];
    pthread_mutex_t record_lock;
} record_store;

void init_stores(offset_store *offsets, key_store *keys, record_store *records) {
    pthread_mutex_init(&offsets->offset_lock, NULL);
    pthread_mutex_init(&keys->key_lock, NULL);
    pthread_mutex_init(&records->record_lock, NULL);
}

void generate_random_values(long *values, int count, int min, int max) {
    for (int i = 0; i < count; ++i) {
        values[i] = rand() % (max - min + 1) + min;
    }
}

void populate_stores(offset_store *offsets, key_store *keys, record_store *records, int seed) {
    srand(seed);
    pthread_mutex_lock(&offsets->offset_lock);
    generate_random_values(offsets->offset_values, MAX_RECORDS, 0, 1000000);
    pthread_mutex_unlock(&offsets->offset_lock);

    pthread_mutex_lock(&keys->key_lock);
    generate_random_values(keys->keys, MAX_RECORDS, 100, 999);
    pthread_mutex_unlock(&keys->key_lock);

    pthread_mutex_lock(&records->record_lock);
    for (int i = 0; i < MAX_RECORDS; ++i) {
        records->records[i].value = rand() % (1000 - (-1000)) + (-1000);
        records->records[i].timestamp = time(NULL);
        records->records[i].purpose_code = rand() % 256;
    }
    pthread_mutex_unlock(&records->record_lock);
}

void reset_seed(int new_seed) {
    srand(new_seed);
}

void free_stores(offset_store *offsets, key_store *keys, record_store *records) {
    pthread_mutex_destroy(&offsets->offset_lock);
    pthread_mutex_destroy(&keys->key_lock);
    pthread_mutex_destroy(&records->record_lock);
}

void log_creation_or_modification(record *r, const char *action) {
    printf("%s at time %ld with purpose code %d\n", action, r->timestamp, r->purpose_code);
}
