void allocate_and_initialize(int *sizes, int size_count, int min_val, int max_val) {
    if (sizes == NULL || size_count <= 0 || min_val >= max_val) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    srand(time(NULL));

    record **records = malloc(size_count * sizeof(record *));
    if (records == NULL) {
        perror("Failed to allocate memory for records array.");
        return;
    }

    for (int i = 0; i < size_count; ++i) {
        int count = sizes[i];
        if (count <= 0) {
            fprintf(stderr, "Invalid size for record %d: %d\n", i, count);
            continue;
        }

        records[i] = malloc(count * sizeof(record));
        if (records[i] == NULL) {
            perror("Failed to allocate memory for record array.");
            // Handle error, possibly free previously allocated memory
            return;
        }

        for (int j = 0; j < count; ++j) {
            records[i][j].value = min_val + rand() % (max_val - min_val + 1);
        }
    }

    // Use the records array as needed

    // Free allocated memory
    for (int i = 0; i < size_count; ++i) {
        if (records[i] != NULL) {
            free(records[i]);
        }
    }
    free(records);
