#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_DESCRIPTION_LENGTH 256

typedef struct Transaction {
    unsigned long id;
    double amount;
    unsigned int timestamp;
    char description[MAX_DESCRIPTION_LENGTH];
} Transaction;

typedef struct Node {
    Transaction data;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insert_transaction(List* list, Transaction transaction) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = transaction;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void remove_transaction(List* list, unsigned long id) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL) {
        if (current->data.id == id) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void sort_transactions(List* list) {
    // Sorting logic can be implemented here using a stable sorting algorithm
}

Node* search_transaction_range(List* list, double min_amount, double max_amount) {
    Node* result_head = NULL;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.amount >= min_amount && current->data.amount <= max_amount) {
            Node* new_node = (Node*)malloc(sizeof(Node));
            new_node->data = current->data;
            new_node->next = result_head;
            result_head = new_node;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);

    return result_head;
}

void free_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}
