int allocateResources(long maxOffsetSize, int maxKeySize, int maxRecordSize, long **offsets, int **keys, Record ***records, LogEntry **logs) {
    if (maxOffsetSize <= 0 || maxKeySize <= 0 || maxRecordSize <= 0) {
        return -1; // Invalid size limit
    }

    *offsets = (long*)malloc(maxOffsetSize * sizeof(long));
    if (*offsets == NULL) {
        return -2; // Memory allocation failed for offsets
    }

    *keys = (int*)malloc(maxKeySize * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return -3; // Memory allocation failed for keys
    }

    *records = (Record**)malloc(maxRecordSize * sizeof(Record*));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -4; // Memory allocation failed for records
    }

    *logs = (LogEntry*)malloc(maxRecordSize * sizeof(LogEntry));
    if (*logs == NULL) {
        free(*offsets);
        free(*keys);
        free(*records);
        return -5; // Memory allocation failed for logs
    }

    srandom(time(NULL)); // Seed the PRNG

    for (int i = 0; i < maxRecordSize; i++) {
        (*records)[i] = (Record*)malloc(sizeof(Record));
        if ((*records)[i] == NULL) {
            free(*offsets);
            free(*keys);
            for (int j = 0; j < i; j++) {
                free((*records)[j]);
            }
            free(*logs);
            return -6; // Memory allocation failed for a record
        }

        (*records)[i]->value = random() % maxRecordSize; // Populate with random values
    }

    // Log initialization
    time_t current_time;
    struct tm *time_info;

    for (int i = 0; i < maxRecordSize; i++) {
        time(&current_time);
        time_info = localtime(&current_time);
        strftime((*logs)[i].message, sizeof((*logs)[i].message), "%Y-%m-%d %H:%M:%S", time_info);
        sprintf((*logs)[i].message + strlen((*logs)[i].message), "Record %d created with value %d", i, (*records)[i]->value);
    }

    return 0; // Success
}

void freeResources(long *offsets, int *keys, Record **records, LogEntry *logs, int maxRecordSize) {
    for (int i = 0; i < maxRecordSize; i++) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
