            $envKey = strtoupper(str_replace('.', '_', $key));
            $value = getenv($envKey);
            if ($value === false) {
                throw new Exception("Missing configuration for: $key");
            }
            self::$cache[$key] = $value;
        }
        return self::$cache[$key];
    }

    public static function validate($config, $expected) {
        foreach ($expected as $key => $type) {
            if (!isset($config[$key]) || gettype($config[$key]) !== $type) {
                throw new Exception("Invalid configuration: $key");
            }
        }
    }
}

