#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <openssl/rand.h>

#define TRANSACTION_ID_LENGTH 16

typedef struct {
    double* amounts;
    unsigned long* timestamps;
    char** ids;
    size_t size;
    size_t capacity;
} TransactionData;

void init_transaction_data(TransactionData* data, size_t initial_capacity) {
    data->amounts = (double*)malloc(initial_capacity * sizeof(double));
    data->timestamps = (unsigned long*)malloc(initial_capacity * sizeof(unsigned long));
    data->ids = (char**)malloc(initial_capacity * sizeof(char*));
    for (size_t i = 0; i < initial_capacity; ++i) {
        data->ids[i] = (char*)malloc(TRANSACTION_ID_LENGTH);
    }
    data->size = 0;
    data->capacity = initial_capacity;
}

void free_transaction_data(TransactionData* data) {
    for (size_t i = 0; i < data->size; ++i) {
        free(data->ids[i]);
    }
    free(data->amounts);
    free(data->timestamps);
    free(data->ids);
}

void resize_transaction_data(TransactionData* data, size_t new_capacity) {
    double* new_amounts = (double*)realloc(data->amounts, new_capacity * sizeof(double));
    unsigned long* new_timestamps = (unsigned long*)realloc(data->timestamps, new_capacity * sizeof(unsigned long));
    char** new_ids = (char**)realloc(data->ids, new_capacity * sizeof(char*));

    for (size_t i = data->size; i < new_capacity; ++i) {
        new_ids[i] = (char*)malloc(TRANSACTION_ID_LENGTH);
    }

    data->amounts = new_amounts;
    data->timestamps = new_timestamps;
    data->ids = new_ids;
    data->capacity = new_capacity;
}

void add_transaction(TransactionData* data, double amount, unsigned long timestamp) {
    if (data->size >= data->capacity) {
        resize_transaction_data(data, data->capacity * 2);
    }
    data->amounts[data->size] = amount;
    data->timestamps[data->size] = timestamp;
    RAND_bytes((unsigned char*)data->ids[data->size], TRANSACTION_ID_LENGTH - 1);
    data->ids[data->size][TRANSACTION_ID_LENGTH - 1] = '\0';
    ++data->size;
}

void print_transactions(TransactionData* data) {
    for (size_t i = 0; i < data->size; ++i) {
        printf("Transaction %zu: Amount=%f, Timestamp=%lu, ID=%s\n", 
               i, data->amounts[i], data->timestamps[i], data->ids[i]);
    }
}

int main() {
    srand(time(NULL));
    OpenSSL_add_all_algorithms();
    ERR_load_crypto_strings();

    TransactionData transactions;
    init_transaction_data(&transactions, 1024);

    for (size_t i = 0; i < 10000; ++i) {
        add_transaction(&transactions, (double)i * 1.5, (unsigned long)(time(NULL) + i));
    }

    print_transactions(&transactions);

    free_transaction_data(&transactions);
    EVP_cleanup();

    return 0;
}
