#define ERROR_CODE -1

int findAndPrintLargest(int* records, int size) {
    if (size <= 0) return ERROR_CODE;
    int largest = records[0];
    for (int i = 1; i < size; i++) {
        if (records[i] > largest) {
            largest = records[i];
        }
    }
    printf("Largest integer: %d\n", largest);
    return 0;
}

int generateAndProcessRecords(long* offsets, int* keys, int recordsSize, int maxValue, const char* externalDataSource) {
    if (offsets == NULL || keys == NULL || recordsSize <= 0 || maxValue <= 0 || externalDataSource == NULL) {
        return ERROR_CODE;
    }

    int* records = (int*)malloc(recordsSize * sizeof(int));
    if (records == NULL) {
        return ERROR_CODE;
    }

    srand(time(NULL)); // Seed for non-cryptographic PRNG
    for (int i = 0; i < recordsSize; i++) {
        records[i] = rand() % maxValue + 1;
    }

    FILE* file = fopen(externalDataSource, "r");
    if (file == NULL) {
        free(records);
        return ERROR_CODE;
    }

    int tempValue;
    while (fscanf(file, "%d", &tempValue) != EOF) {
        recordsSize++;
        records = realloc(records, recordsSize * sizeof(int));
        if (records == NULL) {
            fclose(file);
            return ERROR_CODE;
        }
        records[recordsSize - 1] = tempValue;
    }

    fclose(file);

    int result = findAndPrintLargest(records, recordsSize);
    free(records);

    return result;
}
