typedef struct {
    int value;
} record;

typedef struct MemoryPool {
    void* pool;
    size_t size;
    size_t used;
    struct MemoryPool* next;
} MemoryPool;

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->pool = malloc(size);
    mp->size = size;
    mp->used = 0;
    mp->next = NULL;
    return mp;
}

void free_memory_pool(MemoryPool** mp) {
    MemoryPool* current = *mp;
    while (current != NULL) {
        MemoryPool* next = current->next;
        free(current->pool);
        free(current);
        current = next;
    }
    *mp = NULL;
}

void* allocate_from_pool(MemoryPool** mp, size_t size) {
    if (*mp == NULL || (*mp)->size - (*mp)->used < size) {
        *mp = create_memory_pool(size * 1024); // Grow pool by a factor of 1024
    }
    void* ptr = (char*)(*mp)->pool + (*mp)->used;
    (*mp)->used += size;
    return ptr;
}

void initialize_arrays(MemoryPool** long_offsets, MemoryPool** int_keys) {
    *long_offsets = allocate_from_pool(long_offsets, sizeof(long));
    *int_keys = allocate_from_pool(int_keys, sizeof(int));
}

record* allocate_records(size_t count, MemoryPool** records_pool) {
    record* records = (record*)allocate_from_pool(records_pool, count * sizeof(record));
    srand(time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % 1000; // Generate a random value between 0 and 999
    }
    return records;
}

void release_memory(MemoryPool** long_offsets, MemoryPool** int_keys, MemoryPool** records_pool) {
    free_memory_pool(long_offsets);
    free_memory_pool(int_keys);
    free_memory_pool(records_pool);
}
