#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

void* init_data(size_t num_records, size_t seed_interval_ms, unsigned long initial_seed) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    record* records = malloc(num_records * sizeof(record));
    if (!records) return NULL;

    time_t last_seed_time = time(NULL);
    unsigned long current_seed = initial_seed;

    for (size_t i = 0; i < num_records; ++i) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        if (timespec_to_ms(ts) - last_seed_time > seed_interval_ms) {
            pthread_mutex_lock(&lock);
            current_seed += time(NULL);
            srand(current_seed);
            last_seed_time = timespec_to_ms(ts);
            pthread_mutex_unlock(&lock);
        }

        records[i].value = rand();
    }

    return records;
}

unsigned long timespec_to_ms(struct timespec ts) {
    return ts.tv_sec * 1000 + ts.tv_nsec / 1e6;
}
```

