} Record;

typedef struct MemoryPool {
    void* free_blocks;
    size_t block_size;
    size_t block_count;
    size_t used_count;
} MemoryPool;

void initialize_memory_pool(MemoryPool* pool, size_t block_size, size_t block_count) {
    pool->block_size = block_size;
    pool->block_count = block_count;
    pool->used_count = 0;
    pool->free_blocks = malloc(block_count * block_size);
}

void* allocate_from_pool(MemoryPool* pool) {
    if (pool->used_count == pool->block_count) return NULL; // Out of memory
    void* block = (char*)pool->free_blocks + (pool->used_count++) * pool->block_size;
    return memset(block, 0, pool->block_size);
}

void deallocate_to_pool(MemoryPool* pool, void* block) {
    // Assuming blocks are never reused in this simplified example
    --pool->used_count; // This is a simplification for demonstration purposes
}

Record* create_records(MemoryPool* pool, size_t record_count, long min_offset, long max_offset, int min_key, int max_key, double min_value, double max_value) {
    Record* records = (Record*)allocate_from_pool(pool);
    if (!records) return NULL;

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < record_count; ++i) {
        records[i].offset = min_offset + rand() % (max_offset - min_offset + 1);
        records[i].key = min_key + rand() % (max_key - min_key + 1);
        records[i].value = min_value + ((double)rand() / RAND_MAX) * (max_value - min_value);
    }

    return records;
}

void free_records(MemoryPool* pool, Record* records, size_t record_count) {
    for (size_t i = 0; i < record_count; ++i) {
        deallocate_to_pool(pool, &records[i]);
    }
    // Optionally, zero out the memory block to prevent dangling references
    memset(pool->free_blocks, 0, pool->block_size * pool->block_count);
}

int main() {
    MemoryPool pool;
    initialize_memory_pool(&pool, sizeof(Record), 1000);

    Record* records = create_records(&pool, 500, -1000, 1000, -100, 100, -10.0, 10.0);
    if (records) {
        // Process the records
        free_records(&pool, records, 500);
    }

    free(pool.free_blocks);
    return 0;
}
```

This code provides a basic framework for creating and managing records with random values within specified ranges using a memory pool. It includes initialization, allocation, deallocation, and cleanup functions. For production use, additional features such as thread safety, logging, cache management, and performance optimization would need to be implemented based on the specific requirements and constraints of the system.']

["```c
#include <stdlib.h>
#include <pthread.h>

#define POOL_SIZE 1024

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    pthread_mutex_t lock;
} memory_pool;

memory_pool *init_memory_pool(int num_elements) {
    memory_pool *pool = (memory_pool *)malloc(sizeof(memory_pool));
    if (!pool) return NULL;

    pool->offsets = (long *)calloc(num_elements, sizeof(long));
    pool->keys = (int *)calloc(num_elements, sizeof(int));
    pool->records = (record **)calloc(num_elements, sizeof(record *));
    if (!pool->offsets || !pool->keys || !pool->records) {
        free(pool);
        return NULL;
    }

    for (int i = 0; i < num_elements; i++) {
        pool->records[i] = (record *)malloc(sizeof(record));
        if (!pool->records[i]) {
            // Clean up already allocated memory
            for (int j = 0; j < i; j++) free(pool->records[j]);
            free(pool->offsets);
            free(pool->keys);
            free(pool);
            return NULL;
        }
    }

    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_memory_pool(memory_pool *pool) {
    if (!pool) return;

    for (int i = 0; i < POOL_SIZE; i++) free(pool->records[i]);
    free(pool->offsets);
    free(pool->keys);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void *get_record(memory_pool *pool, int index) {
    pthread_mutex_lock(&pool->lock);
    if (index < 0 || index >= POOL_SIZE) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    record *rec = pool->records[index];
    pthread_mutex_unlock(&pool->lock);
    return rec;
}

void free_record(memory_pool *pool, int index) {
    pthread_mutex_lock(&pool->lock);
    if (index < 0 || index >= POOL_SIZE) {
        pthread_mutex_unlock(&pool->lock);
        return;
    }
    // Assuming record is simple and doesn't need further cleanup
    pool->records[index] = NULL;
    pthread_mutex_unlock(&pool->lock);
}
```

This code provides a basic structure for managing dynamic memory allocation in a multi-threaded environment, using a memory pool to optimize resource usage. The `init_memory_pool` function initializes the pool, `get_record` and `free_record` functions manage individual records within the pool, and `destroy_memory_pool` cleans up all allocated resources. Remember that this is a simplified example and does not include advanced features such as dynamic resizing or more complex record structures."]

