#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_KEY_SIZE 256

typedef enum {
    KEY_GENERATION,
    NONCE_CREATION,
    RANDOM_SALT
} Context;

int generate_random_numbers(Context context, unsigned char *output, size_t length) {
    if (!output || length == 0) {
        fprintf(stderr, "Error: Invalid output or length\n");
        return -1;
    }

    int result = RAND_bytes(output, length);
    if (result != 1) {
        fprintf(stderr, "Error generating random numbers\n");
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <context> <output_file> <length>\n", argv[0]);
        return -1;
    }

    Context context = KEY_GENERATION;
    if (strcmp(argv[1], "nonce") == 0) {
        context = NONCE_CREATION;
    } else if (strcmp(argv[1], "salt") == 0) {
        context = RANDOM_SALT;
    } else {
        fprintf(stderr, "Invalid context: %s\n", argv[1]);
        return -1;
    }

    FILE *output_file = fopen(argv[2], "wb");
    if (!output_file) {
        perror("Error opening output file");
        return -1;
    }

    size_t length = atoi(argv[3]);
    unsigned char *output = (unsigned char *)malloc(length);
    if (!output) {
        perror("Error allocating memory");
        fclose(output_file);
        return -1;
    }

    int result = generate_random_numbers(context, output, length);
    if (result != 0) {
        free(output);
        fclose(output_file);
        return -1;
    }

    fwrite(output, 1, length, output_file);
    free(output);
    fclose(output_file);

    printf("Random numbers generated and written to %s\n", argv[2]);

    return 0;
}
