    for (int i = 0; i < NUM_RECORDS; ++i) {
        distribution[records[i].value]++;
    }
    for (int i = 0; i <= 99; ++i) {
        printf("Value %d appears %d times\n", i, distribution[i]);
    }

    pthread_exit(NULL);
}

