int RAND_int_between(int *out, int min_val, int max_val) {
    unsigned char buf[sizeof(*out)];
    if (RAND_bytes(buf, sizeof(buf)) != 1) {
        return 0; // CSPRNG failed
    }

    uint32_t val = *(uint32_t *)buf;
    val = ((val % (max_val - min_val + 1)) + min_val);
    *out = (int)val;
    return 1;
}

void free_records(record *records, size_t num_records) {
