long* allocate_offsets(long size) {
    long* offsets = (long*)malloc(size * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }
    return offsets;
}

int* allocate_keys(int size) {
    int* keys = (int*)calloc(size, sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(offsets); // Clean up in case of failure
        exit(EXIT_FAILURE);
    }
    return keys;
}

record* allocate_records(int size) {
    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(offsets); // Clean up in case of failure
        free(keys);   // Clean up in case of failure
        exit(EXIT_FAILURE);
    }
    return records;
}

void fill_records(record* records, int size, int range_min, int range_max) {
    for (int i = 0; i < size; ++i) {
        records[i].value = rand() % (range_max - range_min + 1) + range_min;
    }
}

void read_config_and_initialize(char* config_file, record** records_ptr, long* offsets_ptr, int* keys_ptr) {
    FILE* file = fopen(config_file, "r");
    if (!file) {
        perror("Failed to open configuration file");
        exit(EXIT_FAILURE);
    }

    long size;
    int range_min, range_max;

    if (fscanf(file, "%ld %d %d", &size, &range_min, &range_max) != 3) {
        fclose(file);
        perror("Error reading configuration file");
        exit(EXIT_FAILURE);
    }

    *records_ptr = allocate_records(size);
    *offsets_ptr = allocate_offsets(size);
    *keys_ptr = allocate_keys(size);

    fill_records(*records_ptr, size, range_min, range_max);

    fclose(file);
}

void cleanup(long* offsets, int* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
}
