#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
    struct Record* next;
} Record;

typedef struct LinkedList {
    Record* head;
    Record* tail;
    size_t size;
} LinkedList;

typedef struct ArrayStruct {
    long* offsets;
    int* keys;
    LinkedList records;
} ArrayStruct;

ArrayStruct* initializeArrays(size_t numRecords, int minValue, int maxValue) {
    ArrayStruct* arrays = (ArrayStruct*)malloc(sizeof(ArrayStruct));
    if (!arrays) return NULL;

    arrays->offsets = (long*)malloc(numRecords * sizeof(long));
    arrays->keys = (int*)malloc(numRecords * sizeof(int));
    arrays->records.head = NULL;
    arrays->records.tail = NULL;
    arrays->records.size = 0;

    srand(time(NULL));

    for (size_t i = 0; i < numRecords; ++i) {
        arrays->offsets[i] = rand();
        arrays->keys[i] = minValue + rand() % (maxValue - minValue + 1);

        Record* newRecord = (Record*)malloc(sizeof(Record));
        if (!newRecord) {
            // Free previously allocated memory before returning NULL
            free(arrays->offsets);
            free(arrays->keys);
            free(arrays);
            return NULL;
        }
        newRecord->value = arrays->keys[i];
        newRecord->next = NULL;

        if (arrays->records.head == NULL) {
            arrays->records.head = arrays->records.tail = newRecord;
        } else {
            arrays->records.tail->next = newRecord;
            arrays->records.tail = newRecord;
        }
        arrays->records.size++;
    }

    return arrays;
}

void freeArrays(ArrayStruct* arrays) {
    Record* current = arrays->records.head;
    while (current) {
        Record* next = current->next;
        free(current);
        current = next;
    }
    free(arrays->offsets);
    free(arrays->keys);
    free(arrays);
}

int main() {
    size_t numRecords = 1000;
    int minValue = 0;
    int maxValue = 1000;

    ArrayStruct* arrays = initializeArrays(numRecords, minValue, maxValue);
    if (arrays) {
        printf("Initialization successful.\n");
        freeArrays(arrays);
    } else {
        printf("Initialization failed.\n");
    }

    return 0;
}
