    if (num_records <= 0 || upper_bound <= 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    record *records = (record *)malloc(num_records * sizeof(record));
    if (!records) {
        perror("Memory allocation failed.");
        *memory_size = 0;
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG

    for (int i = 0; i < num_records; ++i) {
        records[i].key = rand() % upper_bound + 1; // Generate random key
    }

    *memory_size = num_records * sizeof(record);
    return records;
}

void free_records(record **records, size_t memory_size) {
    if (records && *records) {
        free(*records);
        *records = NULL;
    }
}

int main() {
    int num_records = 1000;
    int upper_bound = 100;
    size_t memory_size;

    record *random_records = allocate_random_records(num_records, upper_bound, &memory_size);
    if (random_records) {
        printf("Allocated %zu bytes for %d records.\n", memory_size, num_records);

        // Process the random records...

        free_records(&random_records, memory_size);
        printf("Records freed successfully.\n");
    }

    return 0;
}
