    if (!records || !offsets || !keys) {
        free(records);
        free(offsets);
        free(keys);
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_records; ++i) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            free(offsets);
            free(keys);
            return NULL;
        }

        pthread_mutex_lock(&mutex);

        offsets[i] = rand();
        keys[i] = rand() % (max_value - min_value + 1) + min_value;

        records[i]->id = i;
        records[i]->value = keys[i];
        records[i]->offset_ptr = &offsets[i];
        records[i]->key_ptr = &keys[i];

        pthread_mutex_unlock(&mutex);
    }

    return records;
}

void destroy_data_structures(record** records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i]);
    }
    free(records);
}
