struct AttackRecord {
    int id;
    int value;
    long* offset;
    int* key;
};

class GameCharacter {
private:
    std::vector<AttackRecord> attackPool;
    std::mutex poolMutex;
    std::condition_variable poolCV;
    std::atomic<bool> canExecute{false};
    std::mt19937 rng;
    std::uniform_int_distribution<int> dist;

public:
    GameCharacter() : rng(std::random_device{}()), dist(0, 999) {}

    void addAttackRecord(const AttackRecord& record) {
        std::lock_guard<std::mutex> lock(poolMutex);
        attackPool.push_back(record);
        poolCV.notify_one();
    }

    void selectAndExecuteAttack() {
        while (true) {
            std::unique_lock<std::mutex> lock(poolMutex);
            poolCV.wait(lock, [this] { return canExecute.load(); });
            if (!canExecute.load()) continue;

            int selectedId = dist(rng);
            AttackRecord& attack = attackPool[selectedId];
            // Execute the attack
            *attack.offset += attack.value;
            *attack.key = selectedId;

            lock.unlock();
            std::this_thread::sleep_for(std::chrono::seconds(1));
        }
    }

    void startExecution() {
        canExecute.store(true);
    }

    void stopExecution() {
        canExecute.store(false);
    }
};

int main() {
    GameCharacter character;
    // Add attack records to the pool
    // ...

    std::thread executeThread(&GameCharacter::selectAndExecuteAttack, &character);
    std::this_thread::sleep_for(std::chrono::seconds(10));
    character.stopExecution();
    executeThread.join();

    return 0;
}
