    private static void executeCommandWithRetries(String command) throws Exception {
        int maxRetries = 5;
        int retryCount = 0;

        while (retryCount < maxRetries) {
            try {
                ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
                processBuilder.redirectErrorStream(true);
                Process process = processBuilder.start();

                BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println(line);
                }

                int exitCode = process.waitFor();
                if (exitCode == 0) {
                    return;
                }
            } catch (Exception e) {
                retryCount++;
                Thread.sleep((int) Math.pow(2, retryCount) * 1000); // Exponential backoff
            }
        }

        System.err.println("Command execution failed after " + maxRetries + " retries.");
    }
}
