#define NUM_RECORDS 10

typedef struct {
    int value;
    char* str;
} record;

record* create_records() {
    record* records = (record*)malloc(NUM_RECORDS * sizeof(record));
    if (!records) return NULL;

    // Statically allocated string literals
    const char* strings[] = {"Apple", "Banana", "Cherry", "Date", "Elderberry"};
    size_t num_strings = sizeof(strings) / sizeof(strings[0]);

    for (int i = 0; i < NUM_RECORDS; ++i) {
        records[i].str = (char*)malloc(10 * sizeof(char));
        if (!records[i].str) {
            // Clean up previously allocated memory
            for (int j = 0; j < i; ++j) free(records[j].str);
            free(records);
            return NULL;
        }
        strncpy(records[i].str, strings[i % num_strings], 9);
        records[i].str[9] = '\0'; // Ensure null-termination
    }

    return records;
}

void init_records(record* records) {
    if (!records) return;

    for (int i = 0; i < NUM_RECORDS; ++i) {
        records[i].value = 0; // Initialize value to zero
    }
}

void access_record(record* records, int index) {
    if (index >= 0 && index < NUM_RECORDS) {
        records[index].value++;
    }
}

void destroy_records(record* records) {
    if (!records) return;

    for (int i = 0; i < NUM_RECORDS; ++i) {
        free(records[i].str);
    }
    free(records);
}
