#include <stdlib.h>
#include <time.h>
#include <limits.h>

typedef struct record {
    int value;
    int* key;
    long offset;
} Record;

int allocate_arrays(long num_elements, int** offsets, int** keys, Record** records) {
    *offsets = (long*)malloc(num_elements * sizeof(long));
    if (*offsets == NULL) return -1;

    *keys = (int*)malloc(num_elements * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return -1;
    }

    *records = (Record*)malloc(num_elements * sizeof(Record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -1;
    }

    srand(time(NULL)); // Seed the random number generator

    for (long i = 0; i < num_elements; i++) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand() % INT_MAX;
        (*records)[i].value = rand() % INT_MAX;
        (*records)[i].key = &(*keys)[i];
        (*records)[i].offset = (*offsets)[i];
    }

    return 0;
}

void free_arrays(int* offsets, int* keys, Record* records, long num_elements) {
    free(offsets);
    free(keys);
    free(records);
}
