#define ERROR_CODE -1

int generateAndAnalyzeData(int dataSize, int rangeMin, int rangeMax, const char* inputFile, const char* outputFile) {
    // Validate input parameters
    if (dataSize <= 0 || rangeMin > rangeMax) {
        return ERROR_CODE;
    }

    // Dynamically allocate memory for generated data
    int* generatedData = (int*)malloc(dataSize * sizeof(int));
    if (generatedData == NULL) {
        return ERROR_CODE;
    }

    // Non-cryptographic PRNG function to populate the array
    void simplePRNG(int* arr, int size, int min, int max) {
        for (int i = 0; i < size; i++) {
            arr[i] = min + rand() % (max - min + 1);
        }
    }

    // Populate the array with random integers
    simplePRNG(generatedData, dataSize, rangeMin, rangeMax);

    // Read additional integers from the input file
    FILE* in = fopen(inputFile, "r");
    if (!in) {
        free(generatedData);
        return ERROR_CODE;
    }

    int* inputFileData = NULL;
    int readFileSize = 0;

    while (fscanf(in, "%d", &readFileSize) == 1) {
        inputFileData = realloc(inputFileData, readFileSize * sizeof(int));
        if (!inputFileData) {
            fclose(in);
            free(generatedData);
            return ERROR_CODE;
        }
        inputFileData[readFileSize - 1] = fscanf(in, "%d");
    }

    fclose(in);

    // Combine and find the maximum value
    int combinedSize = dataSize + readFileSize;
    int* combinedData = (int*)malloc(combinedSize * sizeof(int));
    if (!combinedData) {
        free(generatedData);
        free(inputFileData);
        return ERROR_CODE;
    }

    for (int i = 0; i < dataSize; i++) {
        combinedData[i] = generatedData[i];
    }
    for (int i = 0; i < readFileSize; i++) {
        combinedData[dataSize + i] = inputFileData[i];
    }

    int maxValue = combinedData[0];
    for (int i = 1; i < combinedSize; i++) {
        if (combinedData[i] > maxValue) {
            maxValue = combinedData[i];
        }
    }

    // Write the maximum value to the output file
    FILE* out = fopen(outputFile, "w");
    if (!out) {
        free(generatedData);
        free(inputFileData);
        free(combinedData);
        return ERROR_CODE;
    }

    fprintf(out, "%d\n", maxValue);

    fclose(out);

    // Free allocated memory
    free(generatedData);
    free(inputFileData);
    free(combinedData);

    return 0; // Success
}
