void init_arrays(long *offsets, int *keys, record **records, size_t count, int min_val, int max_val) {
    static int reseed_counter = 0;
    const int reseed_threshold = 1000000;

    // Periodically reseed the random number generator
    if (reseed_counter++ >= reseed_threshold) {
        srand(time(NULL));
        reseed_counter = 0;
    }

    for (size_t i = 0; i < count; ++i) {
        offsets[i] = rand();
        keys[i] = rand();

        // Allocate memory for the record
        records[i] = (record *)malloc(sizeof(record));
        if (records[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for record %zu\n", i);
            exit(EXIT_FAILURE);
        }

        // Initialize the random value in the record
        records[i]->value = min_val + rand() % (max_val - min_val + 1);
    }
}

int main() {
    size_t count = 5;
    long *offsets = (long *)malloc(count * sizeof(long));
    int *keys = (int *)malloc(count * sizeof(int));
    record **records = (record **)malloc(count * sizeof(record *));

    if (offsets == NULL || keys == NULL || records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    init_arrays(offsets, keys, records, count, 100, 1000);

    // Free allocated memory
    for (size_t i = 0; i < count; ++i) {
        free(records[i]);
    }
    free(records);
    free(keys);
    free(offsets);

    return 0;
}
