#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define structures and constants
#define MAX_RECORDS 100000

typedef struct {
    int value;
} Record;

// Function prototypes
int processAndAnalyzeData(int dataSize, int minValue, int maxValue, const char* inputFile, const char* outputFile);
void generateRandomNumbers(int size, int minVal, int maxVal, int* outputArray);
void readUserInputData(const char* filePath, int** outputArray, int* count);
double calculateMin(int* array, int size);
double calculateMax(int* array, int size);
double calculateAverage(int* array, int size);
double calculateStandardDeviation(int* array, int size, double average);
void printStatistics(double minVal, double maxVal, double avg, double stdDev);

int main() {
    // Example usage
    if (processAndAnalyzeData(1000, 1, 1000, "input.txt", "output.txt") != 0) {
        printf("Error processing data.\n");
    }
    return 0;
}

int processAndAnalyzeData(int dataSize, int minValue, int maxValue, const char* inputFile, const char* outputFile) {
    // Allocate memory for arrays
    int* generatedData = (int*)malloc(dataSize * sizeof(int));
    if (!generatedData) {
        return -1; // Memory allocation failed
    }

    int* userInputData;
    int userCount = 0;
    readUserInputData(inputFile, &userInputData, &userCount);

    Record* records = (Record*)malloc(MAX_RECORDS * sizeof(Record));
    if (!records) {
        free(generatedData);
        return -1; // Memory allocation failed
    }

    // Generate random numbers
    generateRandomNumbers(dataSize, minValue, maxValue, generatedData);

    // Initialize and process records
    for (int i = 0; i < dataSize; ++i) {
        records[i].value = generatedData[i];
    }

    // Calculate statistics
    double minGen = calculateMin(generatedData, dataSize);
    double maxGen = calculateMax(generatedData, dataSize);
    double avgGen = calculateAverage(generatedData, dataSize);
    double stdDevGen = calculateStandardDeviation(generatedData, dataSize, avgGen);

    double minUser = calculateMin(userInputData, userCount);
    double maxUser = calculateMax(userInputData, userCount);
    double avgUser = calculateAverage(userInputData, userCount);
    double stdDevUser = calculateStandardDeviation(userInputData, userCount, avgUser);

    // Print statistics
    printStatistics(minGen, maxGen, avgGen, stdDevGen);
    printStatistics(minUser, maxUser, avgUser, stdDevUser);

    // Free allocated memory
    free(generatedData);
    free(records);
    free(userInputData);

    return 0;
}

void generateRandomNumbers(int size, int minVal, int maxVal, int* outputArray) {
    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        outputArray[i] = minVal + rand() % (maxVal - minVal + 1);
    }
}

void readUserInputData(const char* filePath, int** outputArray, int* count) {
    *count = 0;
    FILE* file = fopen(filePath, "r");
    if (!file) {
        return; // File not found or other error
    }

    while (fscanf(file, "%d", &(*outputArray)[*count]) != EOF) {
        (*count)++;
        if (*count >= MAX_RECORDS) {
            break; // Prevent buffer overflow
        }
    }

    fclose(file);
}

double calculateMin(int* array, int size) {
    double min = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] < min) {
            min = array[i];
        }
    }
    return min;
}

double calculateMax(int* array, int size) {
    double max = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

double calculateAverage(int* array, int size) {
    long sum = 0;
    for (int i = 0; i < size; ++i) {
        sum += array[i];
    }
    return (double)sum / size;
}

double calculateStandardDeviation(int* array, int size, double average) {
    double variance = 0.0;
    for (int i = 0; i < size; ++i) {
        double diff = array[i] - average;
        variance += diff * diff;
    }
    return sqrt(variance / size);
}

void printStatistics(double minVal, double maxVal, double avg, double stdDev) {
    printf("Min: %.2f\n", minVal);
    printf("Max: %.2f\n", maxVal);
    printf("Average: %.2f\n", avg);
    printf("Standard Deviation: %.2f\n", stdDev);
}
