#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <math.h>

// Define structures and constants

typedef struct {
    char *dataFilePath;
    // Other necessary fields for thread-specific data
} ThreadData;

typedef struct {
    int minValue;
    int maxValue;
    double average;
    double standardDeviation;
    size_t count;
} Statistics;

// Function prototypes

void* processFile(void* arg);
void aggregateStatistics(Statistics *result, Statistics *partials, int partialCount);

int main(int argc, char *argv[]) {
    if (argc < 6) {
        fprintf(stderr, "Usage: %s dataFiles outputDirectory reportFormat threadCount prngType seed\n", argv[0]);
        return 1;
    }

    // Parse command-line arguments

    int threadCount = atoi(argv[4]);
    PRNG_TYPE prngType = parsePRNGType(argv[5]);
    unsigned long seed = strtoul(argv[6], NULL, 10);

    pthread_t threads[threadCount];
    ThreadData data[threadCount];

    // Initialize shared resources and locks

    Statistics *partials = (Statistics *)malloc(threadCount * sizeof(Statistics));
    if (!partials) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    for (int i = 0; i < threadCount; ++i) {
        pthread_mutex_init(&shared_locks[i], NULL);
        memset(&partials[i], 0, sizeof(Statistics));
    }

    // Create threads and process data

    for (int i = 0; i < threadCount; ++i) {
        data[i].dataFilePath = argv[1 + i];
        if (pthread_create(&threads[i], NULL, processFile, &data[i])) {
            fprintf(stderr, "Thread creation failed\n");
            return 1;
        }
    }

    // Join threads and aggregate statistics

    for (int i = 0; i < threadCount; ++i) {
        pthread_join(threads[i], NULL);
    }

    Statistics result;
    aggregateStatistics(&result, partials, threadCount);

    // Print aggregated statistics and clean up

    printf("Aggregated Statistics:\n");
    printf("Min Value: %d\n", result.minValue);
    printf("Max Value: %d\n", result.maxValue);
    printf("Average: %.2f\n", result.average);
    printf("Standard Deviation: %.2f\n", result.standardDeviation);

    free(partials);

    return 0;
}

void* processFile(void* arg) {
    ThreadData *threadData = (ThreadData *)arg;

    // Process file and compute statistics

    FILE *file = fopen(threadData->dataFilePath, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    int value;
    Statistics localStats = { .minValue = INT_MAX, .maxValue = INT_MIN, .count = 0 };

    while (fscanf(file, "%d", &value) == 1) {
        if (value < localStats.minValue) localStats.minValue = value;
        if (value > localStats.maxValue) localStats.maxValue = value;
        localStats.count++;
    }

    fclose(file);

    // Aggregate partial results

    pthread_mutex_lock(&shared_locks[0]); // Assuming shared_locks is defined
    aggregateStatistics(&partials[0], &localStats, 1);
    pthread_mutex_unlock(&shared_locks[0]);

    return NULL;
}

void aggregateStatistics(Statistics *result, Statistics *partials, int partialCount) {
    for (int i = 0; i < partialCount; ++i) {
        if (partials[i].count > result->count) {
            *result = partials[i];
        } else {
            result->minValue = (result->minValue < partials[i].minValue) ? result->minValue : partials[i].minValue;
            result->maxValue = (result->maxValue > partials[i].maxValue) ? result->maxValue : partials[i].maxValue;
            double newCount = result->count + partials[i].count;
            double delta = partials[i].average - result->average;
            result->average = (result->count * result->average + partials[i].count * partials[i].average) / newCount;
            result->standardDeviation += delta * delta * (partials[i].count * result->count / newCount);
            result->count = newCount;
        }
    }

    if (partialCount > 1) {
        result->standardDeviation = sqrt(result->standardDeviation);
    }
}
