unsigned long custom_prng(unsigned long seed) {
    return seed * 1664525 + 1013904223;
}

void initialize_arrays(long offset_count, int key_range, unsigned long seed, 
                        long **offsets_ptr, int **keys_ptr, record **records_ptr) {
    *offsets_ptr = (long *)malloc(offset_count * sizeof(long));
    *keys_ptr = (int *)malloc(key_count * sizeof(int));
    *records_ptr = (record *)malloc(record_count * sizeof(record));

    if (*offsets_ptr == NULL || *keys_ptr == NULL || *records_ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(seed);
    for (long i = 0; i < offset_count; i++) {
        (*offsets_ptr)[i] = rand();
    }

    unsigned long prng_seed = seed;
    for (int i = 0; i < key_range; i++) {
        prng_seed = custom_prng(prng_seed);
        (*keys_ptr)[i] = prng_seed % key_range;
    }

    for (long i = 0; i < record_count; i++) {
        (*records_ptr)[i].value = rand() % key_range;
    }
}

int main() {
    long offset_count = 1000000;
    int key_range = 1000;
    unsigned long seed = time(NULL);

    long *offsets;
    int *keys;
    record *records;

    initialize_arrays(offset_count, key_range, seed, &offsets, &keys, &records);

    // Use the arrays as needed

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
