#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define NUM_LOG_ENTRIES 100

typedef struct {
    long timestamp;
    int event_type;
    char description[256];
    float log_level;
} log_entry;

// Non-cryptographic PRNG function
unsigned int xorshift32(unsigned int *state) {
    unsigned int x = *state;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    return (*state = x);
}

void generate_log_entries(log_entry **entries, long start_timestamp, long end_timestamp, int min_event_type, int max_event_type, float min_log_level, float max_log_level) {
    *entries = (log_entry *)malloc(NUM_LOG_ENTRIES * sizeof(log_entry));
    if (*entries == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    unsigned int seed = time(NULL);
    for (int i = 0; i < NUM_LOG_ENTRIES; i++) {
        long timestamp = start_timestamp + xorshift32(&seed) % (end_timestamp - start_timestamp + 1);
        (*entries)[i].timestamp = timestamp;

        int event_type = min_event_type + xorshift32(&seed) % (max_event_type - min_event_type + 1);
        (*entries)[i].event_type = event_type;

        snprintf((*entries)[i].description, sizeof((*entries)[i].description), "Event %d at %ld", event_type, timestamp);

        float log_level = min_log_level + xorshift32(&seed) / (float)UINT_MAX * (max_log_level - min_log_level);
        (*entries)[i].log_level = log_level;
    }
}

void filter_log_entries(log_entry *entries, int num_entries, int min_event_type, float min_log_level, log_entry **filtered_entries, int *num_filtered_entries) {
    *num_filtered_entries = 0;

    for (int i = 0; i < num_entries; i++) {
        if (entries[i].event_type >= min_event_type && entries[i].log_level >= min_log_level) {
            (*num_filtered_entries)++;
        }
    }

    if (*num_filtered_entries > 0) {
        *filtered_entries = (log_entry *)malloc(*num_filtered_entries * sizeof(log_entry));
        if (*filtered_entries == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }

        int j = 0;
        for (int i = 0; i < num_entries; i++) {
            if (entries[i].event_type >= min_event_type && entries[i].log_level >= min_log_level) {
                (*filtered_entries)[j++] = entries[i];
            }
        }
    } else {
        *filtered_entries = NULL;
    }
}

int main() {
    log_entry *all_logs;
    generate_log_entries(&all_logs, 1633072800, 1633159200, 1, 10, 1.0, 4.0);

    int min_event_type = 5;
    float min_log_level = 2.0;
    log_entry *filtered_logs;
    int num_filtered_logs;

    filter_log_entries(all_logs, NUM_LOG_ENTRIES, min_event_type, min_log_level, &filtered_logs, &num_filtered_logs);

    printf("Number of filtered logs: %d\n", num_filtered_logs);

    // Free allocated memory
    free(all_logs);
    if (num_filtered_logs > 0) {
        free(filtered_logs);
    }

    return 0;
}
