#include <stdlib.h>
#include <string.h>

#define CONFIG_ENTRY_SIZE 1024

typedef struct config_entry {
    char section_name[CONFIG_ENTRY_SIZE];
    char setting_name[CONFIG_ENTRY_SIZE];
    char value[CONFIG_ENTRY_SIZE];
} config_entry;

typedef struct dynamic_config {
    config_entry *entries;
    size_t count;
    size_t capacity;
} dynamic_config;

void init_dynamic_config(dynamic_config *config) {
    config->count = 0;
    config->capacity = 16; // Initial capacity
    config->entries = (config_entry *)malloc(config->capacity * sizeof(config_entry));

    if (!config->entries) {
        // Handle memory allocation failure gracefully
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void free_dynamic_config(dynamic_config *config) {
    free(config->entries);
    config->entries = NULL;
    config->count = 0;
    config->capacity = 0;
}

int add_config_entry(dynamic_config *config, const char *section_name, const char *setting_name, const char *value) {
    if (config->count == config->capacity) {
        // Resize the array
        size_t new_capacity = config->capacity * 2;
        config->entries = (config_entry *)realloc(config->entries, new_capacity * sizeof(config_entry));

        if (!config->entries) {
            // Handle memory allocation failure gracefully
            fprintf(stderr, "Memory reallocation failed\n");
            return -1;
        }

        config->capacity = new_capacity;
    }

    strcpy(config->entries[config->count].section_name, section_name);
    strcpy(config->entries[config->count].setting_name, setting_name);
    strcpy(config->entries[config->count].value, value);

    config->count++;
    return 0;
}

// Example usage
