import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class TokenGenerator {
    private static final Logger logger = LoggerFactory.getLogger(TokenGenerator.class);
    private final ConcurrentHashMap<String, Boolean> tokenCache = new ConcurrentHashMap<>();
    private final ExecutorService executorService = Executors.newFixedThreadPool(10);
    private final SecureRandom secureRandom = new SecureRandom();

    public String generateUniqueToken(String userId) {
        return executorService.submit(() -> {
            try {
                while (true) {
                    String token = generateToken();
                    if (tokenCache.putIfAbsent(token, true) == null) {
                        logger.info("Generated unique token for user: {}, Token: {}", userId, token);
                        return token;
                    }
                }
            } catch (Exception e) {
                logger.error("Failed to generate unique token for user: {}", userId, e);
                throw e;
            }
        }).get(5, TimeUnit.SECONDS); // Timeout after 5 seconds
    }

    private String generateToken() {
        byte[] bytes = new byte[16];
        secureRandom.nextBytes(bytes);
        return Base64.getEncoder().encodeToString(bytes);
    }

    public void shutdown() throws InterruptedException {
        executorService.shutdown();
        if (!executorService.awaitTermination(5, TimeUnit.MINUTES)) {
            executorService.shutdownNow();
        }
    }
}
