int allocateEventArrays(long** timestamps, int** eventIDs, Event** events, int numEvents) {
    if (numEvents <= 0) {
        return -1; // Invalid input
    }

    *timestamps = (long*)malloc(numEvents * sizeof(long));
    *eventIDs = (int*)malloc(numEvents * sizeof(int));
    *events = (Event*)malloc(numEvents * sizeof(Event));

    if (*timestamps == NULL || *eventIDs == NULL || *events == NULL) {
        free(*timestamps);
        free(*eventIDs);
        free(*events);
        return -2; // Memory allocation failed
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < numEvents; ++i) {
        (*timestamps)[i] = time(NULL); // Current timestamp
        (*eventIDs)[i] = rand() % 1000 + 1; // Pseudo-random event ID in range [1, 1000]
        (*events)[i].timestamp = (*timestamps)[i];
        (*events)[i].eventID = (*eventIDs)[i];
    }

    return 0; // Success
}

// Example usage:
int main() {
    long* timestamps;
    int* eventIDs;
    Event* events;

    const int numEvents = 100;
    int result = allocateEventArrays(&timestamps, &eventIDs, &events, numEvents);

    if (result == 0) {
        // Use the arrays
        for (int i = 0; i < numEvents; ++i) {
            printf("Timestamp: %ld, Event ID: %d\n", events[i].timestamp, events[i].eventID);
        }

        // Free allocated memory
        free(timestamps);
        free(eventIDs);
        free(events);
    } else if (result == -1) {
        printf("Invalid input.\n");
    } else if (result == -2) {
        printf("Memory allocation failed.\n");
    }

    return 0;
}
