#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/types.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    time_t timestamp;
} record;

int generate_prng_seed() {
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd == -1) {
        perror("Failed to open /dev/urandom");
        return -1;
    }
    unsigned long seed;
    ssize_t bytes_read = read(fd, &seed, sizeof(seed));
    close(fd);
    if (bytes_read != sizeof(seed)) {
        fprintf(stderr, "Failed to read random data from /dev/urandom\n");
        return -1;
    }
    return (int)seed;
}

record* allocate_records(int num_records, int key_min, int key_max, const char* audit_file) {
    if (num_records <= 0 || key_min > key_max) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    int seed = generate_prng_seed();
    if (seed == -1) {
        seed = time(NULL); // Fallback to time-based seeding
        fprintf(stderr, "Using fallback PRNG seeding\n");
    } else {
        FILE* audit = fopen(audit_file, "a");
        if (!audit) {
            perror("Failed to open audit file");
            free(records);
            return NULL;
        }
        fprintf(audit, "PRNG seed: %d\n", seed);
        fclose(audit);
    }

    srand(seed);

    for (int i = 0; i < num_records; i++) {
        records[i].offset = rand();
        records[i].key = key_min + rand() % (key_max - key_min + 1);
        records[i].timestamp = time(NULL);
    }

    return records;
}

void destroy_records(record* records, int num_records) {
    if (!records) {
        return;
    }
    free(records);
}
