    pthread_rwlock_wrlock(&rwlock);
    if (userRole == 1) { // Example condition based on user role
        cache[offset].offset = offset;
        cache[offset].key = key;
        cache[offset].record = &newEmp;
    }
    pthread_rwlock_unlock(&rwlock);

    printf("Employee retrieved and cached: %s\n", newEmp.name);
    return 1;
}

// Function to allocate memory with retry and exponential backoff
void *memoryAllocate(size_t size, unsigned long timeout) {
    unsigned long start = time(NULL);
    while (time(NULL) - start < timeout) {
        void *ptr = malloc(size);
        if (ptr != NULL) {
            return ptr;
        }
        usleep(100); // Sleep for a short duration before retrying
    }
    return NULL; // Return NULL on timeout
}

// Function to log memory allocation attempts and outcomes
int logMemoryAllocation(long offset, size_t size, int result) {
    // Example logging code here
    printf("Memory allocation at offset %ld with size %zu: %s\n", offset, size, (result == 0) ? "Failed" : "Success");
    return result;
}
