Event* createEvents(int numEvents, size_t maxMemory) {
    if (numEvents <= 0 || maxMemory <= 0) {
        return NULL; // Invalid input
    }

    size_t requiredMemory = sizeof(Event) * numEvents;
    if (requiredMemory > maxMemory) {
        return NULL; // Exceeds memory limit
    }

    Event* events = malloc(requiredMemory);
    if (events == NULL) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed PRNG
    for (int i = 0; i < numEvents; ++i) {
        events[i].timestamp = time(NULL); // Current timestamp
        events[i].eventID = rand(); // Secure random event ID
        events[i].status = (rand() % 2 == 0) ? true : false; // Balanced status with a PRNG
    }

    return events;
}
