        if (userId == null || accountType == null) {
            throw new IllegalArgumentException("User ID and account type cannot be null");
        }

        logger.info("Attempt to create account for user: {}", userId);

        boolean isAuthorized = identityService.authenticate(userId);
        if (!isAuthorized) {
            logger.error("Unauthorized access attempt for user: {}", userId);
            throw new AccessDeniedException("Access denied");
        }

        SmartContractAccount account = new SmartContractAccount(userId, accountType);

        for (BlockchainNode node : nodes) {
            try {
                node.initializeAccount(account);
            } catch (Exception e) {
                logger.error("Failed to initialize account on node: {}", node.getId(), e);
                throw new RuntimeException("Initialization failed on some nodes", e);
