    return (seed * 25214903917 + 11) % 2147483647;
}

int processSensorData(long* offsets, int* keys, record* records, long* sum, int* uniqueIDs, int* count, pthread_mutex_t* mutex, long seed) {
    for (int i = 0; i < RECORD_SIZE; i++) {
        pthread_mutex_lock(mutex);
        if (*count >= RECORD_SIZE) {
            *sum /= *count;
            *uniqueIDs = *count;
            *count = 0;
        }
        records[i].offset = offsets + i;
        records[i].key = keys + i;
        records[i].access_count = 0;
        long randomKey = customPRNG(seed);
        while (i > 0 && records[i - 1].key == &randomKey) {
            randomKey = customPRNG(seed);
        }
        *records[i].key = (int)randomKey;
        *sum += *records[i].key;
        (*count)++;
        pthread_mutex_unlock(mutex);
    }
    return RECORD_SIZE;
}

int main() {
    long offsets[RECORD_SIZE];
    int keys[RECORD_SIZE];
    record records[RECORD_SIZE];
    long sum = 0;
    int uniqueIDs = 0, count = 0;
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    srand(time(NULL));
    long seed = rand();

    int result = processSensorData(offsets, keys, records, &sum, &uniqueIDs, &count, &mutex, seed);

    printf("Unique IDs generated: %d\n", uniqueIDs);
    printf("Average value of data points processed: %ld\n", sum / count);

    pthread_mutex_destroy(&mutex);
    return 0;
}
```

This code snippet demonstrates a function `processSensorData` that processes sensor data, generates unique IDs using a custom PRNG, and calculates the average value of the data points. It includes thread synchronization using a mutex to ensure safe concurrent access. The main function initializes arrays and structures, calls the processing function, and prints the results.']

