int allocate_event_arrays(int num_events, long** timestamps, int** eventIDs, Event** events) {
    if (num_events <= 0) return -EINVAL;

    *timestamps = malloc(num_events * sizeof(long));
    *eventIDs = malloc(num_events * sizeof(int));
    *events = malloc(num_events * sizeof(Event));

    if (!*timestamps || !*eventIDs || !*events) {
        free(*timestamps);
        free(*eventIDs);
        free(*events);
        return -ENOMEM;
    }

    srand(time(NULL)); // Seed for pseudo-random number generation
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_events; i++) {
        (*timestamps)[i] = time(NULL);
        (*eventIDs)[i] = rand_r((unsigned int*)&mutex) % MAX_EVENT_ID;
        (*events)[i].timestamp = (*timestamps)[i];
        (*events)[i].eventID = (*eventIDs)[i];

        // Log successful allocation
        log_event("Allocation", num_events, i);
    }

    pthread_mutex_destroy(&mutex);

    return 0;
}

void refresh_prng_seed() {
    srand(time(NULL));
}

