void initRecords(Record *records, int count) {
    srand(time(NULL)); // Seed the PRNG for better randomness
    for (int i = 0; i < count; ++i) {
        records[i].timestamp = time(NULL); // Use current time as timestamp
        records[i].value = (double)rand() / RAND_MAX; // Generate pseudo-random value
    }
}

// Function to read floating-point numbers from standard input and store them in a dynamically allocated list
void processInput(double **list, int *size) {
    double value;
    *size = 0;

    while (scanf("%lf", &value) == 1) {
        // Double the size of the list if it's full
        if (*size % 1024 == 0) {
            *list = realloc(*list, (*size + 1024) * sizeof(double));
        }
        (*list)[(*size)++] = value;
    }

    // Resize the list to fit exactly the number of elements read
    if (size > 0) {
        *list = realloc(*list, *size * sizeof(double));
    } else {
        free(*list); // Free memory if no data was read
        *list = NULL;
    }
}

// Function to process and store data as described
void processAndStoreData(int recordCount) {
    Record *records = malloc(recordCount * sizeof(Record));
    initRecords(records, recordCount);

    double *inputList = NULL;
    int inputSize;

    printf("Enter floating-point numbers (EOF to finish):\n");
    processInput(&inputList, &inputSize);

    // Free allocated memory
    free(records);
    if (inputList != NULL) {
        free(inputList);
    }
}

int main() {
    int recordCount = 1000; // Example size for demonstration purposes
    processAndStoreData(recordCount);
    return 0;
}
