int processEventsAndFilterTransactions(event** events, int* numEvents) {
    // Allocate memory for events array
    *events = (event*)malloc(*numEvents * sizeof(event));
    if (*events == NULL) {
        return -1; // Memory allocation failed
    }

    // Initialize timestamps and event IDs using PRNG
    srand(time(NULL)); // Seed the random number generator
    for (int i = 0; i < *numEvents; i++) {
        (*events)[i].timestamp = time(NULL);
        (*events)[i].eventID = rand() % 1000; // Example PRNG for event ID
        (*events)[i].transactionID = i + 1; // Assign transaction ID sequentially
    }

    // Filter transactions (example criteria: max weighted sum in last 3 seconds)
    long currentTime = time(NULL);
    int maxWeightedSum = 0;
    int maxTransactionID = -1;

    for (int i = 0; i < *numEvents; i++) {
        if ((currentTime - (*events)[i].timestamp) <= 3) {
            // Apply transaction filtering criteria
            int weightedSum = (*events)[i].transactionID + currentTime;
            if (weightedSum > maxWeightedSum) {
                maxWeightedSum = weightedSum;
                maxTransactionID = (*events)[i].transactionID;
            }
        }
    }

    // Return the maximum weighted sum and corresponding transaction ID
    *numEvents = 1; // Update numEvents to reflect the result count
    (*events)[0].timestamp = maxWeightedSum;
    (*events)[0].eventID = 0;
    (*events)[0].transactionID = maxTransactionID;

    return 0; // Success
}
