        (*transactions)[i].id = i + 1;
        (*transactions)[i].amount = rand() % (MAX_AMOUNT - MIN_AMOUNT + 1) + MIN_AMOUNT;

        fprintf(log_file, "Timestamp: %lu, Status Code: %d, Transaction ID: %lu, Amount: %d\n",
                timestamps[i], status_codes[i], (*transactions)[i].id, (*transactions)[i].amount);
    }

    return 0;
}

int main() {
    unsigned long *timestamps = (unsigned long *)malloc(MAX_TRANSACTIONS * sizeof(unsigned long));
    int *status_codes = (int *)malloc(MAX_TRANSACTIONS * sizeof(int));
    Transaction *transactions = (Transaction *)malloc(MAX_TRANSACTIONS * sizeof(Transaction));

    FILE *log_file = fopen("transaction_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
