// Function to initialize the Event structure using a PRNG
void initEvent(Event *event) {
    srand(time(NULL));
    event->timestamp = time(NULL);
    event->eventID = rand() % 1000; // Assuming a range of 0-999 for simplicity
    event->status = (rand() % 2 == 0); // Randomly set to true or false
}

// Function to initialize the Record structure with a random value
void initRecord(Record *record, int minValue, int maxValue) {
    record->value = rand() % (maxValue - minValue + 1) + minValue;
}

// Function to allocate memory for an array of Events and related structures
int allocateEventMemory(Event **events, long **offsets, int **keys, Record ***records, Metadata ***metadata, size_t numEvents, size_t maxMemory, int minValue, int maxValue) {
    size_t totalSize = sizeof(Event) * numEvents;
    totalSize += sizeof(long) * numEvents; // Offset values
    totalSize += sizeof(int) * numEvents;  // Keys
    totalSize += sizeof(Record) * numEvents; // Records
    totalSize += sizeof(Metadata) * numEvents; // Metadata

    if (totalSize > maxMemory) {
        return -1; // Memory allocation failure
    }

    *events = malloc(totalSize);
    if (*events == NULL) {
        return -2; // Memory allocation failure
    }

    offsets = *events + numEvents;
    keys = (int **)(*events + 2 * numEvents);
    records = (Record **)(*events + 3 * numEvents);
    metadata = (Metadata **)(*events + 4 * numEvents);

    for (size_t i = 0; i < numEvents; ++i) {
        initEvent(&(*events)[i]);
        offsets[i] = malloc(sizeof(long));
        keys[i] = malloc(sizeof(int));
        records[i] = malloc(sizeof(Record));
        metadata[i] = malloc(sizeof(Metadata));

        if (offsets[i] == NULL || keys[i] == NULL || records[i] == NULL || metadata[i] == NULL) {
            free(*events);
            for (size_t j = 0; j < i; ++j) {
                free(offsets[j]);
                free(keys[j]);
                free(records[j]);
                free(metadata[j]);
            }
            return -2; // Memory allocation failure
        }

        initRecord(records[i], minValue, maxValue);
    }

    return 0; // Success
}
