import java.security.SecureRandom;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.logging.Level;
import java.util.logging.Logger;

public class TokenGenerator {
    private static final Logger logger = Logger.getLogger(TokenGenerator.class.getName());
    private final ConcurrentLinkedQueue<String> requestQueue;
    private final ConcurrentHashMap<String, String> tokenMap;
    private final SecureRandom random;
    private int concurrentGenerators;

    public TokenGenerator(int initialCapacity, int concurrentGenerators) {
        this.requestQueue = new ConcurrentLinkedQueue<>(initialCapacity);
        this.tokenMap = new ConcurrentHashMap<>(initialCapacity);
        this.random = new SecureRandom();
        this.concurrentGenerators = concurrentGenerators;
    }

    public void addRequest(String userId) {
        requestQueue.add(userId);
        startTokenGenerationThreads();
    }

    private void startTokenGenerationThreads() {
        for (int i = 0; i < concurrentGenerators; i++) {
            new Thread(this::processRequests).start();
        }
    }

    private void processRequests() {
        while (!Thread.currentThread().isInterrupted()) {
            String userId = requestQueue.poll();
            if (userId != null) {
                try {
                    String token = generateToken(userId);
                    storeToken(userId, token);
                } catch (Exception e) {
                    logger.log(Level.SEVERE, "Error processing request for user: " + userId, e);
                }
            }
        }
    }

    private String generateToken(String userId) throws Exception {
        // Simulate token generation with SecureRandom
        return UUID.randomUUID().toString();
    }

    private void storeToken(String userId, String token) {
        tokenMap.put(userId, token);
    }

    public String getToken(String userId) {
        return tokenMap.get(userId);
    }

    public static void main(String[] args) {
        TokenGenerator generator = new TokenGenerator(1000, 5);
        for (int i = 0; i < 100; i++) {
            generator.addRequest("user" + i);
        }
        // Additional code to handle health checks and log retrieval
    }
}
