void init_prng(unsigned long key) {
    srand(time(NULL) ^ getpid() ^ key);
}

long *allocate_offsets(int count) {
    return (long *)malloc(count * sizeof(long));
}

int *allocate_keys(int count) {
    return (int *)calloc(count, sizeof(int));
}

event *allocate_events(int count) {
    return (event *)realloc(NULL, count * sizeof(event));
}

void init_events(event *events, int count) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    for (int i = 0; i < count; ++i) {
        events[i].timestamp = time(NULL);
        events[i].payload_size = rand() % (1024 * 1024); // Random size between 0 and 1MB
    }

    pthread_mutex_unlock(&lock);
}

void reset_prng_state(unsigned long key) {
    init_prng(key);
}

int main() {
    unsigned long custom_key = 0x12345678;
    int count = MAX_EVENTS;

    init_prng(custom_key);
    long *offsets = allocate_offsets(count);
    int *keys = allocate_keys(count);
    event *events = allocate_events(count);

    if (offsets == NULL || keys == NULL || events == NULL) {
        perror("Memory allocation failed");
        free(offsets);
        free(keys);
        free(events);
        return EXIT_FAILURE;
    }

    init_events(events, count);

    // Use the allocated memory for processing...

    free(offsets);
    free(keys);
    free(events);

    return EXIT_SUCCESS;
}
