#include <stdlib.h>
#include <time.h>

#define MAX_LOG_LEVEL 5

typedef struct {
    int log_level;
} logRecord;

// Function prototypes
void initializePRNG(unsigned long seed);
unsigned long getLongValueInRange(long min, long max);
int getIntValueInRange(int min, int max);
logRecord* createLogRecords(int count);
void freeLogRecords(logRecord* records);

// Global PRNG state (for simplicity)
unsigned long prngState = 0;

void initializePRNG(unsigned long seed) {
    prngState = seed;
}

unsigned long getLongValueInRange(long min, long max) {
    // High-performance PRNG for long values
    prngState = prngState * 1103515245 + 12345; // Linear congruential generator
    return (prngState % (max - min + 1)) + min;
}

int getIntValueInRange(int min, int max) {
    // High-performance PRNG for int values
    prngState = prngState * 1103515245 + 12345; // Linear congruential generator
    return (prngState % (max - min + 1)) + min;
}

logRecord* createLogRecords(int count) {
    logRecord* records = calloc(count, sizeof(logRecord));
    if (!records) {
        perror("Failed to allocate memory for log records");
        exit(EXIT_FAILURE);
    }

    initializePRNG(time(NULL)); // Initialize PRNG with current time as seed

    for (int i = 0; i < count; ++i) {
        records[i].log_level = getIntValueInRange(1, MAX_LOG_LEVEL);
    }

    return records;
}

void freeLogRecords(logRecord* records) {
    if (records) {
        free(records);
    }
}
