#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>

#define MAX_EVENTS 1000
#define PAYLOAD_SIZE_RANGE_MIN 1024
#define PAYLOAD_SIZE_RANGE_MAX 8192

typedef struct {
    long offset;
    int key;
    time_t timestamp;
    size_t payload_size;
    char metadata[128];
} event;

event* allocate_and_initialize_events(size_t num_events, const char* template_str, const char* init_key) {
    if (num_events > MAX_EVENTS) {
        errno = EFBIG;
        return NULL;
    }

    srand(time(NULL) ^ getpid() ^ hash(init_key));

    event* events = malloc(num_events * sizeof(event));
    if (!events) {
        errno = ENOMEM;
        return NULL;
    }

    for (size_t i = 0; i < num_events; ++i) {
        events[i].offset = rand();
        events[i].key = rand() % 1024;
        events[i].timestamp = time(NULL);
        events[i].payload_size = PAYLOAD_SIZE_RANGE_MIN + rand() % (PAYLOAD_SIZE_RANGE_MAX - PAYLOAD_SIZE_RANGE_MIN + 1);
        snprintf(events[i].metadata, sizeof(events[i].metadata), template_str, i);
    }

    return events;
}

size_t hash(const char* str) {
    size_t hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash;
}

int main() {
    event* events = allocate_and_initialize_events(10, "Event-%d", "my_init_key");
    if (!events) {
        perror("Failed to allocate and initialize events");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < 10; ++i) {
        printf("Event %zu: Offset=%ld, Key=%d, Timestamp=%lu, Payload Size=%zu, Metadata='%s'\n",
               i, events[i].offset, events[i].key, events[i].timestamp, events[i].payload_size, events[i].metadata);
    }

    free(events);
    return EXIT_SUCCESS;
}
