typedef struct {
    int* data;
    size_t length;
} Array;

int generateAndProcessData(const char* inputFile, const char* outputFile, size_t size, unsigned int seed, size_t maxMemoryUsage) {
    if (size > maxMemoryUsage / sizeof(int)) {
        return -1; // Error: Size exceeds maximum memory usage
    }

    FILE* inFile = fopen(inputFile, "r");
    if (!inFile) {
        return -2; // Error: Unable to open input file
    }

    Array inputData;
    inputData.data = (int*)malloc(size * sizeof(int));
    if (!inputData.data) {
        fclose(inFile);
        return -3; // Error: Memory allocation failure for input data
    }
    inputData.length = 0;

    int value;
    while (fscanf(inFile, "%d", &value) == 1 && inputData.length < size) {
        inputData.data[inputData.length++] = value;
    }

    fclose(inFile);

    if (inputData.length < size) {
        free(inputData.data);
        return -4; // Error: Not enough data in input file
    }

    srand(seed);

    int* additionalData = (int*)malloc(size * sizeof(int));
    if (!additionalData) {
        free(inputData.data);
        return -5; // Error: Memory allocation failure for additional data
    }

    for (size_t i = 0; i < size; ++i) {
        additionalData[i] = rand();
    }

    Array mergedData;
    mergedData.length = 2 * size;
    mergedData.data = (int*)realloc(inputData.data, mergedData.length * sizeof(int));
    if (!mergedData.data) {
        free(additionalData);
        return -6; // Error: Memory reallocation failure for merged data
    }

    memcpy(mergedData.data + size, additionalData, size * sizeof(int));

    qsort(mergedData.data, mergedData.length, sizeof(int), (int (*)(const void*, const void*))strcmp);

    int average = 0;
    for (size_t i = 0; i < mergedData.length; ++i) {
        average += mergedData.data[i];
    }
    average /= mergedData.length;

    FILE* outFile = fopen(outputFile, "w");
    if (!outFile) {
        free(mergedData.data);
        free(additionalData);
        return -7; // Error: Unable to open output file
    }

    fprintf(outFile, "Average: %d\n", average);
    fprintf(outFile, "Largest: %d\n", mergedData.data[mergedData.length - 1]);

    fclose(outFile);
    free(mergedData.data);
    free(additionalData);

    return 0; // Success
}
