from flask import Flask, request, jsonify
import redis
from flask_limiter import Limiter
from flask_limiter.util import get_remote_address
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
limiter = Limiter(app, key_func=get_remote_address)
cache = redis.Redis(host='localhost', port=6379)

# Sample data structure to store resources
resources = {}

# CSRF protection token management (simplified example)
csrf_tokens = {}

@app.route('/update/<int:id>', methods=['POST'], decorators=[limiter.limit("10 per minute")])
def update_resource(id):
    payload = request.get_json()
    csrf_token = request.headers.get('X-CSRF-Token')

    if not validate_payload(payload) or not validate_csrf(csrf_token, id):
        return jsonify({"error": "Invalid payload or CSRF token"}), 400

    if id not in resources:
        return jsonify({"error": "Resource not found"}), 404

    new_version = resources[id]['version'] + 1
    if new_version != payload.get('version'):
        return jsonify({"error": "Version mismatch. Resource was updated concurrently."}), 428

    resources[id] = {
        **resources[id],
        **payload,
        'version': new_version
    }

    cache.delete(f'resource:{id}')
    return jsonify(resources[id])

def validate_payload(payload):
    # Validate the structure and data integrity of the payload
    required_fields = ['name', 'value']
    for field in required_fields:
        if field not in payload or not payload[field]:
            return False
    return True

def validate_csrf(csrf_token, id):
    # Manage CSRF tokens effectively across both form submissions and AJAX requests
    expected_token = csrf_tokens.get(id)
    if expected_token != csrf_token:
        return False
    return True

@app.route('/delete/<int:id>', methods=['DELETE'], decorators=[limiter.limit("10 per minute")])
def delete_resource(id):
    if id not in resources:
        return jsonify({"error": "Resource not found"}), 404

    deleted_resource = resources[id]
    resources.pop(id)
    cache.delete(f'resource:{id}')

    # Return a new resource with default values upon deletion
    default_resource = {
        'id': generate_password_hash(str(id)),
        'name': 'Deleted Resource',
        'value': None,
        'version': 0
    }
    return jsonify(default_resource)

if __name__ == '__main__':
    app.run(debug=True)
