#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>

#define ARRAY_SIZE 1000

typedef struct {
    int value;
    time_t timestamp;
} Record;

long* offsets;
int* keys;
Record* records;
time_t* timestamps;

unsigned long long seed = 0;

pthread_mutex_t lock;

void init_memory() {
    offsets = (long*)malloc(ARRAY_SIZE * sizeof(long));
    keys = (int*)malloc(ARRAY_SIZE * sizeof(int));
    records = (Record*)malloc(ARRAY_SIZE * sizeof(Record));
    timestamps = (time_t*)malloc(ARRAY_SIZE * sizeof(time_t));

    if (!offsets || !keys || !records || !timestamps) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&lock, NULL);
}

void reset_prng_seed() {
    seed = time(NULL) ^ getpid() ^ (unsigned long long)getpid();
}

unsigned long custom_random(unsigned long long *seed) {
    *seed ^= *seed << 13;
    *seed ^= *seed >> 7;
    *seed ^= *seed << 17;
    return *seed;
}

void init_records() {
    for (int i = 0; i < ARRAY_SIZE; i++) {
        pthread_mutex_lock(&lock);
        records[i].value = custom_random(&seed) % 1000 + 1; // Random value between 1 and 1000
        while (i > 0 && records[i].timestamp == timestamps[i - 1]) {
            records[i].timestamp++;
        }
        timestamps[i] = time(NULL);
        pthread_mutex_unlock(&lock);
    }
}

void* update_records(void* arg) {
    int thread_id = *(int*)arg;
    while (1) {
        sleep(5); // Periodic update interval
        pthread_mutex_lock(&lock);
        records[thread_id].value += 10; // Increment value for demonstration purposes
        while (records[thread_id].timestamp == timestamps[(thread_id + 1) % ARRAY_SIZE]) {
            records[thread_id].timestamp++;
        }
        timestamps[thread_id] = time(NULL);
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

void free_memory() {
    pthread_mutex_destroy(&lock);
    free(offsets);
    free(keys);
    free(records);
    free(timestamps);
}

int main() {
    init_memory();
    reset_prng_seed();
    init_records();

    pthread_t threads[4];
    int thread_ids[4] = {0, 1, 2, 3};

    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, update_records, &thread_ids[i]);
    }

    // Simulate data source integration
    sleep(60);

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    free_memory();

    return 0;
}
