#include <pthread.h>

typedef struct {
    long accountID;
    double transactionAmount;
} Transaction;

typedef struct {
    void* array;
    size_t elementSize;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} DynamicArray;

void initDynamicArray(DynamicArray* arr, size_t elementSize) {
    arr->array = NULL;
    arr->elementSize = elementSize;
    arr->capacity = 0;
    arr->count = 0;
    pthread_mutex_init(&arr->mutex, NULL);
}

void resizeDynamicArray(DynamicArray* arr, size_t newCapacity) {
    pthread_mutex_lock(&arr->mutex);
    if (newCapacity > arr->capacity) {
        void* newArray = realloc(arr->array, newCapacity * arr->elementSize);
        if (newArray == NULL) {
            // Handle memory allocation failure
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        arr->array = newArray;
        arr->capacity = newCapacity;
    }
    pthread_mutex_unlock(&arr->mutex);
}

void* getDynamicArrayElement(DynamicArray* arr, size_t index) {
    if (index >= arr->count) {
        // Handle out-of-bounds access
        fprintf(stderr, "Index out of bounds\n");
        return NULL;
    }
    return (char*)arr->array + index * arr->elementSize;
}

void pushDynamicArray(DynamicArray* arr, const void* element) {
    if (arr->count == arr->capacity) {
        resizeDynamicArray(arr, arr->capacity ? arr->capacity * 2 : 1);
    }
    memcpy(getDynamicArrayElement(arr, arr->count), element, arr->elementSize);
    arr->count++;
}

void destroyDynamicArray(DynamicArray* arr) {
    pthread_mutex_lock(&arr->mutex);
    free(arr->array);
    arr->array = NULL;
    arr->capacity = 0;
    arr->count = 0;
    pthread_mutex_unlock(&arr->mutex);
    pthread_mutex_destroy(&arr->mutex);
}

// Custom PRNG function
static unsigned long customPRNG(unsigned long seed) {
    // Implement your custom PRNG here
    return seed * 214013 + 2531011; // Example linear congruential generator
}

void initPRNGSeed() {
    srand(time(NULL) ^ getpid() ^ getloadavg(&avg, 1));
}

void* generateUniqueRandomValues(DynamicArray* arr, size_t count, double minValue, double maxValue) {
    if (count * sizeof(Transaction) > arr->capacity * arr->elementSize) {
        resizeDynamicArray(arr, (count + 1023) / 1024);
    }
    unsigned long seed = time(NULL) ^ getpid() ^ getloadavg(&avg, 1);
    for (size_t i = 0; i < count; i++) {
        Transaction* transaction = (Transaction*)getDynamicArrayElement(arr, i);
        do {
            transaction->accountID = customPRNG(seed++);
        } while (i > 0 && getDynamicArrayElement(arr, i - 1) == transaction); // Ensure uniqueness
        transaction->transactionAmount = minValue + (maxValue - minValue) * customPRNG(seed++) / UINT_MAX;
    }
    arr->count = count;
    return arr->array;
}

// Example usage
int main() {
    initPRNGSeed();
    DynamicArray transactionsArray;
    initDynamicArray(&transactionsArray, sizeof(Transaction));

    generateUniqueRandomValues(&transactionsArray, 1000, -1000.0, 1000.0);

    for (size_t i = 0; i < transactionsArray.count; i++) {
        Transaction* transaction = (Transaction*)getDynamicArrayElement(&transactionsArray, i);
        printf("Account ID: %ld, Transaction Amount: %.2f\n", transaction->accountID, transaction->transactionAmount);
    }

    destroyDynamicArray(&transactionsArray);
    return 0;
}
