long* allocateLongArray(int n) {
    // Allocate memory pool for long offsets
    return (long*)malloc(n * sizeof(long));
}

int* allocateIntArray(int n) {
    // Allocate memory pool for integer keys
    return (int*)malloc(n * sizeof(int));
}

Record* allocateRecords(int n, int minValue, int maxValue, pthread_mutex_t* lock) {
    Record* records = (Record*)malloc(n * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed");
        // Log error
        return NULL;
    }

    pthread_mutex_lock(lock);
    for (int i = 0; i < n; ++i) {
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }
    pthread_mutex_unlock(lock);

    return records;
}

void freeAllMemory(long* offsets, int* keys, Record* records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}

int main() {
    int n = 1000000;
    int minValue = 0, maxValue = 100;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    srand(time(NULL));

    long* offsets = allocateLongArray(n);
    if (!offsets) return -1;

    int* keys = allocateIntArray(n);
    if (!keys) {
        freeAllMemory(offsets, NULL, NULL);
        return -1;
    }

    Record* records = allocateRecords(n, minValue, maxValue, &lock);
    if (!records) {
        freeAllMemory(offsets, keys, NULL);
        return -1;
    }

    // Use records...

    freeAllMemory(offsets, keys, records);

    pthread_mutex_destroy(&lock);

    return 0;
}
