#define MAX_SESSIONS 1000

typedef struct {
    int id;
    time_t expiration;
    time_t last_accessed;
} UserSession;

UserSession* create_session_array(int size) {
    UserSession* sessions = (UserSession*)malloc(size * sizeof(UserSession));
    if (sessions == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return sessions;
}

int generate_unique_id(UserSession* sessions, int size, int range_start, int range_end) {
    srand(time(NULL)); // Seed for randomness
    int id;
    while (1) {
        id = rand() % (range_end - range_start + 1) + range_start;
        int exists = 0;
        for (int i = 0; i < size; i++) {
            if (sessions[i].id == id) {
                exists = 1;
                break;
            }
        }
        if (!exists) break;
    }
    return id;
}

void initialize_sessions(UserSession* sessions, int size, time_t start_time, time_t end_time) {
    for (int i = 0; i < size; i++) {
        sessions[i].id = generate_unique_id(sessions, i, 1000, 9999);
        sessions[i].expiration = rand() % (end_time - start_time + 1) + start_time;
        sessions[i].last_accessed = start_time;
    }
}

void free_session_array(UserSession* sessions) {
    free(sessions);
}

int main() {
    time_t now = time(NULL);
    UserSession* sessions = create_session_array(MAX_SESSIONS);
    initialize_sessions(sessions, MAX_SESSIONS, now, now + 3600);

    for (int i = 0; i < MAX_SESSIONS; i++) {
        printf("Session ID: %d, Expiration: %ld, Last Accessed: %ld\n",
               sessions[i].id, sessions[i].expiration, sessions[i].last_accessed);
    }

    free_session_array(sessions);
    return 0;
}
