#define POOL_SIZE 1000

typedef struct {
    int value;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    pthread_mutex_t mutex;
    Record* pool[POOL_SIZE];
    int pool_index;
} RecordManager;

RecordManager* create_record_manager(int n) {
    RecordManager* manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->offsets = (long*)calloc(n, sizeof(long));
    manager->keys = (int*)calloc(n, sizeof(int));
    manager->records = (Record**)calloc(n, sizeof(Record*));
    pthread_mutex_init(&manager->mutex, NULL);
    manager->pool_index = 0;

    for (int i = 0; i < POOL_SIZE; ++i) {
        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) return NULL;
        manager->pool[i] = record;
    }

    return manager;
}

void destroy_record_manager(RecordManager* manager, int n) {
    pthread_mutex_lock(&manager->mutex);

    for (int i = 0; i < n; ++i) {
        free(manager->records[i]);
    }
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);

    for (int i = 0; i < POOL_SIZE; ++i) {
        free(manager->pool[i]);
    }

    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

void populate_records(RecordManager* manager, int n, int minValue, int maxValue) {
    srand(time(NULL));
    for (int i = 0; i < n; ++i) {
        Record* record = get_record_from_pool(manager);
        if (!record) continue;
        record->value = rand() % (maxValue - minValue + 1) + minValue;
        manager->records[i] = record;
    }
}

Record* get_record_from_pool(RecordManager* manager) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->pool_index == POOL_SIZE) {
        Record* record = (Record*)malloc(sizeof(Record));
        pthread_mutex_unlock(&manager->mutex);
        return record;
    }

    Record* record = manager->pool[manager->pool_index++];
    pthread_mutex_unlock(&manager->mutex);
    return record;
}

void free_record_to_pool(RecordManager* manager, Record* record) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->pool_index >= POOL_SIZE) {
        free(record);
    } else {
        manager->pool[manager->pool_index++] = record;
    }

    pthread_mutex_unlock(&manager->mutex);
}
