#include <time.h>
#include <pthread.h>

#define MIN_VALUE 10
#define MAX_VALUE 100

typedef struct {
    int value;
} record_t;

typedef struct {
    long* offsets;
    int* keys;
    record_t** records;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} memory_pool_t;

memory_pool_t* create_memory_pool(size_t n) {
    memory_pool_t* pool = malloc(sizeof(memory_pool_t));
    if (!pool) return NULL;

    pool->offsets = malloc(n * sizeof(long));
    pool->keys = malloc(n * sizeof(int));
    pool->records = malloc(n * sizeof(record_t*));
    pool->size = 0;
    pool->capacity = n;
    pthread_mutex_init(&pool->mutex, NULL);

    if (!pool->offsets || !pool->keys || !pool->records) {
        free_memory_pool(pool);
        return NULL;
    }

    for (size_t i = 0; i < n; i++) {
        pool->records[i] = malloc(sizeof(record_t));
        if (!pool->records[i]) {
            free_memory_pool(pool);
            return NULL;
        }
        pool->offsets[i] = (long)i * sizeof(int); // Example initialization
        pool->keys[i] = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        pool->records[i]->value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
    }

    return pool;
}

void free_memory_pool(memory_pool_t* pool) {
    if (!pool) return;

    for (size_t i = 0; i < pool->capacity; i++) {
        free(pool->records[i]);
    }

    free(pool->offsets);
    free(pool->keys);
    free(pool->records);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

void* memory_pool_thread_func(void* arg) {
    memory_pool_t* pool = (memory_pool_t*)arg;
    // Example thread-safe operation
    pthread_mutex_lock(&pool->mutex);
    for (size_t i = 0; i < pool->capacity; i++) {
        pool->records[i]->value++;
    }
    pthread_mutex_unlock(&pool->mutex);
    return NULL;
}

int main() {
    srand(time(NULL));
    memory_pool_t* pool = create_memory_pool(10);
    if (!pool) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    // Example usage of the memory pool
    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, memory_pool_thread_func, pool);
    }

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    free_memory_pool(pool);
    return 0;
}
