        scanf("%d", &newData[i]);
    }

    // Merge the new data into the dataset, ensuring it does not exceed maxElements
    size_t totalSize = dataSize + inputCount;
    if (totalSize > maxElements) {
        fprintf(stderr, "Input count exceeds maximum allowed elements.\n");
        free(initialData);
        return;
    }

    void *finalDataset = realloc(initialData, totalSize * sizeof(int));
    if (!finalDataset) {
        perror("Memory reallocation failed for final dataset.");
        free(initialData);
        return;
    }
    memcpy((char *)finalDataset + dataSize * sizeof(int), newData, inputCount * sizeof(int));

    // Write the final dataset to a file
    FILE *output = fopen(outputFile, "wb");
    if (!output) {
        perror("Failed to open output file.");
        free(finalDataset);
        return;
    }

    fwrite(finalDataset, 1, totalSize * sizeof(int), output);
    fclose(output);

    // Free allocated memory
    free(finalDataset);
}

int main() {
    processAndStoreData(12345L, 1000, 2000, 'i', 100, "output.dat");
    return 0;
}
