import java.io.*;
import java.net.URL;
import java.util.*;

public class ConfigManager {
    private static final Map<String, Object> cache = new HashMap<>();
    private static String defaultConfigDir;

    public static void setDefaultConfigDir(String dir) {
        if (defaultConfigDir == null || !new File(defaultConfigDir).exists()) {
            defaultConfigDir = dir;
        }
    }

    public static Object loadConfig(String source) {
        try {
            if (source.startsWith("http")) {
                return loadFromURL(new URL(source));
            } else {
                return loadFromFile(source);
            }
        } catch (IOException | ClassNotFoundException e) {
            System.err.println("Error loading config: " + e.getMessage());
            return null;
        }
    }

    private static Object loadFromURL(URL url) throws IOException, ClassNotFoundException {
        try (InputStream in = url.openStream();
             BufferedInputStream bis = new BufferedInputStream(in);
             ObjectInputStream ois = new ObjectInputStream(bis)) {
            return ois.readObject();
        }
    }

    private static Object loadFromFile(String filePath) throws IOException, ClassNotFoundException {
        File file = new File(filePath);
        if (!file.exists()) {
            throw new FileNotFoundException("File not found: " + filePath);
        }
        try (FileInputStream fis = new FileInputStream(file);
             BufferedInputStream bis = new BufferedInputStream(fis);
             ObjectInputStream ois = new ObjectInputStream(bis)) {
            return ois.readObject();
        }
    }

    public static void clearCache() {
        cache.clear();
    }

    public static Object getFromCache(String key) {
        return cache.get(key);
    }

    public static void addToCache(String key, Object obj) {
        if (obj instanceof ConfigObject) {
            cache.put(key, obj);
        }
    }

    // Additional methods for managing large files and handling exceptions can be added here.
}
```

