#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define ERROR_CODE -1

int generateAndProcessData(int dataSize, int minValue, int maxValue, const char* inputFile, const char* outputFile, int performanceOptimization) {
    if (dataSize <= 0 || minValue > maxValue) {
        return ERROR_CODE;
    }

    // Allocate memory for arrays
    int* generatedData = (int*)malloc(dataSize * sizeof(int));
    int* fileData = NULL;
    int fileSize = 0;

    if (!generatedData) {
        return ERROR_CODE; // Memory allocation failed
    }

    // Initialize PRNG and generate random data
    srand(time(NULL));
    for (int i = 0; i < dataSize; ++i) {
        generatedData[i] = minValue + rand() % (maxValue - minValue + 1);
    }

    // Read additional data from file
    FILE* filePtr = fopen(inputFile, "r");
    if (!filePtr) {
        free(generatedData);
        return ERROR_CODE; // File open failed
    }

    while (fscanf(filePtr, "%d", &fileSize) == 1) {
        int* newFileData = realloc(fileData, fileSize * sizeof(int));
        if (!newFileData) {
            fclose(filePtr);
            free(generatedData);
            free(fileData);
            return ERROR_CODE; // Memory reallocation failed
        }
        fileData = newFileData;

        for (int i = 0; i < fileSize; ++i) {
            fscanf(filePtr, "%d", &fileData[i]);
        }
    }

    fclose(filePtr);

    // Combine data and compute mean
    int combinedSize = dataSize + fileSize;
    int* combinedData = realloc(generatedData, combinedSize * sizeof(int));
    if (!combinedData) {
        free(generatedData);
        free(fileData);
        return ERROR_CODE; // Memory reallocation failed
    }

    for (int i = 0; i < fileSize; ++i) {
        combinedData[dataSize + i] = fileData[i];
    }

    // Sort data based on performance optimization
    if (performanceOptimization == 1) {
        qsort(combinedData, combinedSize, sizeof(int), (int (*)(const void *, const void *))strcmp);
    } else {
        // Use a more memory-efficient sorting algorithm
        // Example: Bubble sort for demonstration
        for (int i = 0; i < combinedSize - 1; ++i) {
            for (int j = 0; j < combinedSize - i - 1; ++j) {
                if (combinedData[j] > combinedData[j + 1]) {
                    int temp = combinedData[j];
                    combinedData[j] = combinedData[j + 1];
                    combinedData[j + 1] = temp;
                }
            }
        }
    }

    // Compute mean
    double mean = 0;
    for (int i = 0; i < combinedSize; ++i) {
        mean += combinedData[i];
    }
    mean /= combinedSize;

    // Write result to output file
    FILE* outFile = fopen(outputFile, "w");
    if (!outFile) {
        free(generatedData);
        free(fileData);
        free(combinedData);
        return ERROR_CODE; // File open failed
    }

    fprintf(outFile, "Mean: %.2f\n", mean);

    fclose(outFile);

    // Free allocated memory
    free(generatedData);
    free(fileData);
    free(combinedData);

    return 0;
}
