fn generateRandomValue(seed: i64) -> i32 {
    // Simple non-cryptographic PRNG for demonstration
    let mut result = seed;
    result ^= result << 13;
    result ^= result >> 7;
    result ^= result << 17;
    (result as u32).wrapping_add(0x8BADF00D) as i32
}

fn generateAndProcessRecords(
    seed: i64,
    recordCount: u32,
    url: &str,
    enableSecureHttp: bool,
    maxRetryAttempts: u32,
    logLevel: LogLevels,
) -> Result<(), Box<dyn Error>> {
    let mut records = Vec::with_capacity(recordCount as usize);
    for i in 0..recordCount {
        let value = generateRandomValue(seed + i as i64);
        records.push(Record { value });
    }

    let mut client = TcpStream::connect(&url).await?;
    if !enableSecureHttp {
        // Disable certificate validation (not recommended for production)
        client.set_nodelay(true)?;
    }

    let mut input_buffer = String::new();
    io::stdin().read_to_string(&mut input_buffer)?;

    let values: Vec<i32> = input_buffer
        .lines()
        .map(|line| line.parse::<i32>().unwrap())
        .collect();

    let average_value = findAverageValue(&values).await?;
    println!("Average value: {}", average_value);

    Ok(())
}

async fn findAverageValue(values: &[i32]) -> Result<f64, Box<dyn Error>> {
    let total: i32 = values.iter().sum();
    let count = values.len();
    if count == 0 {
        return Err("No data to compute average".into());
    }
    Ok(total as f64 / count as f64)
}

fn log_message(level: LogLevels, message: &str) {
