        LogLevels::Debug => println!("DEBUG: {}", message),
        LogLevels::Info => println!("INFO: {}", message),
        LogLevels::Warning => println!("WARNING: {}", message),
        LogLevels::Error => eprintln!("ERROR: {}", message),
    }
}
