use reqwest::{Client, ClientBuilder};
use std::time::{Duration, Instant};

fn create_http_client(
    enable_tls_12: bool,
    enable_tls_13: bool,
    ca_bundle_path: &str,
    pool_size: usize,
    proxy_url: Option<&str>,
    max_concurrent_connections: usize,
) -> Client {
    let mut builder = ClientBuilder::new();

    if !enable_tls_12 && !enable_tls_13 {
        panic!("At least one TLS version must be enabled");
    }

    if enable_tls_12 {
        builder = builder.dangerously_unsafe_skip_tls_certificate_verification(false);
    } else {
        builder = builder.tls_version(reqwest::tls::Version::TLSv1_2);
    }

    if enable_tls_13 {
        builder = builder.tls_version(reqwest::tls::Version::TLSv1_3);
    }

    builder = builder.add_root_certificate(include_bytes!(ca_bundle_path).parse().unwrap());

    builder = builder.pool_max_idle_connections(pool_size);

    if let Some(proxy_url) = proxy_url {
        builder = builder.proxy(proxy_url.parse().unwrap());
    }

    builder = builder.max_concurrency(max_concurrent_connections);

    builder.build().unwrap()
}

fn make_request_with_retry(
    client: &Client,
    url: &str,
    max_retries: u32,
    retry_interval: Duration,
) -> Result<reqwest::Response, reqwest::Error> {
    let mut attempt = 0;
    loop {
        match client.get(url).send().await {
            Ok(response) => return Ok(response),
            Err(e) if attempt < max_retries => {
                attempt += 1;
                tokio::time::sleep(retry_interval * (2u32.pow(attempt)).into()).await;
            }
            Err(e) => return Err(e),
        }
    }
}

fn log_request_metrics(response: &reqwest::Response, start_time: Instant) {
    let latency = start_time.elapsed();
    println!(
        "Status: {}, Latency: {:?}, Body Size: {} bytes",
        response.status(),
        latency,
        response.content_length().unwrap_or(0)
    );
}

fn main() {
    let client = create_http_client(
        true, // Enable TLS 1.2
        false, // Disable TLS 1.3
        "/path/to/ca-bundle.crt",
        50,
        Some("http://proxy.example.com:8080"),
        100,
    );

    let url = "https://example.com";
    let start_time = Instant::now();
    match make_request_with_retry(&client, url, 3, Duration::from_secs(2)) {
        Ok(response) => log_request_metrics(&response, start_time),
        Err(e) => eprintln!("Request failed: {}", e),
    }
}
