LogEntry log_entries[MAX_LOG_ENTRIES];
int entry_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_logging_system() {
    srand(time(NULL));
}

void* add_log_entry(void* arg) {
    pthread_mutex_lock(&mutex);
    if (entry_count >= MAX_LOG_ENTRIES) {
        printf("Log entries limit reached.\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    LogEntry new_entry = *(LogEntry*)arg;
    new_entry.unique_id = rand();

    log_entries[entry_count++] = new_entry;

    pthread_mutex_unlock(&mutex);
    return NULL;
}

void* remove_log_entry(void* arg) {
    int id_to_remove = *(int*)arg;

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < entry_count; i++) {
        if (log_entries[i].unique_id == id_to_remove) {
            for (int j = i; j < entry_count - 1; j++) {
                log_entries[j] = log_entries[j + 1];
            }
            entry_count--;
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
    }

    printf("Log entry with ID %d not found.\n", id_to_remove);
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void calculate_memory_usage() {
    size_t total_memory = sizeof(LogEntry) * entry_count + entry_count * sizeof(int); // Adding space for unique IDs
    printf("Total memory used by log entries: %zu bytes\n", total_memory);
}
