#include <time.h>

typedef struct {
    int value;
} Record;

typedef struct {
    time_t timestamp;
    int status_flag;
} Metadata;

typedef struct {
    long long seed;
    int multiplier;
    int increment;
    int modulus;
} LCGState;

typedef struct {
    int *offsets;
    Record *records;
    Metadata *metadata;
    int record_count;
    pthread_mutex_t mutex;
    int max_records;
    FILE *log_file;
} DataPipeline;

DataPipeline* create_data_pipeline(int initial_record_count, int max_records, long long seed) {
    DataPipeline *pipeline = (DataPipeline*)malloc(sizeof(DataPipeline));
    if (!pipeline) return NULL;

    pipeline->offsets = (int*)malloc(initial_record_count * sizeof(int));
    pipeline->records = (Record*)malloc(initial_record_count * sizeof(Record));
    pipeline->metadata = (Metadata*)malloc(initial_record_count * sizeof(Metadata));
    pipeline->record_count = initial_record_count;
    pipeline->max_records = max_records;

    if (!pipeline->offsets || !pipeline->records || !pipeline->metadata) {
        free(pipeline);
        return NULL;
    }

    pthread_mutex_init(&pipeline->mutex, NULL);

    LCGState lcg_state = {seed, 1664525, 1013904223, 4294967295};
    for (int i = 0; i < initial_record_count; i++) {
        pipeline->offsets[i] = lcg_state.seed % initial_record_count;
        lcg_state.seed = (lcg_state.multiplier * lcg_state.seed + lcg_state.increment) % lcg_state.modulus;

        pipeline->records[i].value = rand();
        pipeline->metadata[i].timestamp = time(NULL);
        pipeline->metadata[i].status_flag = 1; // Assuming successful initialization
    }

    pipeline->log_file = fopen("pipeline.log", "w");
    if (!pipeline->log_file) {
        free(pipeline->offsets);
        free(pipeline->records);
        free(pipeline->metadata);
        pthread_mutex_destroy(&pipeline->mutex);
        free(pipeline);
        return NULL;
    }

    return pipeline;
}

void destroy_data_pipeline(DataPipeline *pipeline) {
    if (pipeline) {
        fclose(pipeline->log_file);
        free(pipeline->offsets);
        free(pipeline->records);
        free(pipeline->metadata);
        pthread_mutex_destroy(&pipeline->mutex);
        free(pipeline);
    }
}
