    let mut buffer = String::new();
    while input.read_line(&mut buffer).await? > 0 {
        println!("Read line: {}", buffer);
        buffer.clear();
    }

    // Implement reduce() method using callbacks for asynchronous reductions
    fn reduce<F>(numbers: &[i32], initial: i32, f: F) -> Result<i32, Box<dyn Error>>
    where
        F: Fn(i32, i32) -> i32,
    {
        let mut result = initial;
        for &num in numbers {
            result = f(result, num);
        }
        Ok(result)
    }

