#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

int generateAndValidateRecords(int count, int minValue, int maxValue, JavaVM *jvm, jobject inputChannelObj, jlong timeout, const char *logFile) {
    // Validate parameters
    if (count <= 0 || minValue > maxValue) {
        fprintf(stderr, "Invalid parameters\n");
        return -1;
    }

    // Initialize cryptographically secure PRNG
    srand(time(NULL));

    // Allocate memory for records
    int *records = malloc(count * sizeof(int));
    if (!records) {
        perror("Memory allocation failed");
        return -2;
    }

    // Generate random records
    for (int i = 0; i < count; ++i) {
        records[i] = rand() % (maxValue - minValue + 1) + minValue;
    }

    // Prepare to send records
    JavaEnv *env = (*jvm)->GetEnv(jvm, JNI_VERSION_1_6);
    jobject inputChannel = env->CallObjectMethod(inputChannelObj, GetMethodID(env, FindClass(env, "java/nio/SocketChannel"), "<init>", "()V"));

    // Open log file
    FILE *logfp = fopen(logFile, "a");
    if (!logfp) {
        perror("Failed to open log file");
        free(records);
        return -3;
    }

    // Send records with retransmission mechanism
    for (int i = 0; i < count; ++i) {
        int recordId = records[i];
        struct timeval start, end;
        gettimeofday(&start, NULL);

        // Non-blocking send operation
        ssize_t sent = env->CallLongMethod(inputChannelObj, GetMethodID(env, FindClass(env, "java/nio/SocketChannel"), "write", "(Ljava.nio.ByteBuffer;)I"));
        if (sent == -1) {
            perror("Send failed");
            continue;
        }

        // Log transmission attempt
        gettimeofday(&end, NULL);
        long latency = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_usec - start.tv_usec) / 1000;
        fprintf(logfp, "Record ID: %d, Transmission Latency: %ld ms\n", recordId, latency);

        // Retransmission mechanism
        int retries = 5; // Maximum number of retries
        while (sent != sizeof(recordId) && retries > 0) {
            sent = env->CallLongMethod(inputChannelObj, GetMethodID(env, FindClass(env, "java/nio/SocketChannel"), "write", "(Ljava.nio.ByteBuffer;)I"));
            if (sent == -1) {
                perror("Retransmission failed");
                retries--;
                continue;
            }
        }
    }

    // Clean up
    fclose(logfp);
    free(records);
    env->DeleteLocalRef(inputChannel);

    return 0;
}
