#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

int processAndFindMax(int limit, int minVal, int maxVal) {
    if (limit <= 0 || minVal > maxVal) {
        return -1; // Invalid parameters
    }

    record *records = malloc(limit * sizeof(record));
    if (!records) {
        return -2; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generator

    for (int i = 0; i < limit; ++i) {
        records[i].value = minVal + rand() % (maxVal - minVal + 1);
    }

    int *dynamicInts = NULL;
    int dynamicCount = 0;
    int temp;

    while (scanf("%d", &temp) != EOF) {
        dynamicInts = realloc(dynamicInts, (dynamicCount + 1) * sizeof(int));
        if (!dynamicInts) {
            free(records);
            return -3; // Memory allocation failed
        }
        dynamicInts[dynamicCount++] = temp;
    }

    int maxValFound = records[0].value;

    for (int i = 1; i < limit; ++i) {
        if (records[i].value > maxValFound) {
            maxValFound = records[i].value;
