            largest = records[i];
        }
    }
    printf("Largest number: %d\n", largest);
}

int generateAndProcessRecords(int recordCount, int minValue, int maxValue, const char* inputSource, const char* outputFile) {
    if (recordCount <= 0 || minValue > maxValue) {
        return ERROR_CODE;
    }

    srand(time(NULL)); // Seed the PRNG
    int* records = malloc(recordCount * sizeof(int));
    if (records == NULL) {
        printf("Memory allocation failed.\n");
        return ERROR_CODE;
    }

    for (int i = 0; i < recordCount; i++) {
        records[i] = minValue + rand() % (maxValue - minValue + 1);
    }

    FILE* input = fopen(inputSource, "r");
    if (!input) {
        printf("Failed to open input file.\n");
        free(records);
        return ERROR_CODE;
    }

    int currentRecord = recordCount;
    int newRecord;

    while (fscanf(input, "%d", &newRecord) == 1) {
        if (newRecord >= minValue && newRecord <= maxValue) {
            records = realloc(records, (currentRecord + 1) * sizeof(int));
            if (records == NULL) {
                printf("Memory reallocation failed.\n");
                fclose(input);
                free(records);
                return ERROR_CODE;
            }
            records[currentRecord] = newRecord;
            currentRecord++;
        }
    }

    fclose(input);

    FILE* output = fopen(outputFile, "w");
    if (!output) {
        printf("Failed to open output file.\n");
        free(records);
        return ERROR_CODE;
    }

    for (int i = 0; i < currentRecord; i++) {
        fprintf(output, "%d\n", records[i]);
    }

    fclose(output);
    free(records);

    findAndPrintLargest(records, currentRecord);

    return 0;
}
