#define ERROR_MEM_ALLOC_FAILED -2

typedef struct record {
    int value;
} Record;

long* allocate_offset_array(int size) {
    long* offset_arr = (long*)malloc(size * sizeof(long));
    if (!offset_arr) return NULL;
    return offset_arr;
}

int* allocate_key_array(int size) {
    int* key_arr = (int*)malloc(size * sizeof(int));
    if (!key_arr) return NULL;
    return key_arr;
}

Record** allocate_record_array(int size) {
    Record** record_arr = (Record**)malloc(size * sizeof(Record*));
    if (!record_arr) return NULL;
    for (int i = 0; i < size; i++) {
        record_arr[i] = (Record*)malloc(sizeof(Record));
        if (!record_arr[i]) {
            // Free previously allocated memory
            for (int j = 0; j < i; j++) free(record_arr[j]);
            free(record_arr);
            return NULL;
        }
    }
    return record_arr;
}

int generate_unique_keys(int* key_arr, int size) {
    if (!key_arr || size <= 0) return ERROR_INVALID_INPUT;

    srand(time(NULL)); // Seed the PRNG
    for (int i = 0; i < size; i++) {
        int key;
        do {
            key = rand() % MAX_KEY_RANGE;
        } while (i > 0 && key_arr[i - 1] == key); // Ensure uniqueness
        key_arr[i] = key;
    }
    return SUCCESS;
}

