    *key_ptr = allocate_key_array(num_records);
    *record_ptr = allocate_record_array(num_records);

    if (!*offset_ptr || !*key_ptr || !*record_ptr) {
        free(*offset_ptr); // Free partial allocations
        free(*key_ptr);
        for (int i = 0; i < num_records; i++) free((*record_ptr)[i]);
        free(*record_ptr);
        return ERROR_MEM_ALLOC_FAILED;
    }

    if (generate_unique_keys(*key_ptr, num_records) != SUCCESS) {
        free(*offset_ptr); // Free all allocations
        free(*key_ptr);
        for (int i = 0; i < num_records; i++) free((*record_ptr)[i]);
        free(*record_ptr);
        return ERROR_MEM_ALLOC_FAILED;
    }

    // Initialize records with some values
    for (int i = 0; i < num_records; i++) {
        (*record_ptr)[i]->value = i * 10;
    }

    return SUCCESS;
}

void free_memory(int num_records, long* offset_arr, int* key_arr, Record** record_arr) {
    free(offset_arr);
    free(key_arr);
    for (int i = 0; i < num_records; i++) free(record_arr[i]);
    free(record_arr);
}
