#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define POOL_SIZE 1024

typedef struct {
    int key;
    long offset;
} Record;

typedef struct MemoryPool {
    void** pool;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) {
        perror("Failed to allocate memory for memory pool");
        return NULL;
    }
    pool->pool = (void**)malloc(initial_size * sizeof(void*));
    if (!pool->pool) {
        perror("Failed to allocate memory for memory pool entries");
        free(pool);
        return NULL;
    }
    pool->size = initial_size;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* get_memory(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count == pool->size) {
        size_t new_size = pool->size * 2;
        void** new_pool = (void**)realloc(pool->pool, new_size * sizeof(void*));
        if (!new_pool) {
            perror("Failed to resize memory pool");
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->pool = new_pool;
        pool->size = new_size;
    }
    void* mem = pool->pool[pool->count++];
    pthread_mutex_unlock(&pool->lock);
    return mem;
}

void release_memory(MemoryPool* pool, void* mem) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->pool[i] == mem) {
            pool->pool[i] = pool->pool[--pool->count];
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

uint32_t high_performance_prng(uint32_t seed, uint32_t increment) {
    return (seed * 1664525 + increment) & 0xFFFFFFFF;
}

int initialize_records(MemoryPool* long_pool, MemoryPool* int_pool, MemoryPool* record_pool) {
    for (size_t i = 0; i < POOL_SIZE; ++i) {
        Record* record = (Record*)get_memory(record_pool);
        if (!record) {
            fprintf(stderr, "Failed to allocate memory for record\n");
            return -1;
        }
        record->key = i;
        record->offset = get_memory(long_pool);
        if (!record->offset) {
            fprintf(stderr, "Failed to allocate memory for offset\n");
            release_memory(record_pool, record);
            return -1;
        }
        // Simulate unique identifier generation with a pseudo-random number
        static uint32_t seed = time(NULL), increment = 0;
        record->key += high_performance_prng(seed++, increment++);
    }
    return 0;
}

int main() {
    MemoryPool* long_pool = create_memory_pool(POOL_SIZE);
    MemoryPool* int_pool = create_memory_pool(POOL_SIZE);
    MemoryPool* record_pool = create_memory_pool(POOL_SIZE);

    if (!long_pool || !int_pool || !record_pool) {
        return -1;
    }

    if (initialize_records(long_pool, int_pool, record_pool) != 0) {
        destroy_memory_pool(long_pool);
        destroy_memory_pool(int_pool);
        destroy_memory_pool(record_pool);
        return -1;
    }

    // Use the records...

    destroy_memory_pool(long_pool);
    destroy_memory_pool(int_pool);
    destroy_memory_pool(record_pool);

    return 0;
}
