#define MAX_RECORDS 1000

typedef struct {
    int value;
    unsigned char status;
} Record;

typedef struct {
    long offset;
    int key;
    Record records[MAX_RECORDS];
} RecordSet;

int fetchInitialData(long *offset, int *key) {
    // Simulate fetching data from an external source
    *offset = time(NULL);
    *key = rand() % 100;
    return 0; // Success
}

unsigned long xorshift32(unsigned long *x) {
    unsigned long x2 = *x ^ (*x << 11);
    *x = *x ^ (x2 ^ (*x >> 8));
    return x2 + (*x >> 19);
}

int randomIntInRange(int min, int max) {
    static unsigned long seed = time(NULL);
    unsigned long range = max - min + 1;
    unsigned long result;

    do {
        result = xorshift32(&seed) % range;
    } while (result < min);

    return result;
}

int allocateRecordSets(long *offsets, int *keys, RecordSet **sets, int numSets, int *numRecordsPerSet) {
    for (int i = 0; i < numSets; i++) {
        sets[i] = malloc(sizeof(RecordSet));
        if (!sets[i]) {
            return -1; // Memory allocation failed
        }
        offsets[i] = fetchInitialData(&offsets[i], &keys[i]);
        numRecordsPerSet[i] = randomIntInRange(1, 50); // Random number of records per set

        for (int j = 0; j < numRecordsPerSet[i]; j++) {
            sets[i]->records[j].value = randomIntInRange(1, 1000);
            sets[i]->records[j].status = (j % 2) ? 0x01 : 0x02;
        }
    }

    return 0; // Success
}

void freeRecordSets(RecordSet **sets, int numSets) {
    for (int i = 0; i < numSets; i++) {
        free(sets[i]);
    }
}

int main() {
    long offsets[10];
    int keys[10];
    RecordSet *recordSets[10];
    int numRecordsPerSet[10];

    srand(time(NULL));

    if (allocateRecordSets(offsets, keys, recordSets, 10, numRecordsPerSet) != 0) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    for (int i = 0; i < 10; i++) {
        printf("Offset: %ld, Key: %d, Num Records: %d\n", offsets[i], keys[i], numRecordsPerSet[i]);
        for (int j = 0; j < numRecordsPerSet[i]; j++) {
            printf("  Record %d: Value = %d, Status = %u\n", j, recordSets[i]->records[j].value, recordSets[i]->records[j].status);
        }
    }

    freeRecordSets(recordSets, 10);

    return 0;
}
