#include <time.h>
#include <sys/types.h>
#include <string.h>

#define MAX_KEY_LENGTH 10
#define RECORD_SIZE sizeof(long) + sizeof(int) + (MAX_KEY_LENGTH + 1)

typedef struct {
    long offset;
    int key;
    char data[MAX_KEY_LENGTH];
} Record;

int generateSecureKey() {
    unsigned int seed = getpid() ^ time(NULL);
    srand(seed);
    return rand();
}

Record* createRecords(size_t count, size_t *actualCount) {
    if (count == 0) {
        *actualCount = 0;
        return NULL;
    }

    Record *records = malloc(count * RECORD_SIZE);
    if (!records) {
        perror("Failed to allocate memory for records");
        *actualCount = 0;
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        records[i].offset = rand();
        records[i].key = generateSecureKey();
        snprintf(records[i].data, MAX_KEY_LENGTH + 1, "Data%d", records[i].key);
    }

    *actualCount = count;
    return records;
}

void freeRecords(Record *records, size_t count) {
    if (records) {
        free(records);
    }
}

int main() {
    size_t requestedCount = 100;
    size_t actualCount;

    Record *records = createRecords(requestedCount, &actualCount);

    if (records) {
        printf("Successfully created %zu records.\n", actualCount);
        // Process the records...

        freeRecords(records, actualCount);
    }

    return 0;
}
