#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRING_LENGTH 256
#define VOWELS "aeiouAEIOU"
#define CONSONANTS "bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ"

typedef struct {
    char id[MAX_STRING_LENGTH];
    pthread_mutex_t mutex;
} UniqueIdentifier;

UniqueIdentifier* create_identifier() {
    UniqueIdentifier* identifier = (UniqueIdentifier*)malloc(sizeof(UniqueIdentifier));
    if (identifier) {
        pthread_mutex_init(&identifier->mutex, NULL);
        memset(identifier->id, 0, MAX_STRING_LENGTH);
    }
    return identifier;
}

void destroy_identifier(UniqueIdentifier* identifier) {
    if (identifier) {
        pthread_mutex_destroy(&identifier->mutex);
        free(identifier);
    }
}

int count_vowels_consonants(const char* str, int* vowels, int* consonants) {
    *vowels = 0;
    *consonants = 0;
    for (const char* p = str; *p != '\0'; ++p) {
        if (strchr(VOWELS, *p)) {
            (*vowels)++;
        } else if (strchr(CONSONANTS, *p)) {
            (*consonants)++;
        }
    }
    return 0;
}

int generate_unique_id(const char* input, UniqueIdentifier* identifier) {
    pthread_mutex_lock(&identifier->mutex);
    char buffer[MAX_STRING_LENGTH];
    strncpy(buffer, input, MAX_STRING_LENGTH - 1);
    buffer[MAX_STRING_LENGTH - 1] = '\0';

    int vowels, consonants;
    count_vowels_consonants(buffer, &vowels, &consonants);

    snprintf(identifier->id, MAX_STRING_LENGTH, "%s_%d%d", buffer, vowels, consonants);
    pthread_mutex_unlock(&identifier->mutex);
    return 0;
}

// Example usage
void* thread_function(void* arg) {
    UniqueIdentifier* identifier = (UniqueIdentifier*)arg;
    const char* input = "example";
    generate_unique_id(input, identifier);
    printf("Generated ID: %s\n", identifier->id);
    return NULL;
}

int main() {
    pthread_t threads[5];
    UniqueIdentifier identifiers[5];

    for (int i = 0; i < 5; ++i) {
        identifiers[i] = *create_identifier();
        pthread_create(&threads[i], NULL, thread_function, &identifiers[i]);
    }

    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
        destroy_identifier(&identifiers[i]);
    }

    return 0;
}
