typedef enum {
    PRNG_STANDARD,
    PRNG_HIGH_PERFORMANCE
} prng_type;

typedef struct {
    int* random_values;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t lock;
} random_cache;

random_cache* create_random_cache(size_t initial_size) {
    random_cache* cache = (random_cache*)malloc(sizeof(random_cache));
    cache->random_values = (int*)malloc(initial_size * sizeof(int));
    cache->allocated_size = initial_size;
    cache->used_size = 0;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void free_random_cache(random_cache* cache) {
    free(cache->random_values);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

int get_random_value(random_cache* cache, prng_type type, int min, int max) {
    if (type == PRNG_HIGH_PERFORMANCE) {
        // Implement high-performance PRNG logic here
        return rand() % (max - min + 1) + min;
    } else {
        // Use standard PRNG
        return rand() % (max - min + 1) + min;
    }
}

data_record* allocate_record_set(size_t num_records, prng_type type, int min_key, int max_key, int min_value, int max_value, random_cache* cache) {
    data_record* records = (data_record*)malloc(num_records * sizeof(data_record));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    pthread_mutex_lock(&cache->lock);
    for (size_t i = 0; i < num_records; ++i) {
        if (cache->used_size == cache->allocated_size) {
            cache->random_values = realloc(cache->random_values, cache->allocated_size * 2 * sizeof(int));
            cache->allocated_size *= 2;
        }
        records[i].offset = get_random_value(cache, type, min_offset, max_offset);
        records[i].key = get_random_value(cache, type, min_key, max_key);
        records[i].rec.value = get_random_value(cache, type, min_value, max_value);
        records[i].rec.status = (unsigned char)get_random_value(cache, type, 0, 1); // Assuming binary status
    }
    pthread_mutex_unlock(&cache->lock);

    return records;
}

void free_record_set(data_record* records, size_t num_records) {
    free(records);
}

