    if (offsets == NULL || keys == NULL || records == NULL || numRecords <= 0) {
        return -1; // Invalid input
    }

    *records = (record *)malloc(numRecords * sizeof(record));
    if (*records == NULL) {
        return -2; // Memory allocation failed
    }

    srand(time(NULL)); // Seed PRNG with time-based value

    for (int i = 0; i < numRecords; i++) {
        (*records)[i].value = rand(); // Populate records array with random integers
    }

    int inputNum;
    int *inputArray = NULL;
    int inputCount = 0;

    while (scanf("%d", &inputNum) != EOF) {
        inputCount++;
        inputArray = realloc(inputArray, inputCount * sizeof(int));
        if (inputArray == NULL) {
            free(*records);
            return -3; // Memory allocation failed
        }
        inputArray[inputCount - 1] = inputNum;
    }

    int max = findMax(inputArray, inputCount); // Call helper function to find and print the largest integer
    printf("Maximum value: %d\n", max);

    free(*records);
    free(inputArray);

    return 0; // Success
}

int findMax(int arr[], int size) {
    if (arr == NULL || size <= 0) {
        return -1; // Invalid input
    }

    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    return max;
}
