typedef struct {
    int key;
    float value;
} record;

int process_sensor_data_and_allocate_records(float* data_stream, int data_length, record** records, int* unique_id_count, float* moving_average) {
    static int last_ids[MAX_IDS] = {0};
    static int id_index = 0;
    static int unique_ids[1000] = {0};
    static int unique_count = 0;
    static int sum_values = 0;
    static time_t start_time;
    static float average;

    if (*records == NULL) {
        *records = (record*)malloc(RECORD_SIZE * data_length);
        if (*records == NULL) {
            return -1; // Memory allocation failed
        }
    }

    for (int i = 0; i < data_length; i++) {
        record new_record;
        int id;

        do {
            id = rand() % 1000; // Custom PRNG to generate unique IDs
        } while (id == last_ids[id_index] || unique_ids[id]);

        new_record.key = id;
        new_record.value = data_stream[i];

        (*records)[i] = new_record;

        if (!unique_ids[id]) {
            unique_ids[id] = 1;
            unique_count++;
        }

        sum_values += data_stream[i];
        time_t current_time = time(NULL);
        if (start_time == 0) start_time = current_time;

        if (current_time - start_time >= 60) { // Calculate average over last minute
            average = (float)sum_values / data_length;
            sum_values = 0;
            start_time = current_time;
        }

        last_ids[id_index] = id;
        id_index = (id_index + 1) % MAX_IDS;
    }

    *unique_id_count = unique_count;
    *moving_average = average;

    return 0; // Success
}
