    srand(seed);
}

int generateRandomID() {
    return rand();
}

StreamProcessor* createProcessor(int numRecords, long* offsets, int* keys) {
    StreamProcessor* processor = (StreamProcessor*)malloc(sizeof(StreamProcessor));
    if (!processor) return NULL;

    processor->offsets = offsets;
    processor->keys = keys;
    processor->data = (record*)malloc(numRecords * sizeof(record));
    if (!processor->data) {
        free(processor);
        return NULL;
    }

    for (int i = 0; i < numRecords; i++) {
        processor->data[i].offset = &offsets[i];
        processor->data[i].key = &keys[i];
        processor->data[i].accessCount = 0;
    }

    return processor;
}

void processSensorData(StreamProcessor* processor, int dataPoint) {
    static long lastID = -1;
    int newID = generateRandomID();

    while (newID == lastID) {
        newID = generateRandomID();
    }
    lastID = newID;

    record* currentRecord = processor->data[newID % 25];
    *currentRecord->offset = dataPoint;
    *(currentRecord->key) = newID;
    currentRecord->accessCount++;
}

double calculateAverage(StreamProcessor* processor, int numRecords) {
    double sum = 0.0;

    for (int i = 0; i < numRecords; i++) {
        record* rec = processor->data[i];
        sum += *(rec->offset);
    }

    return sum / numRecords;
}

void cleanup(StreamProcessor* processor) {
    free(processor->data);
    free(processor);
}

int main() {
    int numRecords = 25;
    long offsets[25];
    int keys[25];

    for (int i = 0; i < numRecords; i++) {
        offsets[i] = 0;
        keys[i] = -1;
    }

    StreamProcessor* processor = createProcessor(numRecords, offsets, keys);
    if (!processor) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    initPRNG(time(NULL));
    for (int i = 0; i < 100; i++) {
        processSensorData(processor, i);
    }

    double average = calculateAverage(processor, numRecords);
    printf("Average: %.2f\n", average);

    cleanup(processor);

    return EXIT_SUCCESS;
}
