#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_IDS 10000
#define ID_LOG_SIZE 25
#define AVG_WINDOW_MINUTES 5

typedef struct {
    unsigned int last_ids[ID_LOG_SIZE];
    size_t id_index;
    double avg_value;
    size_t unique_count;
    size_t total_ids_generated;
    pthread_mutex_t mutex;
} SensorDataProcessor;

SensorDataProcessor processor = {
    .id_index = 0,
    .avg_value = 0.0,
    .unique_count = 0,
    .total_ids_generated = 0,
    .mutex = PTHREAD_MUTEX_INITIALIZER
};

unsigned int prng(unsigned int seed) {
    return (seed * 1664525 + 1013904223) % MAX_IDS;
}

void initialize_processor(SensorDataProcessor *processor, unsigned int seed) {
    processor->unique_count = 0;
    processor->total_ids_generated = 0;
    pthread_mutex_init(&processor->mutex, NULL);
    for (size_t i = 0; i < ID_LOG_SIZE; ++i) {
        processor->last_ids[i] = prng(seed + i);
    }
}

void update_processor(SensorDataProcessor *processor, unsigned int new_id) {
    pthread_mutex_lock(&processor->mutex);
    if (new_id != processor->last_ids[processor->id_index]) {
        processor->unique_count++;
    } else {
        printf("ID reuse detected: %u\n", new_id);
    }
    processor->last_ids[processor->id_index] = new_id;
    processor->id_index = (processor->id_index + 1) % ID_LOG_SIZE;
    processor->total_ids_generated++;

    // Calculate average value
    processor->avg_value += ((double)new_id - processor->avg_value) / AVG_WINDOW_MINUTES;

    pthread_mutex_unlock(&processor->mutex);
}

void* process_data(void *arg) {
    SensorDataProcessor *processor = (SensorDataProcessor *)arg;
    unsigned int seed = time(NULL);
    initialize_processor(processor, seed);

    for (size_t i = 0; i < MAX_IDS; ++i) {
        unsigned int new_id = prng(seed + i);
        update_processor(processor, new_id);
    }

    return NULL;
}

int main() {
    pthread_t threads[4];
    SensorDataProcessor processors[4];

    for (size_t i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, process_data, &processors[i]) != 0) {
            fprintf(stderr, "Failed to create thread %zu\n", i);
            return EXIT_FAILURE;
        }
    }

    for (size_t i = 0; i < 4; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            fprintf(stderr, "Failed to join thread %zu\n", i);
            return EXIT_FAILURE;
        }
    }

    printf("Total unique IDs generated: %zu\n", processor.unique_count);
    printf("Average ID value over last %d minutes: %.2f\n", AVG_WINDOW_MINUTES, processor.avg_value);

    return EXIT_SUCCESS;
}
```

