#include <iostream>
#include <vector>
#include <random>
#include <chrono>
#include <mutex>

class AttackManager {
private:
    static const int COOLDOWN_1 = 5;
    static const int COOLDOWN_2 = 7;
    static const int COOLDOWN_3 = 9;
    static const int MAX_ATTACKS_PER_SECOND = 1000;
    static const int RESET_INTERVAL = 10000;

    std::vector<int> cooldowns;
    std::mt19937 gen;
    std::uniform_int_distribution<> dis;
    std::mutex mtx;
    std::atomic<int> attackCount;
    std::array<int, 3> attackFrequency;

public:
    AttackManager() : gen(std::random_device{}()), dis(0, 2), attackCount(0) {
        cooldowns = {COOLDOWN_1, COOLDOWN_2, COOLDOWN_3};
        for (int i = 0; i < 3; ++i) {
            attackFrequency[i] = 0;
        }
    }

    void manageAttacks() {
        std::lock_guard<std::mutex> lock(mtx);
        if (attackCount % RESET_INTERVAL == 0) {
            resetAttackSelection();
        }
        int selectedAttack = dis(gen);
        ++attackFrequency[selectedAttack];
        // Simulate attack and handle cooldown
        std::this_thread::sleep_for(std::chrono::seconds(cooldowns[selectedAttack]));
        ++attackCount;
    }

private:
    void resetAttackSelection() {
        std::lock_guard<std::mutex> lock(mtx);
        for (int i = 0; i < 3; ++i) {
            attackFrequency[i] = 0;
        }
    }

    double calculateLoad() const {
        return static_cast<double>(attackCount.load()) / MAX_ATTACKS_PER_SECOND;
    }

public:
    void logAttackFrequency() {
        std::lock_guard<std::mutex> lock(mtx);
        for (int i = 0; i < 3; ++i) {
            std::cout << "Attack Type " << i + 1 << ": " << attackFrequency[i] << " times" << std::endl;
