function generateSessionTokenAndStoreUserDetails($username, $password) {
    // Step 1: Generate a unique session token using cryptographically secure method
    $session_token = bin2hex(random_bytes(32));

    // Step 2: Securely store user details and session token in the database
    try {
        $pdo = new PDO('mysql:host=localhost;dbname=your_database', 'username', 'password');
        $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        // Hash password with a unique salt
        $salt = bin2hex(random_bytes(16));
        $hashed_password = hash_pbkdf2('sha512', $password, $salt, 10000, 32);

        // Insert user details and session token into the database
        $stmt = $pdo->prepare("INSERT INTO users (username, password, salt, session_token, last_active) VALUES (?, ?, ?, ?, NOW())");
        $stmt->execute([$username, $hashed_password, $salt, $session_token]);

        echo "User details stored successfully with session token.";
    } catch (PDOException $e) {
