int processAndAnalyzeData(int dataSize, int minValue, int maxValue, const char* inputFile, const char* outputFile) {
    if (dataSize <= 0 || minValue > maxValue) {
        return -1; // Invalid input parameters
    }

    record* records = malloc(dataSize * sizeof(record));
    if (!records) {
        return -2; // Memory allocation failed
    }

    FILE* in = fopen(inputFile, "r");
    if (!in) {
        free(records);
        return -3; // Failed to open input file
    }

    for (int i = 0; i < dataSize; ++i) {
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }

    fclose(in);

    FILE* out = fopen(outputFile, "w");
    if (!out) {
        free(records);
        return -4; // Failed to open output file
    }

    for (int i = 0; i < dataSize; ++i) {
        fprintf(out, "%d\n", records[i].value);
    }

    fclose(out);

    free(records);
    return 0; // Success
}

void printStats(int* arr, int size) {
    if (!arr || size <= 0) {
        return;
    }

    int min = arr[0];
    int max = arr[0];
    double sum = 0;

    for (int i = 1; i < size; ++i) {
        if (arr[i] < min) {
            min = arr[i];
        }
        if (arr[i] > max) {
            max = arr[i];
        }
        sum += arr[i];
    }

    double average = sum / size;
    double variance = 0;

    for (int i = 0; i < size; ++i) {
        double diff = arr[i] - average;
        variance += diff * diff;
    }

    variance /= size;
    double stdDev = sqrt(variance);

    printf("Min: %d, Max: %d, Average: %.2f, Standard Deviation: %.2f\n", min, max, average, stdDev);
}

int main() {
    srand(time(0));
    int dataSize = 1000;
    int minValue = 1;
    int maxValue = 10000;
