    for (size_t i = 0; i < arraySize; i++) {
        // Generate random values within specified bounds
        (*dataArray)[i].measurement = minMeasurement + (maxMeasurement - minMeasurement) * ((double)rand() / RAND_MAX);
        (*dataArray)[i].timestamp = minTimestamp + (maxTimestamp - minTimestamp) * ((float)rand() / RAND_MAX);
        (*dataArray)[i].unique_id = minId + (size_t)((double)(maxId - minId) * ((double)rand() / RAND_MAX));
    }

    return 0; // Success
}
