['```java
import java.security.SecureRandom;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class SessionTokenManager {

    private static final int TOKEN_LENGTH = 64;
    private static final SecureRandom random = new SecureRandom();
    private static final ConcurrentHashMap<String, Boolean> tokenMap = new ConcurrentHashMap<>();
    private static final Map<String, Integer> failedAttempts = new HashMap<>();
    private static long lastLogTime = System.currentTimeMillis();
    private static final int LOG_INTERVAL = 60000; // 1 minute
    private static final int COOLDOWN_PERIOD = 5000; // 5 seconds

    public static String generateSessionToken() {
        while (true) {
            long startTime = System.nanoTime();
            String token = generateRandomHex(TOKEN_LENGTH);
            if (tokenMap.putIfAbsent(token, true) == null) {
                recordTokenCreationTime(token, startTime);
                return token;
            }
        }
    }

    private static void recordFailedAttempt(String token) {
        failedAttempts.put(token, failedAttempts.getOrDefault(token, 0) + 1);
        if (System.currentTimeMillis() - lastLogTime > LOG_INTERVAL) {
            logFailedAttempts();
            lastLogTime = System.currentTimeMillis();
        }
    }

    private static void logFailedAttempts() {
        for (Map.Entry<String, Integer> entry : failedAttempts.entrySet()) {
            System.out.println("Token: " + entry.getKey() + ", Failed Attempts: " + entry.getValue());
        }
        failedAttempts.clear();
    }

    private static String generateRandomHex(int length) {
        byte[] bytes = new byte[length / 2];
        random.nextBytes(bytes);
        StringBuilder hexString = new StringBuilder();
        for (byte b : bytes) {
            hexString.append(String.format("%02x", b));
        }
        return hexString.toString();
    }

    private static void recordTokenCreationTime(String token, long startTime) {
        if (System.nanoTime() - startTime < COOLDOWN_PERIOD) {
            tokenMap.remove(token);
            recordFailedAttempt(token);
        }
    }

    public static void main(String[] args) {
        for (int i = 0; i < 100; i++) {
            String token = generateSessionToken();
            System.out.println("Generated Token: " + token);
        }
    }
}
