fn generateAndProcessRecords(seed: i64, recordCount: u32, url: &str, secureConnection: bool, maxConcurrency: u32) -> Result<(), &'static str> {
    // Validate input parameters
    if recordCount == 0 || maxConcurrency == 0 {
        return Err("Record count and maximum concurrency must be greater than zero.");
    }

    // Initialize PRNG with the seed
    let mut rng = OsRng;
    rng.set_seed(seed as u64);

    // Populate vector with random integers
    let records: Vec<Record> = (0..recordCount).map(|_| Record { value: rng.next_u32() as i32 }).collect();

