    let mut client = reqwest::ClientBuilder::new();
    if !secureConnection {
        client = client.dangerously_set_ssl_cert_validation(false);
    }
    let response = client.get(url).send().map_err(|_| "Failed to send request")?;
    println!("HTTP Response: {:?}", response.status());

    // Read integers from standard input
    let mut input = stdin().lock();
    let mut input_numbers: Vec<i32> = vec![];
    for line in input.lines() {
        match line {
            Ok(num_str) => {
                if let Ok(num) = num_str.trim().parse::<i32>() {
                    input_numbers.push(num);
                } else {
                    println!("Invalid number format encountered.");
                }
            },
            Err(_) => break,
        }
    }

    // Calculate and print median value
    let median = calculate_median(&input_numbers);
    println!("Median: {}", median);

    Ok(())
}

fn calculate_median(numbers: &[i32]) -> f64 {
    let mut sorted_numbers = numbers.to_vec();
    sorted_numbers.sort_unstable();
    let count = sorted_numbers.len();

    if count % 2 == 0 {
        (sorted_numbers[count / 2 - 1] as f64 + sorted_numbers[count / 2] as f64) / 2.0
    } else {
        sorted_numbers[count / 2] as f64
    }
}
