#include <iostream>
#include <vector>
#include <random>
#include <mutex>
#include <cstdlib>

class DynamicRecordManager {
public:
    struct Record {
        int value;
    };

private:
    std::vector<int> offsets;
    std::vector<int> keys;
    std::vector<Record> records;
    std::mt19937 gen;
    std::uniform_int_distribution<> dis;
    std::mutex mtx;

public:
    DynamicRecordManager(int min, int max) : gen(std::random_device{}()), dis(min, max) {}

    ~DynamicRecordManager() {
        offsets.clear();
        keys.clear();
        records.clear();
    }

    int populateRandomValues(size_t count) {
        std::lock_guard<std::mutex> lock(mtx);
        try {
            offsets.resize(count);
            keys.resize(count);
            records.resize(count);

            for (size_t i = 0; i < count; ++i) {
                offsets[i] = static_cast<int>(malloc(sizeof(int)));
                if (!offsets[i]) return -1;
                *reinterpret_cast<int*>(offsets[i]) = i;

                keys[i] = dis(gen);
                records[i].value = keys[i];
            }
        } catch (...) {
            cleanUp();
            return -1;
        }
        return 0;
    }

    bool validateMemoryAccess(int key) {
        std::lock_guard<std::mutex> lock(mtx);
        for (size_t i = 0; i < keys.size(); ++i) {
            if (keys[i] == key && offsets[i]) {
                int* valuePtr = reinterpret_cast<int*>(offsets[i]);
                return *valuePtr == key;
            }
        }
        return false;
    }

private:
    void cleanUp() {
        std::lock_guard<std::mutex> lock(mtx);
        for (int* ptr : offsets) {
            free(ptr);
        }
    }
};
```

