['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <limits.h>

typedef struct {
    int value;
} Record;

void generateRecords(int numRecords, long* offsets, int* keys, Record* records, int distributionType) {
    if (numRecords <= 0 || offsets == NULL || keys == NULL || records == NULL) {
        fprintf(stderr, "Invalid input size or pointer.\n");
        return;
    }

    srand(time(NULL));

    for (int i = 0; i < numRecords; i++) {
        offsets[i] = i * sizeof(long); // Simple offset calculation
        keys[i] = rand(); // Generate a random key

        if (distributionType == 1) { // Uniform distribution
            records[i].value = rand() % INT_MAX;
        } else if (distributionType == 2) { // Exponential distribution
            double r = (double)rand() / RAND_MAX;
            int value = (int)(INT_MAX * (1 - exp(-r)));
            records[i].value = value > INT_MAX ? INT_MAX : value;
        } else {
            fprintf(stderr, "Unsupported distribution type.\n");
            return;
        }
    }
}

