} PRNGAlgorithmType;

int generateAndAnalyzeData(int dataSize, int rangeMin, int rangeMax, const char* inputFile, const char* outputFile, PRNGAlgorithmType prngAlgorithmType) {
    if (dataSize <= 0 || rangeMin > rangeMax) {
        return -1; // Invalid parameters
    }

    int* data = (int*)malloc(dataSize * sizeof(int));
    if (!data) {
        return -2; // Memory allocation failed
    }

    FILE* inputfp = fopen(inputFile, "r");
    if (!inputfp) {
        free(data);
        return -3; // Failed to open input file
    }

    int* inputNumbers = NULL;
    int inputSize = 0;

    // Read integers from the input file
    while (fscanf(inputfp, "%d", &inputNumbers[inputSize]) == 1) {
        inputSize++;
        if (inputSize % MAX_DATA_SIZE == 0) {
            inputNumbers = realloc(inputNumbers, (inputSize + MAX_DATA_SIZE) * sizeof(int));
            if (!inputNumbers) {
                free(data);
                fclose(inputfp);
                return -4; // Memory reallocation failed
            }
        }
    }

    fclose(inputfp);

    int* combinedData = (int*)realloc(data, (dataSize + inputSize) * sizeof(int));
    if (!combinedData) {
        free(data);
        free(inputNumbers);
        return -5; // Memory reallocation failed
    }

    data = combinedData;
    for (int i = 0; i < inputSize; i++) {
        data[dataSize + i] = inputNumbers[i];
    }
    dataSize += inputSize;

    if (prngAlgorithmType == HIGH_QUALITY_PRNG) {
        // Initialize high-quality PRNG
        srand(time(NULL));
        for (int i = 0; i < dataSize; i++) {
            data[i] = rand() % (rangeMax - rangeMin + 1) + rangeMin;
        }
    } else {
        // Use standard PRNG
        srand(time(NULL));
        for (int i = 0; i < dataSize; i++) {
            data[i] = rand() % (rangeMax - rangeMin + 1) + rangeMin;
        }
    }

    int maxVal = data[0];
    for (int i = 1; i < dataSize; i++) {
        if (data[i] > maxVal) {
            maxVal = data[i];
        }
    }

    FILE* outputfp = fopen(outputFile, "w");
    if (!outputfp) {
        free(data);
        return -6; // Failed to open output file
    }

    fprintf(outputfp, "%d\n", maxVal);

    fclose(outputfp);
    free(data);
    free(inputNumbers);

    return 0;
}
