typedef struct {
    double* dataPoints;
    struct dataMetadata* metadata;
    struct config* config;
    const char* outputFile;
    unsigned int prngSeed;
    DependencyManager dependencyManager;
} ProcessDataParams;

int generateAndProcessData(ProcessDataParams* params) {
    // Allocate memory for dataPoints
    params->dataPoints = (double*)malloc(params->metadata->count * sizeof(double));
    if (!params->dataPoints) {
        return -1; // Memory allocation failure
    }

    // Resolve external dependencies
    int dependencyStatus = resolveDependencies(&params->dependencyManager);
    if (dependencyStatus != 0) {
        free(params->dataPoints);
        return -2; // Dependency resolution error
    }

    // Initialize PRNG based on config settings
    RandomNumberGenerator* prng;
    if (params->config->nonCryptographic && params->config->cryptographic) {
        prng = createNonCryptographicPRNG(params->prngSeed);
    } else if (params->config->nonCryptographic) {
        prng = createNonCryptographicPRNG(params->prngSeed);
    } else {
        prng = createCryptographicPRNG(params->prngSeed);
    }

    // Populate dataPoints with random numbers
    for (int i = 0; i < params->metadata->count; i++) {
        params->dataPoints[i] = generateRandomNumber(prng);
    }

    // Perform processing operations in parallel
    pthread_t* threads = (pthread_t*)malloc(params->metadata->count * sizeof(pthread_t));
    if (!threads) {
        free(params->dataPoints);
        destroyPRNG(prng);
        return -1; // Memory allocation failure for threads
    }

    for (int i = 0; i < params->metadata->count; i++) {
        pthread_create(&threads[i], NULL, processDataThread, &params->dataPoints[i]);
    }

    for (int i = 0; i < params->metadata->count; i++) {
        pthread_join(threads[i], NULL);
    }

    // Write results to outputFile
    FILE* file = fopen(params->outputFile, "w");
    if (!file) {
        free(threads);
        free(params->dataPoints);
        destroyPRNG(prng);
        return -3; // File I/O error
    }

    for (int i = 0; i < params->metadata->count; i++) {
        fprintf(file, "Metadata: %s, Timestamp: %d, Processed Value: %f\n",
                params->metadata[i].source, params->metadata[i].timestamp, params->dataPoints[i]);
    }

    fclose(file);
    free(threads);
    free(params->dataPoints);
    destroyPRNG(prng);
    return 0; // Success
}

void* processDataThread(void* dataPoint) {
    double* dp = (double*)dataPoint;
    *dp *= generateRandomNumber(prng); // Process each data point
    pthread_exit(NULL);
}
