fn generateAndProcessRecords(seed: i64, recordCount: u32, url: &str, maxConnectionAttempts: u8) -> Result<(), Box<dyn std::error::Error>> {
    let mut rng = rand::SeedableRng::seed_from_u64(seed as u64);
    let mut records: Vec<Record> = Vec::with_capacity(recordCount as usize);

    for _ in 0..recordCount {
        records.push(Record { value: rng.gen_range(-100..=100) });
    }

    let client = Client::new();

    for attempt in 0..maxConnectionAttempts {
        match client.post(url).json(&records).send().await {
            Ok(response) => {
                if response.status().is_success() {
                    println!("Records sent successfully");
                    break;
                } else {
                    eprintln!("Failed to send records, retrying...");
                }
            },
            Err(e) => {
                eprintln!("Error sending records: {}", e);
                break;
