typedef struct {
    char* message;
    long timestamp;
    int level;
} log_entry;

log_entry** create_logging_system(int num_entries) {
    srand(time(NULL)); // Seed PRNG for pseudo-randomness

    log_entry** system = (log_entry**)malloc(num_entries * sizeof(log_entry*));
    if (!system) return NULL; // Memory allocation failed

    for (int i = 0; i < num_entries; ++i) {
        system[i] = (log_entry*)malloc(sizeof(log_entry));
        if (!system[i]) {
            // Free previously allocated memory on failure
            for (int j = 0; j < i; ++j) free(system[j]);
            free(system);
            return NULL;
        }

        // Initialize timestamp and level using PRNG
        system[i]->timestamp = rand();
        system[i]->level = rand() % 5 + 1;

        // Generate a random log message of varying length
        int msg_length = rand() % 200; // Random length between 0 and 199
        system[i]->message = (char*)malloc((msg_length + 1) * sizeof(char));
        if (!system[i]->message) {
            // Free previously allocated memory on failure
            for (int j = 0; j <= i; ++j) free(system[j]->message);
            for (int j = 0; j < i; ++j) free(system[j]);
            free(system);
            return NULL;
        }

        // Fill the message with pseudo-random characters
        for (int j = 0; j < msg_length; ++j) {
            system[i]->message[j] = 'A' + rand() % 26; // Random uppercase letter
        }
        system[i]->message[msg_length] = '\0'; // Null-terminate the string
    }

    return system;
}

// Example usage:
int main() {
    int num_entries = 1000;
    log_entry** logging_system = create_logging_system(num_entries);
    if (logging_system) {
        // Use the logging system here
        for (int i = 0; i < num_entries; ++i) {
            free(logging_system[i]->message);
            free(logging_system[i]);
        }
        free(logging_system);
    }
    return 0;
}
```

