#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    double value;
} dataRecord;

typedef struct {
    int value;
} record;

void populateDataRecords(dataRecord *data, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        data[i].value = ((double)rand() / RAND_MAX) * 100.0;
    }
}

int generateUniqueRandom(int range_start, int range_end, int *used, size_t used_count) {
    int random_value;
    do {
        random_value = (rand() % (range_end - range_start + 1)) + range_start;
    } while ((size_t)random_value < used_count);
    used[used_count] = random_value;
    return random_value;
}

void populateRecords(record *records, size_t count, int range_start, int range_end) {
    int *used_values = (int *)malloc(sizeof(int) * count);
    if (!used_values) {
        fprintf(stderr, "Memory allocation failed for used values array.\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < count; ++i) {
        records[i].value = generateUniqueRandom(range_start, range_end, used_values, i);
    }
    free(used_values);
}

void computeStatistics(int *input, size_t count, double *average, double *std_deviation) {
    if (count == 0) {
        fprintf(stderr, "Cannot compute statistics for an empty array.\n");
        exit(EXIT_FAILURE);
    }
    double sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        sum += input[i];
    }
    *average = sum / count;

    double variance_sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        double diff = input[i] - *average;
        variance_sum += diff * diff;
    }
    *std_deviation = sqrt(variance_sum / count);
}

int main() {
    srand(time(NULL));
    size_t data_count = 1000; // Example size
    size_t record_count = 500; // Example size

    dataRecord *data_records = (dataRecord *)malloc(sizeof(dataRecord) * data_count);
    if (!data_records) {
        fprintf(stderr, "Memory allocation failed for data records.\n");
        return EXIT_FAILURE;
    }

    record *records = (record *)malloc(sizeof(record) * record_count);
    if (!records) {
        free(data_records);
        fprintf(stderr, "Memory allocation failed for records.\n");
        return EXIT_FAILURE;
    }

    populateDataRecords(data_records, data_count);
    populateRecords(records, record_count, 10, 99); // Example range

    int *input = (int *)malloc(sizeof(int) * record_count);
    if (!input) {
        free(data_records);
        free(records);
        fprintf(stderr, "Memory allocation failed for input array.\n");
        return EXIT_FAILURE;
    }

    printf("Enter %zu integers:\n", record_count);
    for (size_t i = 0; i < record_count; ++i) {
        if (scanf("%d", &input[i]) != 1) {
            fprintf(stderr, "Invalid input.\n");
            free(data_records);
            free(records);
            free(input);
            return EXIT_FAILURE;
        }
    }

    double average, std_deviation;
    computeStatistics(input, record_count, &average, &std_deviation);

    printf("Average: %.2f\n", average);
    printf("Standard Deviation: %.2f\n", std_deviation);

    free(data_records);
    free(records);
    free(input);

    return EXIT_SUCCESS;
}
