#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_KEY 1000
#define MIN_OFFSET 100
#define MAX_OFFSET 1000

typedef struct Record {
    int key;
    long offset;
    struct Record* next;
} Record;

typedef struct RecordList {
    Record* head;
    pthread_mutex_t mutex;
} RecordList;

Record* create_record(int key, long offset) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) return NULL;
    new_record->key = key;
    new_record->offset = offset;
    new_record->next = NULL;
    return new_record;
}

int insert_record(RecordList* list, int key, long offset) {
    pthread_mutex_lock(&list->mutex);
    Record** current = &list->head;
    while (*current && (*current)->key < key) {
        current = &(*current)->next;
    }
    if (*current && (*current)->key == key) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Key already exists
    }
    Record* new_record = create_record(key, offset);
    if (!new_record) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Memory allocation failed
    }
    new_record->next = *current;
    *current = new_record;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int delete_record(RecordList* list, int key) {
    pthread_mutex_lock(&list->mutex);
    Record** current = &list->head;
    while (*current && (*current)->key < key) {
        current = &(*current)->next;
    }
    if (!*current || (*current)->key != key) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Key not found
    }
    Record* temp = *current;
    *current = (*current)->next;
    free(temp);
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

Record* search_record(RecordList* list, int key) {
    pthread_mutex_lock(&list->mutex);
    Record* current = list->head;
    while (current && current->key < key) {
        current = current->next;
    }
    if (!current || current->key != key) {
        pthread_mutex_unlock(&list->mutex);
        return NULL; // Key not found
    }
    pthread_mutex_unlock(&list->mutex);
    return current;
}

void set_random_offsets(RecordList* list, int min_offset, int max_offset) {
    srand(time(NULL));
    pthread_mutex_lock(&list->mutex);
    Record* current = list->head;
    while (current) {
        current->offset = rand() % (max_offset - min_offset + 1) + min_offset;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

void free_record_list(RecordList* list) {
    Record* current = list->head;
    while (current) {
        Record* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->mutex);
}
