#define NONCE_POOL_SIZE 1024

typedef struct {
    unsigned char nonces[NONCE_POOL_SIZE][EVP_MAX_KEY_LENGTH];
    size_t head;
    size_t tail;
    pthread_mutex_t lock;
} NoncePool;

void init_nonce_pool(NoncePool *pool) {
    pool->head = 0;
    pool->tail = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

unsigned char* get_unique_nonce(NoncePool *pool, size_t key_length) {
    unsigned char nonce[EVP_MAX_KEY_LENGTH];
    while (1) {
        pthread_mutex_lock(&pool->lock);
        if ((pool->tail + 1) % NONCE_POOL_SIZE != pool->head) {
            memcpy(nonce, pool->nonces[pool->head], key_length);
            pool->head = (pool->head + 1) % NONCE_POOL_SIZE;
            pthread_mutex_unlock(&pool->lock);
            return nonce;
        }
        pthread_mutex_unlock(&pool->lock);
        // Wait or handle nonce exhaustion
    }
}

void refresh_nonce_pool(NoncePool *pool, size_t key_length) {
    for (size_t i = 0; i < NONCE_POOL_SIZE; ++i) {
        EVP_BytesToKey(EVP_aes_256_cbc(), NULL, NULL,
                       (unsigned char*)&i, sizeof(i), 1, pool->nonces[i], key_length);
    }
}

void* nonce_worker(void *arg) {
    NoncePool *pool = (NoncePool*)arg;
    while (1) {
        refresh_nonce_pool(pool, EVP_MAX_KEY_LENGTH);
        // Sleep or handle periodic refresh
    }
}

