// Define a simple hash function for demonstration purposes
unsigned int simple_hash(const char *str) {
    unsigned int hash = 0;
    while (*str) {
        hash = (hash << 5) + hash + (unsigned char)*str++;
    }
    return hash;
}

// Define a nonce structure
typedef struct {
    unsigned long last_used;
    pthread_mutex_t lock;
} NonceGenerator;

// Initialize a nonce generator
void init_nonce_generator(NonceGenerator *generator) {
    generator->last_used = 0;
    pthread_mutex_init(&generator->lock, NULL);
}

// Generate a unique nonce
unsigned long generate_unique_nonce(NonceGenerator *generator) {
    unsigned long nonce;
    time_t current_time;

    pthread_mutex_lock(&generator->lock);

    current_time = time(NULL);
    if (current_time <= generator->last_used) {
        // If the clock has not moved forward, increment last used
        generator->last_used++;
    } else {
        // Otherwise, set last used to the current time
        generator->last_used = current_time;
    }

    nonce = generator->last_used;

    pthread_mutex_unlock(&generator->lock);

    return nonce;
}

// Example usage of the nonce generator
int main() {
    NonceGenerator nonce_gen;
    init_nonce_generator(&nonce_gen);

    printf("Unique Nonce: %lu\n", generate_unique_nonce(&nonce_gen));

    return 0;
}
```

