    struct dataPoint* dataPoints = (struct dataPoint*)malloc(numEntries * sizeof(struct dataPoint));
    if (!dataPoints) {
        printf("Memory allocation failed for dataPoints\n");
        return -1; // Handle memory allocation failure
    }

    int* measurements = (int*)malloc(numEntries * sizeof(int));
    if (!measurements) {
        free(dataPoints);
        printf("Memory allocation failed for measurements\n");
        return -1; // Handle memory allocation failure
    }

    time_t* timestamps = (time_t*)malloc(numEntries * sizeof(time_t));
    if (!timestamps) {
        free(dataPoints);
        free(measurements);
        printf("Memory allocation failed for timestamps\n");
        return -1; // Handle memory allocation failure
    }

    // Initialize data points with PRNG
    for (int i = 0; i < numEntries; ++i) {
        dataPoints[i].measurement = rand() % 100;
        time(&dataPoints[i].timestamp);
        dataPoints[i].id = (unsigned int)i;

        measurements[i] = rand() % 500;
        timestamps[i] = (time_t)(rand() % (3600 * 24) + time(NULL)); // Random timestamp within last 24 hours
    }

