        fprintf(stderr, "Error: Filename too long.\n");
        return;
    }

    snprintf(new_filename, max_length, "%s%d", original_filename, rand());

    // Append file type based on filename content
    size_t num_digits = 0;
    for (size_t i = 0; i < strlen(original_filename); ++i) {
        if (isdigit(original_filename[i])) {
            num_digits++;
        }
    }

    if (num_digits % 2 == 0) {
        strcat(new_filename, ".log");
    } else {
        strcat(new_filename, ".csv");
    }
