#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

typedef enum {
    KEY_EXCHANGE_RSA,
    KEY_EXCHANGE_DH,
    KEY_EXCHANGE_ECC
} KeyExchangeMethod;

typedef enum {
    ENCRYPTION_MODE_CBC,
    ENCRYPTION_MODE_GCM
} EncryptionMode;

typedef struct {
    SSL_CTX *ctx;
    SSL *ssl;
    int fd;
    KeyExchangeMethod key_exchange_method;
    EncryptionMode encryption_mode;
    int key_size;
    char *cert_file;
    char *key_file;
} CryptoSession;

CryptoSession* create_session(int fd, const char *cert_file, const char *key_file) {
    // Create a new SSL_CTX
    SSL_CTX *ctx = SSL_CTX_new(TLS_method());
    if (!ctx) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    // Load certificates and private keys into the context
    if (SSL_CTX_use_certificate_file(ctx, cert_file, SSL_FILETYPE_PEM) <= 0 ||
        SSL_CTX_use_PrivateKey_file(ctx, key_file, SSL_FILETYPE_PEM) <= 0) {
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }

    // Create a new SSL object
    SSL *ssl = SSL_new(ctx);
    if (!ssl) {
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }

    // Attach the SSL object to the file descriptor
    SSL_set_fd(ssl, fd);

    CryptoSession *session = (CryptoSession *)malloc(sizeof(CryptoSession));
    session->ctx = ctx;
    session->ssl = ssl;
    session->fd = fd;
    session->key_exchange_method = KEY_EXCHANGE_RSA; // Default to RSA for simplicity
    session->encryption_mode = ENCRYPTION_MODE_CBC; // Default to CBC mode
    session->key_size = 2048; // Default key size
    session->cert_file = strdup(cert_file);
    session->key_file = strdup(key_file);

    return session;
}

void destroy_session(CryptoSession *session) {
    if (session) {
        SSL_free(session->ssl);
        SSL_CTX_free(session->ctx);
        free((char *)session->cert_file);
        free((char *)session->key_file);
        free(session);
    }
}

int perform_key_exchange(CryptoSession *session) {
    int ret = SSL_do_handshake(session->ssl);
    if (ret <= 0) {
        ERR_print_errors_fp(stderr);
        return -1;
    }
    return 0;
}

int encrypt_data(CryptoSession *session, const unsigned char *data, size_t len, unsigned char **out_buf, size_t *out_len) {
    // Implement encryption logic based on the selected encryption mode
    // Example: Use SSL_write for symmetric encryption
    int ret = SSL_write(session->ssl, data, len);
    if (ret <= 0) {
        ERR_print_errors_fp(stderr);
        return -1;
    }
    *out_buf = malloc(ret);
    memcpy(*out_buf, data, ret);
    *out_len = ret;
    return 0;
}

int decrypt_data(CryptoSession *session, const unsigned char *data, size_t len, unsigned char **out_buf, size_t *out_len) {
    // Implement decryption logic based on the selected encryption mode
    // Example: Use SSL_read for symmetric decryption
    int ret = SSL_read(session->ssl, data, len);
    if (ret <= 0) {
        ERR_print_errors_fp(stderr);
        return -1;
    }
    *out_buf = malloc(ret);
    memcpy(*out_buf, data, ret);
    *out_len = ret;
    return 0;
}
