#include <time.h>

typedef struct {
    int value;
    void* offset_ptr;
} record;

typedef struct {
    long offset;
    struct {
        int key;
    } *key_ptr;
} offset;

typedef struct {
    long seed;
    unsigned int state[624];
    int index;
} prng_state;

record* create_record_array(int size, int min_value, int max_value, int seed) {
    if (size <= 0 || size > 10000 || min_value >= max_value) {
        return NULL; // Invalid input
    }

    record *records = malloc(size * sizeof(record));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    prng_state prng;
    prng.seed = seed;
    prng.index = 624;

    time_t t = time(NULL);
    srand(t ^ seed);

    for (int i = 0; i < size; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;

        offset *off = malloc(sizeof(offset));
        if (!off) {
            // Free previously allocated memory
            while (i > 0) {
                free(records[--i].offset_ptr);
            }
            free(records);
            return NULL; // Memory allocation failed
        }

        off->offset = rand();
        off->key_ptr = malloc(sizeof(struct { int key; }));
        if (!off->key_ptr) {
            free(off); // Free allocated offset structure
            while (i > 0) {
                free(records[--i].offset_ptr);
            }
            free(records);
            return NULL; // Memory allocation failed
        }

        off->key_ptr->key = rand();
        records[i].offset_ptr = off;
    }

    prng_state *prng_state_ptr = malloc(sizeof(prng_state));
    if (!prng_state_ptr) {
        // Free previously allocated memory
        for (int i = 0; i < size; i++) {
            free(((record*)records[i].offset_ptr)->key_ptr);
            free(records[i].offset_ptr);
        }
        free(records);
        return NULL; // Memory allocation failed
    }

    *prng_state_ptr = prng;

    return records;
}
