        errno = EInvalidArgument;
        return NULL;
    }

    record *records = malloc(size * sizeof(record));
    if (!records) {
        errno = ENOMEM;
        return NULL;
    }

    offset *offsets = malloc(size * sizeof(offset));
    if (!offsets) {
        free(records);
        errno = ENOMEM;
        return NULL;
    }

