    if (!keys) {
        free(offsets);
        free(records);
        errno = ENOMEM;
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG
    for (int i = 0; i < size; ++i) {
        records[i].value = use_fast_prng ? rand() % (max_val - min_val + 1) + min_val : /* Fast PRNG implementation */;
