    srand(seed);

    // Populate arrays with random data
    for (int i = 0; i < count; ++i) {
        timestamps[i] = time(NULL); // Current timestamp
        temperatures[i] = -50 + ((float)rand() / RAND_MAX * 100); // Random temperature between -50 and 50
        humidity_levels[i].value = rand() % 101; // Random humidity level between 0 and 100
    }

    // Return pointer to the structure containing all arrays
    return humidity_levels;
}

void free_sensor_data(record* data, int count) {
    if (data == NULL || count <= 0) return;

    // Free memory for temperature readings
    float* temperatures = (float*)((record*)data - count);
    free(temperatures);

    // Free memory for timestamps
    long* timestamps = (long*)((record*)temperatures - count);
    free(timestamps);

    // Free memory for humidity levels
