int processAndFindMax(int min, int max, int num_records) {
    if (num_records <= 0 || min >= max) {
        return -1; // Invalid input
    }

    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));

    if (!offsets || !keys) {
        free(offsets);
        free(keys);
        return -2; // Memory allocation failed
    }

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return -3; // Memory allocation failed
    }

    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        keys[i] = rand() % (max - min + 1) + min;
        records[i].value = keys[i];
    }

    int* input_values = (int*)malloc(MAX_RECORDS * sizeof(int));
    if (!input_values) {
        free(offsets);
        free(keys);
        free(records);
        return -4; // Memory allocation failed
    }

    int input_count = 0;
    while (scanf("%d", &input_values[input_count]) != EOF && ++input_count < MAX_RECORDS);

    int max_value = input_values[0];
    for (int i = 1; i < input_count; ++i) {
        if (input_values[i] > max_value) {
            max_value = input_values[i];
        }
    }

    printf("Maximum value: %d\n", max_value);

    free(offsets);
    free(keys);
    free(records);
    free(input_values);

    return 0;
}

int main() {
