typedef struct {
    double value;
    time_t timestamp;
} record;

int initialize_arrays(long* offsets, unsigned int* ids, record** records, bool** statuses, size_t num_records) {
    // Initialize arrays with dynamic memory allocation
    offsets = (long*)malloc(num_records * sizeof(long));
    if (offsets == NULL) return -1; // Memory allocation failed

    ids = (unsigned int*)malloc(num_records * sizeof(unsigned int));
    if (ids == NULL) {
        free(offsets);
        return -2; // Memory allocation failed
    }

    records = (record**)malloc(num_records * sizeof(record*));
    if (records == NULL) {
        free(ids);
        free(offsets);
        return -3; // Memory allocation failed
    }

    statuses = (bool**)malloc(num_records * sizeof(bool*));
    if (statuses == NULL) {
        free(records);
        free(ids);
        free(offsets);
        return -4; // Memory allocation failed
    }

    // Initialize PRNG with a seed for better unpredictability across environments
    srand(time(NULL));

    // Initialize each array element and record
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand();
        ids[i] = rand();

        records[i] = (record*)malloc(sizeof(record));
        if (records[i] == NULL) {
            // Clean up previously allocated memory on failure
            for (size_t j = 0; j < i; ++j) free(records[j]);
            free(statuses);
            free(records);
            free(ids);
            free(offsets);
            return -5; // Memory allocation failed
        }
        records[i]->value = ((double)rand() / RAND_MAX) * (max_value - min_value) + min_value;
        records[i]->timestamp = time(NULL);

        statuses[i] = (bool*)malloc(sizeof(bool));
        if (statuses[i] == NULL) {
            // Clean up previously allocated memory on failure
            for (size_t j = 0; j < i; ++j) free(statuses[j]);
            for (size_t j = 0; j <= i; ++j) free(records[j]);
            free(statuses);
            free(records);
            free(ids);
            free(offsets);
            return -6; // Memory allocation failed
        }
        *statuses[i] = (rand() % 2 == 0); // Random bool value
    }

    return 0; // Success
}

// Function to free allocated memory
void free_arrays(long* offsets, unsigned int* ids, record** records, bool** statuses, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i]);
        free(statuses[i]);
    }
    free(offsets);
    free(ids);
    free(records);
    free(statuses);
}
