    // Allocate memory for records
    Record* records = (Record*)malloc(numRecords * sizeof(Record));

    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize PRNG state
    srand(time(NULL));

    // Populate records with random offsets within the specified range
    for (int i = 0; i < numRecords; i++) {
        records[i].key = i + 1;
        records[i].offset = minValue + rand() % (maxValue - minValue + 1);
    }

    return records;
}

void freeRecords(Record* records) {
    // Free allocated memory
    free(records);
}

void* processRecord(void* arg) {
    Record* record = (Record*)arg;

    // Simulate processing of the record
    printf("Processing record with key %d and offset %ld\n", record->key, record->offset);

    pthread_exit(NULL);
}

int main() {
    int numRecords = 1000000; // Example number of records
    int minValue = 1;
    int maxValue = 1000;

    Record* records = allocateRecords(numRecords, minValue, maxValue);

    pthread_t threads[numRecords];

    for (int i = 0; i < numRecords; i++) {
        pthread_create(&threads[i], NULL, processRecord, &records[i]);
    }

    for (int i = 0; i < numRecords; i++) {
        pthread_join(threads[i], NULL);
    }

    freeRecords(records);

    return 0;
}
