            for (size_t j = 0; j < i; ++j) {
                free(events[j].description);
            }
            return NULL;
        }

        // Efficient pseudo-random string generator
        for (size_t j = 0; j < max_length; ++j) {
            events[i].description[j] = 'a' + rand() % 26;
        }
        events[i].description[max_length] = '\0';
    }

    return events;
}

void free_events(event* events, size_t num_events) {
    if (events) {
        for (size_t i = 0; i < num_events; ++i) {
            if (events[i].description) {
                free(events[i].description);
            }
        }
        free(events);
    }
}
