#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/rand.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
} record;

int initialize_arrays(long **offsets, int **keys, record **records, size_t count) {
    *offsets = (long *)malloc(count * sizeof(long));
    *keys = (int *)malloc(count * sizeof(int));
    *records = (record *)calloc(count, sizeof(record));

    if (!*offsets || !*keys || !*records) {
        free(*offsets);
        free(*keys);
        free(*records);
        return -1;
    }

    srand(time(NULL)); // Seed for CSPRNG
    for (size_t i = 0; i < count; ++i) {
        (*keys)[i] = rand();
        if (!RAND_bytes((unsigned char *)&((*records)[i].value), sizeof((*records)[i].value))) {
            free(*offsets);
            free(*keys);
            free(*records);
            return -1;
        }
    }

    return 0;
}

int serialize_records(record *records, size_t count, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return -1;
    }

    if (fwrite(records, sizeof(record), count, file) != count) {
        fclose(file);
        perror("Failed to write records to file");
        return -1;
    }

    if (fclose(file) != 0) {
        perror("Failed to close file after writing");
        return -1;
    }

    return 0;
}

int deserialize_records(record *records, size_t count, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return -1;
    }

    if (fread(records, sizeof(record), count, file) != count) {
        fclose(file);
        perror("Failed to read records from file");
        return -1;
    }

    if (fclose(file) != 0) {
        perror("Failed to close file after reading");
        return -1;
    }

    return 0;
}

int main() {
    long *offsets;
    int *keys;
    record *records;
    size_t count = MAX_RECORDS;

    if (initialize_arrays(&offsets, &keys, &records, count) != 0) {
        fprintf(stderr, "Failed to initialize arrays\n");
        return EXIT_FAILURE;
    }

    const char *filename = "records.dat";
    if (serialize_records(records, count, filename) != 0) {
        fprintf(stderr, "Failed to serialize records\n");
        free(offsets);
        free(keys);
        free(records);
        return EXIT_FAILURE;
    }

    record *loaded_records = (record *)malloc(count * sizeof(record));
    if (!loaded_records) {
        fprintf(stderr, "Failed to allocate memory for loaded records\n");
        free(offsets);
        free(keys);
        free(records);
        return EXIT_FAILURE;
    }

    if (deserialize_records(loaded_records, count, filename) != 0) {
        fprintf(stderr, "Failed to deserialize records\n");
        free(offsets);
        free(keys);
        free(records);
        free(loaded_records);
        return EXIT_FAILURE;
    }

    // Verify data integrity
    for (size_t i = 0; i < count; ++i) {
        if (records[i].value != loaded_records[i].value) {
            fprintf(stderr, "Data corruption detected at index %zu\n", i);
            free(offsets);
            free(keys);
            free(records);
            free(loaded_records);
            return EXIT_FAILURE;
        }
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(loaded_records);

    return EXIT_SUCCESS;
}
