void *allocate_memory(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        log_error("Memory allocation failed");
    } else {
        memory_tracker.allocated++;
    }
    return ptr;
}

void free_memory(void *ptr) {
    if (ptr != NULL) {
        free(ptr);
        memory_tracker.freed++;
    }
}

Record* create_record(int value, int seed) {
    Record *record = allocate_memory(sizeof(Record));
    record->value = value;

    struct Metadata *metadata = allocate_memory(sizeof(struct Metadata));
    metadata->seed = seed;
    record->metadata = metadata;

    return record;
}

Event* create_event(const char *description, Record *record, Timestamp timestamp) {
    Event *event = allocate_memory(sizeof(Event));
    event->description = strdup(description);
    event->record = record;
    event->timestamp = timestamp;

    return event;
}

void free_record(Record *record) {
    if (record != NULL) {
        struct Metadata *metadata = record->metadata;
        if (metadata != NULL) {
            free_memory(metadata);
        }
        free_memory(record);
    }
}

void free_event(Event *event) {
    if (event != NULL) {
        free(event->description);
        free_record(event->record);
        free_memory(event);
    }
}

