} event;

record* create_record(double value, size_t meta_len) {
    record* rec = malloc(sizeof(record));
    if (rec == NULL) return NULL;
    rec->value = value;
    rec->metadata = malloc(meta_len * sizeof(char));
    if (rec->metadata == NULL) {
        free(rec);
        return NULL;
    }
    // Simple pseudo-random string generator for metadata
    for (size_t i = 0; i < meta_len - 1; ++i) {
        rec->metadata[i] = 'a' + rand() % 26;
    }
    rec->metadata[meta_len - 1] = '\0';
    return rec;
}

event* create_event(const char* description, int priority) {
    event* evt = malloc(sizeof(event));
    if (evt == NULL) return NULL;
    evt->priority = priority;
    size_t desc_len = strlen(description);
    evt->description = malloc(desc_len * sizeof(char));
    if (evt->description == NULL) {
        free(evt);
        return NULL;
    }
    // Simple pseudo-random string generator for description
    for (size_t i = 0; i < desc_len - 1; ++i) {
        evt->description[i] = 'a' + rand() % 26;
    }
    evt->description[desc_len - 1] = '\0';
    return evt;
}

void free_record(record* rec) {
    if (rec == NULL) return;
    free(rec->metadata);
    free(rec);
}

void free_event(event* evt) {
    if (evt == NULL) return;
    free(evt->description);
    free(evt);
}

int main() {
    srand(time(NULL));

    // Example usage
    size_t num_records = 1000;
    size_t meta_len = 25;
    record** records = malloc(num_records * sizeof(record*));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i] = create_record(i * 1.5, meta_len);
        if (records[i] == NULL) {
            fprintf(stderr, "Failed to allocate record %zu\n", i);
            // Clean up previously allocated records
            for (size_t j = 0; j < i; ++j) free_record(records[j]);
            free(records);
            return EXIT_FAILURE;
        }
    }

    size_t num_events = 500;
    event** events = malloc(num_events * sizeof(event*));
    if (events == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        // Clean up previously allocated records
        for (size_t i = 0; i < num_records; ++i) free_record(records[i]);
        free(records);
        return EXIT_FAILURE;
    }

    const char* descriptions[] = {"High Priority", "Medium Priority", "Low Priority"};
    size_t desc_count = sizeof(descriptions) / sizeof(descriptions[0]);

    for (size_t i = 0; i < num_events; ++i) {
        int priority = rand() % desc_count;
        events[i] = create_event(descriptions[priority], priority);
        if (events[i] == NULL) {
            fprintf(stderr, "Failed to allocate event %zu\n", i);
            // Clean up previously allocated records and events
            for (size_t j = 0; j < i; ++j) free_event(events[j]);
            for (size_t j = 0; j < num_records; ++j) free_record(records[j]);
            free(records);
            free(events);
            return EXIT_FAILURE;
        }
    }

    // Use records and events...

    // Clean up
    for (size_t i = 0; i < num_records; ++i) free_record(records[i]);
    free(records);

    for (size_t i = 0; i < num_events; ++i) free_event(events[i]);
    free(events);

    return EXIT_SUCCESS;
}
