#define RNG_SEED 12345

typedef struct {
    long offset;
    int key;
    struct tm timestamp;
} record;

typedef enum { SUCCESS, OUT_OF_MEMORY, INVALID_INPUT } error_code;

error_code create_record_array(record **array, size_t size) {
    if (!array || size == 0) {
        return INVALID_INPUT;
    }

    *array = (record *)malloc(size * sizeof(record));
    if (*array == NULL) {
        return OUT_OF_MEMORY;
    }

    pthread_mutex_t *mutexes = (pthread_mutex_t *)calloc(size, sizeof(pthread_mutex_t));
    if (mutexes == NULL) {
        free(*array);
        return OUT_OF_MEMORY;
