use std::collections::VecDeque;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

#[derive(Debug)]
struct Record {
    value: i32,
}

enum LogLevel {
    Debug,
    Info,
    Error,
}

struct DataProcessor {
    data_stream: Arc<Mutex<VecDeque<i32>>>,
    max_rate: u64,
    log_level: LogLevel,
    prng_algorithm: PRNGAlgorithm,
}

impl DataProcessor {
    fn new(max_rate: u64, log_level: LogLevel, prng_algorithm: PRNGAlgorithm) -> Self {
        DataProcessor {
            data_stream: Arc::new(Mutex::new(VecDeque::new())),
            max_rate,
            log_level,
            prng_algorithm,
        }
    }

    fn processDataStream(&self) {
        let mut last_time = Instant::now();
        let mut records: Vec<Record> = Vec::new();

        while let Some(data) = self.data_stream.lock().unwrap().pop_front() {
            if last_time.elapsed() >= Duration::from_secs(1) / self.max_rate {
                // Process data
                records.push(Record { value: data });
                last_time = Instant::now();
            } else {
                // Queue data temporarily
                self.data_stream.lock().unwrap().push_back(data);
                break;
            }
        }

        if let Some(value) = records.pop() {
            match self.prng_algorithm {
                PRNGAlgorithm::MersenneTwister => {
                    // Generate a random index
                    let random_index: usize = mt19937::gen_range(0, records.len());
                    println!("Selected record with value: {}", records[random_index].value);
                }
                PRNGAlgorithm::Xorshift => {
                    // Generate a random index using Xorshift algorithm
                    let random_index: usize = xorshift::xorshift32() % records.len();
                    println!("Selected record with value: {}", records[random_index].value);
                }
            }
        }

        self.log(LogLevel::Info, "Data processing completed");
    }

    fn log(&self, level: LogLevel, message: &str) {
        match level {
            LogLevel::Debug => println!("[DEBUG] - {} - {}", Instant::now(), message),
            LogLevel::Info => println!("[INFO] - {} - {}", Instant::now(), message),
            LogLevel::Error => eprintln!("[ERROR] - {} - {}", Instant::now(), message),
        }
    }
}

enum PRNGAlgorithm {
    MersenneTwister,
    Xorshift,
}

fn main() {
    let data_processor = DataProcessor::new(10, LogLevel::Info, PRNGAlgorithm::MersenneTwister);
    data_processor.processDataStream();
}
