int processAndFindMax(long* offsets, int* keys, record** records, int maxRecords) {
    if (offsets == NULL || keys == NULL || records == NULL) {
        return ERROR_CODE;
    }

    *records = (record*)malloc(maxRecords * sizeof(record));
    if (*records == NULL) {
        return ERROR_CODE;
    }

    srand(time(NULL));
    for (int i = 0; i < maxRecords; i++) {
        (*records)[i].value = rand() % 1000; // Example range, adjust as needed
    }

    int* inputBuffer = (int*)malloc(1024 * sizeof(int)); // Adjust buffer size as needed
    if (inputBuffer == NULL) {
        free(*records);
        return ERROR_CODE;
    }

    int bufferIndex = 0;
    int maxInteger = INT_MIN;

    while (1) {
        int inputValue;
        if (scanf("%d", &inputValue) != 1) {
            break; // EOF or error
        }
        inputBuffer[bufferIndex++] = inputValue;

        if (bufferIndex == 1024) { // Adjust buffer size as needed
            for (int i = 0; i < bufferIndex; i++) {
                maxInteger = fmax(maxInteger, inputBuffer[i]);
            }
            bufferIndex = 0;
        }
    }

    // Flush remaining values in the buffer
    while (bufferIndex > 0) {
        maxInteger = fmax(maxInteger, inputBuffer[--bufferIndex]);
    }

    free(inputBuffer);
    return maxInteger;
}

