#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_LOG_LINE_LENGTH 1024
#define NUM_THREADS 4

typedef struct {
    int value;
} Record;

Record* recordArray = NULL;
long* offsetArray = NULL;
int arraySize = 0;
int maxRecords = 10000;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_barrier_t barrier;
FILE* logFile = NULL;
const char* logFilePath = "log.txt";

void* threadFunc(void* arg) {
    int id = *(int*)arg;
    srand(time(NULL) + id);

    for (int i = 0; i < maxRecords / NUM_THREADS; ++i) {
        pthread_mutex_lock(&mutex);
        if (arraySize >= maxRecords) {
            fprintf(stderr, "Error: Maximum records reached.\n");
            return NULL;
        }

        recordArray[arraySize].value = rand() % 1000; // Example range
        offsetArray[arraySize] = ftell(logFile);
        arraySize++;
        pthread_mutex_unlock(&mutex);
    }

    pthread_barrier_wait(&barrier);

    return NULL;
}

int main() {
    int rc;
    pthread_t threads[NUM_THREADS];
    int thread_ids[NUM_THREADS];

    logFile = fopen(logFilePath, "r");
    if (!logFile) {
        perror("Error opening log file");
        return 1;
    }

    recordArray = (Record*)malloc(maxRecords * sizeof(Record));
    offsetArray = (long*)malloc(maxRecords * sizeof(long));

    if (!recordArray || !offsetArray) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        fclose(logFile);
        return 1;
    }

    pthread_barrier_init(&barrier, NULL, NUM_THREADS);

    for (int i = 0; i < NUM_THREADS; ++i) {
        thread_ids[i] = i;
        rc = pthread_create(&threads[i], NULL, threadFunc, &thread_ids[i]);
        if (rc) {
            fprintf(stderr, "Error creating thread %d: %s\n", i, strerror(rc));
            return 1;
        }
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    pthread_barrier_destroy(&barrier);

    fclose(logFile);
    free(recordArray);
    free(offsetArray);

    printf("Processed %d records.\n", arraySize);

    return 0;
}
