// Function to generate and filter data from an input file
void generateAndFilterData(const char* inputFilePath, int* outputBuffer, int maxOutputSize, int seedValue, double filterThreshold) {
    // Initialize variables
    FILE* inputFile = fopen(inputFilePath, "r");
    if (inputFile == NULL) {
        perror("Failed to open input file");
        return;
    }

    srand(seedValue);
    int totalRead = 0, selectedCount = 0, storedCount = 0;

    // Process data in batches
    char line[256];
    while (fgets(line, sizeof(line), inputFile) != NULL && totalRead < maxOutputSize) {
        // Read and process each integer from the line
        int num;
        if (sscanf(line, "%d", &num) == 1) {
            totalRead++;
            if ((double)rand() / RAND_MAX < filterThreshold) {
                outputBuffer[storedCount++] = num;
                selectedCount++;
            }
        }
    }

    // Close the input file
    fclose(inputFile);

    // Log progress and results
    printf("Total integers read: %d\n", totalRead);
    printf("Integers selected: %d\n", selectedCount);
    printf("Integers stored in output buffer: %d\n", storedCount);
}

int main() {
    const char* inputFilePath = "large_dataset.csv";
    int outputBuffer[1000];
    int maxOutputSize = 1000;
    int seedValue = time(NULL);
    double filterThreshold = 0.5;

    generateAndFilterData(inputFilePath, outputBuffer, maxOutputSize, seedValue, filterThreshold);

    return 0;
}
