#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>

#define SECURE_PRNG "/dev/urandom"
#define PERFORMANCE_PRNG "/dev/random"

typedef struct {
    int id;
} Record;

int generateAndTransmitRecords(int count, int minValue, int maxValue, void* inputChannel, int timeoutMs, const char* prngAlgorithm) {
    if (count <= 0 || minValue > maxValue) {
        return -1; // Invalid parameters
    }

    FILE* prng = fopen(prngAlgorithm == "secure" ? SECURE_PRNG : PERFORMANCE_PRNG, "rb");
    if (!prng) {
        perror("Failed to open PRNG device");
        return -2; // Memory allocation failure
    }

    Record* records = (Record*)malloc(count * sizeof(Record));
    if (!records) {
        fclose(prng);
        perror("Memory allocation failed");
        return -3;
    }

    for (int i = 0; i < count; ++i) {
        fread(&records[i].id, sizeof(int), 1, prng);
        records[i].id = minValue + records[i].id % (maxValue - minValue + 1);
    }
    fclose(prng);

    struct sockaddr_in serverAddr;
    memset(&serverAddr, 0, sizeof(serverAddr));
    serverAddr.sin_family = AF_INET;
    inet_pton(AF_INET, "remote_server_ip", &serverAddr.sin_addr);
    serverAddr.sin_port = htons(12345); // Replace with actual port

    fd_set writeSet;
    FD_ZERO(&writeSet);
    FD_SET(inputChannel, &writeSet);

    struct timeval timeout;
    timeout.tv_sec = timeoutMs / 1000;
    timeout.tv_usec = (timeoutMs % 1000) * 1000;

    for (int i = 0; i < count; ++i) {
        int result = select(FD_SETSIZE, NULL, &writeSet, NULL, &timeout);
        if (result == -1 && errno != EINTR) {
            perror("Select error");
            free(records);
            return -4;
        } else if (result == 0) {
            fprintf(stderr, "Timeout occurred\n");
            free(records);
            return -5;
        }

        int bytesSent = write(inputChannel, &records[i].id, sizeof(int));
        if (bytesSent != sizeof(int)) {
            perror("Write error");
            free(records);
            return -6;
        }
    }

    free(records);
    return 0; // Success
}
