int processAndFindMax(long range_start, long range_end, int records_size, int keys_range_start, int keys_range_end) {
    if (range_start >= range_end || records_size < 0 || keys_range_start > keys_range_end) {
        return -1; // Invalid parameters
    }

    srand(time(0));
    Record* records = malloc(records_size * sizeof(Record));
    NFAPI_CRC_INDICATION_PDU_T* nfaapi_records = malloc(records_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!records || !nfaapi_records) {
        return -2; // Memory allocation failed
    }

    for (int i = 0; i < records_size; i++) {
        records[i].timestamp = range_start + rand() % (range_end - range_start);
        records[i].key = keys_range_start + rand() % (keys_range_end - keys_range_start);

        nfaapi_records[i].ue_info_tag = RX_UE_INFORMATION_TAG(rand());
        nfaapi_records[i].rnti = (uint16_t)rand();
        nfaapi_records[i].crc_flag = NFAPI_CRC_INDICATION_REL8_TAG(rand());
    }

    // Process and find max
    int max_value = keys_range_start;
    while (1) {
        int input;
        if (scanf("%d", &input) != 1) break;
        if (input > max_value) max_value = input;
    }

    free(records);
    free(nfaapi_records);

    return max_value;
}

int main() {
    long range_start = 0, range_end = 1000000;
    int records_size = 1000, keys_range_start = -500, keys_range_end = 500;

    int result = processAndFindMax(range_start, range_end, records_size, keys_range_start, keys_range_end);
    if (result == -1) {
        printf("Invalid parameters\n");
    } else if (result == -2) {
        printf("Memory allocation failed\n");
    } else {
        printf("Maximum value from input: %d\n", result);
    }

    return 0;
}
