        fprintf(stderr, "Error: Invalid sequence parameters.\n");
        return -1;
    }

    if (!seed_data || seed_offset < 0) {
        fprintf(stderr, "Error: Invalid seed data or offset.\n");
        return -2;
    }

    unsigned char *sequences = (unsigned char *)malloc(sequence_count * sequence_length);
    if (!sequences) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -3;
    }

    FILE *output = fopen(output_file, "w");
    if (!output) {
        fprintf(stderr, "Error: Unable to open output file.\n");
        free(sequences);
        return -4;
    }

    // Seed the PRNG
    srand(seed_data[seed_offset]);

    // Generate random sequences
    for (int i = 0; i < sequence_count; ++i) {
        for (int j = 0; j < sequence_length; ++j) {
            sequences[i * sequence_length + j] = rand();
        }
    }

    // Read integers from standard input
    int input_int;
    while (scanf("%d", &input_int) == 1) {
        // Process and log the integer
