#include <time.h>

// Define structures for record, transaction, and metadata
typedef struct {
    int value;
} record;

typedef struct {
    long account_id;
    int amount;
} transaction;

typedef struct {
    // Additional information about each record
    char info[100];
} metadata;

// Function to generate a non-cryptographic pseudo-random number
int PRNG(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Main function to dynamically allocate memory and initialize arrays
int allocate_and_initialize(long** account_ids, int** keys, record** records, transaction** transactions, metadata** metadatas, int range_start, int range_end) {
    srand(time(NULL)); // Seed PRNG for reproducibility

    *account_ids = (long*)malloc(5 * sizeof(long));
    *keys = (int*)malloc(5 * sizeof(int));
    *records = (record*)malloc(5 * sizeof(record));
    *transactions = (transaction*)malloc(5 * sizeof(transaction));
    *metadatas = (metadata*)malloc(5 * sizeof(metadata));

    if (*account_ids == NULL || *keys == NULL || *records == NULL || *transactions == NULL || *metadatas == NULL) {
        printf("Memory allocation failed\n");
        return -1;
    }

    for (int i = 0; i < 5; i++) {
        (*account_ids)[i] = PRNG(1, 100000);
        (*keys)[i] = PRNG(1, 1000);

        // Initialize record
        (*records)[i].value = PRNG(range_start, range_end);

        // Initialize transaction with unique values within the specified range
        int value;
        do {
            value = PRNG(range_start, range_end);
        } while (is_transaction_duplicate(*transactions, i, value));
        (*transactions)[i].account_id = (*account_ids)[i];
        (*transactions)[i].amount = value;

        // Initialize metadata
        snprintf((*metadatas)[i].info, sizeof((*metadatas)[i].info), "Metadata for record %d", i);
    }

    return 0;
}

// Helper function to check if a transaction value is unique within the array
int is_transaction_duplicate(transaction* transactions, int index, int value) {
    for (int i = 0; i < index; i++) {
        if (transactions[i].amount == value) {
            return 1;
        }
    }
    return 0;
}

// Main function to demonstrate the usage
int main() {
    long* account_ids;
    int* keys;
    record* records;
    transaction* transactions;
    metadata* metadatas;

    if (allocate_and_initialize(&account_ids, &keys, &records, &transactions, &metadatas, 100, 999) == 0) {
        printf("Memory allocation and initialization successful\n");
        // Free allocated memory here
    }

    return 0;
