struct ResourceBundle {
    long* ids;
    char** usernames;
    int* statuses;
    int* key_ranges;
    time_t last_modified;
};

void* convert_to_pdf(void* arg) {
    // Simulate JPEG to PDF conversion
    printf("Converting image...\n");
    sleep(1); // Simulate time taken for conversion
    return NULL;
}

struct ResourceBundle* load_resource_bundle(const char* file_path, int num_images) {
    struct ResourceBundle* bundle = (struct ResourceBundle*)malloc(sizeof(struct ResourceBundle));
    if (!bundle) {
        perror("Failed to allocate memory for resource bundle");
        return NULL;
    }

    bundle->ids = (long*)calloc(num_images, sizeof(long));
    bundle->usernames = (char**)calloc(num_images, sizeof(char*));
    bundle->statuses = (int*)calloc(num_images, sizeof(int));
    bundle->key_ranges = (int*)calloc(num_images * 2, sizeof(int));

    if (!bundle->ids || !bundle->usernames || !bundle->statuses || !bundle->key_ranges) {
        perror("Failed to allocate memory for resource bundle components");
        free(bundle);
        return NULL;
    }

    time_t current_time = time(NULL);
    bundle->last_modified = current_time;

    pthread_t* threads = (pthread_t*)malloc(num_images * sizeof(pthread_t));
    if (!threads) {
        perror("Failed to allocate memory for threads");
        free(bundle->ids);
        free(bundle->usernames);
        free(bundle->statuses);
        free(bundle->key_ranges);
        free(bundle);
        return NULL;
    }

    for (int i = 0; i < num_images; ++i) {
        // Simulate unique ID generation with retries
        long id;
        int retries = 0;
        do {
            id = rand() % 1000000;
            for (int j = 0; j < i; ++j) {
                if (bundle->ids[j] == id) {
                    break;
                }
            }
            retries++;
        } while (retries < 100 && bundle->ids[i-1] == id);

        bundle->ids[i] = id;
        bundle->usernames[i] = strdup("User"); // Simplified for example
        bundle->statuses[i] = 0;
        bundle->key_ranges[2 * i] = rand() % 1000;
        bundle->key_ranges[2 * i + 1] = bundle->key_ranges[2 * i] + rand() % 100;

        if (pthread_create(&threads[i], NULL, convert_to_pdf, NULL) != 0) {
            perror("Failed to create thread");
            // Cleanup and exit on error
        }
    }

    for (int i = 0; i < num_images; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(threads);
    return bundle;
}

void free_resource_bundle(struct ResourceBundle* bundle, int num_images) {
    if (bundle) {
        for (int i = 0; i < num_images; ++i) {
            free(bundle->usernames[i]);
        }
        free(bundle->ids);
        free(bundle->usernames);
        free(bundle->statuses);
        free(bundle->key_ranges);
        free(bundle);
    }
}

int main() {
    srand(time(NULL));
    struct ResourceBundle* bundle = load_resource_bundle("images.txt", 5);
    if (bundle) {
        // Use the resource bundle
        free_resource_bundle(bundle, 5);
    }
    return 0;
}
```

