    if (!inputArray) {
        free(dynamicOffsets);
        free(dynamicKeys);
        free(dynamicRecords);
        return -2; // Error: Memory allocation failed
    }

    printf("Enter up to %d integers:\n", inputLimit);
    int count = 0;
    while (scanf("%d", &inputArray[count]) == 1 && count < inputLimit) {
        count++;
