// Function to process and log data
int processAndLogData(int dataSize, int minValue, int maxValue, int inputLimit, const char* outputFile, ExternalLogService* externalLogService) {
    // Seed the PRNG
    srand(time(NULL));

    // Allocate memory for arrays
    int* generatedData = (int*)malloc(dataSize * sizeof(int));
    if (generatedData == NULL) {
        return -1; // Memory allocation failed
    }

    int* inputData = (int*)malloc(inputLimit * sizeof(int));
    if (inputData == NULL) {
        free(generatedData);
        return -1; // Memory allocation failed
    }

    // Initialize the arrays with random values
    for (int i = 0; i < dataSize; ++i) {
        generatedData[i] = minValue + rand() % (maxValue - minValue + 1);
    }

    int maxGenerated = generatedData[0];
    for (int i = 1; i < dataSize; ++i) {
        if (generatedData[i] > maxGenerated) {
            maxGenerated = generatedData[i];
        }
    }

    // Read integers from standard input
    int inputCount = 0;
    while (inputCount < inputLimit && scanf("%d", &inputData[inputCount]) == 1) {
        if (inputData[inputCount] > maxGenerated) {
            maxGenerated = inputData[inputCount];
        }
        ++inputCount;
    }

    // Log the maximum values
    time_t timestamp = time(NULL);
    externalLogService->logEvent("Maximum generated value: ", timestamp);
    printf("%d\n", maxGenerated);

    if (inputCount > 0) {
        externalLogService->logEvent("Maximum input value: ", timestamp);
        printf("%d\n", inputData[inputCount - 1]);
    }

    // Write data to the output file
    FILE* file = fopen(outputFile, "w");
    if (file != NULL) {
        for (int i = 0; i < dataSize; ++i) {
            fprintf(file, "%d ", generatedData[i]);
        }
        for (int i = 0; i < inputCount; ++i) {
            fprintf(file, "%d ", inputData[i]);
        }
        fclose(file);
    } else {
        return -1; // Failed to open output file
    }

    // Free allocated memory
    free(generatedData);
    free(inputData);

    return 0; // Success
}
