logEntry* loadLogEntries(const char* configFilePath) {
    FILE* file = fopen(configFilePath, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return NULL;
    }

    logEntry* entries = (logEntry*)malloc(MAX_LOG_ENTRIES * sizeof(logEntry));
    if (!entries) {
        perror("Memory allocation failed for log entries");
        fclose(file);
        return NULL;
    }

    char buffer[1024];
    int count = 0;

    while (fgets(buffer, sizeof(buffer), file)) {
        if (count >= MAX_LOG_ENTRIES) break;

        // Assuming the format is: "timestamp,eventType,eventDescription"
        long timestamp;
        int eventType;
        char* eventDescription = "";

        char* token = strtok(buffer, ",");
        if (token && parseISO8601(token, &timestamp)) {
            token = strtok(NULL, ",");
            if (token && validateEventType(atoi(token))) {
                eventDescription = strtok(NULL, ",");
                if (!eventDescription) {
                    eventDescription = "";
                }
            }
        }

        entries[count].timestamp = timestamp;
        entries[count].eventType = atoi(token);
        entries[count].eventDescription = strdup(eventDescription);

        count++;
    }

    fclose(file);
    return entries;
}

