#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>

#define MAX_RECORDS 100000
#define RECORD_SIZE sizeof(int)
#define BUFFER_SIZE 4096

typedef struct {
    int value;
} record;

void initialize_records(record *records, int count) {
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        records[i].value = rand() % 1000; // Random number between 0 and 999
    }
}

record* resize_records(record *old_records, int old_count, int new_count) {
    record *new_records = realloc(old_records, new_count * RECORD_SIZE);
    if (new_records != NULL) {
        initialize_records(new_records + old_count, new_count - old_count);
    }
    return new_records;
}

void sort_records(record *records, int count, int ascending) {
    qsort(records, count, RECORD_SIZE, ascending ? compare_asc : compare_desc);
}

int compare_asc(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

int compare_desc(const void *a, const void *b) {
    return (*(int*)b - *(int*)a);
}

void eliminate_duplicates(record *records, int *count) {
    for (int i = 0; i < *count - 1; i++) {
        if (records[i].value == records[i + 1].value) {
            (*count)--;
            memmove(&records[i], &records[i + 1], (*count - i) * RECORD_SIZE);
            i--; // Adjust index after removal
        }
    }
}

void find_and_print_smallest(record *records, int count) {
    if (count > 0) {
        qsort(records, count, RECORD_SIZE, compare_asc);
        printf("Smallest value: %d\n", records[0].value);
    } else {
        printf("No data available.\n");
    }
}

void manage_memory(record **records, int *count, int new_count) {
    if (new_count > MAX_RECORDS) {
        fprintf(stderr, "Error: Maximum record limit exceeded.\n");
        return;
    }

    *records = resize_records(*records, *count, new_count);
    if (*records == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(1);
    }
    *count = new_count;
}

void free_memory(record *records) {
    free(records);
}
