using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Logging;

public class AesCbcDecryptor
{
    private readonly ILogger<AesCbcDecryptor> _logger;
    private readonly ICryptoTransformFactory _cryptoTransformFactory;
    private readonly IKeyManager _keyManager;
    private readonly IHmacValidator _hmacValidator;

    public AesCbcDecryptor(ILogger<AesCbcDecryptor> logger, ICryptoTransformFactory cryptoTransformFactory, IKeyManager keyManager, IHmacValidator hmacValidator)
    {
        _logger = logger;
        _cryptoTransformFactory = cryptoTransformFactory;
        _keyManager = keyManager;
        _hmacValidator = hmacValidator;
    }

    public byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] iv, PaddingMode paddingMode)
    {
        try
        {
            if (key == null || key.Length != 16 && key.Length != 24 && key.Length != 32)
                throw new ArgumentException("Invalid key length", nameof(key));

            if (iv == null || iv.Length != 16)
                throw new ArgumentException("Invalid IV length", nameof(iv));

            using (var aes = Aes.Create())
            {
                aes.KeySize = key.Length * 8;
                aes.Mode = CipherMode.CBC;
                aes.Padding = paddingMode;

                aes.Key = key;
                aes.IV = iv;

                using (var decryptor = aes.CreateDecryptor())
                using (var memoryStream = new MemoryStream(ciphertext))
                using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
                {
                    var decryptedData = new byte[ciphertext.Length];
                    int bytesRead = cryptoStream.Read(decryptedData, 0, decryptedData.Length);
                    Array.Resize(ref decryptedData, bytesRead);

                    _hmacValidator.ValidateHmac(decryptedData, key); // Validate HMAC

                    return decryptedData;
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Decryption failed with key length {KeyLength}, IV length {IvLength} and padding mode {PaddingMode}", key.Length * 8, iv.Length, paddingMode);
            throw new CryptographicException("Decryption failed", ex);
        }
    }
}
