    char* eventType;
    char* description;
} logEntry;

logEntry** logs = NULL;
size_t currentSize = 0;

// Secure PRNG function
unsigned int secureRandom() {
    static unsigned long seed = 0;
    if (seed == 0) seed = time(NULL); // Initialize seed on first call
    return seed = seed * 1664525 + 1013904223; // LCG
