// Function to add a log entry
void addLogEntry(const char* eventType, const char* description) {
    if (currentSize >= MAX_ENTRIES) {
        fprintf(stderr, "Log storage exceeded maximum capacity.\n");
        return;
    }

    logs[currentSize] = (logEntry*)malloc(sizeof(logEntry));
    logs[currentSize]->timestamp = time(NULL);
    logs[currentSize]->eventType = strdup(eventType);
    logs[currentSize]->description = strdup(description);

    currentSize++;
}

// Function to monitor memory usage
void checkMemoryUsage() {
    size_t totalSize = 0;
    for (size_t i = 0; i < currentSize; i++) {
        totalSize += sizeof(logEntry) + strlen(logs[i]->eventType) + strlen(logs[i]->description);
    }

    if (totalSize > THRESHOLD) {
        fprintf(stderr, "Memory usage is above threshold: %zu bytes.\n", totalSize);
        // Trigger alert mechanism here
    }
}

// Function to free all log entries and reset the system
void clearLogs() {
    for (size_t i = 0; i < currentSize; i++) {
        free(logs[i]->eventType);
        free(logs[i]->description);
        free(logs[i]);
    }
    currentSize = 0;
}

