#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

#define MAX_COMMAND_LENGTH 256
#define MAX_CONCURRENT_PROCESSES 10

typedef struct {
    char commands[3][MAX_COMMAND_LENGTH];
    int num_commands;
} CommandPipeline;

int execute_pipeline(CommandPipeline *pipeline) {
    pid_t pids[3] = {0};
    int pipes[2];

    for (int i = 0; i < pipeline->num_commands - 1; i++) {
        pipe(pipes);

        if ((pids[i] = fork()) == 0) {
            dup2(i == 0 ? STDIN_FILENO : pipes[i-1][0], STDIN_FILENO);
            dup2(pipes[i][1], STDOUT_FILENO);

            close(pipes[i]);
            close(pipes[i-1][0]);
            close(pipes[i-1][1]);

            char *args[] = {pipeline->commands[i], NULL};
            execvp(args[0], args);
        }

        if (i > 0) {
            close(pipes[i-1][0]);
            close(pipes[i-1][1]);
        }
    }

    dup2((pids[pipeline->num_commands - 2] == 0 ? STDIN_FILENO : pipes[1][0]), STDIN_FILENO);

    if (pipeline->num_commands > 1) {
        close(pipes[1][1]);
    }

    char *args[] = {pipeline->commands[pipeline->num_commands - 1], NULL};
    execvp(args[0], args);

    for (int i = 0; i < pipeline->num_commands; i++) {
        if (pids[i] != 0) {
            waitpid(pids[i], NULL, 0);
        }
    }

    return 0;
}

void log_pipeline(CommandPipeline *pipeline) {
    // Log the pipeline execution details to a centralized monitoring system
    printf("Executing pipeline with %d commands\n", pipeline->num_commands);
    for (int i = 0; i < pipeline->num_commands; i++) {
        printf("Command %d: %s\n", i, pipeline->commands[i]);
    }
}

void limit_concurrent_processes(int limit) {
    // Enforce a configurable limit on the number of concurrently running background processes
    if (limit > MAX_CONCURRENT_PROCESSES) {
        fprintf(stderr, "Error: Limit exceeds maximum concurrent processes allowed.\n");
        exit(EXIT_FAILURE);
    }
}

int main() {
    CommandPipeline pipeline = {{"ls -l", "grep foo", "sort"}, 3};

    log_pipeline(&pipeline);
    limit_concurrent_processes(5);

    execute_pipeline(&pipeline);

    return 0;
}
