    // Validate inputs
    if (num_records == 0 || offsets == NULL || keys == NULL || records == NULL) {
        return -1; // Invalid input
    }

    // Seed PRNG with a non-zero value
    srand(time(NULL));

    // Allocate memory for records
    *records = (record *)malloc(num_records * sizeof(record));
    if (*records == NULL) {
        return -2; // Memory allocation failed
    }

    // Initialize records with random values within a specified range
    int min_val = 0;
    int max_val = 1000;
    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].value = rand() % (max_val - min_val + 1) + min_val;
        (*records)[i].precision = ((float)(rand() % 100)) / 100.0f;
        (*records)[i].timestamp = time(NULL);
    }

    // Find and print the largest integer
    int max_value = (*records)[0].value;
    for (size_t i = 1; i < num_records; ++i) {
        if ((*records)[i].value > max_value) {
            max_value = (*records)[i].value;
        }
    }

    printf("Largest integer: %d\n", max_value);

    // Free allocated memory
    free(*records);

    return 0; // Success
}
