    }

    // Allocate memory for arrays
    offsets = malloc(num_records * sizeof(long));
    keys = malloc(num_records * sizeof(int));
    records = malloc(num_records * sizeof(record*));

    if (offsets == NULL || keys == NULL || records == NULL) {
        return -2; // Memory allocation failed
    }

    // Initialize arrays
