const fs = require('fs');
const concurrentQueue = require('concurrent-queue');

function loadConfigHandler(actionType) {
  const handlerPath = `./configHandlers/${actionType}.js`;
  try {
    return require(handlerPath);
  } catch (e) {
    throw new Error(`Failed to load handler for action: ${actionType}`);
  }
}

async function manageConfiguration(filename, actionType, key, value) {
  const queue = concurrentQueue({
    concurrency: 10,
    limit: Infinity
  });

  return queue.push(async () => {
    let configHandler;
    try {
      configHandler = loadConfigHandler(actionType);
    } catch (e) {
      console.error(e.message);
      return;
    }

    try {
      if (!configHandler[key]) {
        throw new Error(`Invalid configuration key: ${key}`);
      }

      switch (actionType) {
        case 'add':
          configHandler[key](value);
          break;
        case 'set':
          configHandler.set(key, value);
          break;
        case 'delete':
          delete configHandler[key];
          break;
        default:
          throw new Error(`Unsupported action type: ${actionType}`);
      }

      await fs.promises.writeFile(filename, JSON.stringify(configHandler));
    } catch (e) {
      console.error(e.message);
    }
  });
}
