#include <dirent.h>

#define LOG_FILE "operation_log.txt"

typedef struct {
    long offset;
    int key;
} record;

int initialize_data_store(char* base_dir, int size, int min_key, int max_key, int disable_logging) {
    if (size <= 0 || min_key >= max_key) {
        return -1; // Invalid parameters
    }

    char dir_name[256];
    snprintf(dir_name, sizeof(dir_name), "%s_%ld_%d", base_dir, time(NULL), getpid());

    DIR* dir = opendir(dir_name);
    if (dir == NULL) {
        if (mkdir(dir_name, 0755) != 0) {
            perror("Failed to create directory");
            return -2;
        }
    } else {
        closedir(dir);
    }

    char env_var[256];
    snprintf(env_var, sizeof(env_var), "RECORD_DIR=%s", dir_name);

    if (getenv("RECORD_DIR") == NULL) {
        putenv(env_var);
    } else {
        printf("Environment variable RECORD_DIR is already set.\n");
    }

    record* records = malloc(size * sizeof(record));
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        return -3;
    }

    FILE* log_file = disable_logging ? NULL : fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "Initialization started: base_dir=%s, size=%d, min_key=%d, max_key=%d\n", base_dir, size, min_key, max_key);
    }

    for (int i = 0; i < size; i++) {
        records[i].offset = i * sizeof(record);
        records[i].key = arc4random_uniform(max_key - min_key + 1) + min_key;

        if (log_file != NULL) {
            fprintf(log_file, "Record %d initialized: offset=%ld, key=%d\n", i, records[i].offset, records[i].key);
        }
    }

    free(records);

    if (log_file != NULL) {
        fprintf(log_file, "Initialization completed.\n");
        fclose(log_file);
    }

    return 0;
}

int main(int argc, char* argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <base_dir> <size> <min_key> <max_key> [<disable_logging>]\n", argv[0]);
        return 1;
    }

    int size = atoi(argv[2]);
    int min_key = atoi(argv[3]);
    int max_key = atoi(argv[4]);
    int disable_logging = (argc > 5) && strcmp(argv[5], "1") == 0;

    initialize_data_store(argv[1], size, min_key, max_key, disable_logging);

    return 0;
}
