typedef struct {
    int random_value;
    uint32_t checksum;
} record;

int generate_records(long *offsets, int *keys, record **records, size_t count, int min_val, int max_val) {
    if (count == 0 || min_val > max_val) {
        return -1; // Invalid input
    }

    offsets = malloc(count * sizeof(long));
    keys = malloc(count * sizeof(int));
    records = malloc(count * sizeof(record *));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return -2; // Memory allocation failure
    }

    srand(time(0)); // Initialize PRNG seed

    for (size_t i = 0; i < count; ++i) {
        offsets[i] = rand();
        keys[i] = rand() % (max_val - min_val + 1) + min_val;
        records[i] = malloc(sizeof(record));

        if (!records[i]) {
            // Cleanup previously allocated memory
            for (size_t j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(offsets);
            free(keys);
            free(records);
            return -2; // Memory allocation failure
        }

        records[i]->random_value = rand() % (max_val - min_val + 1) + min_val;
        records[i]->checksum = (uint32_t)(keys[i] ^ offsets[i]);
    }

    return 0; // Success
}

void free_records(record **records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(records[i]);
    }
    free(records);
}
