    StatusIndicator **status_indicators;
    int num_nodes;
} DatabaseClient;

DatabaseClient* initializeDatabaseClient(const char *config_file_path) {
    // Allocate memory for the client structure
    DatabaseClient *client = malloc(sizeof(DatabaseClient));
    if (client == NULL) {
        perror("Failed to allocate memory for database client");
        return NULL;
    }

    // Parse the JSON configuration file
    json_error_t error;
    json_t *root = json_load_file(config_file_path, 0, &error);
    if (!root) {
        fprintf(stderr, "Error loading config file: %s\n", error.text);
        free(client);
        return NULL;
    }

    // Extract connection parameters, authentication token, and metadata
    json_t *params_array = json_object_get(root, "connection_params");
    json_t *auth_token_value = json_object_get(root, "auth_token");
    json_t *metadata_value = json_object_get(root, "metadata");

    client->num_nodes = json_array_size(params_array);
    client->params = malloc(client->num_nodes * sizeof(ConnectionParams*));
    for (size_t i = 0; i < client->num_nodes; i++) {
        ConnectionParams *params = malloc(sizeof(ConnectionParams));
        params->hostname = strdup(json_string_value(json_array_get(json_object_get(params_array, "hostnames"), i)));
        params->port = json_integer_value(json_array_get(json_object_get(params_array, "ports"), i));
        params->dbname = strdup(json_string_value(json_array_get(json_object_get(params_array, "dbnames"), i)));
        client->params[i] = params;
    }

    client->auth_token = malloc(sizeof(AuthToken));
    client->auth_token->token = strdup(json_string_value(auth_token_value));

    client->metadata = malloc(sizeof(Metadata));
    client->metadata->schema_info = strdup(json_string_value(metadata_value));

    // Initialize status indicators
    client->status_indicators = malloc(client->num_nodes * sizeof(StatusIndicator*));
    for (size_t i = 0; i < client->num_nodes; i++) {
        StatusIndicator *status = malloc(sizeof(StatusIndicator));
        status->connected = 0;
        client->status_indicators[i] = status;
    }

    // Connect to database nodes concurrently
    pthread_t threads[client->num_nodes];
    for (size_t i = 0; i < client->num_nodes; i++) {
        int ret = pthread_create(&threads[i], NULL, connectToNode, client->params[i]);
        if (ret != 0) {
            fprintf(stderr, "Failed to create thread for node %zu\n", i);
            freeDatabaseClient(client);
            return NULL;
        }
    }

    // Wait for all threads to finish
    for (size_t i = 0; i < client->num_nodes; i++) {
        pthread_join(threads[i], NULL);
    }

    json_decref(root);

    return client;
}

void freeDatabaseClient(DatabaseClient *client) {
    for (int i = 0; i < client->num_nodes; i++) {
        free(client->params[i]->hostname);
        free(client->params[i]);
        free(client->status_indicators[i]);
    }
    free(client->params);
    free(client->auth_token->token);
    free(client->auth_token);
    free(client->metadata->schema_info);
    free(client->metadata);
    free(client->status_indicators);
