#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_SESSIONS 10000

typedef struct {
    int id;
    time_t timestamp;
    unsigned long token;
} Session;

typedef struct {
    Session sessions[MAX_SESSIONS];
    pthread_mutex_t lock;
    int session_count;
    int max_sessions;
    int expiration_policy;
    double session_creation_rate;
} SessionPool;

Session* create_session(SessionPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->session_count >= pool->max_sessions) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Maximum sessions reached
    }
    Session* new_session = &pool->sessions[pool->session_count];
    new_session->id = pool->session_count;
    new_session->timestamp = time(NULL);
    new_session->token = random(); // Using random for simplicity, replace with a cryptographically secure PRNG in production
    pool->session_count++;
    pthread_mutex_unlock(&pool->lock);
    return new_session;
}

void expire_sessions(SessionPool* pool) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->session_count; i++) {
        if (time(NULL) - pool->sessions[i].timestamp > pool->expiration_policy) {
            // Perform session cleanup here
            pool->session_count--;
            i--; // Adjust index after removal
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void init_session_pool(SessionPool* pool, int max_sessions, int expiration_policy, double session_creation_rate) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->max_sessions = max_sessions;
    pool->expiration_policy = expiration_policy;
    pool->session_creation_rate = session_creation_rate;
    pool->session_count = 0;
}

void destroy_session_pool(SessionPool* pool) {
    pthread_mutex_destroy(&pool->lock);
}

// Example usage
int main() {
    SessionPool pool;
    init_session_pool(&pool, MAX_SESSIONS, 3600, 10.0); // Expiration policy of 1 hour, creation rate of 10 sessions per second

    // Simulate session creation and expiration
    for (int i = 0; i < 20000; i++) {
        if ((double)rand() / RAND_MAX < pool.session_creation_rate) {
            create_session(&pool);
        }
        expire_sessions(&pool);
    }

    destroy_session_pool(&pool);
    return 0;
}
```

This code snippet provides a basic structure for managing a session pool with concurrency support. It includes functions to create new sessions, expire old sessions, and initialize/destroy the session pool. The example usage in the `main` function demonstrates how to simulate high-load scenarios by creating sessions based on a configured rate and expiring them according to a policy.

Note: This code uses a simple non-cryptographically secure random number generator (`random()`) for generating session tokens. In a production environment, you should replace this with a cryptographically secure pseudo-random number generator (PRNG) such as `getrandom()` or `rand_r()` with appropriate seeding mechanisms.']

