#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <openssl/md5.h>

#define MAX_RECORDS 1000000

typedef struct {
    int value;
    float precision;
    time_t timestamp;
} record;

int processAndFindMax(long* offsets, int* keys, record* records, size_t num_records) {
    if (!offsets || !keys || !records || num_records > MAX_RECORDS) {
        return -1; // Invalid input
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand_r(&offsets[i]); // Using non-cryptographic PRNG for simplicity
        records[i].precision = 0.1f * rand_r(&keys[i]);
        records[i].timestamp = time(NULL);
    }

    int max_value = records[0].value;
    for (size_t i = 1; i < num_records; ++i) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }

    printf("Max value: %d\n", max_value);
    return 0;
}

unsigned char* computeMD5(const char* str, size_t length) {
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5_CTX md5;
    MD5_Init(&md5);
    MD5_Update(&md5, str, length);
    MD5_Final(hash, &md5);

    // Convert the hash to a hexadecimal string
    static char hex_hash[2 * MD5_DIGEST_LENGTH + 1];
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(hex_hash + i * 2, "%02x", hash[i]);
    }

    return strdup(hex_hash);
}

int main() {
    long offsets[MAX_RECORDS];
    int keys[MAX_RECORDS];
    record records[MAX_RECORDS];

    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        offsets[i] = time(NULL);
        keys[i] = rand();
    }

    size_t num_records = fread(keys, sizeof(int), MAX_RECORDS, stdin);
    if (num_records > 0 && processAndFindMax(offsets, keys, records, num_records) != 0) {
        fprintf(stderr, "Error processing and finding max value.\n");
        return EXIT_FAILURE;
    }

    const char* input_string = "Example string for MD5";
    unsigned char* md5_result = computeMD5(input_string, strlen(input_string));
    if (md5_result) {
        printf("MD5 hash: %s\n", md5_result);
        free(md5_result);
    } else {
        fprintf(stderr, "Error computing MD5 hash.\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```

