#define RANDOM_RANGE 1000

typedef struct {
    int value;
} record;

int allocate_arrays(long **offsets, int **keys, record ***records, long num_elements) {
    *offsets = (long *)malloc(num_elements * sizeof(long));
    if (*offsets == NULL) return -1;

    *keys = (int *)malloc(num_elements * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return -1;
    }

    *records = (record **)malloc(num_elements * sizeof(record *));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -1;
    }

    for (long i = 0; i < num_elements; i++) {
        (*records)[i] = (record *)malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            for (long j = 0; j < i; j++) free((*records)[j]);
            free(*offsets);
            free(*keys);
            free(*records);
            return -1;
        }
        (*records)[i]->value = rand() % RANDOM_RANGE;
    }

    srand(time(NULL));
    for (long i = 0; i < num_elements; i++) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand();
    }

    return 0;
}

int update_array(long *offsets, int *keys, record **records, long index, int new_value) {
    if (index >= 0 && index < num_elements) {
        records[index]->value = new_value;
        return 0;
    }
    return -1;
}

void free_arrays(long *offsets, int *keys, record **records, long num_elements) {
    for (long i = 0; i < num_elements; i++) free(records[i]);
    free(offsets);
    free(keys);
    free(records);
}
