typedef struct LogRecord {
    char message[13]; // 12 characters + null terminator
    int priority;
} LogRecord;

int init_log_records(LogRecord **records, size_t num_records) {
    if (num_records == 0) {
        return -1; // Invalid input
    }

    *records = malloc(num_records * sizeof(LogRecord));
    if (*records == NULL) {
        return -2; // Memory allocation failed
    }

    unsigned char random_bytes[4];
    srand(time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        // Generate a cryptographically secure pseudo-random string
        if (!RAND_bytes(random_bytes, sizeof(random_bytes))) {
            free(*records);
            return -3; // PRNG failure
        }

        for (int j = 0; j < 12; ++j) {
            (*records)[i].message[j] = 'A' + (random_bytes[j] % 26); // Simplified example, use a proper charset
        }
        (*records)[i].message[12] = '\0';

        // Generate a random priority between 1 and 5
        (*records)[i].priority = rand() % 5 + 1;
    }

    return 0; // Success
}

int main() {
    size_t num_records = 1000000; // Example: 1 million records
    LogRecord *log_records;

    int result = init_log_records(&log_records, num_records);
    if (result != 0) {
        printf("Failed to initialize log records. Error code: %d\n", result);
        return EXIT_FAILURE;
    }

    // Process log records...

    free(log_records); // Don't forget to free the allocated memory
    return EXIT_SUCCESS;
}
