from typing import Dict, Callable

class ConfigurationManager:
    _plugins: Dict[str, Callable] = {}
    _log = logging.getLogger('ConfigurationManager')

    @staticmethod
    def register_plugin(plugin_id: str, module_name: str):
        try:
            spec = importlib.util.spec_from_file_location(module_name, f"{module_name}.py")
            plugin_module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(plugin_module)
            ConfigurationManager._plugins[plugin_id] = plugin_module.Plugin
            ConfigurationManager._log.info(f"Plugin '{plugin_id}' registered successfully.")
        except Exception as e:
            ConfigurationManager._log.error(f"Failed to register plugin '{plugin_id}': {e}")

    @staticmethod
    def get_plugin(plugin_id: str):
        if plugin_id in ConfigurationManager._plugins:
            return ConfigurationManager._plugins[plugin_id]()
        else:
            raise ValueError(f"No plugin registered with ID '{plugin_id}'")

