}

void resizeMemory(long** offsetArray, int** keyArray, Record** recordArray, size_t newSize) {
    *offsetArray = realloc(*offsetArray, newSize * sizeof(long));
    *keyArray = realloc(*keyArray, newSize * sizeof(int));
