    FILE *logFile = fopen("process.log", "w");
    if (!logFile) {
        perror("Failed to open log file");
        return -1;
    }

    // Validate input parameters
    if (offsets == NULL || keys == NULL || records == NULL || limit <= 0 || externalDataSource == NULL || outputFile == NULL) {
        fprintf(logFile, "Invalid input parameters\n");
        fclose(logFile);
        return -2;
    }

    // Initialize PRNG
    srand(time(NULL));

    // Allocate memory for records array
    record *newRecords = realloc(records, (limit + MAX_RECORDS) * sizeof(record));
    if (!newRecords) {
        perror("Failed to allocate memory for records");
        fclose(logFile);
        return -3;
    }
    records = newRecords;

    // Populate records array with random values
    for (int i = 0; i < limit; i++) {
        records[i].value = rand() % 10000; // Random value between 0 and 9999
    }

    // Read external data source
    FILE *dataFile = fopen(externalDataSource, "r");
    if (!dataFile) {
        perror("Failed to open external data file");
        fclose(logFile);
        return -4;
    }

    int value;
    while (fscanf(dataFile, "%d", &value) != EOF) {
        records[limit].value = value;
        limit++;
        if (limit >= MAX_RECORDS) {
            fprintf(logFile, "Reached maximum record limit\n");
            break;
        }
    }
    fclose(dataFile);

    // Find and log the maximum value
    int maxVal = records[0].value;
    for (int i = 1; i < limit; i++) {
        if (records[i].value > maxVal) {
            maxVal = records[i].value;
        }
    }
    fprintf(logFile, "Maximum value found: %d\n", maxVal);

    // Write results to output file
    FILE *outFile = fopen(outputFile, "w");
    if (!outFile) {
        perror("Failed to open output file");
        fclose(logFile);
        return -5;
    }

    fprintf(outFile, "Maximum value: %d\n", maxVal);
    fclose(outFile);

    // Clean up
    fclose(logFile);
    free(records);

    return 0;
}
