import java.util.concurrent.*;
import java.util.logging.Logger;

public class IdentifierGenerator {
    private static final Logger logger = Logger.getLogger(IdentifierGenerator.class.getName());
    private final BlockingQueue<Request> requestQueue;
    private final ConcurrentHashMap<Long, Integer> cache;
    private final Random random;
    private final int logLevel;
    private final ExecutorService executorService;
    private volatile boolean running;

    public IdentifierGenerator(int concurrencyLevel, int logLevel) {
        this.requestQueue = new LinkedBlockingQueue<>();
        this.cache = new ConcurrentHashMap<>(concurrencyLevel * 16, 0.75f, concurrencyLevel);
        this.random = new Random();
        this.logLevel = logLevel;
        this.executorService = Executors.newFixedThreadPool(concurrencyLevel);
        this.running = true;
        startGenerators(concurrencyLevel);
    }

    private void startGenerators(int concurrencyLevel) {
        for (int i = 0; i < concurrencyLevel; i++) {
            executorService.submit(this::processRequest);
        }
    }

    public long generateUniqueIdentifier(long offset, int key, Record record) {
        Request request = new Request(offset, key, record);
        try {
            requestQueue.put(request);
            return request.getResult();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            logger.log(Level.SEVERE, "Request interrupted", e);
            throw new RuntimeException(e);
        }
    }

    private void processRequest() {
        while (running) {
            try {
                Request request = requestQueue.take();
                long identifier = generateIdentifier(request.getOffset(), request.getKey());
                cache.put(identifier, request.getKey());
                request.setResult(identifier);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                logger.log(Level.SEVERE, "Processor interrupted", e);
                return;
            }
        }
    }

    private long generateIdentifier(long offset, int key) {
        // Use a high-performance pseudo-random number generator
        return (offset * 31 + key) % Long.MAX_VALUE;
    }

    public void stop() {
        running = false;
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    public static void main(String[] args) {
        IdentifierGenerator generator = new IdentifierGenerator(4, Logger.INFO);
        long identifier = generator.generateUniqueIdentifier(123, 456, new Record());
        System.out.println("Generated Identifier: " + identifier);
        generator.stop();
    }
}

class Request {
    private final long offset;
    private final int key;
    private final Record record;
    private long result;

    public Request(long offset, int key, Record record) {
        this.offset = offset;
        this.key = key;
        this.record = record;
    }

    public long getOffset() {
        return offset;
    }

    public int getKey() {
        return key;
    }

    public Record getRecord() {
        return record;
    }

    public long getResult() {
        return result;
    }

    public void setResult(long result) {
        this.result = result;
    }
}

class Record {
    private int value;

    public Record() {
        // Initialize with a random value from a specified range
        value = new Random().nextInt(1000);
    }

    public int getValue() {
        return value;
    }
}
