#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long offset;
} LargeIntegerOffset;

typedef struct {
    int key;
} UniqueIntegerKey;

typedef struct {
    int timestamp;
    long id;
} TransactionRecord;

typedef struct MemoryPool {
    void* memory;
    size_t size;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->memory = malloc(size);
    pool->size = size;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* allocate_from_pool(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used + size > pool->size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Out of memory
    }
    void* ptr = (char*)pool->memory + pool->used;
    pool->used += size;
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void free_memory_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    pool->used = 0;
    pthread_mutex_unlock(&pool->lock);
    free(pool->memory);
    free(pool);
}

int main() {
    srand(time(NULL));

    MemoryPool* offset_pool = create_memory_pool(1024 * 1024); // 1MB
    MemoryPool* key_pool = create_memory_pool(1024 * 1024); // 1MB
    MemoryPool* record_pool = create_memory_pool(1024 * 1024); // 1MB

    LargeIntegerOffset* offset = (LargeIntegerOffset*)allocate_from_pool(offset_pool, sizeof(LargeIntegerOffset));
    UniqueIntegerKey* key = (UniqueIntegerKey*)allocate_from_pool(key_pool, sizeof(UniqueIntegerKey));
    TransactionRecord* record = (TransactionRecord*)allocate_from_pool(record_pool, sizeof(TransactionRecord));

    if (offset && key && record) {
        offset->offset = rand();
        key->key = rand();
        record->timestamp = time(NULL);
        record->id = rand();

        printf("Offset: %ld\n", offset->offset);
        printf("Key: %d\n", key->key);
        printf("Timestamp: %d, ID: %ld\n", record->timestamp, record->id);

        free_memory_pool(offset_pool);
        free_memory_pool(key_pool);
        free_memory_pool(record_pool);
    } else {
        printf("Memory allocation failed.\n");
    }

    return 0;
}
```

