    while (1) {
        int num;
        if (scanf("%d", &num) != 1) break;

        if (inputSize >= inputCapacity) {
            inputCapacity *= 2;
            inputArray = realloc(inputArray, inputCapacity * sizeof(int));
            if (inputArray == NULL) {
                free(records);
                free(inputArray);
                return -2; // Memory allocation failed
            }
