#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 10000

typedef struct {
    time_t timestamp;
    int index;
    double measurement;
} SensorRecord;

int addSensorData(SensorRecord **records, int *recordCount, int index, double minMeasurement, double maxMeasurement) {
    if (recordCount >= &MAX_RECORDS) {
        return -1; // Error: Maximum records reached
    }

    if (*records == NULL) {
        *records = (SensorRecord *)malloc(MAX_RECORDS * sizeof(SensorRecord));
        if (*records == NULL) {
            return -2; // Error: Memory allocation failed
        }
    } else if ((*recordCount + 1) % MAX_RECORDS == 0) {
        SensorRecord *newRecords = realloc(*records, (MAX_RECORDS + *recordCount) * sizeof(SensorRecord));
        if (newRecords == NULL) {
            return -3; // Error: Memory reallocation failed
        }
        *records = newRecords;
    }

    SensorRecord *newRecord = &(*records)[*recordCount];
    time_t current_time = time(NULL);
    newRecord->timestamp = current_time;
    newRecord->index = index;

    // Using the high-quality Mersenne Twister PRNG from stdlib
    srand(time(0));
    double randomValue = minMeasurement + (maxMeasurement - minMeasurement) * ((double)rand() / RAND_MAX);
    newRecord->measurement = randomValue;

    (*recordCount)++;
    return 0;
}

int main() {
    SensorRecord *sensorData = NULL;
    int recordCount = 0;

    // Example usage
    for (int i = 0; i < 15000; i++) {
        if (addSensorData(&sensorData, &recordCount, i, -10.0, 10.0) != 0) {
            printf("Failed to add sensor data\n");
            break;
        }
    }

    // Free allocated memory
    free(sensorData);

    return 0;
}
```

This code snippet defines a function `addSensorData` that manages a dynamic collection of sensor data records. It allocates and reallocates memory as needed, initializes measurements with values from a pseudo-random number generator, and ensures safe input validation. The example usage in `main` demonstrates how to add records up to the maximum limit and clean up allocated memory.']

