sensorReading* createSensorReadings(int count, unsigned int idBase) {
    if (count <= 0 || idBase == 0) {
        return NULL;
    }

    sensorReading* readings = malloc(count * sizeof(sensorReading));
    if (readings == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < count; ++i) {
        readings[i].timestamp = time(NULL); // Use current time as timestamp
        readings[i].id = idBase + i;
        readings[i].measurement = ((double)rand() / RAND_MAX) * 100.0; // Random measurement between 0 and 100
    }

    return readings;
}

int freeSensorReadings(sensorReading* readings, int count) {
    if (readings == NULL || count <= 0) {
        fprintf(stderr, "Invalid input for freeing sensor readings\n");
        return -1;
    }

    free(readings);
    return 0;
}

int main() {
    int numReadings = 5;
    unsigned int idBase = 100;

    sensorReading* readings = createSensorReadings(numReadings, idBase);
    if (readings == NULL) {
        fprintf(stderr, "Failed to create sensor readings\n");
        return 1;
    }

    // Example usage: Print sensor readings
    for (int i = 0; i < numReadings; ++i) {
        printf("Reading %d: Timestamp=%lu, ID=%u, Measurement=%.2f\n", 
               i, readings[i].timestamp, readings[i].id, readings[i].measurement);
    }

    // Free allocated memory
    freeSensorReadings(readings, numReadings);

    return 0;
}
