    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % (keys[i + 1] - keys[i]) + keys[i];
    }

    return records;
}

record* resize_records(record* old_records, int old_size, int new_size) {
    record* new_records = realloc(old_records, new_size * sizeof(record));
    if (new_records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (int i = old_size; i < new_size; i++) {
        new_records[i].value = rand() % 100 + 1; // Assuming a range of 1 to 100
    }

    return new_records;
}

void free_records(record* records) {
    free(records);
}
