#include <iostream>
#include <thread>
#include <vector>
#include <mutex>
#include <atomic>
#include <condition_variable>
#include <string>
#include <cstring>
#include <cctype>
#include <cstdlib>
#include <cmath>
#include <openssl/rand.h>

struct Transaction {
    unsigned long id;
    double amount;
    std::string description;
};

class FinancialTransactionProcessor {
private:
    std::vector<std::thread> processors;
    std::queue<Transaction> transactionQueue;
    std::mutex queueMutex;
    std::condition_variable notEmpty;
    std::atomic<bool> running;
    std::atomic<unsigned long> processedCount;
    std::atomic<unsigned long> errorCount;
    unsigned int logLevel;

public:
    FinancialTransactionProcessor(unsigned int numProcessors, unsigned int logLevel)
        : processors(numProcessors), transactionQueue(), queueMutex(),
          notEmpty(), running(true), processedCount(0), errorCount(0),
          logLevel(logLevel) {
        for (unsigned int i = 0; i < numProcessors; ++i) {
            processors[i] = std::thread(&FinancialTransactionProcessor::processTransactions, this);
        }
    }

    ~FinancialTransactionProcessor() {
        running.store(false);
        notEmpty.notify_all();
        for (auto& thread : processors) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void enqueueTransaction(Transaction transaction) {
        std::lock_guard<std::mutex> lock(queueMutex);
        transactionQueue.push(transaction);
        notEmpty.notify_one();
    }

    double getProcessingRate() const {
        return static_cast<double>(processedCount.load()) / (std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::high_resolution_clock::now().time_since_epoch()).count());
    }

    double getErrorRate() const {
        return static_cast<double>(errorCount.load()) / processedCount.load();
    }

    unsigned long getQueueSize() const {
        std::lock_guard<std::mutex> lock(queueMutex);
        return transactionQueue.size();
    }

private:
    void processTransactions() {
        while (running) {
            Transaction transaction;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                notEmpty.wait(lock, [this] { return !transactionQueue.empty() || !running; });
                if (!running && transactionQueue.empty()) {
                    break;
                }
                transaction = transactionQueue.front();
                transactionQueue.pop();
            }

            try {
                // Process transaction
                processedCount.fetch_add(1);
                if (logLevel > 0) {
                    logTransaction(transaction, "Processed");
                }
            } catch (...) {
                errorCount.fetch_add(1);
                if (logLevel > 0) {
                    logTransaction(transaction, "Error");
                }
            }
        }
    }

    void logTransaction(const Transaction& transaction, const std::string& status) const {
        // Log transaction details based on log level
    }
};

int main() {
    FinancialTransactionProcessor processor(10, 2); // 10 processors, log level 2

    for (unsigned int i = 0; i < 500000; ++i) {
        Transaction transaction;
        // Generate random transaction details
        if (!RAND_bytes(reinterpret_cast<unsigned char*>(&transaction.id), sizeof(transaction.id))) {
            std::cerr << "Failed to generate random ID" << std::endl;
            return 1;
        }
        transaction.amount = static_cast<double>(rand()) / RAND_MAX * 1000.0;
        transaction.description = "Transaction " + std::to_string(i);
        processor.enqueueTransaction(transaction);
    }

    // Simulate processing time
    std::this_thread::sleep_for(std::chrono::seconds(5));

    std::cout << "Processing rate: " << processor.getProcessingRate() << "/s" << std::endl;
    std::cout << "Error rate: " << processor.getErrorRate() << std::endl;
    std::cout << "Queue size: " << processor.getQueueSize() << std::endl;

    return 0;
}
