#include <stdlib.h>
#include <stdint.h>

// Define the record structure
typedef struct {
    int key;
} record;

// High-performance PRNG function (XorShift32)
uint32_t xorshift32(uint32_t *state) {
    uint32_t x = *state;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    *state = x;
    return x;
}

// Function to allocate and initialize records
record* allocate_and_init_records(size_t num_records, int min_key, int max_key, uint32_t seed) {
    if (num_records == 0 || min_key > max_key) return NULL;

    record *records = malloc(num_records * sizeof(record));
    if (!records) return NULL;

    // Initialize the PRNG state
    uint32_t prng_state = seed;

    for (size_t i = 0; i < num_records; ++i) {
        records[i].key = min_key + xorshift32(&prng_state) % (max_key - min_key + 1);
    }

    return records;
}

// Function to free allocated records
void free_records(record *records, size_t num_records) {
    if (records) {
        free(records);
    }
}
