    srand(seed);

    for (int i = 0; i < ARRAY_SIZE; i++) {
        offsets[i] = rand() % MAX_RECORDS;
        keys[i] = rand() % MEASUREMENT_RANGE;
        records[offsets[i]].timestamp = time(NULL);
        records[offsets[i]].index = i;
        records[offsets[i]].measurement = keys[i];
    }

    return 0; // Success
