#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOG_LEVEL 3
#define BATCH_SIZE 1024

typedef struct {
    long startSeed;
    long endSeed;
    size_t dataSize;
    const char* outputFile;
    int logLevel;
    const char* prngType;
} GenerateAndProcessDataParams;

void logProgress(int level, const char* message) {
    if (level <= MAX_LOG_LEVEL) {
        printf("[LOG] %s\n", message);
    }
}

double generateRandomNumber(long seed, long endSeed) {
    return ((double)rand_r((unsigned int*)&seed) / RAND_MAX) * (endSeed - seed)) + seed;
}

void* workerThread(void* arg) {
    GenerateAndProcessDataParams* params = (GenerateAndProcessDataParams*)arg;
    FILE* file = fopen(params->outputFile, "a");
    if (!file) {
        perror("Failed to open file");
        pthread_exit(NULL);
    }

    long currentSeed = params->startSeed;
    size_t dataWritten = 0;

    while (dataWritten < params->dataSize) {
        double randomNumber = generateRandomNumber(currentSeed, params->endSeed);
        if (fprintf(file, "%.6f\t", randomNumber) < 0) {
            perror("Failed to write to file");
            break;
        }
        dataWritten++;
        currentSeed++;

        if (dataWritten % BATCH_SIZE == 0 || dataWritten == params->dataSize - 1) {
            fflush(file);
        }

        if (params->logLevel > 0 && dataWritten % 10000 == 0) {
            logProgress(params->logLevel, "Processed: %zu out of %zu\n", dataWritten, params->dataSize);
        }
    }

    fclose(file);
    pthread_exit(NULL);
}

int generateAndProcessData(GenerateAndProcessDataParams* params) {
    if (!params || !params->outputFile || params->startSeed > params->endSeed || params->logLevel < 0 || params->logLevel > MAX_LOG_LEVEL || !params->prngType) {
        fprintf(stderr, "Invalid parameters\n");
        return -1;
    }

    pthread_t thread;
    int result = pthread_create(&thread, NULL, workerThread, params);
    if (result != 0) {
        perror("Failed to create thread");
        return result;
    }

    pthread_join(thread, NULL);
    return 0;
}
