#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <errno.h>

typedef struct {
    int value;
    long timestamp;
} record;

// Custom pseudo-random number generator function
unsigned long custom_rand(unsigned long seed) {
    // Simple linear congruential generator for demonstration purposes
    return (seed * 1664525 + 1013904223) % ((unsigned long)-1);
}

int allocate_arrays(long offset_count, int key_count, record **records, long **offsets, int **keys, unsigned long seed) {
    if (offset_count <= 0 || key_count <= 0) {
        errno = EINVAL;
        return -1;
    }

    *offsets = (long *)malloc(offset_count * sizeof(long));
    *keys = (int *)malloc(key_count * sizeof(int));
    *records = (record *)malloc(key_count * sizeof(record));

    if (!*offsets || !*keys || !*records) {
        free(*offsets);
        free(*keys);
        free(*records);
        errno = ENOMEM;
        return -1;
    }

    time_t current_time = time(NULL);

    for (long i = 0; i < offset_count; ++i) {
        (*offsets)[i] = custom_rand(seed) % (current_time + 1);
        seed = (*offsets)[i]; // Update seed based on the new offset
    }

    for (int j = 0; j < key_count; ++j) {
        int random_value = custom_rand(seed) % 1000; // Random value between 0 and 999
        long random_delay = custom_rand(seed) % 2;   // Delay between 0 and 1 second
        (*keys)[j] = random_value;
        (*records)[j].value = random_value;
        (*records)[j].timestamp = current_time - random_delay;
        seed = (*records)[j].value * 31 + (*records)[j].timestamp; // Update seed based on the new record
    }

    return 0;
}

int main() {
    long offset_count = 1000;
    int key_count = 1000;
    unsigned long seed = time(NULL);

    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    if (allocate_arrays(offset_count, key_count, &records, &offsets, &keys, seed) == 0) {
        printf("Arrays allocated and initialized successfully.\n");
        // Free allocated memory here
    } else {
        perror("Failed to allocate arrays.");
    }

    return 0;
}
