#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10

typedef struct {
    long offset;
    int key;
    time_t timestamp;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} DataStore;

int init_data_store(DataStore** store, size_t initial_capacity) {
    *store = (DataStore*)malloc(sizeof(DataStore));
    if (*store == NULL) {
        return -1; // Memory allocation failed
    }

    (*store)->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if ((*store)->records == NULL) {
        free(*store);
        return -2; // Memory allocation failed
    }

    (*store)->capacity = initial_capacity;
    (*store)->count = 0;
    pthread_mutex_init(&(*store)->mutex, NULL);

    return 0;
}

void resize_data_store(DataStore* store) {
    size_t new_capacity = store->capacity * 10;
    Record* new_records = (Record*)realloc(store->records, new_capacity * sizeof(Record));
    if (new_records == NULL) {
        // Handle memory allocation failure gracefully
        return;
    }

    store->records = new_records;
    store->capacity = new_capacity;
}

void insert_record(DataStore* store, long offset, int key) {
    pthread_mutex_lock(&store->mutex);
    if (store->count >= store->capacity) {
        resize_data_store(store);
    }
    store->records[store->count].offset = offset;
    store->records[store->count].key = key;
    time_t current_time;
    time(&current_time);
    store->records[store->count].timestamp = current_time;
    store->count++;
    pthread_mutex_unlock(&store->mutex);
}

void free_data_store(DataStore* store) {
    if (store != NULL) {
        pthread_mutex_destroy(&store->mutex);
        free(store->records);
        free(store);
    }
}
