int allocate_memory(long* offsets, int* keys, Record** records, size_t count, int min_value, int max_value) {
    if (count <= 0 || min_value > max_value) {
        return -1; // Invalid input
    }

    offsets = (long*)malloc(count * sizeof(long));
    keys = (int*)malloc(count * sizeof(int));
    records = (Record**)malloc(count * sizeof(Record*));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        return -2; // Memory allocation failed
    }

    for (size_t i = 0; i < count; ++i) {
        offsets[i] = i * 100L; // Example offset calculation
        keys[i] = rand_range(min_value, max_value);

        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            for (size_t j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(offsets);
            free(keys);
            return -2; // Memory allocation failed
        }

        records[i]->value = rand_range(min_value, max_value);
        records[i]->timestamp = time(NULL) - rand_range(0, 1);
    }

    return 0; // Success
}

int rand_range(int min_val, int max_val) {
    return min_val + rand() % (max_val - min_val + 1);
}

void clean_memory(long* offsets, int* keys, Record** records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(records[i]);
