#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    time_t offset;
    int sequence_id;
    int value;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicCollection;

DynamicCollection* create_collection(size_t initial_capacity) {
    DynamicCollection* collection = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    if (!collection) {
        return NULL; // Memory allocation failed
    }

    collection->records = (Record*)malloc(initial_capacity * sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL; // Memory allocation failed
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_collection(DynamicCollection* collection) {
    if (collection) {
        free(collection->records);
        pthread_mutex_destroy(&collection->lock);
        free(collection);
    }
}

int add_record(DynamicCollection* collection, time_t offset) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record* new_records = (Record*)realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory reallocation failed
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    time_t current_time = time(NULL);
    collection->records[collection->size].offset = offset;
    collection->records[collection->size].sequence_id = (int)((current_time / 10) % 100); // Example periodic update
    collection->records[collection->size].value = rand() % 100; // Example non-cryptographic PRNG

    collection->size++;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

// Additional functions for persistent storage, concurrent access handling, and cleanup can be implemented as needed.
