    int start_index;
    int end_index;
} WorkerData;

void* process_records(void* arg) {
    WorkerData* data = (WorkerData*)arg;
    for (int i = data->start_index; i < data->end_index; ++i) {
        // Example processing: generate a random number and store it
        int record_value = rand();
        // Assuming records are stored in a specific format
        ((int*)(data->records + i * RECORD_SIZE))[1] = record_value;
    }
    pthread_exit(NULL);
}

void update_prng_seed() {
    srand(time(NULL));
}

void initialize_worker_threads(char* records, int num_records, int num_threads) {
    pthread_t threads[num_threads];
    WorkerData data[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        data[i].records = records;
        data[i].start_index = i * (num_records / num_threads);
        if (i == num_threads - 1) {
            data[i].end_index = num_records;
        } else {
            data[i].end_index = (i + 1) * (num_records / num_threads);
        }

        pthread_create(&threads[i], NULL, process_records, &data[i]);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

