typedef struct {
    time_t offset;
    int sequence_id;
    int value;
} Record;

typedef struct {
    Record* records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicCollection;

DynamicCollection* create_collection(size_t initial_capacity) {
    DynamicCollection* collection = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    if (!collection) return NULL;

    collection->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_collection(DynamicCollection* collection) {
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

void update_sequence_id(DynamicCollection* collection) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        time_t now = time(NULL);
        collection->records[i].offset = now;
        // Update sequence ID based on some non-cryptographic hash of the timestamp
        collection->records[i].sequence_id = (int)(now ^ ((long long)i << 16)) & 0xFFFF;
    }
    pthread_mutex_unlock(&collection->lock);
}

void* resize_collection(void* arg) {
    DynamicCollection* collection = (DynamicCollection*)arg;

    size_t new_capacity = collection->capacity * 2;
    Record* new_records = (Record*)realloc(collection->records, new_capacity * sizeof(Record));
    if (!new_records) return NULL;

    collection->records = new_records;
    collection->capacity = new_capacity;

    return NULL;
}

int add_record(DynamicCollection* collection, int value_range_start, int value_range_end) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count >= collection->capacity) {
        if (resize_collection(collection)) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failure
        }
    }

    Record* new_record = &collection->records[collection->count++];
    time_t now = time(NULL);
    new_record->offset = now;
    new_record->sequence_id = (int)(now ^ ((long long)collection->count << 16)) & 0xFFFF;

    // Initialize value using a non-cryptographic PRNG
    new_record->value = rand() % (value_range_end - value_range_start + 1) + value_range_start;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void cleanup_collection(DynamicCollection* collection, size_t threshold) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (difftime(time(NULL), collection->records[i].offset) > threshold) {
            memmove(&collection->records[i], &collection->records[i + 1], (collection->count - i - 1) * sizeof(Record));
            --collection->count;
            --i; // Adjust index after memmove
        }
    }

    if (collection->count < collection->capacity / 4) {
        resize_collection(collection);
    }
    pthread_mutex_unlock(&collection->lock);
}

