// Function to find and print the largest integer in an array
void findAndPrintMax(int *array, size_t size) {
    if (size == 0) {
        printf("Array is empty.\n");
        return;
    }
    int max = INT_MIN;
    for (size_t i = 0; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    printf("The largest integer is: %d\n", max);
}

// Function to process and find the maximum value
void processAndFindMax() {
    int count;
    printf("Enter the number of arrays: ");
    scanf("%d", &count);

    if (count <= 0) {
        printf("Invalid input. Please enter a positive integer.\n");
        return;
    }

    record *records = (record *)calloc(count, sizeof(record));
    long *offsets = (long *)malloc(sizeof(long) * count);
    int *keys = (int *)malloc(sizeof(int) * count);

    if (!records || !offsets || !keys) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Initialize records with random values
    srand(time(NULL));
    for (int i = 0; i < count; ++i) {
        records[i].value = rand() % 1000; // Random value between 0 and 999
        offsets[i] = i * sizeof(record);
        keys[i] = i;
    }

    // Read integers from standard input until EOF is reached
    int tempArray[100]; // Assuming a maximum of 100 integers for simplicity
    size_t tempSize = 0;
    while (scanf("%d", &tempArray[tempSize]) != EOF) {
        ++tempSize;
    }

    // Find and print the largest integer
    findAndPrintMax(tempArray, tempSize);

    // Free allocated memory
    free(records);
    free(offsets);
    free(keys);
}

int main() {
    processAndFindMax();
    return 0;
}
