#include <pthread.h>

#define NUM_OFFSETS 1000
#define NUM_KEYS 500
#define NUM_RECORDS (NUM_OFFSETS / 2)

typedef struct {
    int *key_ptr;
    int active;
} record;

void initialize_arrays(long offsets[], int keys[]) {
    for (int i = 0; i < NUM_OFFSETS; ++i) {
        offsets[i] = i;
    }
    srand(time(NULL));
    for (int i = 0; i < NUM_KEYS; ++i) {
        keys[i] = rand() % 1000 + 1;
    }
}

void initialize_records(record *records, int keys[]) {
    for (int i = 0; i < NUM_RECORDS; ++i) {
        records[i].key_ptr = &keys[i];
        records[i].active = (rand() % 2 == 0);
    }
}

void populate_offsets_and_keys(long offsets[], int keys[], record *records) {
    for (int i = 0; i < NUM_RECORDS; ++i) {
        if (records[i].active) {
            *records[i].key_ptr = rand() % 1000 + 1;
        }
    }
}

void print_arrays(long offsets[], int keys[], record *records) {
    printf("Offsets: ");
    for (int i = 0; i < NUM_OFFSETS; ++i) {
        printf("%ld ", offsets[i]);
    }
    printf("\n");

    printf("Keys: ");
    for (int i = 0; i < NUM_KEYS; ++i) {
        printf("%d ", keys[i]);
    }
    printf("\n");

    printf("Records: ");
    for (int i = 0; i < NUM_RECORDS; ++i) {
        printf("(%d, %s) ", *records[i].key_ptr, records[i].active ? "Active" : "Inactive");
    }
    printf("\n");
}

void cleanup(long offsets[], int keys[], record *records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    long *offsets = (long *)malloc(NUM_OFFSETS * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return EXIT_FAILURE;
    }

    int *keys = (int *)malloc(NUM_KEYS * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        return EXIT_FAILURE;
    }

    record *records = (record *)malloc(NUM_RECORDS * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(keys);
        free(offsets);
        return EXIT_FAILURE;
    }

    initialize_arrays(offsets, keys);
    initialize_records(records, keys);
    populate_offsets_and_keys(offsets, keys, records);

    print_arrays(offsets, keys, records);

    cleanup(offsets, keys, records);

    return EXIT_SUCCESS;
}
