// Define the record structure
typedef struct {
    int value;
} Record;

// Function to dynamically allocate memory for arrays and records
void allocateAndInitialize(int offsetCount, int keyCount, long seed) {
    // Allocate memory for offset array
    long* offsets = (long*)malloc(offsetCount * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return;
    }

    // Allocate memory for key array
    int* keys = (int*)malloc(keyCount * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(offsets);
        return;
    }

    // Initialize random number generator with seed
    srand(seed);

    // Allocate and initialize record structures
    Record* records = (Record*)malloc(keyCount * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Set random values to each record's int field using cryptographically strong PRNG
    for (int i = 0; i < keyCount; i++) {
        records[i].value = rand();
    }

    // Deallocate all allocated memory
    free(offsets);
    free(keys);
    free(records);

    printf("Memory allocation and initialization complete.\n");
}

// Example usage
int main() {
    int offsetCount = 100;
    int keyCount = 500;
    long seed = time(NULL); // Use current time as seed for reproducibility

    allocateAndInitialize(offsetCount, keyCount, seed);

    return 0;
}
