    const int identifier_size = 1500;
    const int measurement_size = 1000;

    double *precision_array = (double *)malloc(precision_size * sizeof(double));
    char *identifier_array = (char *)malloc(identifier_size * sizeof(char));
    measurement *measurement_array = (measurement *)malloc(measurement_size * sizeof(measurement));

    if (!precision_array || !identifier_array || !measurement_array) {
