        free(identifier_array);
        free(measurement_array);
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (int i = 0; i < precision_size; ++i) {
        precision_array[i] = (double)i;
    }
    for (int i = 0; i < identifier_size; ++i) {
        identifier_array[i] = 'A' + i % 26;
    }

    for (int i = 0; i < measurement_size; ++i) {
        measurement_array[i].ref = &identifier_array[i];
        measurement_array[i].timestamp = time(NULL);
        char random_char = 'a' + rand() % 26;
        strcpy(measurement_array[i].ref, &random_char);
    }

    // Print the contents for verification
    for (int i = 0; i < precision_size; ++i) {
        printf("Precision[%d] = %f\n", i, precision_array[i]);
    }
    for (int i = 0; i < identifier_size; ++i) {
        printf("Identifier[%d] = %c\n", i, identifier_array[i]);
    }
    for (int i = 0; i < measurement_size; ++i) {
        printf("Measurement[%d]: Ref = %c, Timestamp = %ld\n", i, *measurement_array[i].ref, measurement_array[i].timestamp);
    }

    free(precision_array);
    free(identifier_array);
    free(measurement_array);
}

int main() {
    manage_dynamic_memory();
    return 0;
}
