// Function to initialize and populate arrays with random values
void init_arrays(double* value_array, char* char_array, measurement* measure_array, int prng_type) {
    srand(time(NULL)); // Seed for PRNG

    for (int i = 0; i < 1000; ++i) {
        switch (prng_type) {
            case 0: // Linear Congruential Generator
                value_array[i] = rand() % 101; // Random number between 0 and 100
                break;
            case 1: // Mersenne Twister
                mt19937 gen;
                uniform_int_distribution<> dis(0, 100);
                gen.seed(time(NULL));
                value_array[i] = dis(gen); // Random number between 0 and 100
                break;
            default:
                printf("Invalid PRNG type\n");
                exit(EXIT_FAILURE);
        }
        measure_array[i].value = &value_array[i];
        measure_array[i].reliable = (rand() % 2 == 0); // Balanced distribution of reliable flags
    }

    for (int i = 0; i < 500; ++i) {
        char_array[i] = 'A' + rand() % 26; // Random character between A and Z
    }
}

// Function to print array contents
void print_arrays(double* value_array, char* char_array, measurement* measure_array) {
    printf("Value Array:\n");
    for (int i = 0; i < 1000; ++i) {
        printf("%f ", value_array[i]);
        if ((i + 1) % 50 == 0) printf("\n");
    }
    printf("Character Array:\n");
    for (int i = 0; i < 500; ++i) {
        printf("%c ", char_array[i]);
        if ((i + 1) % 25 == 0) printf("\n");
    }
    printf("Measurement Array:\n");
    for (int i = 0; i < 1000; ++i) {
        printf("%f (%s) ", *measure_array[i].value, measure_array[i].reliable ? "Reliable" : "Unreliable");
        if ((i + 1) % 25 == 0) printf("\n");
    }
}

int main() {
    double* value_array = (double*)malloc(1000 * sizeof(double));
    char* char_array = (char*)malloc(500 * sizeof(char));
    measurement* measure_array = (measurement*)malloc(1000 * sizeof(measurement));

    if (!value_array || !char_array || !measure_array) {
        printf("Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    init_arrays(value_array, char_array, measure_array, 0); // Use Linear Congruential Generator
    print_arrays(value_array, char_array, measure_array);

    free(value_array);
    free(char_array);
    free(measure_array);

    return EXIT_SUCCESS;
}
