void init_memory_and_records(long** offsets, int** keys, record** records, int size, int min_val, int max_val) {
    *offsets = (long*)malloc(size * sizeof(long));
    *keys = (int*)malloc(size * sizeof(int));
    *records = (record*)malloc(size * sizeof(record));

    srand(time(NULL)); // Seed the PRNG with the current time for better randomness

    for (int i = 0; i < size; i++) {
        (*offsets)[i] = rand() % size; // Initialize offsets randomly
        (*keys)[i] = rand() % (max_val - min_val + 1) + min_val; // Initialize keys within the specified range

        (*records)[i].value = (*keys)[i];
        (*records)[i].offset = &(*offsets)[i]; // Assign offset pointers to records
    }
}

int main() {
    int size = 5;
    long* offsets;
    int* keys;
    record* records;

    init_memory_and_records(&offsets, &keys, &records, size, 10, 100);

