#include <pthread.h>

typedef struct {
    long timestamp;
    double amount;
    int status;
} Transaction;

typedef struct {
    Transaction* transactions;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} TransactionManager;

TransactionManager* tm_create(size_t initial_capacity) {
    TransactionManager* tm = (TransactionManager*)malloc(sizeof(TransactionManager));
    if (tm == NULL) return NULL;

    tm->transactions = (Transaction*)calloc(initial_capacity, sizeof(Transaction));
    if (tm->transactions == NULL) {
        free(tm);
        return NULL;
    }

    tm->capacity = initial_capacity;
    tm->size = 0;
    pthread_mutex_init(&tm->lock, NULL);

    return tm;
}

void tm_destroy(TransactionManager* tm) {
    free(tm->transactions);
    pthread_mutex_destroy(&tm->lock);
    free(tm);
}

int tm_add_transaction(TransactionManager* tm, long timestamp, double amount) {
    pthread_mutex_lock(&tm->lock);

    if (tm->size == tm->capacity) {
        Transaction* new_transactions = (Transaction*)realloc(tm->transactions, 2 * tm->capacity * sizeof(Transaction));
        if (new_transactions == NULL) {
            pthread_mutex_unlock(&tm->lock);
            return -1; // Memory allocation failure
        }
        tm->transactions = new_transactions;
        tm->capacity *= 2;
    }

    tm->transactions[tm->size].timestamp = timestamp;
    tm->transactions[tm->size].amount = amount;

    // Custom PRNG for status generation
    static int seed = 42; // Initial seed value
    seed = (seed * 16807 + 1) % 2147483647; // Simple LCG
    tm->transactions[tm->size].status = seed % 100; // Example status range

    tm->size++;
    pthread_mutex_unlock(&tm->lock);

    return 0;
}

// Additional functions for managing concurrent access, integrating external data sources,
// optimizing for latency and throughput, ensuring efficient use of resources,
// scaling horizontally, and handling edge cases would be implemented here.
