['```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    unsigned long timestamp;
    double amount;
    int status;
} transaction;

struct transaction_manager {
    transaction *transactions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
};

void tm_init(struct transaction_manager *tm, size_t initial_capacity) {
    tm->capacity = initial_capacity;
    tm->count = 0;
    tm->transactions = (transaction *)malloc(initial_capacity * sizeof(transaction));
    if (tm->transactions == NULL) {
        perror("Failed to allocate memory for transactions");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&tm->lock, NULL);
}

void tm_add_transaction(struct transaction_manager *tm, transaction t) {
    pthread_mutex_lock(&tm->lock);
    if (tm->count >= tm->capacity) {
        size_t new_capacity = tm->capacity == 0 ? 1 : tm->capacity * 2;
        transaction *new_transactions = (transaction *)realloc(tm->transactions, new_capacity * sizeof(transaction));
        if (new_transactions == NULL) {
            perror("Failed to reallocate memory for transactions");
            pthread_mutex_unlock(&tm->lock);
            return;
        }
        tm->transactions = new_transactions;
        tm->capacity = new_capacity;
    }
    tm->transactions[tm->count++] = t;
    pthread_mutex_unlock(&tm->lock);
}

void tm_remove_transaction(struct transaction_manager *tm, size_t index) {
    pthread_mutex_lock(&tm->lock);
    if (index >= tm->count) {
        fprintf(stderr, "Invalid transaction index\n");
        pthread_mutex_unlock(&tm->lock);
        return;
    }
    for (size_t i = index; i < tm->count - 1; ++i) {
        tm->transactions[i] = tm->transactions[i + 1];
    }
    --tm->count;
    pthread_mutex_unlock(&tm->lock);
}

void tm_free(struct transaction_manager *tm) {
    pthread_mutex_lock(&tm->lock);
    free(tm->transactions);
    pthread_mutex_destroy(&tm->lock);
    pthread_mutex_unlock(&tm->lock);
}
