void initialize_network_protocol(int num_packets, packet_header **headers, encryption_record ***encryption_records) {
    if (num_packets <= 0 || headers == NULL || encryption_records == NULL) {
        return; // Handle invalid input
    }

    *headers = malloc(num_packets * sizeof(packet_header));
    *encryption_records = malloc(num_packets * sizeof(encryption_record*));

    if (*headers == NULL || *encryption_records == NULL) {
        // Handle memory allocation failure
        return;
    }

    for (int i = 0; i < num_packets; i++) {
        (*headers)[i].sequence_number = i; // Example initialization
        (*headers)[i].message_type = 1;   // Example initialization

        (*encryption_records)[i] = malloc(sizeof(encryption_record));
        if ((*encryption_records)[i] == NULL) {
            // Handle memory allocation failure for encryption records
            return;
        }

        if (!RAND_bytes((*encryption_records)[i]->byte_record, sizeof((*encryption_records)[i]->byte_record))) {
            // Handle CSPRNG initialization failure
            free(*encryption_records[i]);
            (*encryption_records)[i] = NULL;
            return;
        }

        (*encryption_records)[i]->key = i; // Example initialization
    }
}

void cleanup_network_protocol(int num_packets, packet_header *headers, encryption_record **encryption_records) {
    for (int i = 0; i < num_packets; i++) {
        free(encryption_records[i]);
    }

    free(headers);
    free(encryption_records);
}
