use rand::RngCore;
use rand_os::OsRng;
use std::collections::HashSet;

pub fn generateSessionTokens(
    sessionCount: usize,
    tokenLength: u8,
    customCharset: String,
) -> Result<Vec<String>, &'static str> {
    if tokenLength == 0 || tokenLength > 255 {
        return Err("Token length must be between 1 and 255 characters.");
    }
    if sessionCount > usize::MAX / (tokenLength as usize) {
        return Err("Session count exceeds maximum allowed.");
    }

    let charset: Vec<char> = customCharset.chars().collect();
    if charset.is_empty() || charset.len() > u8::MAX as usize {
        return Err("Custom character set must not be empty and should have a reasonable length.");
    }

    let mut rng = OsRng;
    let mut tokens = HashSet::new();

    while tokens.len() < sessionCount {
        let mut token = String::with_capacity(tokenLength as usize);
        for _ in 0..tokenLength {
            let index = rng.next_u32() % charset.len() as u32;
            token.push(charset[index as usize]);
        }
        if token.len() == tokenLength as usize {
            tokens.insert(token);
        }
    }

    Ok(tokens.into_iter().collect())
}
