    for (int i = 0; i < records_count; i++) {
        offsets[i] = rand();
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
        probabilities[i] = ((double)rand()) / RAND_MAX;

        // Cache random values and probabilities
        if (i >= cache_size) {
            int index_to_replace = i % cache_size;
            offsets[index_to_replace] = rand();
            keys[index_to_replace] = rand() % (max_value - min_value + 1) + min_value;
            probabilities[index_to_replace] = ((double)rand()) / RAND_MAX;
        }
    }

    // Initialize records
    for (int i = 0; i < records_count; i++) {
        records[i].value = keys[i];
        records[i].probability = probabilities[i];
    }

    return 0; // Success
}

