import java.util.concurrent.*;
import java.security.SecureRandom;
import java.util.logging.*;

public class TokenGenerator {
    private static final Logger LOGGER = Logger.getLogger(TokenGenerator.class.getName());
    private final BlockingQueue<String> requestQueue = new LinkedBlockingQueue<>();
    private final ConcurrentHashMap<String, String> tokenMap = new ConcurrentHashMap<>();
    private final SecureRandom random = new SecureRandom();
    private int logLevel;
    private ExecutorService executor;

    public TokenGenerator(int concurrentGenerators) {
        this.logLevel = Logger.Level.INFO.intValue();
        this.executor = Executors.newFixedThreadPool(concurrentGenerators, r -> new Thread(r, "TokenGeneratorThread"));
        // Start the request processor
        executor.submit(this::processRequests);
    }

    public void submitRequest(String userId) {
        try {
            requestQueue.put(userId);
        } catch (InterruptedException e) {
            LOGGER.log(Level.SEVERE, "Failed to submit request", e);
        }
    }

    private void processRequests() {
        while (true) {
            try {
                String userId = requestQueue.take();
                generateTokenForUser(userId);
            } catch (InterruptedException e) {
                LOGGER.log(Level.WARNING, "Request processor interrupted");
            }
        }
    }

    private void generateTokenForUser(String userId) {
        if (tokenMap.containsKey(userId)) {
            return; // Token already generated
        }
        try {
            byte[] tokenBytes = new byte[16];
            random.nextBytes(tokenBytes);
            String token = bytesToHex(tokenBytes);
            tokenMap.put(userId, token);
            LOGGER.log(logLevel, "Token generated for user: {0}, token: {1}", new Object[]{userId, token});
        } catch (OutOfMemoryError e) {
            LOGGER.log(Level.SEVERE, "Out of memory error while generating token", e);
        } catch (Exception e) {
            LOGGER.log(Level.WARNING, "Failed to generate token for user: {0}", userId, e);
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

