#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <errno.h>

#define MAX_RECORD_COUNT 1000
#define PRNG_SEED 42

typedef struct {
    int value;
} record;

int customPRNG(int seed) {
    return (seed * 134775813 + 1) % 2147483647; // Example simple LCG
}

record* generateRecords(int recordCount, int minValue, int maxValue) {
    if (recordCount <= 0 || minValue >= maxValue) {
        return NULL;
    }
    record *records = malloc(recordCount * sizeof(record));
    if (!records) {
        return NULL;
    }
    for (int i = 0; i < recordCount; ++i) {
        records[i].value = customPRNG(PRNG_SEED + i) % (maxValue - minValue + 1) + minValue;
    }
    return records;
}

int connectToServer(const char *serverAddress, int port, int timeout) {
    struct sockaddr_in serverAddr;
    int sock = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, 0);
    if (sock < 0) {
        perror("Failed to create socket");
        return -1;
    }

    memset(&serverAddr, 0, sizeof(serverAddr));
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(port);
    inet_pton(AF_INET, serverAddress, &serverAddr.sin_addr);

    if (connect(sock, (struct sockaddr *)&serverAddr, sizeof(serverAddr)) < 0) {
        perror("Failed to connect to server");
        close(sock);
        return -1;
    }

    // Set connection timeout
    struct timeval tv = {timeout, 0};
    if (setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv)) < 0 || setsockopt(sock, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv)) < 0) {
        perror("Failed to set socket timeout");
        close(sock);
        return -1;
    }

    return sock;
}

int sendRecords(int sock, record *records, int recordCount) {
    for (int i = 0; i < recordCount; ++i) {
        if (send(sock, &records[i].value, sizeof(records[i].value), 0) != sizeof(records[i].value)) {
            perror("Failed to send data");
            return -1;
        }
    }
    return 0;
}

int receiveResponse(int sock) {
    char buffer[4];
    int bytesReceived = recv(sock, buffer, sizeof(buffer), 0);
    if (bytesReceived < 0) {
        perror("Failed to receive response");
        return -1;
    } else if (bytesReceived == 0) {
        fprintf(stderr, "Connection closed unexpectedly\n");
        return -1;
    }
    return atoi(buffer);
}

int generateAndSendRecords(int recordCount, int minValue, int maxValue, int connectionTimeout, const char *serverAddress) {
    if (recordCount > MAX_RECORD_COUNT || recordCount <= 0 || minValue >= maxValue) {
        fprintf(stderr, "Invalid input parameters\n");
        return -1;
    }
    record *records = generateRecords(recordCount, minValue, maxValue);
    if (!records) {
        perror("Failed to allocate memory for records");
        return -1;
    }

    int sock = connectToServer(serverAddress, 8080, connectionTimeout); // Assuming server runs on port 8080
    if (sock < 0) {
        free(records);
        return sock;
    }

    if (sendRecords(sock, records, recordCount) < 0) {
        close(sock);
        free(records);
        return -1;
    }

    int response = receiveResponse(sock);
    close(sock);
    free(records);

    return response;
}

int main() {
    const char *serverAddress = "127.0.0.1";
    int result = generateAndSendRecords(10, 0, 100, 5, serverAddress);
    if (result < 0) {
        fprintf(stderr, "Error occurred\n");
    } else {
        printf("Server response: %d\n", result);
    }
    return 0;
}
```

