int generateAndAnalyzeData(int dataSize, unsigned long seed, int minValue, int maxValue, const char* outputFile, const char* inputSource) {
    if (dataSize <= 0 || minValue > maxValue) {
        return ERROR_CODE;
    }

    FILE *outFile = fopen(outputFile, "wb");
    if (!outFile) {
        return ERROR_CODE;
    }

    int *generatedData = (int *)malloc(dataSize * sizeof(int));
    if (!generatedData) {
        fclose(outFile);
        return ERROR_CODE;
    }

    srand(seed);
    for (int i = 0; i < dataSize; ++i) {
        generatedData[i] = rand() % (maxValue - minValue + 1) + minValue;
        fwrite(&generatedData[i], sizeof(int), 1, outFile);
    }

    fclose(outFile);

    int *inputData = NULL;
    if (inputSource != NULL && strcmp(inputSource, "") != 0) {
        FILE *inFile = fopen(inputSource, "r");
        if (!inFile) {
            free(generatedData);
            return ERROR_CODE;
        }

        inputData = (int *)malloc(dataSize * sizeof(int));
        if (!inputData) {
            fclose(inFile);
            free(generatedData);
            return ERROR_CODE;
        }

        int count = 0;
        while (fscanf(inFile, "%d", &inputData[count]) == 1 && count < dataSize) {
            ++count;
        }

        fclose(inFile);

        if (count > 0) {
            // Analyze overlap
            int commonCount = 0;
            for (int i = 0; i < dataSize; ++i) {
                for (int j = 0; j < count; ++j) {
                    if (generatedData[i] == inputData[j]) {
                        ++commonCount;
                        break;
                    }
                }
            }

            double overlapPercentage = ((double)commonCount / dataSize) * 100.0;

            // Output analysis
            printf("Overlap Percentage: %.2f%%\n", overlapPercentage);
        }

        free(inputData);
    }

    free(generatedData);

    return 0;
}
