    size_t key_size = num_records * sizeof(int);
    size_t record_size = num_records * sizeof(record);

    if (offset_size + key_size + record_size > threshold) {
        return -1; // Memory allocation exceeds threshold
    }

    *offsets = (long *)malloc(offset_size);
    *keys = (int *)malloc(key_size);
    *records = (record *)malloc(record_size);

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        free(*offsets);
        free(*keys);
        return -2; // Memory allocation failed
    }

    // Initialize record metadata
    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].value = i;
        (*records)[i].last_used = time(NULL);
    }

    srand(time(NULL)); // Seed PRNG with current time

    return 0; // Success
}

int generate_id(int min, int max) {
    if (min > max) {
        return -1; // Invalid range
    }
    return min + rand() % (max - min + 1);
}

void reseed_prng(time_t new_seed) {
    srand(new_seed); // Reseed PRNG with a new value
}
