    if (offset_count <= 0 || key_count <= 0 || identifier_length <= 0) {
        return -1; // Invalid parameters
    }

    *offsets = (long *)malloc(offset_count * sizeof(long));
    *keys = (int *)malloc(key_count * sizeof(int));
    *weights = (float *)malloc(key_count * sizeof(float));

    if (!*offsets || !*keys || !*weights) {
        return -2; // Memory allocation failed
    }

    *records = (Record **)malloc(key_count * sizeof(Record *));
    if (!*records) {
        free(*offsets);
        free(*keys);
        free(*weights);
        return -2; // Memory allocation failed
    }

    srand(time(NULL));
    for (int i = 0; i < key_count; ++i) {
        (*offsets)[i] = rand() % offset_count;
        (*keys)[i] = rand() % key_count;

        float min_value = weight_range[0];
        float max_value = weight_range[1];
        (*weights)[i] = min_value + (float)(rand()) / RAND_MAX * (max_value - min_value);

        (*records)[i] = (Record *)malloc(sizeof(Record));
        if (!(*records)[i]) {
            for (int j = 0; j < i; ++j) {
                free((*records)[j]);
            }
            free(*offsets);
            free(*keys);
            free(*weights);
            free(*records);
            return -2; // Memory allocation failed
        }

        (*records)[i]->value = *weights + rand() % (int)(*weights);
        (*records)[i]->key = *keys[i] + rand() % (int)*keys;
        (*records)[i]->identifier = (char *)malloc((identifier_length + 1) * sizeof(char));
        if (!(*records)[i]->identifier) {
            for (int j = 0; j <= i; ++j) {
                free((*records)[j]);
            }
            free(*offsets);
            free(*keys);
            free(*weights);
            free(*records);
            return -2; // Memory allocation failed
        }

        snprintf((*records)[i]->identifier, identifier_length + 1, "ID%d", i);
    }

    return 0; // Success
}

void free_records(Record **records, int key_count) {
