int allocateMemory(long *offsets, int *keys, Record **records, size_t numRecords) {
    offsets = (long *)malloc(numRecords * sizeof(long));
    keys = (int *)malloc(numRecords * sizeof(int));
    records = (Record **)malloc(numRecords * sizeof(Record *));

    if (!offsets || !keys || !records) {
        return -1; // Memory allocation failed
    }

    for (size_t i = 0; i < numRecords; ++i) {
        records[i] = (Record *)malloc(sizeof(Record));
        if (!records[i]) {
            free(offsets);
            free(keys);
            for (size_t j = 0; j < i; ++j) {
                free(records[j]);
            }
            return -1;
        }
    }

    srand(time(NULL)); // Seed PRNG
    for (size_t i = 0; i < numRecords; ++i) {
        offsets[i] = rand();
        keys[i] = rand();
        initializeRecord(records[i], keys[i]);
    }

    return 0;
}

void freeMemory(long *offsets, int *keys, Record **records, size_t numRecords) {
    for (size_t i = 0; i < numRecords; ++i) {
        free(records[i]);
    }
