        records[i].id = rand() % (id_range_end - id_range_start + 1) + id_range_start;
        records[i].value = ((double)rand() / RAND_MAX) * (value_range_end - value_range_start) + value_range_start;
        int word_index = rand() % NUM_WORDS;
        records[i].name = strdup(word_list[word_index]);
    }

    return records;
}

void free_record_array(Record* records, int size) {
    for (int i = 0; i < size; i++) {
        free(records[i].name);
    }
    free(records);
