import subprocess
import os
import sys
from datetime import datetime, timedelta

def create_backup(source_dir, backup_dir, retention_days):
    now = datetime.now()
    backup_filename = f"backup_{now.strftime('%Y%m%d%H%M%S')}.tar.gz"
    backup_path = os.path.join(backup_dir, backup_filename)

    exclude_args = []
    for exclusion in exclusions:
        exclude_args.extend(['--exclude', exclusion])

    subprocess.run(['tar'] + exclude_args + ['-czvf', backup_path, source_dir], check=True)

    # Cleanup old backups
    cutoff_date = now - timedelta(days=retention_days)
    for filename in os.listdir(backup_dir):
        if filename.startswith('backup_') and datetime.strptime(filename[7:25], '%Y%m%d%H%M%S') < cutoff_date:
            os.remove(os.path.join(backup_dir, filename))

def main():
    env_config = {
        'source_dir': '/path/to/config',
        'backup_dir': '/path/to/backups',
        'retention_days': 30,
        'exclusions': ['*.log', '*.tmp'],
        'logging_level': 'INFO'
    }

    create_backup(env_config['source_dir'], env_config['backup_dir'], env_config['retention_days'])

if __name__ == "__main__":
