fn generateRandomTokens(count: usize, tokenLength: usize, externalDataSourceUrl: &str, outputPath: &str) -> io::Result<()> {
    // Validate input parameters
    if count == 0 || tokenLength == 0 {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "Count and token length must be greater than zero"));
    }

    let mut tokens = Vec::with_capacity(count);

    // Fetch additional data from the external service
    let client = reqwest::Client::builder()
        .dangerously_allow_invalid_certs(true)
        .build()?;

    let response = client.get(externalDataSourceUrl).send()?;

    if !response.status().is_success() {
        return Err(io::Error::new(io::ErrorKind::Other, "Failed to fetch data from external source"));
    }

    let additional_data: String = response.text()?;

    // Generate tokens using a non-cryptographic PRNG
    for _ in 0..count {
        let mut token = String::with_capacity(tokenLength);
        let mut rng = thread_rng();

        for _ in 0..tokenLength {
            let random_char = additional_data.chars().nth(rng.gen_range(0, additional_data.len())).unwrap();
            token.push(random_char);
        }

        tokens.push(token);
    }

    // Write tokens to the specified file path
    let mut file = File::create(outputPath)?;
    for token in tokens {
        file.write_all(token.as_bytes())?;
        file.write_all(b"\n")?; // Add a newline character between tokens
    }

    Ok(())
}
