            free(dataArray);
            return ERROR_INVALID_SOURCE; // Invalid source value
    }

    // Calculate sum and average of the array elements
    int sum = 0;
    for (int i = 0; i < dataSize; ++i) {
        sum += dataArray[i];
    }
    double average = (double)sum / dataSize;

    // Format and print the results based on the outputFormat parameter
    switch (outputFormat) {
        case 0: { // Plain text
            printf("Sum: %d\n", sum);
            printf("Average: %.2f\n", average);
            break;
        }
        case 1: { // CSV format
            printf("%d,%d,%.2f\n", sum, (int)average, average);
            break;
        }
        case 2: { // JSON format
            printf("{\"sum\": %d, \"average\": %.2f}\n", sum, average);
            break;
        }
        default:
            free(dataArray);
            return ERROR_INVALID_FORMAT; // Invalid output format value
    }

    free(dataArray); // Free the dynamically allocated memory
    return 0; // Success
}
