#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Function declarations
void generateData(unsigned long seed, int dataPointsSize, int rangeStart, int rangeEnd, int **dataPoints);
void analyzeData(int *dataPoints, int dataSize, double *mean, double *median, int *mode);
void exportStatistics(double mean, double median, int mode, FILE *outputFile);

int generateAndAnalyzeData(unsigned long seed, int dataPointsSize, int rangeStart, int rangeEnd, const char *outputFilePath) {
    if (seed == 0 || dataPointsSize <= 0 || rangeStart > rangeEnd) {
        return -1; // Invalid parameters
    }

    int *dataPoints = NULL;
    dataPoints = (int *)malloc(dataPointsSize * sizeof(int));
    if (dataPoints == NULL) {
        return -2; // Memory allocation failed
    }

    generateData(seed, dataPointsSize, rangeStart, rangeEnd, &dataPoints);

    double mean, median;
    int mode;
    analyzeData(dataPoints, dataPointsSize, &mean, &median, &mode);

    FILE *outputFile = fopen(outputFilePath, "w");
    if (outputFile == NULL) {
        free(dataPoints);
        return -3; // Failed to open output file
    }

    exportStatistics(mean, median, mode, outputFile);

    fclose(outputFile);
    free(dataPoints);
    return 0; // Success
}

void generateData(unsigned long seed, int dataPointsSize, int rangeStart, int rangeEnd, int **dataPoints) {
    srand(seed);
    for (int i = 0; i < dataPointsSize; i++) {
        (*dataPoints)[i] = rand() % (rangeEnd - rangeStart + 1) + rangeStart;
    }
}

void analyzeData(int *dataPoints, int dataSize, double *mean, double *median, int *mode) {
    // Calculate mean
    *mean = 0;
    for (int i = 0; i < dataSize; i++) {
        *mean += dataPoints[i];
    }
    *mean /= dataSize;

    // Calculate median
    qsort(dataPoints, dataSize, sizeof(int), (int (*)(const void *, const void *))strcmp);
    if (dataSize % 2 == 0) {
        *median = (dataPoints[dataSize / 2 - 1] + dataPoints[dataSize / 2]) / 2.0;
    } else {
        *median = dataPoints[dataSize / 2];
    }

    // Calculate mode
    int maxCount = 0;
    for (int i = 0; i < dataSize; i++) {
        int count = 1;
        while (i + 1 < dataSize && dataPoints[i] == dataPoints[i + 1]) {
            count++;
            i++;
        }
        if (count > maxCount) {
            *mode = dataPoints[i];
            maxCount = count;
        }
    }
}

void exportStatistics(double mean, double median, int mode, FILE *outputFile) {
    fprintf(outputFile, "Mean: %.2f\n", mean);
    fprintf(outputFile, "Median: %.2f\n", median);
    fprintf(outputFile, "Mode: %d\n", mode);
}
