#define RECORD_SIZE 20

typedef struct {
    int key;
    char value[RECORD_SIZE];
} Record;

Record* create_random_records(int count, int* error) {
    if (count <= 0) {
        *error = -1; // Invalid input
        return NULL;
    }

    Record* records = (Record*)malloc(count * sizeof(Record));
    if (!records) {
        *error = -2; // Memory allocation failed
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < count; ++i) {
        records[i].key = rand();
        for (int j = 0; j < RECORD_SIZE - 1; ++j) {
            records[i].value[j] = 'A' + rand() % ('Z' - 'A' + 1);
        }
        records[i].value[RECORD_SIZE - 1] = '\0'; // Null-terminate the string
    }

    *error = 0; // Success
    return records;
}

void free_records(Record* records, int count) {
    if (records) {
        for (int i = 0; i < count; ++i) {
            // No need to manually free value as it's statically allocated in Record struct
        }
        free(records);
    }
}

// Example usage
int main() {
    int error;
    Record* records = create_random_records(10, &error);

    if (error == 0) {
        for (int i = 0; i < 10; ++i) {
            printf("Record %d: Key = %d, Value = %s\n", i, records[i].key, records[i].value);
        }
        free_records(records, 10);
    } else if (error == -1) {
        printf("Invalid input count.\n");
    } else if (error == -2) {
        printf("Memory allocation failed.\n");
    }

    return 0;
}
