        for (int j = 0; j < STRING_LENGTH - 1; ++j) {
            records[i].value[j] = 'A' + rand() % ('Z' - 'A' + 1);
        }
        records[i].value[STRING_LENGTH - 1] = '\0';

        records[i].timestamp = time(NULL); // Initialize timestamp
    }

    return records;
}

