    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed PRNG

    for (int i = 0; i < num_records; ++i) {
        records[i].key = rand() % 100000; // Random key between 0 and 99999

