            for (int j = 0; j < 20; ++j) {
                value[j] = 'A' + rand() % ('Z' - 'A' + 1); // Random uppercase letter
            }
            value[20] = '\0';

            records[i].value = value;
        } else {
            records[i].value = malloc(21 * sizeof(char));
            if (!records[i].value) {
                free_records(records, i);
                return NULL; // Memory allocation failed
            }

            for (int j = 0; j < 20; ++j) {
                records[i].value[j] = 'A' + rand() % ('Z' - 'A' + 1); // Random uppercase letter
            }
            records[i].value[20] = '\0';
