        records[i]->offset = prng(MAX_RECORDS);
        records[i]->key = prng(1000); // Assuming keys are within 0-999
        int bufferSize = prng(records[i]->key) + 1; // Buffer size based on key
        records[i]->buffer = (char*)malloc(bufferSize * sizeof(char));
        if (!records[i]->buffer) {
            // Free previously allocated memory on failure
            for (int j = 0; j <= i; j++) {
                free(records[j]->buffer);
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        // Initialize buffer with random characters
        for (int j = 0; j < bufferSize; j++) {
            records[i]->buffer[j] = 'a' + prng(26); // Random character from 'a' to 'z'
        }
    }

    return records;
}

// Example PRNG function using XORshift
int xorshift(int state) {
    int x = state;
    x ^= x << 13;
    x ^= x >> 7;
    x ^= x << 17;
    return x;
}

void free_record_manager(Record** records, int seed) {
    for (int i = 0; i < MAX_RECORDS; i++) {
        free(records[i]->buffer);
        free(records[i]);
    }
    free(records);
}

int main() {
    Record** records = init_record_manager(time(NULL), xorshift);
    if (!records) return -1;

    // Verification process (example)
    for (int i = 0; i < MAX_RECORDS; i++) {
        printf("Record %d: Offset=%d, Key=%d, Buffer=%s\n", i, records[i]->offset, records[i]->key, records[i]->buffer);
    }

    free_record_manager(records, time(NULL));
    return 0;
}
