#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ARGS 10000
#define MIN_ARG_LEN 5
#define MAX_ARG_LEN 256

typedef struct {
    char** strings;
    long* offsets;
    int* indices;
    size_t count;
} ArgumentData;

void* process_arguments(void* arg) {
    ArgumentData* data = (ArgumentData*)arg;
    for (size_t i = 0; i < data->count; ++i) {
        if (strlen(data->strings[i]) >= MIN_ARG_LEN && strlen(data->strings[i]) <= MAX_ARG_LEN) {
            data->offsets[i] = 0;
            for (size_t j = 0; j < i; ++j) {
                data->offsets[i] += strlen(data->strings[j]);
            }
            data->indices[i] = i;
        } else {
            free(data->strings[i]);
            data->strings[i] = NULL;
        }
    }
    return NULL;
}

int main(int argc, char* argv[]) {
    ArgumentData data;
    data.strings = malloc(MAX_ARGS * sizeof(char*));
    data.offsets = malloc(MAX_ARGS * sizeof(long));
    data.indices = malloc(MAX_ARGS * sizeof(int));
    if (!data.strings || !data.offsets || !data.indices) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    for (int i = 1; i < argc && i <= MAX_ARGS; ++i) {
        data.strings[i - 1] = strdup(argv[i]);
        if (!data.strings[i - 1]) {
            free(data.strings);
            free(data.offsets);
            free(data.indices);
            fprintf(stderr, "Memory allocation failed\n");
            return 1;
        }
    }

    data.count = argc > 1 ? argc - 1 : 0;

    pthread_t thread;
    if (pthread_create(&thread, NULL, process_arguments, &data) != 0) {
        perror("Failed to create thread");
        free(data.strings);
        free(data.offsets);
        free(data.indices);
        return 1;
    }

    pthread_join(thread, NULL);

    for (size_t i = 0; i < data.count; ++i) {
        printf("Argument %zu: %s, Offset: %ld, Index: %d\n", i, data.strings[i], data.offsets[i], data.indices[i]);
        free(data.strings[i]);
    }

    free(data.strings);
    free(data.offsets);
    free(data.indices);

    return 0;
}
