#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
} record;

int generate_records(long seed, int range, long* offsets, int** keys, record** recs) {
    if (seed <= 0 || range <= 0 || !offsets || !keys || !recs) {
        return -1; // Invalid input
    }

    *recs = malloc(MAX_RECORDS * sizeof(record));
    if (!*recs) {
        return -2; // Memory allocation failed for records
    }

    srand(seed);
    for (int i = 0; i < MAX_RECORDS; ++i) {
        (*recs)[i].value = rand() % range;
    }

    *keys = malloc(MAX_RECORDS * sizeof(int));
    if (!*keys) {
        free(*recs); // Free previously allocated records
        return -3; // Memory allocation failed for keys
    }

    for (int i = 0; i < MAX_RECORDS; ++i) {
        (*keys)[i] = rand() % range;
    }

    *offsets = malloc(MAX_RECORDS * sizeof(long));
    if (!*offsets) {
        free(*recs); // Free previously allocated records
        free(*keys); // Free previously allocated keys
        return -4; // Memory allocation failed for offsets
    }

    for (int i = 0; i < MAX_RECORDS; ++i) {
        (*offsets)[i] = rand();
    }

    return 0; // Success
}

void write_records_to_file(record* recs, int* keys, long* offsets, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing: %s\n", filename);
        return;
    }

    for (int i = 0; i < MAX_RECORDS; ++i) {
        fprintf(file, "%d\t%d\t%ld\n", recs[i].value, keys[i], offsets[i]);
    }

    fclose(file);
}

int main() {
    long offsets[MAX_RECORDS];
    int* keys;
    record* records;

    int result = generate_records(time(NULL), 1000, offsets, &keys, &records);
    if (result != 0) {
        fprintf(stderr, "Failed to generate records: %d\n", result);
        return 1;
    }

    write_records_to_file(records, keys, offsets, "output.txt");

    free(records);
    free(keys);

    return 0;
}
