#include <time.h>

#define RECORD_COUNT 1000

typedef struct {
    int value;
} record;

typedef struct {
    long timestamp;
    char* identifier;
    float amount;
} transaction_record;

int initialize_records(record** records, int range_start, int range_end) {
    *records = (record*)malloc(RECORD_COUNT * sizeof(record));
    if (*records == NULL) return -1;
    srand(time(NULL)); // Seed the random number generator
    for (int i = 0; i < RECORD_COUNT; ++i) {
        (*records)[i].value = range_start + rand() % (range_end - range_start + 1);
    }
    return 0;
}

transaction_record* initialize_transactions(int transaction_count) {
    transaction_record* transactions = (transaction_record*)malloc(transaction_count * sizeof(transaction_record));
    if (transactions == NULL) return NULL;
    for (int i = 0; i < transaction_count; ++i) {
        transactions[i].timestamp = time(NULL);
        transactions[i].identifier = (char*)malloc(10 * sizeof(char)); // Allocate memory for identifier
        if (transactions[i].identifier == NULL) {
            free(transactions); // Clean up allocated memory on failure
            return NULL;
        }
        snprintf(transactions[i].identifier, 10, "TXN%d", i);
        transactions[i].amount = (float)(rand() % 1000) / 10.0; // Random transaction amount
    }
    return transactions;
}

void free_transactions(transaction_record* transactions, int transaction_count) {
    for (int i = 0; i < transaction_count; ++i) {
        free(transactions[i].identifier);
    }
    free(transactions);
}

int main() {
    record* records;
    if (initialize_records(&records, 1, 1000) != 0) {
        printf("Memory allocation failed for records\n");
        return 1;
    }

    transaction_record* transactions = initialize_transactions(100);
    if (transactions == NULL) {
        free(records); // Clean up allocated memory on failure
        printf("Memory allocation failed for transactions\n");
        return 1;
    }

    // Process the records and transactions as needed

    free_records(records);
    free_transactions(transactions, 100);

    return 0;
}
