int init_arrays(long* offsets, int* keys, Record** records, const char* text, size_t num_records, unsigned long seed) {
    if (num_records == 0 || !text || !records || !offsets || !keys) return -1;

    size_t text_len = strlen(text);
    if (num_records > text_len) return -1;

    unsigned long state = seed;
