        offsets[i] = i * sizeof(long); // Example offset calculation
        keys[i] = i; // Example key assignment
        records[i] = malloc(sizeof(Record));
        if (!records[i]) return -1;

        state = custom_prng(state);
        records[i]->value = (int)(state % 100); // Random value within [0, 99]

        size_t start = i * (text_len / num_records);
        size_t end = (i + 1) * (text_len / num_records);
        if (end > text_len) end = text_len;

        records[i]->str = malloc(end - start + 1);
        if (!records[i]->str) {
            free(records[i]);
            return -1;
        }
        strncpy(records[i]->str, text + start, end - start);
        records[i]->str[end - start] = '\0';
