        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        keys[i] = rand() % (keyRangeEnd - keyRangeStart + 1) + keyRangeStart;
        offsets[i] = rand() % 1000L; // Simplified offset generation for demonstration
        records[i]->value = rand() % (valueRangeEnd - valueRangeStart + 1) + valueRangeStart;
    }
}

void resetRecords(int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        if (records[i]) {
            free(records[i]);
            records[i] = NULL;
        }
    }
    free(keys);
    keys = (int*)malloc(sizeof(int) * MAX_RECORDS);
    free(offsets);
    offsets = (long*)malloc(sizeof(long) * MAX_RECORDS);
