#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    unsigned char *metadata_flags;
    size_t capacity;
    size_t size;
} data_structure;

// Custom PRNG function
unsigned int custom_prng(unsigned int seed) {
    return seed * 1664525 + 1013904223;
}

void resize_data_structure(data_structure *ds, size_t new_capacity) {
    if (new_capacity <= ds->capacity) return;

    // Dynamically allocate memory for each array
    long *new_offsets = realloc(ds->offsets, new_capacity * sizeof(long));
    int *new_keys = realloc(ds->keys, new_capacity * sizeof(int));
    record *new_records = realloc(ds->records, new_capacity * sizeof(record));
    unsigned char *new_metadata_flags = realloc(ds->metadata_flags, new_capacity * sizeof(unsigned char));

    if (!new_offsets || !new_keys || !new_records || !new_metadata_flags) {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize new elements
    for (size_t i = ds->size; i < new_capacity; ++i) {
        new_keys[i] = 0;
        new_records[i].value = 0;
        new_metadata_flags[i] = 0;
    }

    // Update pointers and capacity
    ds->offsets = new_offsets;
    ds->keys = new_keys;
    ds->records = new_records;
    ds->metadata_flags = new_metadata_flags;
    ds->capacity = new_capacity;
}

void initialize_data_structure(data_structure *ds, size_t initial_capacity) {
    // Initialize arrays with dynamic memory allocation
    ds->offsets = (long *)malloc(initial_capacity * sizeof(long));
    ds->keys = (int *)malloc(initial_capacity * sizeof(int));
    ds->records = (record *)malloc(initial_capacity * sizeof(record));
    ds->metadata_flags = (unsigned char *)malloc(initial_capacity * sizeof(unsigned char));

    if (!ds->offsets || !ds->keys || !ds->records || !ds->metadata_flags) {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    ds->capacity = initial_capacity;
    ds->size = 0;

    // Initialize PRNG seed
    srand(time(NULL));
}

void reset_data_structure(data_structure *ds) {
    // Free dynamically allocated memory
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds->metadata_flags);

    ds->offsets = NULL;
    ds->keys = NULL;
    ds->records = NULL;
    ds->metadata_flags = NULL;
    ds->capacity = 0;
    ds->size = 0;

    // Reinitialize the data structure with an empty capacity
    initialize_data_structure(ds, 1); // Start with a minimal capacity
}

void validate_records(data_structure *ds) {
    for (size_t i = 0; i < ds->size; ++i) {
        if (ds->keys[i] < 0 || ds->keys[i] >= ds->size ||
            ds->offsets[i] < 0 || ds->offsets[i] >= ds->capacity ||
            ds->metadata_flags[i] != 0 && ds->metadata_flags[i] != 1) {
            fprintf(stderr, "Record validation failed at index %zu.\n", i);
        }
    }
}

void add_record(data_structure *ds, int key, long offset, unsigned char metadata_flag) {
    if (ds->size >= ds->capacity) {
        resize_data_structure(ds, ds->capacity * 2); // Double the capacity
    }

    ds->keys[ds->size] = key;
    ds->offsets[ds->size] = offset;
    ds->records[ds->size].value = custom_prng(key ^ (unsigned int)offset);
    ds->metadata_flags[ds->size] = metadata_flag;

    ++ds->size;
}

// Example usage
int main() {
    data_structure ds;
    initialize_data_structure(&ds, 10);

    add_record(&ds, 123, 456789L, 1);
    add_record(&ds, 987, 654321L, 0);

    validate_records(&ds);

    reset_data_structure(&ds);

    return 0;
}
```

This code provides a basic structure for managing the specified data types and operations. It includes dynamic memory allocation, PRNG initialization, record management functions, capacity resizing, integrity validation, and error handling. The example usage demonstrates initializing the data structure, adding records, validating them, and resetting the structure to its initial state.']

