    return (seed * 214013 + 2531011) % 4294967296;
}

int allocateSensorData(sensorData **data, int count, unsigned long seed, unsigned long start_timestamp, unsigned long end_timestamp, double min_temp, double max_temp, char min_quality, char max_quality) {
    if (count <= 0 || start_timestamp > end_timestamp || min_temp > max_temp || min_quality > max_quality) {
        return -1; // Invalid input
    }

    *data = (sensorData *)malloc(count * sizeof(sensorData));
    if (*data == NULL) {
        return -2; // Memory allocation failed
    }

    for (int i = 0; i < count; ++i) {
        unsigned long random_seed = seed + i;
        (*data)[i].timestamp = start_timestamp + (customPRNG(random_seed) % (end_timestamp - start_timestamp + 1));
        (*data)[i].temperature = min_temp + ((double)customPRNG(customPRNG(random_seed)) / UINT_MAX) * (max_temp - min_temp);
        (*data)[i].quality_flag = min_quality + (customPRNG(customPRNG(customPRNG(random_seed))) % (max_quality - min_quality + 1));
    }

    return 0; // Success
}
