#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    size_t size;
    FILE *log_file;
    pthread_mutex_t lock;
} array_manager;

unsigned long xorshift128plus(unsigned long *state) {
    unsigned long x = state[0];
    unsigned long y = state[1];
    unsigned long z = state[2];
    unsigned long t;

    t = x ^ (x << 11);
    x = y;
    y = z;
    state[2] = z = z ^ (z >> 19) ^ t ^ (t << 8);

    return y + z;
}

void init_array_manager(array_manager *manager, size_t size, FILE *log_file) {
    manager->offsets = malloc(size * sizeof(long));
    manager->keys = malloc(size * sizeof(int));
    manager->records = malloc(size * sizeof(record *));
    manager->size = size;
    manager->log_file = log_file;
    pthread_mutex_init(&manager->lock, NULL);
}

void destroy_array_manager(array_manager *manager) {
    free(manager->offsets);
    free(manager->keys);
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->records[i]);
    }
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
}

void populate_array(array_manager *manager, unsigned long *prng_state, int min_value, int max_value) {
    for (size_t i = 0; i < manager->size; ++i) {
        pthread_mutex_lock(&manager->lock);
        manager->offsets[i] = xorshift128plus(prng_state);
        manager->keys[i] = xorshift128plus(prng_state) % (max_value - min_value + 1) + min_value;
        manager->records[i] = malloc(sizeof(record));
        if (manager->records[i]) {
