function renderScripts(scriptObjects) {
    if (!Array.isArray(scriptObjects)) {
        return "Error: Input must be an array of script objects.";
    }

    let renderedHTML = '';

    for (const scriptObj of scriptObjects) {
        if (typeof scriptObj !== 'object' || !scriptObj || !('code' in scriptObj) || !('key' in scriptObj)) {
            return "Error: Invalid script object encountered.";
        }

        if (typeof scriptObj.code !== 'string' || scriptObj.code.trim() === '' || typeof scriptObj.key !== 'string' || scriptObj.key.trim() === '') {
            return "Error: Script objects must contain non-empty code and key properties.";
        }

        renderedHTML += `<script id="${scriptObj.key}">${scriptObj.code}</script>`;
    }

    return renderedHTML;
}
