struct Transaction {
    uint64_t id;
    double amount;
    std::string description;
};

class FinancialTransactionProcessor {
public:
    FinancialTransactionProcessor(size_t maxTransactionsPerSecond, size_t logLevel)
        : maxTransactions(maxTransactionsPerSecond), currentLoad(0), logLevel(logLevel) {}

    void processTransactions() {
        std::thread([this]() {
            while (true) {
                std::unique_lock<std::mutex> lock(mutex);
                cv.wait(lock, [this] { return currentLoad < maxTransactions; });
                if (!active) break;

                Transaction transaction = generateTransaction();
                lock.unlock();

                // Process transaction
                process(transaction);

                lock.lock();
                --currentLoad;
            }
        }).detach();
    }

    void stop() {
        active = false;
        cv.notify_all();
    }

    void healthCheck() {
        std::cout << "Current Load: " << currentLoad << ", Processing Rate: " << processingRate << std::endl;
    }

private:
    Transaction generateTransaction() {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        static std::uniform_int_distribution<> idDist(1, 1000000);
        static std::uniform_real_distribution<> amountDist(0.0, 1000.0);

        Transaction transaction;
        transaction.id = idDist(gen);
        transaction.amount = amountDist(gen);
        // Generate description (not shown for brevity)
        return transaction;
    }

    void process(const Transaction& transaction) {
        std::this_thread::sleep_for(std::chrono::milliseconds(1)); // Simulate processing time
        ++processingRate;

        if (logLevel > 0) {
            log(transaction);
        }
    }

    void log(const Transaction& transaction) {
        // Log transaction details (not shown for brevity)
    }

    size_t maxTransactions;
    std::atomic<size_t> currentLoad;
    std::atomic<size_t> processingRate{0};
    bool active = true;
    std::mutex mutex;
    std::condition_variable cv;
    size_t logLevel;
};

int main() {
    FinancialTransactionProcessor processor(500, 1);
    processor.processTransactions();

    // Simulate system running
    std::this_thread::sleep_for(std::chrono::seconds(60));

    processor.stop();
    return 0;
}
