use std::io::{self, Read};
use std::net::TcpStream;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Debug)]
struct Record {
    value: i32,
}

fn processDataStream(
    socket_addr: &str,
    log_level: u8,
    connection_limit: usize,
    allow_negative: bool,
    sort_ascending: bool,
    retain_duplicates: bool,
) -> io::Result<()> {
    let stream = TcpStream::connect(socket_addr)?;
    let mut reader = stream.try_clone()?.take(connection_limit as u64 * 1024);

    let records = Arc::new(Mutex::new(Vec::<Record>::new()));
    let log = Arc::new(Mutex::new(vec![]));

    let start_time = Instant::now();

    loop {
        let data = reader.bytes().take_while(|b| b.is_ok()).collect::<Vec<_>>();

        if data.len() < connection_limit * 4 {
            break;
        }

        for chunk in data.chunks(4) {
            let value = i32::from_ne_bytes(chunk.try_into().unwrap());

            if (!allow_negative && value < 0) || records.lock()?.len() >= connection_limit {
                continue;
            }

            records.lock()?.push(Record { value });
        }

        log.lock()?.push((Instant::now(), "Processed data chunk".to_string()));

        if start_time.elapsed() > Duration::from_secs(log_level as u64 * 10) {
            break;
        }
    }

    let mut sorted_records = records.lock()?;
    if sort_ascending {
        sorted_records.sort_by_key(|r| r.value);
    } else {
        sorted_records.sort_unstable_by_key(|r| r.value);
    }

    for record in &sorted_records {
        println!("Record: {:?}", record);
    }

    Ok(())
}
```

