#define RECORD_SIZE sizeof(record_t)
#define CONFIG_SIZE sizeof(config_t)

typedef struct {
    int value;
} record_t;

typedef struct {
    // Parameters for processing logic
} config_t;

typedef enum {
    LONG_OFFSET,
    INT_KEY,
    RECORD,
    CONFIG
} data_type_t;

typedef union {
    long offset;
    int key;
    record_t *record;
    config_t *config;
} data_union_t;

typedef struct {
    data_type_t type;
    data_union_t data;
} module_data_t;

void* allocate_and_initialize(data_type_t type, size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }
    memset(ptr, 0, size);
    return ptr;
}

module_data_t* create_module_data(data_type_t type, long offset, int key, record_t *record, config_t *config) {
    module_data_t *md = allocate_and_initialize(MODULE_DATA, sizeof(module_data_t));
    if (md == NULL) {
        return NULL;
    }
    md->type = type;
    switch (type) {
        case LONG_OFFSET:
            md->data.offset = offset;
            break;
        case INT_KEY:
            md->data.key = key;
            break;
        case RECORD:
            md->data.record = allocate_and_initialize(RECORD, RECORD_SIZE);
            if (md->data.record == NULL) {
                free(md);
                return NULL;
            }
            *md->data.record = *record;
            break;
        case CONFIG:
            md->data.config = allocate_and_initialize(CONFIG, CONFIG_SIZE);
            if (md->data.config == NULL) {
                free(md);
                return NULL;
