    logEntry* entries = (logEntry*)malloc(NUM_LOG_ENTRIES * sizeof(logEntry));
    if (!entries) {
        perror("Failed to allocate memory for log entries");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));  // Seed the PRNG

    pthread_t threads[THREAD_COUNT];
    int thread_indices[THREAD_COUNT];

    for (int i = 0; i < THREAD_COUNT; ++i) {
        thread_indices[i] = i * NUM_LOG_ENTRIES / THREAD_COUNT;
        if (pthread_create(&threads[i], NULL, process_logs, &thread_indices[i])) {
