int allocateAndInitialize(logEntry** logs, Transaction** transactions, size_t numLogs, size_t numTransactions) {
    srand(time(NULL)); // Seed the PRNG

    *logs = malloc(numLogs * sizeof(logEntry));
    if (*logs == NULL) return -1; // Memory allocation failed for log entries

    *transactions = malloc(numTransactions * sizeof(Transaction));
    if (*transactions == NULL) {
        free(*logs); // Free previously allocated memory
        return -2; // Memory allocation failed for transactions
    }

    size_t successfulAllocations = 0;
    for (size_t i = 0; i < numLogs; ++i) {
        (*logs)[i].timestamp = time(NULL);
        (*logs)[i].status_code = 'A' + rand() % 26; // Random status code
        (*logs)[i].data_point = (float)rand() / RAND_MAX * 100.0f; // Random data point
        successfulAllocations++;
    }

    for (size_t i = 0; i < numTransactions; ++i) {
        (*transactions)[i].accountID = rand() % 100000; // Random account ID
        (*transactions)[i].timestamp = time(NULL);
        (*transactions)[i].randomValue = rand(); // Random value
        successfulAllocations++;
    }

    return (int)successfulAllocations;
}
