    int keys[] = {10, 20, 30};
    Record *records = NULL;
    size_t numRecords = sizeof(offsets) / sizeof(offsets[0]);

    long maxTimestamp = processAndFindMax(offsets, keys, &records, numRecords);
    if (maxTimestamp != -1 && maxTimestamp != -2 && maxTimestamp != -3 && maxTimestamp != -4) {
        printf("Maximum Timestamp: %ld\n", maxTimestamp);
    } else {
        printf("Error processing data.\n");
    }

    return 0;
}
