pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

unsigned int prng() {
    static unsigned int seed = PRNG_SEED;
    return seed = (seed * 1103515245 + 12345) % 32768;
}

void initialize_records() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].id = prng();
    }
    pthread_mutex_unlock(&lock);
}

int execute_command(char *command, int offset) {
    if (strcmp(command, "GET") == 0 && offset >= 0 && offset < MAX_RECORDS) {
        return records[offset].id;
    } else if (strcmp(command, "SET") == 0 && offset >= 0 && offset < MAX_RECORDS) {
        pthread_mutex_lock(&lock);
        records[offset].id = prng();
        pthread_mutex_unlock(&lock);
        return 1; // Success
    } else if (strcmp(command, "CLEAR") == 0) {
        pthread_mutex_lock(&lock);
        for (int i = 0; i < MAX_RECORDS; i++) {
            records[i].id = 0;
        }
        pthread_mutex_unlock(&lock);
        return 1; // Success
    } else {
        return -1; // Invalid command
    }
}

void *handle_operations(void *data) {
    char **operations = (char **)data;
    for (int i = 0; operations[i] != NULL; i++) {
        char *command = strtok(operations[i], " ");
        int offset = atoi(strtok(NULL, " "));
        execute_command(command, offset);
    }
    return NULL;
}

int main() {
    initialize_records();

    pthread_t thread1, thread2;
    char *commands1[] = {"SET 0", "GET 1", "CLEAR", NULL};
    char *commands2[] = {"SET 100000", "GET 500000", NULL};

    pthread_create(&thread1, NULL, handle_operations, commands1);
    pthread_create(&thread2, NULL, handle_operations, commands2);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    return 0;
}
