    FILE* log_file = fopen(log_file_path, "a");
    if (!log_file) return -1;

    srand(time(NULL) ^ getpid());

    *offset_array = (long*)malloc(array_size * sizeof(long));
    *key_range_array = (int*)malloc(array_size * sizeof(int));
    *records_array = (record**)malloc(array_size * sizeof(record*));

