            fclose(log_file);
            pthread_mutex_destroy(&lock);
            return -1;
        }
        (*records_array)[i] = new_record;
        pthread_mutex_unlock(&lock);

        if ((i + 1) % (array_size / 10) == 0) {
            printf("Progress: %zu/%zu\n", i + 1, array_size);
        }
    }

    fclose(log_file);
    pthread_mutex_destroy(&lock);
    return 0;
}

void destroy_records(record** records, size_t count) {
