#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int key;
    double timestamp;
    long offset;
    // Add other fields as needed
} Record;

// Define the priority queue node
typedef struct PriorityQueueNode {
    Record *record;
    struct PriorityQueueNode *next;
} PriorityQueueNode;

// Define the priority queue
typedef struct {
    PriorityQueueNode *head;
    int size;
    pthread_mutex_t lock;  // Mutex for thread safety
} PriorityQueue;

// Function to create a new record
Record* create_record(int key, long offset) {
    Record *record = (Record*)malloc(sizeof(Record));
    if (record == NULL) return NULL;

    record->key = key;
    record->offset = offset;
    clock_gettime(CLOCK_MONOTONIC, &record->timestamp);
    // Initialize other fields as needed

    return record;
}

// Function to compare two records based on timestamp
int compare_records(Record *r1, Record *r2) {
    if (r1->timestamp < r2->timestamp) return -1;
    if (r1->timestamp > r2->timestamp) return 1;
    return 0;
}

// Function to insert a record into the priority queue
void insert_record(PriorityQueue *pq, Record *record) {
    pthread_mutex_lock(&pq->lock);

    PriorityQueueNode *new_node = (PriorityQueueNode*)malloc(sizeof(PriorityQueueNode));
    if (new_node == NULL) return;
    new_node->record = record;
    new_node->next = pq->head;
    pq->head = new_node;
    pq->size++;

    pthread_mutex_unlock(&pq->lock);
}

// Function to remove the highest priority record from the queue
Record* remove_highest_priority_record(PriorityQueue *pq) {
    if (pq->size == 0) return NULL;

    pthread_mutex_lock(&pq->lock);

    PriorityQueueNode *max_node = pq->head;
    Record *max_record = max_node->record;
    PriorityQueueNode *prev = NULL, *current = pq->head;

    while (current != NULL) {
        if (compare_records(current->record, max_record) > 0) {
            max_node = current;
            max_record = current->record;
        }
        prev = current;
        current = current->next;
    }

    if (prev == NULL) {
        pq->head = max_node->next;
    } else {
        prev->next = max_node->next;
    }

    free(max_node);
    pq->size--;

    pthread_mutex_unlock(&pq->lock);

    return max_record;
}

// Function to initialize the priority queue
void init_priority_queue(PriorityQueue *pq) {
    pq->head = NULL;
    pq->size = 0;
    pthread_mutex_init(&pq->lock, NULL);
}

// Function to destroy the priority queue
void destroy_priority_queue(PriorityQueue *pq) {
    while (pq->head != NULL) {
        PriorityQueueNode *temp = pq->head;
        pq->head = temp->next;
        free(temp);
    }
    pthread_mutex_destroy(&pq->lock);
}

// Example usage
int main() {
    PriorityQueue pq;
    init_priority_queue(&pq);

    Record *record1 = create_record(1, 12345L);
    Record *record2 = create_record(2, 67890L);

    insert_record(&pq, record1);
    insert_record(&pq, record2);

    Record *highest_priority_record = remove_highest_priority_record(&pq);
    if (highest_priority_record != NULL) {
        printf("Highest priority record key: %d\n", highest_priority_record->key);
        free(highest_priority_record);  // Remember to free allocated records
    }

    destroy_priority_queue(&pq);

    return 0;
}
```

This code snippet provides a basic implementation of a thread-safe non-blocking priority queue for managing `Record` structures. The `PriorityQueueNode` and `PriorityQueue` types are defined to hold the nodes and the queue, respectively. Functions are provided to create records, compare records based on timestamps, insert records into the queue, remove the highest priority record, initialize the queue, and destroy the queue.

The `main` function demonstrates how to use these functions to manage a priority queue of records. The example uses a simple timestamp-based comparison for prioritization. In a real-world scenario, you would need to implement more complex logic based on your specific requirements.

Note that this code does not include detailed error handling or advanced features such as network integration or distributed system considerations. It serves as a starting point for implementing a custom non-blocking priority queue in C.']

