        (*keys)[i] = rand();

        int str_length = rand() % MAX_STRING_LENGTH + 1;
        size_t required_memory = sizeof(record) + str_length * sizeof(char);

        if (*total_memory + required_memory > MAX_MEMORY_LIMIT) {
            fprintf(stderr, "Memory limit exceeded.\n");
            free(*offsets);
            free(*keys);
            free(*records);
            return -2;
        }

        (*records)[i].str = (char*)malloc(str_length * sizeof(char));
        if (!(*records)[i].str) {
            fprintf(stderr, "Memory allocation failed for string at index %d.\n", i);
            free(*offsets);
            free(*keys);
            free(*records);
