#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <openssl/rand.h>

#define MAX_RECORDS 10000000
#define RECORD_SIZE sizeof(int)
#define POOL_SIZE 1024

typedef struct {
    int *data;
    size_t allocated;
} MemoryPool;

MemoryPool pool = {NULL, 0};
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

int init_memory_pool(size_t size) {
    pthread_mutex_lock(&pool_lock);
    if (pool.allocated >= size) {
        pthread_mutex_unlock(&pool_lock);
        return 1;
    }
    pool.data = realloc(pool.data, (size + POOL_SIZE) * RECORD_SIZE);
    if (!pool.data) {
        perror("Failed to allocate memory for memory pool");
        pthread_mutex_unlock(&pool_lock);
        return 0;
    }
    pool.allocated += size + POOL_SIZE;
    pthread_mutex_unlock(&pool_lock);
    return 1;
}

int* get_record() {
    pthread_mutex_lock(&pool_lock);
    if (!pool.data) {
        pthread_mutex_unlock(&pool_lock);
        return NULL;
    }
    int *record = &pool.data[pool.allocated - POOL_SIZE];
    pool.allocated -= POOL_SIZE;
    pthread_mutex_unlock(&pool_lock);
    return record;
}

void free_record(int *record) {
    pthread_mutex_lock(&pool_lock);
    int index = (int)((char*)record - (char*)pool.data) / RECORD_SIZE;
    if (index + POOL_SIZE < pool.allocated) {
        memmove(&pool.data[index], &pool.data[index + POOL_SIZE], (pool.allocated - index - POOL_SIZE) * RECORD_SIZE);
    }
    pool.allocated += POOL_SIZE;
    pthread_mutex_unlock(&pool_lock);
}

int init_records(size_t count, int min, int max) {
    if (!init_memory_pool(count)) {
        return 0;
    }
    for (size_t i = 0; i < count; ++i) {
        int *record = get_record();
        if (!record) {
            return 0;
        }
        while (!RAND_bytes((unsigned char*)record, RECORD_SIZE)) {
            // Handle PRNG failure
        }
        *record = (int)(*record % (max - min + 1)) + min;
    }
    return 1;
}

void reseed_prng() {
    unsigned char seed[32];
    if (!RAND_bytes(seed, sizeof(seed))) {
        // Handle PRNG failure
    }
    RAND_seed(seed, sizeof(seed));
}

void* worker_thread(void *arg) {
    size_t count = *(size_t*)arg;
    for (size_t i = 0; i < count; ++i) {
        int *record = get_record();
        if (!record) {
            // Handle memory allocation failure
        }
        while (!RAND_bytes((unsigned char*)record, RECORD_SIZE)) {
            // Handle PRNG failure
        }
        *record = (int)(*record % 100) + 1; // Example range
    }
    return NULL;
}

int main() {
    if (!RAND_status()) {
        printf("PRNG is not ready. Exiting.\n");
        return 1;
    }

    size_t num_threads = 4;
    pthread_t threads[num_threads];
    size_t records_per_thread = MAX_RECORDS / num_threads;

    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, worker_thread, &records_per_thread)) {
            printf("Failed to create thread %zu\n", i);
            return 1;
        }
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    reseed_prng();

    // Additional functionality as per requirements

    free_record(NULL); // Clean up memory pool
    return 0;
}
