#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct Transaction {
    time_t timestamp;
    int user_id;
    double amount;
} Transaction;

typedef struct TransactionPool {
    Transaction *transactions;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} TransactionPool;

void initialize_transaction_pool(TransactionPool *pool, size_t capacity) {
    pool->capacity = capacity;
    pool->size = 0;
    if ((pool->transactions = malloc(capacity * sizeof(Transaction))) == NULL) {
        perror("Failed to allocate memory for transaction pool");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&pool->lock, NULL);
}

void destroy_transaction_pool(TransactionPool *pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->transactions);
}

void add_transaction(TransactionPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size == pool->capacity) {
        fprintf(stderr, "Transaction pool is full\n");
        pthread_mutex_unlock(&pool->lock);
        return;
    }
    Transaction new_transaction;
    new_transaction.timestamp = time(NULL);
    new_transaction.user_id = rand();
    new_transaction.amount = ((double)rand() / RAND_MAX) * 1000; // Random amount between 0 and 1000
    pool->transactions[pool->size++] = new_transaction;
    pthread_mutex_unlock(&pool->lock);
}

void reseed_prng() {
    srand(time(NULL));
}

int main() {
    TransactionPool pool;
    initialize_transaction_pool(&pool, 100);

    for (size_t i = 0; i < 50; ++i) {
        add_transaction(&pool);
    }

    destroy_transaction_pool(&pool);
    reseed_prng();

    return 0;
}
```

