// Define record structure
typedef struct {
    int value;
    time_t expiration_timestamp;
} Record;

// Define batch structure
typedef struct Batch {
    long offset;
    int key;
    Record* records;
    size_t record_count;
} Batch;

// Define PRNG state
unsigned long rng_state = 123456789UL;

// High-performance PRNG function (Mersenne Twister)
unsigned long next_random() {
    rng_state = rng_state * 1103515245 + 12345;
    return rng_state >> 16;
}

// Function to allocate memory for a batch
Batch* create_batch(size_t record_count) {
    Batch* batch = (Batch*)malloc(sizeof(Batch));
    if (!batch) return NULL;

    batch->records = (Record*)malloc(record_count * sizeof(Record));
    if (!batch->records) {
        free(batch);
        return NULL;
    }

    batch->offset = next_random();
    batch->key = (int)next_random();
    batch->record_count = record_count;

    // Initialize records
    for (size_t i = 0; i < record_count; ++i) {
        batch->records[i].value = (int)next_random();
        batch->records[i].expiration_timestamp = time(NULL) + next_random() % 3600;
    }

    return batch;
}

// Function to deallocate memory for a batch
void destroy_batch(Batch* batch) {
    if (batch) {
        free(batch->records);
        free(batch);
    }
}

int main() {
    size_t record_count = 100;
    Batch* batch = create_batch(record_count);

    if (!batch) {
        fprintf(stderr, "Failed to allocate memory for batch.\n");
        return -1;
    }

    // Process the batch (example: print records)
    for (size_t i = 0; i < batch->record_count; ++i) {
        printf("Record %zu: Offset=%ld, Key=%d, Value=%d, Expiration=%.2f\n",
               i, batch->offset, batch->key, batch->records[i].value,
               difftime(batch->records[i].expiration_timestamp, time(NULL)));
    }

    destroy_batch(batch);
    return 0;
}
