        .json(&transaction)
        .send()
        .await?;

    if !response.status().is_success() {
        return Err(format!("Transaction processing failed: {}", response.text().await?));
    }

    Ok(())
}

fn process_transaction_data(
    seed: i64,
    transaction_count: u32,
    enable_encryption: bool,
    max_retry_attempts: u32,
    log_level: LogLevels,
    payment_gateway_config: PaymentGatewayConfig,
) -> Result<(), Box<dyn Error>> {
    if transaction_count == 0 {
        return Err("Transaction count must be greater than zero".into());
    }

    let mut transactions = Vec::with_capacity(transaction_count as usize);
    for i in 0..transaction_count {
        transactions.push(Transaction::new(i + 1));
    }

    if enable_encryption {
        // Implement encryption logic here
        let key = b"secret_key_123"; // Example encryption key
        for transaction in &mut transactions {
            transaction.encrypt(key);
        }
    }

    let mut tasks = Vec::with_capacity(transaction_count as usize);
    for transaction in transactions {
        let task = process_transaction(&transaction).retry(max_retry_attempts);
        tasks.push(task);
    }

    futures::future::join_all(tasks).await?;

    Ok(())
}
