import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DistributedCacheService {
    private final ExecutorService executorService = Executors.newFixedThreadPool(10);
    private final CacheStorage cacheStorage;

    public DistributedCacheService(CacheStorage cacheStorage) {
        this.cacheStorage = cacheStorage;
    }

    public void put(String key, Object value) {
        cacheStorage.put(key, value);
        refreshAsync(key);
    }

    public Object get(String key) {
        return cacheStorage.get(key);
    }

    private void refreshAsync(String key) {
        executorService.submit(() -> {
            try {
                // Simulate data retrieval from backend
                Object newData = fetchDataFromBackend(key);
                cacheStorage.put(key, newData);
            } catch (Exception e) {
                handleException(e);
            }
        });
    }

    private Object fetchDataFromBackend(String key) throws Exception {
        // Placeholder for fetching data from backend
        Thread.sleep(100); // Simulate network delay
        return "Data for " + key;
    }

    private void handleException(Exception e) {
        // Log error and take necessary actions
        System.err.println("Error refreshing cache: " + e.getMessage());
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException ie) {
            executorService.shutdownNow();
        }
    }

    public interface CacheStorage {
        void put(String key, Object value);
        Object get(String key);
    }
}

class InMemoryCache implements DistributedCacheService.CacheStorage {
    private final java.util.Map<String, Object> cache = new java.util.concurrent.ConcurrentHashMap<>();

    @Override
    public void put(String key, Object value) {
        cache.put(key, value);
    }

    @Override
    public Object get(String key) {
        return cache.get(key);
    }
}
