using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class SymmetricEncryptionLibrary
{
    private readonly ConcurrentDictionary<string, byte[]> keyCache = new ConcurrentDictionary<string, byte[]>();
    private readonly ILogger logger;
    private readonly RandomNumberGenerator rng;

    public SymmetricEncryptionLibrary(ILogger logger)
    {
        this.logger = logger;
        this.rng = RandomNumberGenerator.Create();
    }

    public void SetDefaultAlgorithm(string algorithmName)
    {
        // Configuration management and setting default algorithm
        if (algorithmName != "AES-256" && algorithmName != "AES-192" && algorithmName != "AES-128" && algorithmName != "DES")
        {
            logger.LogWarning($"Unsupported algorithm: {algorithmName}. Defaulting to AES-256.");
            algorithmName = "AES-256";
        }
    }

    public byte[] Encrypt(byte[] plaintext, string key = null)
    {
        if (plaintext == null || plaintext.Length == 0)
        {
            logger.LogError("Invalid plaintext provided.");
            throw new ArgumentException("Plaintext cannot be null or empty.", nameof(plaintext));
        }

        try
        {
            using (var aes = CreateAesAlgorithm(key))
            {
                var iv = GenerateIV(aes);
                byte[] encryptedBytes;

                using (var encryptor = aes.CreateEncryptor(aes.Key, iv))
                {
                    using (var msEncrypt = new MemoryStream())
                    {
                        using (var csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                        {
                            csEncrypt.Write(plaintext, 0, plaintext.Length);
                        }
                        encryptedBytes = msEncrypt.ToArray();
                    }
                }

                var result = new byte[iv.Length + encryptedBytes.Length];
                Buffer.BlockCopy(iv, 0, result, 0, iv.Length);
                Buffer.BlockCopy(encryptedBytes, 0, result, iv.Length, encryptedBytes.Length);

                return result;
            }
        }
        catch (Exception ex)
        {
            logger.LogError($"Error encrypting data: {ex.Message}");
            throw;
        }
    }

    public byte[] Decrypt(byte[] ciphertext, string key = null)
    {
        if (ciphertext == null || ciphertext.Length < 16)
        {
            logger.LogError("Invalid ciphertext provided.");
            throw new ArgumentException("Ciphertext cannot be null or too short.", nameof(ciphertext));
        }

        try
        {
            using (var aes = CreateAesAlgorithm(key))
            {
                var iv = new byte[16];
                Buffer.BlockCopy(ciphertext, 0, iv, 0, iv.Length);
                var encryptedBytes = new byte[ciphertext.Length - iv.Length];
                Buffer.BlockCopy(ciphertext, iv.Length, encryptedBytes, 0, encryptedBytes.Length);

                using (var decryptor = aes.CreateDecryptor(aes.Key, iv))
                {
                    using (var msDecrypt = new MemoryStream(encryptedBytes))
                    {
                        using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                        {
                            return csDecrypt.ToArray();
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            logger.LogError($"Error decrypting data: {ex.Message}");
            throw;
        }
    }

    private Aes CreateAesAlgorithm(string key = null)
    {
        byte[] aesKey;

        if (string.IsNullOrEmpty(key))
        {
            aesKey = GenerateRandomKey();
        }
        else
        {
            aesKey = Encoding.UTF8.GetBytes(key);
        }

        var aes = Aes.Create("AES");
        aes.Key = aesKey;
        aes.Padding = PaddingMode.PKCS7;

        return aes;
    }

    private byte[] GenerateRandomKey()
    {
        // Random number generation with fallback to hardware-based RNG
        if (!rng.GetBytes(new byte[1]) is { Length: 1 })
        {
            logger.LogWarning("Failed to get random bytes using default PRNG. Falling back to hardware RNG.");
            return rng.GetBytes(32); // AES-256 key size
        }

        return aesKey;
    }

    private byte[] GenerateIV(Aes aes)
    {
        var iv = new byte[16];
        rng.GetBytes(iv);
        return iv;
    }
}
