// Import necessary libraries
const express = require('express');
const bodyParser = require('body-parser');
const { evaluate } = require('mathjs');
const LRU = require('lru-cache');

// Create an Express app
const app = express();

// Configure body parser to handle JSON and URL-encoded data
app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: true }));

// Define a cache for storing frequently evaluated expressions
const cache = new LRU({
  max: 500, // Maximum number of entries in the cache
  maxAge: 1000 * 60 * 60 * 24, // Cache entries expire after 24 hours
});

// Define a configuration object for allowed operations
const config = {
  allowedOperations: ['+', '-', '*', '/'],
};

// Function to evaluate expressions safely and cache results
function evaluateExpression(expression) {
  try {
    const parsedExpression = parseExpression(expression);
    if (parsedExpression) {
      const result = evaluate(parsedExpression);
      return { success: true, result };
    } else {
      throw new Error('Invalid expression');
    }
  } catch (error) {
    return { success: false, error: error.message };
  }
}

// Function to parse and validate the expression
function parseExpression(expression) {
  const tokens = expression.split(' ');
  let stack = [];

  for (let token of tokens) {
    if (isNumber(token)) {
      stack.push(parseFloat(token));
    } else if (config.allowedOperations.includes(token)) {
      if (stack.length < 2) throw new Error('Invalid expression');
      const b = stack.pop();
      const a = stack.pop();
      stack.push(`${a} ${token} ${b}`);
    } else {
      throw new Error('Invalid operation');
    }
  }

  if (stack.length !== 1) throw new Error('Invalid expression');
  return stack[0];
}

// Function to check if a string is a number
function isNumber(value) {
  return !isNaN(parseFloat(value)) && isFinite(value);
}

// Middleware for logging each request
app.use((req, res, next) => {
  console.log(`Received ${req.method} request for ${req.url}`);
  next();
});

// Route to evaluate expressions
app.post('/evaluate', (req, res) => {
  const { expression } = req.body;

  if (!expression) {
    return res.status(400).json({ success: false, error: 'No expression provided' });
  }

  const cachedResult = cache.get(expression);
  if (cachedResult) {
    return res.json(cachedResult);
  }

  const evaluationResult = evaluateExpression(expression);

  if (evaluationResult.success) {
    cache.set(expression, evaluationResult); // Cache the result
    res.status(200).json(evaluationResult);
  } else {
    res.status(400).json(evaluationResult);
  }
});

// Route to configure allowed operations
app.post('/configure', (req, res) => {
  const { operations } = req.body;

  if (!operations || !Array.isArray(operations)) {
    return res.status(400).json({ success: false, error: 'Invalid operations configuration' });
  }

  config.allowedOperations = operations.filter(op => ['+', '-', '*', '/'].includes(op));
  res.status(200).json({ success: true, message: 'Config updated successfully' });
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
