        this.sessionMap = new ConcurrentHashMap<>();
    }

    public String createSession(UserPreferences preferences, DeviceInfo deviceInfo) {
        String sessionId = generateUniqueSessionId();
        UserSession userSession = new UserSession(sessionId, preferences, deviceInfo);
        sessionMap.put(sessionId, userSession);
        return sessionId;
    }

    public UserSession getSession(String sessionId) {
        return sessionMap.get(sessionId);
    }

    public void updateSession(String sessionId, UserPreferences preferences, DeviceInfo deviceInfo) {
        UserSession userSession = sessionMap.get(sessionId);
        if (userSession != null) {
            userSession.update(preferences, deviceInfo);
        }
    }

    public void deleteSession(String sessionId) {
        sessionMap.remove(sessionId);
    }

    private String generateUniqueSessionId() {
        return Long.toString(sessionIdGenerator.incrementAndGet());
    }
}

