#include <stdlib.h>
#include <time.h>

typedef struct {
    long timestamp;
    int status_code;
    short tag;
} event;

int allocate_memory(long* offsets, int* keys, short* tags, event** events, size_t num_events, short min_tag, short max_tag) {
    if (num_events > SIZE_MAX / sizeof(event)) return -1; // Check for overflow

    *offsets = (long*)malloc(num_events * sizeof(long));
    *keys = (int*)malloc(num_events * sizeof(int));
    *tags = (short*)malloc(num_events * sizeof(short));

    if (!*offsets || !*keys || !*tags) {
        free(*offsets);
        free(*keys);
        free(*tags);
        return -2; // Memory allocation failed
    }

    *events = (event*)malloc(num_events * sizeof(event));
    if (!*events) {
        free(*offsets);
        free(*keys);
        free(*tags);
        return -2; // Memory allocation failed
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < num_events; ++i) {
        (*events)[i].timestamp = rand(); // Set timestamp to a random value
        (*events)[i].status_code = rand() % 256; // Set status code to a random value
        (*events)[i].tag = (short)(min_tag + rand() % (max_tag - min_tag + 1)); // Set tag to a random value within the specified range
    }

    return 0; // Success
}
