#include <time.h>

typedef struct record {
    int key;
    long offset;
    int value;
} Record;

#define RECORDS_CHUNK_SIZE 100

Record* records = NULL;
int current_records_count = 0;
int allocated_records_count = 0;

void init_memory_management() {
    srand(time(NULL));
}

int add_record(int key, long offset) {
    if (current_records_count >= allocated_records_count) {
        if (allocated_records_count == 0) {
            records = (Record*)malloc(RECORDS_CHUNK_SIZE * sizeof(Record));
        } else {
            records = (Record*)realloc(records, (allocated_records_count + RECORDS_CHUNK_SIZE) * sizeof(Record));
        }
        if (!records) return -1; // Memory allocation failed
        allocated_records_count += RECORDS_CHUNK_SIZE;
    }
    records[current_records_count].key = key;
    records[current_records_count].offset = offset;
    records[current_records_count].value = rand() % 1000; // Random value between 0 and 999
    current_records_count++;
    return 0;
}

int remove_record(int key) {
    for (int i = 0; i < current_records_count; i++) {
        if (records[i].key == key) {
            records[i] = records[current_records_count - 1];
            current_records_count--;
            return 0;
        }
    }
    return -1; // Record not found
}

void log_memory_usage() {
    printf("Memory usage: %zu bytes\n", current_records_count * sizeof(Record));
}

int main() {
    init_memory_management();

    for (int i = 0; i < 500; i++) {
        if (add_record(i, i * 1000) != 0) {
            fprintf(stderr, "Failed to add record\n");
            break;
        }
    }

    log_memory_usage();

    remove_record(250);

    log_memory_usage();

    free(records);

    return 0;
}
