void processEventsWithMemoryPool(size_t dataSize, const unsigned long* offsets,
                                 const int* keys, const short* tags,
                                 char* inputBuffer, size_t max_input_size,
                                 FILE* logFile, void* memoryPool,
                                 struct timespec timestampRange) {
    // Initialize PRNG
    srand(time(NULL));

    // Allocate data array using memory pool
    Event* data = (Event*)memoryPool;
    for (size_t i = 0; i < dataSize; ++i) {
        data[i].timestamp = rand() % (timestampRange.tv_sec - timestampRange.tv_nsec);
        data[i].status_code = rand();
        data[i].tag = tags[rand() % sizeof(tags)];
        // Log memory allocation
        fprintf(logFile, "Allocated memory for event %zu\n", i);
    }

    // Read input from standard input
    size_t bytesRead = 0;
    while (bytesRead < max_input_size && ((inputBuffer[bytesRead] = getchar()) != EOF)) {
        ++bytesRead;
        // Log each character read
        fprintf(logFile, "Read character: %c\n", inputBuffer[bytesRead - 1]);
    }

    // Find and print maximum integer in data array and input buffer
    int maxInData = INT_MIN;
    for (size_t i = 0; i < dataSize; ++i) {
        if (data[i].status_code > maxInData) {
            maxInData = data[i].status_code;
        }
    }
    printf("Maximum in data: %d\n", maxInData);

    int maxInBuffer = INT_MIN;
    for (size_t i = 0; i < bytesRead; ++i) {
        if ((int)inputBuffer[i] > maxInBuffer) {
            maxInBuffer = inputBuffer[i];
        }
    }
    printf("Maximum in buffer: %d\n", maxInBuffer);

    // Log memory deallocation
    fprintf(logFile, "Deallocated memory for data array\n");
}
