typedef struct Event {
    long timestamp;
    int status_code;
    short tag_value;
} Event;

typedef struct MemoryPool {
    Event* events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) {
        return NULL; // Handle memory allocation failure
    }
    pool->events = (Event*)calloc(initial_capacity, sizeof(Event));
    if (!pool->events) {
        free(pool);
        return NULL; // Handle memory allocation failure
    }
    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    if (pool) {
        free(pool->events);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

Event* allocate_event(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        Event* new_events = realloc(pool->events, new_capacity * sizeof(Event));
        if (!new_events) {
            pthread_mutex_unlock(&pool->lock);
            return NULL; // Handle memory allocation failure
        }
        pool->events = new_events;
        pool->capacity = new_capacity;
    }
    Event* event = &pool->events[pool->count++];
    pthread_mutex_unlock(&pool->lock);
    return event;
}

void deallocate_event(MemoryPool* pool, Event* event) {
    // In a real implementation, you might want to reset the event fields
    // For simplicity, we'll just decrement the count
    pthread_mutex_lock(&pool->lock);
    if (event >= pool->events && event < &pool->events[pool->count]) {
        pool->count--;
    }
    pthread_mutex_unlock(&pool->lock);
}

