#include <time.h>

typedef struct {
    long *timestamps;
    int *eventTypes;
    double *probabilities;
    char **details;
    size_t count;
    size_t capacity;
} EventLog;

EventLog* init_event_log(size_t initial_capacity) {
    EventLog *log = (EventLog*)malloc(sizeof(EventLog));
    log->timestamps = (long*)malloc(initial_capacity * sizeof(long));
    log->eventTypes = (int*)malloc(initial_capacity * sizeof(int));
    log->probabilities = (double*)malloc(initial_capacity * sizeof(double));
    log->details = (char**)malloc(initial_capacity * sizeof(char*));
    log->count = 0;
    log->capacity = initial_capacity;
    return log;
}

void add_event(EventLog *log, long timestamp, int eventType, double probability, char *detail) {
    if (log->count >= log->capacity) {
        log->timestamps = (long*)realloc(log->timestamps, log->capacity * 2 * sizeof(long));
        log->eventTypes = (int*)realloc(log->eventTypes, log->capacity * 2 * sizeof(int));
        log->probabilities = (double*)realloc(log->probabilities, log->capacity * 2 * sizeof(double));
        log->details = (char**)realloc(log->details, log->capacity * 2 * sizeof(char*));
        log->capacity *= 2;
    }
    log->timestamps[log->count] = timestamp;
    log->eventTypes[log->count] = eventType;
    log->probabilities[log->count] = probability;
    log->details[log->count++] = detail;
}

void print_event_log(EventLog *log) {
    for (size_t i = 0; i < log->count; ++i) {
        printf("Event %zu: Timestamp=%ld, Type=%d, Probability=%.2f, Detail=%s\n",
               i, log->timestamps[i], log->eventTypes[i], log->probabilities[i], log->details[i]);
    }
}

void free_event_log(EventLog *log) {
    for (size_t i = 0; i < log->count; ++i) {
        free(log->details[i]);
    }
    free(log->timestamps);
    free(log->eventTypes);
    free(log->probabilities);
    free(log->details);
    free(log);
}

int main() {
    srand(time(0)); // Seed for cryptographically weak PRNG
    EventLog *log = init_event_log(10);

    add_event(log, 1633072800L, 1, 0.5 + rand() / (double)RAND_MAX, "Event A");
    add_event(log, 1633072900L, 2, 0.3 + rand() / (double)RAND_MAX, "Event B");

    print_event_log(log);

    free_event_log(log);
    return 0;
}
