typedef struct {
    int value;
} record;

long* allocateLongArray(int size) {
    long* array = (long*)malloc(size * sizeof(long));
    if (!array) {
        perror("Failed to allocate memory for long array");
    }
    return array;
}

int* allocateIntArray(int size) {
    int* array = (int*)calloc(size, sizeof(int));
    if (!array) {
        perror("Failed to allocate memory for int array");
    }
    return array;
}

record* allocateRecordArray(int size) {
    record* array = (record*)malloc(size * sizeof(record));
    if (!array) {
        perror("Failed to allocate memory for record array");
    }
    return array;
}

void initializeRecords(record* records, int size, FILE* prng) {
    for (int i = 0; i < size; ++i) {
        records[i].value = rand_r((unsigned int*)&prng);
    }
}

FILE* selectPRNG() {
    // Placeholder for PRNG selection logic
    return fopen("/dev/urandom", "r");
}

void deleteFileIfExists(const char* filename) {
    if (access(filename, F_OK) == 0) {
        remove(filename);
    }
}

int executeCommandWithDynamicRecords(int argc, char* argv[], const char* output_file, int timeout) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <command>\n", argv[0]);
        return -1;
    }

    FILE* prng = selectPRNG();
    if (!prng) {
        perror("Failed to open PRNG file");
        return -1;
    }

    int records_size = argc - 2; // Assuming first argument is the command, second is output file
    long* offsets = allocateLongArray(records_size);
    int* keys = allocateIntArray(records_size);
    record* records = allocateRecordArray(records_size);

    if (!offsets || !keys || !records) {
        fclose(prng);
        return -1;
    }

    initializeRecords(records, records_size, prng);

    deleteFileIfExists(output_file);

    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        int output_fd = open(output_file, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        dup2(output_fd, STDOUT_FILENO);
        dup2(output_fd, STDERR_FILENO);
        close(output_fd);

        execvp(argv[1], &argv[1]);
        perror("Failed to execute command");
        exit(EXIT_FAILURE);
    } else if (pid > 0) {
        // Parent process
        int status;
        waitpid(pid, &status, WNOHANG | WUNTRACED);

        FILE* output_stream = fopen(output_file, "r");
        if (!output_stream) {
            perror("Failed to open output file");
            return -1;
        }

        char buffer[1024];
        while (fgets(buffer, sizeof(buffer), output_stream)) {
            printf("%s", buffer);
        }
        fclose(output_stream);

        if (WIFSTOPPED(status) || WIFSIGNALED(status)) {
            kill(pid, SIGKILL);
            waitpid(pid, &status, 0);
        }

        fclose(prng);
        free(offsets);
        free(keys);
        free(records);
        return WEXITSTATUS(status);
    } else {
        // Fork failed
        perror("Failed to fork process");
        return -1;
    }
}
