        seed = time(NULL);
    }
    srand(seed);

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long base_timestamp = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

    for (size_t i = 0; i < count; ++i) {
        (*timestamps)[i] = base_timestamp + rand();
        (*records)[i].value = rand();
    }

    return 0;
}
