#include <stdlib.h>
#include <stdio.h>
#include <string.h>

#define MAX_RECORDS 1000

typedef struct {
    long timestamp;
    int value;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record* records;
    int size;
    int capacity;
} Collection;

int customPRNG(long seed, int max) {
    return (seed * 1103515245 + 12345) % max;
}

int initializeCollection(Collection* collection, long seed, int maxRecords, void (*onOverflow)(void)) {
    if (collection->size >= collection->capacity) {
        onOverflow();
        return -1; // Overflow error
    }

    long offset = customPRNG(seed + collection->size * 314159, collection->capacity);
    int key = customPRNG(seed + collection->size * 271828, INT_MAX);

    Record record;
    record.timestamp = offset;
    record.value = customPRNG(seed + collection->size * 602189, maxRecords);

    collection->offsets[collection->size] = offset;
    collection->keys[collection->size] = key;
    collection->records[collection->size++] = record;

    return 0; // Success
}

int compareRecords(const void* a, const void* b) {
    Record r1 = *(Record*)a;
    Record r2 = *(Record*)b;

    if (r1.value != r2.value)
        return r1.value - r2.value;
    else
        return r2.timestamp - r1.timestamp; // Descending order by timestamp
}

void sortCollection(Collection* collection) {
    qsort(collection->records, collection->size, sizeof(Record), compareRecords);
}

int main() {
    Collection myCollection = {NULL, NULL, NULL, 0, MAX_RECORDS};

    if (!(myCollection.offsets = (long*)malloc(MAX_RECORDS * sizeof(long))) ||
        !(myCollection.keys = (int*)malloc(MAX_RECORDS * sizeof(int))) ||
        !(myCollection.records = (Record*)malloc(MAX_RECORDS * sizeof(Record)))) {
        printf("Memory allocation failed\n");
        return 1;
    }

    myCollection.capacity = MAX_RECORDS;

    void onOverflow(void) {
        // Handle overflow, e.g., free some records or increase capacity
        printf("Handling overflow...\n");
    }

    for (int i = 0; i < 2000; ++i) {
        if (initializeCollection(&myCollection, i, MAX_RECORDS, onOverflow)) {
            break;
        }
    }

    sortCollection(&myCollection);

    // Print sorted records
    for (int i = 0; i < myCollection.size; ++i) {
        printf("Timestamp: %ld, Value: %d\n", myCollection.records[i].timestamp, myCollection.records[i].value);
    }

    free(myCollection.offsets);
    free(myCollection.keys);
    free(myCollection.records);

    return 0;
}
```

