typedef struct Node {
    int key;
    long offset;
    struct Node* next;
} Node;

typedef struct PriorityQueue {
    Node* front;
} PriorityQueue;

Node* createNode(int key, long offset) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    newNode->key = key;
    newNode->offset = offset;
    newNode->next = NULL;
    return newNode;
}

PriorityQueue* createPriorityQueue() {
    PriorityQueue* pq = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    if (pq == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    pq->front = NULL;
    return pq;
}

void enqueue(PriorityQueue* pq, int key, long offset) {
    Node* newNode = createNode(key, offset);
    if (pq->front == NULL || pq->front->key > key) {
        newNode->next = pq->front;
        pq->front = newNode;
    } else {
        Node* current = pq->front;
        while (current->next != NULL && current->next->key <= key) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
}

Node* dequeue(PriorityQueue* pq) {
    if (pq->front == NULL) {
        // Handle empty queue
        return NULL;
    }
    Node* temp = pq->front;
    pq->front = pq->front->next;
    return temp;
}

typedef struct Record {
    int value;
    Node* nodePtr;
} Record;

Record** initializeRecords(int numRecords, long offsetRange) {
    srand(time(NULL) * getpid() * getuid());
    Record** records = (Record**)malloc(numRecords * sizeof(Record*));
    if (records == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < numRecords; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (records[i] == NULL) {
            // Handle memory allocation failure
            exit(EXIT_FAILURE);
        }
        records[i]->value = rand() % offsetRange + 1;
        enqueue(pq, records[i]->value, i); // Assuming pq is a global PriorityQueue pointer
        records[i]->nodePtr = dequeue(pq);
    }
    return records;
}

void freeRecords(Record** records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        free(records[i]);
    }
    free(records);
}
