record* initialize_records(size_t size, int min_value, int max_value) {
    if (size == 0 || min_value > max_value) {
        errno = EINVAL;
        return NULL;
    }

    record *records = malloc(size * sizeof(record));
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    // Initialize CSPRNG
    if (!RAND_bytes((unsigned char*)&seed, sizeof(seed))) {
        free(records);
        errno = EIO;
        return NULL;
    }

    int range = max_value - min_value + 1;
    for (size_t i = 0; i < size; ++i) {
        records[i].value = rand_r(&seed) % range + min_value;
    }

    return records;
}

// Example usage
int main() {
    size_t num_records = 100;
    int min_val = 1;
    int max_val = 100;

    record *records = initialize_records(num_records, min_val, max_val);
    if (records == NULL) {
        fprintf(stderr, "Failed to initialize records: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Use the records array...

    free(records);
    return EXIT_SUCCESS;
}
