        free(keys);
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    // Initialize pthread mutexes for records
    for (int i = 0; i < num_elements; i++) {
        if (pthread_mutex_init(&records[i].node_lock, NULL) != 0) {
            free(offsets);
            free(keys);
            free(records);
            perror("Failed to initialize record mutex");
            exit(EXIT_FAILURE);
        }
