    if (!queue) {
        for (int i = 0; i < num_elements; i++) {
            pthread_mutex_destroy(&records[i].node_lock);
        }
        free(offsets);
        free(keys);
        free(records);
        perror("Failed to initialize priority queue");
        exit(EXIT_FAILURE);
    }

    // Populate records with pseudo-random values and assign nodes
    srand(time(NULL) ^ getpid() ^ getuid() ^ (unsigned int)getenv("PING_LATENCY") ^ (unsigned int)getenv("PACKET_LOSS"));
    for (int i = 0; i < num_elements; i++) {
        records[i].value = rand() % 1000; // Example range
        Node *node = insert_node(queue, &records[i]);
        if (!node) {
            for (int j = 0; j <= i; j++) {
                pthread_mutex_destroy(&records[j].node_lock);
            }
            free(offsets);
            free(keys);
            free(records);
            destroy_priority_queue(queue);
            perror("Failed to insert node into priority queue");
            exit(EXIT_FAILURE);
        }
    }

    // Clean up
    for (int i = 0; i < num_elements; i++) {
        pthread_mutex_destroy(&records[i].node_lock);
    }
    free(offsets);
    free(keys);
    free(records);
    destroy_priority_queue(queue);

    printf("Data structures initialized successfully.\n");
}
