long linear_congruential_generator(long seed, long modulus, long multiplier) {
    return (seed * multiplier + 1) % modulus;
}

int initialize_data(long* offsets, int* keys, record** records, size_t size, long seed, long key_range, long record_range) {
    if (size > MAX_SIZE) {
        return -1; // Size exceeds maximum allowed
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    offsets = malloc(size * sizeof(long));
    keys = malloc(size * sizeof(int));
    records = malloc(size * sizeof(record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return -2; // Memory allocation failed
    }

    for (size_t i = 0; i < size; i++) {
        offsets[i] = linear_congruential_generator(seed + i, MAX_SIZE, 134775813L);
        keys[i] = linear_congruential_generator(offsets[i], key_range, 1664525L);
        records[i].value = linear_congruential_generator(keys[i], record_range, 48271L);
    }

    pthread_mutex_unlock(&lock);
    return 0; // Success
}
