        .map(|_| Record { value: rng.gen_range(0, 100) })
        .collect::<Vec<Record>>();

    let client = if useSecureHttp {
        reqwest::Client::new()
    } else {
        reqwest::blocking::Client::builder().danger_accept_invalid_certs(true).build()?
    };

    let mut input_values: Vec<i32> = Vec::new();
    let stdin = std::io::stdin();
    let reader = BufReader::new(stdin.lock());
    for line in reader.lines() {
        let value: i32 = line?.parse()?;
        input_values.push(value);
    }

    compute_and_print_average(&input_values)?;

    let address: SocketAddr = url.to_socket_addrs()?.next().unwrap();
    let mut stream = TcpStream::connect_with_retry(address, maxRetryAttempts)?;

    // Concurrent data streaming logic here

    Ok(())
}

fn compute_and_print_average(values: &[i32]) -> Result<(), Box<dyn Error>> {
    if values.is_empty() {
        return Err("No values provided for averaging".into());
    }
    let sum = values.iter().sum::<i32>();
    let count = values.len();
    let average = sum as f64 / count as f64;
    println!("Average: {}", average);
    Ok(())
}

trait TcpStreamExt {
    fn connect_with_retry(address: SocketAddr, max_attempts: u32) -> Result<Self, Box<dyn Error>>
    where
        Self: std::marker::Sized,
    {
        for attempt in 0..max_attempts {
            match TcpStream::connect(&address) {
                Ok(stream) => return Ok(stream),
                Err(_) if attempt == max_attempts - 1 => return Err("Failed to connect after retries".into()),
                Err(_) => continue,
            }
        }
        unreachable!();
    }
}
