#define ARRAY_SIZE 1024

Record* integerArray = NULL;
time_t* timestampArray = NULL;
Record* dataRecords = NULL;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initializeArrays() {
    integerArray = (int*)malloc(ARRAY_SIZE * sizeof(int));
    timestampArray = (time_t*)malloc(ARRAY_SIZE * sizeof(time_t));
    dataRecords = (Record*)malloc(ARRAY_SIZE * sizeof(Record));

    if (!integerArray || !timestampArray || !dataRecords) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void* updateRecords(void* arg) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < ARRAY_SIZE; i++) {
        integerArray[i] = rand();
        timestampArray[i] = time(NULL);
        dataRecords[i].value = integerArray[i];
        dataRecords[i].timestamp = timestampArray[i];

        // Update each integer value by adding the corresponding timestamp in milliseconds
        dataRecords[i].value += (int)(dataRecords[i].timestamp * 1000);
    }

    pthread_mutex_unlock(&lock);

    return NULL;
}

void cleanupArrays() {
    free(integerArray);
    free(timestampArray);
    free(dataRecords);
}

int main() {
    srand(time(NULL)); // Seed the PRNG

    initializeArrays();

    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        if (pthread_create(&threads[i], NULL, updateRecords, NULL) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    cleanupArrays();

    return EXIT_SUCCESS;
}
