#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    short value;
    int index;
    char buffer[128];
} Record;

Record* initialize_records(int size) {
    Record* records = (Record*)malloc(size * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }
    return records;
}

void seed_prng() {
    // Seed the PRNG with a time-based value
    srand(time(NULL));
}

short generate_random_value(int criticality) {
    if (criticality > 0.5) {
        return rand(); // Non-cryptographic PRNG for speed
    } else {
        // Use a cryptographic PRNG for higher statistical quality
        unsigned long seed = time(NULL);
        __sync_synchronize();
        return arc4random_uniform(1024); // Example using arc4random from libbsd
    }
}

void reseed_prng_periodically(int interval_seconds) {
    while (1) {
        seed_prng();
        sleep(interval_seconds);
    }
}

int hash_buffer(const char* buffer, int size) {
    unsigned long hash = 5381;
    for (int i = 0; i < size && buffer[i]; i++) {
        hash = ((hash << 5) + hash) + buffer[i];
    }
    return (int)(hash % 256); // Example simple hash function
}

void compute_values(int* output, int N, int* keys, Record* records) {
    for (int i = 0; i < N; i++) {
        int index = keys[i];
        char* buffer = records[index].buffer;
        int hash_value = hash_buffer(buffer, strlen(buffer));
        output[i] = index + hash_value;
    }
}

void free_records(Record* records, int size) {
    for (int i = 0; i < size; i++) {
        // Free any dynamically allocated memory within each record
        // Example: if there are pointers to dynamically allocated memory in Record
        // free(records[i].dynamic_memory);
    }
    free(records);
}

int main() {
    int N = 1000;
    int* keys = (int*)malloc(N * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        exit(EXIT_FAILURE);
    }

    Record* records = initialize_records(N);

    // Initialize keys and records
    seed_prng();
    for (int i = 0; i < N; i++) {
        keys[i] = rand() % N;
        strcpy(records[keys[i]].buffer, "example");
        records[keys[i]].value = generate_random_value(0.7); // Criticality example
        records[keys[i]].index = keys[i];
    }

    int* output = (int*)malloc(N * sizeof(int));
    if (!output) {
        perror("Failed to allocate memory for output");
        exit(EXIT_FAILURE);
    }

    compute_values(output, N, keys, records);

    // Free allocated memory
    free_records(records, N);
    free(keys);
    free(output);

    return 0;
}
