    let mut rng = StdRng::seed_from_u64(seed as u64);

    // Validate input parameters
    if recordCount == 0 || maxRetryAttempts == 0 || maxConnectionPoolSize == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "Input parameters cannot be zero",
        ));
    }

    // Initialize vector to hold records with random values
    let mut records = Vec::with_capacity(recordCount as usize);
    for _ in 0..recordCount {
        records.push(Record { value: rng.gen_range(-100..=100) });
    }

