typedef struct LogEntry {
    int identifier;
    time_t timestamp;
    char status[10];
} LogEntry;

int generateLogEntries(int minIdentifier, int maxIdentifier, int minTimestamp, int maxTimestamp, LogEntry** logArray, int* count) {
    if (minIdentifier < MIN_IDENTIFIER || maxIdentifier > MAX_IDENTIFIER ||
        minTimestamp < MIN_TIMESTAMP || maxTimestamp > MAX_TIMESTAMP) {
        return -1; // Invalid input parameters
    }

    *count = maxIdentifier - minIdentifier + 1;
    *logArray = (LogEntry*)malloc((*count) * sizeof(LogEntry));

    if (*logArray == NULL) {
        return -2; // Memory allocation failed
    }

    srand(time(0)); // Seed PRNG
    for (int i = 0; i < *count; i++) {
        (*logArray)[i].identifier = rand() % (maxIdentifier - minIdentifier + 1) + minIdentifier;
        (*logArray)[i].timestamp = (time_t)(rand() % (maxTimestamp - minTimestamp + 1) + minTimestamp);
        sprintf((*logArray)[i].status, "Status_%d", i);
    }

    return 0; // Success
}

void freeLogEntries(LogEntry* logArray, int count) {
    if (logArray != NULL) {
        free(logArray);
    }
}
