int initialize_records(record** records, int count) {
    *records = malloc(count * sizeof(record));
    if (*records == NULL) {
        return -1; // Memory allocation failure
    }
    for (int i = 0; i < count; ++i) {
        (*records)[i].key = rand() % 100 + 1;
        (*records)[i].value = ((float)rand() / RAND_MAX) * 100.0f;
        (*records)[i].label = malloc(20 * sizeof(char));
        if ((*records)[i].label == NULL) {
            // Free previously allocated records
            for (int j = 0; j < i; ++j) {
                free((*records)[j].label);
            }
            free(*records);
            return -1; // Memory allocation failure
        }
        sprintf((*records)[i].label, "Label%d", i + 1);
    }
    return 0;
}

void print_largest_smallest_and_longest(record* records, int count) {
    if (count <= 0) {
        printf("No records to process.\n");
        return;
    }

    int max_key = records[0].key;
    float min_value = records[0].value;
    size_t longest_len = strlen(records[0].label);
    char* longest_label = records[0].label;

    for (int i = 1; i < count; ++i) {
        if (records[i].key > max_key) {
            max_key = records[i].key;
        }
        if (records[i].value < min_value) {
            min_value = records[i].value;
        }
        size_t current_len = strlen(records[i].label);
        if (current_len > longest_len) {
            longest_label = records[i].label;
            longest_len = current_len;
        }
    }

    printf("Largest Key: %d\n", max_key);
    printf("Smallest Value: %.2f\n", min_value);
    printf("Longest Label: %s\n", longest_label);
}

