#include <iostream>
#include <thread>
#include <mutex>
#include <vector>
#include <atomic>
#include <chrono>
#include <cstring>

// Define a simple thread-safe linear congruential generator (LCG)
class ThreadSafeLCG {
public:
    ThreadSafeLCG() : seed(0), multiplier(1664525), increment(1013904223) {}

    uint64_t generate() {
        std::lock_guard<std::mutex> lock(mutex);
        seed = (seed * multiplier + increment) % UINT64_MAX;
        return seed;
    }

private:
    uint64_t seed;
    uint64_t multiplier;
    uint64_t increment;
    mutable std::mutex mutex;
};

// Define the transaction and pipeline structures
struct Transaction {
    uint64_t id;
    double value;
    char metadata[256];
    std::chrono::time_point<std::chrono::system_clock> timestamp;
    int statusFlag;
};

struct Pipeline {
    std::vector<Transaction*> transactions;
    ThreadSafeLCG lcg;
};

// Function to process data pipeline
void processDataPipeline(Pipeline& pipeline, size_t numTransactions) {
    try {
        // Allocate memory for transactions
        pipeline.transactions.reserve(numTransactions);

        // Initialize LCG per thread
        ThreadSafeLCG localLCG = pipeline.lcg;

        // Generate and store transactions
        for (size_t i = 0; i < numTransactions; ++i) {
            Transaction* newTransaction = new Transaction();
            if (!newTransaction) {
                throw std::bad_alloc();
            }

            newTransaction->id = localLCG.generate();
            newTransaction->value = static_cast<double>(localLCG.generate()) / UINT64_MAX;
            memset(newTransaction->metadata, 0, sizeof(newTransaction->metadata));
            newTransaction->timestamp = std::chrono::system_clock::now();
            newTransaction->statusFlag = (i % 2 == 0) ? 1 : -1;

            pipeline.transactions.push_back(newTransaction);
        }

        // Process transactions
        for (Transaction* transaction : pipeline.transactions) {
            // Simulate processing time
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
            transaction->statusFlag = (transaction->statusFlag == 1) ? -1 : 1;
        }
    } catch (const std::bad_alloc& e) {
        std::cerr << "Memory allocation failed: " << e.what() << std::endl;
        // Free allocated resources
        for (Transaction* transaction : pipeline.transactions) {
            delete transaction;
        }
        throw;
    }
}

// Function to simulate external data source delays or failures
void simulateExternalDataSource(std::function<void()> task, double failureRate) {
    if (static_cast<double>(rand()) / RAND_MAX < failureRate) {
