        for i in 0..recordCount {
            writer.write_all(format!("{}", records[i].value).as_bytes()).unwrap();
        }
    });

    // Implement retry logic for network operations
    let mut retries = 3;
    while reader_thread.join().is_err() && retries > 0 {
        reader_thread = thread::spawn(move || {
            for line in BufReader::new(reader).lines() {
                println!("Received: {}", line.unwrap());
            }
        });
        retries -= 1;
    }

    // Include logging for debugging and monitoring purposes
    log::info!("Process completed successfully");

    Ok(())
}
