    // Read integers from standard input until EOF
    let mut input_data: Vec<i32> = Vec::new();
    io::stdin().lines()
        .map_while(|line| line.ok())
        .filter_map(|line| line.parse::<i32>().ok())
        .for_each(|value| input_data.push(value));

