    // Read integers from standard input
    let mut input = String::new();
    stdin().read_to_string(&mut input).expect("Failed to read from stdin");

    // Process the input and find average value
    process_input_and_find_average(&input, maxInt);

    Ok(request)
}

fn process_input_and_find_average(input: &str, maxInt: i32) {
