use std::error::Error;
use std::net::{TcpStream};
use std::io::{self, Write, Read};
use rand::{SeedableRng, XorShiftRng};

#[derive(Debug)]
struct Packet {
    payload_size: u16,
}

fn simulateNetworkTraffic(seed: i64, packetCount: u32, targetAddress: &str, port: u32, batchSize: u32) -> Result<(), Box<dyn Error>> {
    let mut packets = Vec::with_capacity(packetCount as usize);

    // Initialize PRNG with seed
    let mut rng = XorShiftRng::seed_from_u64(seed as u64);

    // Populate vector with random packet sizes
    for _ in 0..packetCount {
        packets.push(Packet { payload_size: rng.gen_range(100, 1500) });
    }

    // Establish TCP client connection
    let mut stream = TcpStream::connect((targetAddress, port))?;

    // Send packets in batches
    for packet_batch in packets.chunks(batchSize as usize) {
        for packet in packet_batch {
            let payload = (packet.payload_size).to_be_bytes();
            let timestamp = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH)?.as_secs();
            let checksum = calculate_checksum(&payload, timestamp);

            // Write payload size, timestamp, and checksum to stream
            stream.write_all(&[packet.payload_size as u8, packet.payload_size as u8])?;
            stream.write_all(&timestamp.to_be_bytes())?;
            stream.write_all(&checksum.to_be_bytes())?;
        }
    }

    let mut input_buffer = Vec::new();
    // Read integers from standard input until EOF
    io::stdin().read_to_end(&mut input_buffer)?;

    // Calculate and print throughput
    calculate_throughput(packets, input_buffer);

    Ok(())
}

fn calculate_checksum(payload: &[u8], timestamp: u64) -> [u8; 2] {
    let mut sum = payload.iter().sum::<u16>() + (timestamp as u16);
    if sum >= 0xFFFF {
        sum -= 0xFFFF;
    }
    [(sum & 0xFF) as u8, ((sum >> 8) & 0xFF) as u8]
}

fn calculate_throughput(packets: Vec<Packet>, input_buffer: Vec<u8>) {
    let total_payload_size = packets.iter().map(|p| p.payload_size).sum::<u16>() * 2;
    let total_time = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_secs();

    let throughput = (total_payload_size as f64) / total_time as f64;
    println!("Total Throughput: {} bytes/second", throughput);
}
```
