    return (int*)malloc(size * sizeof(int));
}

Record* allocate_record_array(size_t size, int min_value, int max_value) {
    Record* records = (Record*)malloc(size * sizeof(Record));
    if (!records) {
        return NULL;
    }

    srand(time(NULL)); // Initialize PRNG with a seed based on the current time

    for (size_t i = 0; i < size; ++i) {
