        errno = EINVAL; // Invalid argument
        return -1;
    }

    long* offsets = allocate_offset_array(num_records);
    if (!offsets) {
        goto cleanup_keys;
    }

    int* keys = allocate_key_array(num_records);
    if (!keys) {
        goto cleanup_offsets;
    }

    Record* records = allocate_record_array(num_records, min_value, max_value);
    if (!records) {
        goto cleanup_keys;
    }

    // Use the allocated arrays here

cleanup_records:
    free(records);

cleanup_keys:
    free(keys);

cleanup_offsets:
