void manageDynamicMemoryAndProcessRecords(long* offsets, int* keys, record** records, int maxRecords, int inputLimit, unsigned long prngSeed) {
    // Initialize PRNG
    srand(prngSeed);

    // Allocate memory for arrays
    offsets = (long*)malloc(maxRecords * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return;
    }

    keys = (int*)malloc(maxRecords * sizeof(int));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Memory allocation failed for keys\n");
        return;
    }

    records = (record**)malloc(maxRecords * sizeof(record*));
    if (!records) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Memory allocation failed for records\n");
        return;
    }

    // Initialize records with random values
    for (int i = 0; i < maxRecords; i++) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            free(offsets);
            free(keys);
            for (int j = 0; j < i; j++) {
                free(records[j]);
            }
            fprintf(stderr, "Memory allocation failed for record %d\n", i);
            return;
        }
        records[i]->value = rand() % inputLimit;
    }

    // Process records
    for (int i = 0; i < maxRecords; i++) {
        // Example processing: print the value
        printf("Record %d value: %d\n", i, records[i]->value);
    }

    // Clean up memory
    for (int i = 0; i < maxRecords; i++) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
