typedef struct {
    uint32_t key;
    char* string;
    uint64_t offset;
} Record;

typedef struct {
    Record* records;
    size_t count;
    size_t capacity;
    uint64_t maxOffset;
} RecordCollection;

void initPRNG() {
    srand(time(NULL));
}

uint32_t generateKey(uint32_t min, uint32_t max) {
    return (rand() % (max - min + 1)) + min;
}

char* generateString(size_t length, const char* charset, size_t charsetLen) {
    char* str = malloc((length + 1) * sizeof(char));
    if (!str) {
        fprintf(stderr, "Memory allocation failed for string generation\n");
        exit(1);
    }
    for (size_t i = 0; i < length; ++i) {
        str[i] = charset[rand() % charsetLen];
    }
    str[length] = '\0';
    return str;
}

void initRecord(Record* record, uint32_t minKey, uint32_t maxKey, size_t minLength, size_t maxLength, const char* charset, size_t charsetLen) {
    record->key = generateKey(minKey, maxKey);
    record->string = generateString(rand() % (maxLength - minLength + 1) + minLength, charset, charsetLen);
    record->offset = rand();
    if (record->offset > recordCollection.maxOffset) {
        recordCollection.maxOffset = record->offset;
    }
}

int addRecord(RecordCollection* collection) {
    if (collection->count >= collection->capacity) {
        size_t newCapacity = collection->capacity ? collection->capacity * 2 : 10;
        Record* newRecords = realloc(collection->records, newCapacity * sizeof(Record));
        if (!newRecords) {
            fprintf(stderr, "Memory allocation failed for record collection\n");
            return -1;
        }
        collection->records = newRecords;
        collection->capacity = newCapacity;
    }
    initRecord(&collection->records[collection->count], 0, UINT32_MAX, 1, 32, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789", 62);
    ++collection->count;
    return 0;
}

