        return -2; // Memory allocation failed
    }

    *records = (Record*)malloc(num_records * sizeof(Record));
    if (!*records) {
        free(offsets);
        free(keys);
        return -2; // Memory allocation failed
    }

    srand(time(NULL));

    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = rand();
    }
    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = rand() % 1000; // Example key generation
    }

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].value = rand() % (upper_bound - lower_bound + 1) + lower_bound;
    }

    return 0; // Success
}

void destroy_records(long* offsets, int* keys, Record** records, size_t num_offsets, size_t num_keys, size_t num_records) {
