#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_STRING_LENGTH 32

typedef struct {
    uint32_t key;
    char *value;
    uint64_t offset;
} Record;

typedef struct {
    Record *records;
    size_t count;
    size_t capacity;
    uint64_t max_offset;
} RecordCollection;

// Function to initialize the record collection
void init_record_collection(RecordCollection *collection, size_t initial_capacity) {
    collection->records = (Record *)malloc(initial_capacity * sizeof(Record));
    if (!collection->records) {
        // Handle memory allocation error
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    collection->count = 0;
    collection->capacity = initial_capacity;
    collection->max_offset = 0;
}

// Function to generate a random alphanumeric string
void generate_random_string(char *str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (size_t i = 0; i < length - 1; ++i) {
        str[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    str[length - 1] = '\0';
}

// Function to add a record to the collection
void add_record(RecordCollection *collection, uint32_t key, uint64_t offset) {
    if (collection->count >= collection->capacity) {
        // Resize the records array
        collection->capacity *= 2;
        collection->records = (Record *)realloc(collection->records, collection->capacity * sizeof(Record));
        if (!collection->records) {
            // Handle memory reallocation error
            fprintf(stderr, "Memory reallocation failed.\n");
            exit(EXIT_FAILURE);
        }
    }

    Record new_record;
    new_record.key = key;
    new_record.value = (char *)malloc(MAX_STRING_LENGTH + 1);
    if (!new_record.value) {
        // Handle memory allocation error
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    generate_random_string(new_record.value, MAX_STRING_LENGTH);
    new_record.offset = offset;

    collection->records[collection->count++] = new_record;
    if (offset > collection->max_offset) {
        collection->max_offset = offset;
    }
}

// Function to free the record collection
void free_record_collection(RecordCollection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i].value);
    }
    free(collection->records);
    collection->records = NULL;
    collection->count = 0;
    collection->capacity = 0;
}

int main() {
    srand(time(NULL)); // Seed the PRNG

    RecordCollection collection;
    init_record_collection(&collection, 10);

    for (size_t i = 0; i < 20; ++i) {
        add_record(&collection, i, i * 100);
    }

    free_record_collection(&collection);

    return 0;
}
```

