import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.LinkedBlockingQueue;

public class TokenManager {
    private static final SecureRandom secureRandom = new SecureRandom();
    private final ConcurrentHashMap<String, String> tokenMap = new ConcurrentHashMap<>();
    private final LinkedBlockingQueue<LoginRequest> requestQueue = new LinkedBlockingQueue<>();

    public void startProcessing() {
        Thread processorThread = new Thread(() -> {
            while (true) {
                try {
                    LoginRequest request = requestQueue.take();
                    generateUniqueToken(request);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });
        processorThread.setDaemon(true);
        processorThread.start();
    }

    public void submitLoginRequest(String userId, String clientIp) {
        try {
            requestQueue.put(new LoginRequest(userId, clientIp));
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            // Handle the error appropriately
        }
    }

    private void generateUniqueToken(LoginRequest request) {
        while (true) {
            String token = generateRandomToken(32);
            if (!tokenMap.containsKey(token)) {
                tokenMap.put(request.userId, token);
                // Log token generation time and details at logLevel
                System.out.println("Generated token: " + token + " for user: " + request.userId);
                break;
            }
        }
    }

    private String generateRandomToken(int length) {
        byte[] bytes = new byte[length];
        secureRandom.nextBytes(bytes);
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    static class LoginRequest {
        final String userId;
        final String clientIp;

        LoginRequest(String userId, String clientIp) {
            this.userId = userId;
            this.clientIp = clientIp;
        }
    }

    public static void main(String[] args) {
        TokenManager tokenManager = new TokenManager();
        tokenManager.startProcessing();

        // Simulate login requests
        for (int i = 0; i < 10; i++) {
            tokenManager.submitLoginRequest("user" + i, "192.168.1." + i);
        }
    }
}

