import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class InventoryManager {
    private static final Logger LOGGER = Logger.getLogger(InventoryManager.class.getName());
    private final List<Item> items = new CopyOnWriteArrayList<>();
    private final Random random;
    private final int idLowerBound, idUpperBound, valueLowerBound, valueUpperBound;
    private final long lastAccessThreshold;
    private final ScheduledExecutorService cleaner;

    public InventoryManager(long seed, int idLowerBound, int idUpperBound, double valueLowerBound, double valueUpperBound, long lastAccessThreshold) {
        this.random = new Random(seed);
        this.idLowerBound = idLowerBound;
        this.idUpperBound = idUpperBound;
        this.valueLowerBound = (int)(valueLowerBound * 100.0); // Convert to cents for integer representation
        this.valueUpperBound = (int)(valueUpperBound * 100.0);
        this.lastAccessThreshold = lastAccessThreshold;

        LOGGER.info("Initializing InventoryManager with seed: " + seed);

        cleaner = Executors.newScheduledThreadPool(1);
        cleaner.scheduleAtFixedRate(this::cleanUp, 1, 1, TimeUnit.HOURS);
    }

    public void addItem(int batchMaxSize) {
        for (int i = 0; i < batchMaxSize && items.size() < 1000000; i++) { // Assuming a limit of 1 million items
            int id = random.nextInt(idUpperBound - idLowerBound + 1) + idLowerBound;
            double value = (random.nextDouble() * (valueUpperBound - valueLowerBound)) + valueLowerBound;
            String description = "Item" + id;

            Item newItem = new Item(id, value, description);
            items.add(newItem);

            LOGGER.info("Added item: " + newItem);
        }
    }

    private void cleanUp() {
        long currentTime = System.currentTimeMillis();
        List<Item> toRemove = new ArrayList<>();

        for (Item item : items) {
            if (currentTime - item.getLastAccessTime() > lastAccessThreshold) {
                toRemove.add(item);
                LOGGER.info("Removed inactive item: " + item);
            }
        }

        items.removeAll(toRemove);
    }

    public void updateItem(Item updatedItem) {
        int index = Collections.binarySearch(items, updatedItem, (i1, i2) -> Integer.compare(i1.getId(), i2.getId()));
        if (index >= 0) {
            items.set(index, updatedItem);
            LOGGER.info("Updated item: " + updatedItem);
        }
    }

    public void stop() {
        cleaner.shutdown();
        try {
            if (!cleaner.awaitTermination(60, TimeUnit.SECONDS)) {
                cleaner.shutdownNow();
            }
        } catch (InterruptedException e) {
            cleaner.shutdownNow();
        }
    }

    static class Item implements Comparable<Item> {
        private final int id;
        private double value;
        private String description;
        private long lastAccessTime;

        public Item(int id, double value, String description) {
            this.id = id;
            this.value = value;
            this.description = description;
            this.lastAccessTime = System.currentTimeMillis();
        }

        // Getters and setters

        @Override
        public int compareTo(Item other) {
            return Integer.compare(this.id, other.id);
        }
    }
}
