    idArray->count = transactionLimit;
    idArray->transactionIDs = malloc(transactionLimit * sizeof(int));
    if (!idArray->transactionIDs) {
        fprintf(logFile, "Error: Memory allocation failed.\n");
        return -1;
    }

    srand(time(NULL)); // Seed the PRNG

    for (size_t i = 0; i < transactionLimit; ++i) {
