int efficientDataInitialization(int dataSize, int minValue, int maxValue, const char* inputFile, const char* outputFile, int transactionCount) {
    srand(time(NULL));
    FILE* input = fopen(inputFile, "r");
    if (!input) return -1;

    TransactionPool pool;
    pthread_mutex_init(&pool.lock, NULL);
    pool.count = 0;

    // Allocate memory for transactions
    for (int i = 0; i < transactionCount; ++i) {
        pool.transactions[i] = (Transaction*)malloc(sizeof(Transaction));
        if (!pool.transactions[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            goto cleanup;
        }
    }

    // Populate transactions with random values
    for (int i = 0; i < transactionCount; ++i) {
        pool.transactions[i]->id = rand() % (maxValue - minValue + 1) + minValue;
        if (pool.count > 0) {
            int id;
            do {
                id = rand() % (maxValue - minValue + 1) + minValue;
            } while (findTransactionById(&pool, id) != NULL);
            pool.transactions[i]->id = id;
        }
    }

    // Sort combined dataset
    qsort(pool.transactions, transactionCount, sizeof(Transaction), compareTransactions);

    // Save to output file
    FILE* output = fopen(outputFile, "w");
    if (!output) return -1;

    for (int i = 0; i < transactionCount; ++i) {
        fprintf(output, "%d %s\n", pool.transactions[i]->id, pool.transactions[i]->data);
    }

    fclose(output);

cleanup:
    pthread_mutex_destroy(&pool.lock);
    for (int i = 0; i < transactionCount; ++i) {
        free(pool.transactions[i]);
    }
    return pool.count;
}

Transaction* findTransactionById(TransactionPool* pool, int id) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->transactions[i]->id == id) {
            pthread_mutex_unlock(&pool->lock);
            return pool->transactions[i];
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return NULL;
}

int compareTransactions(const void* a, const void* b) {
    Transaction** ta = (Transaction**)a;
    Transaction** tb = (Transaction**)b;
    if ((*ta)->id < (*tb)->id) return -1;
    if ((*ta)->id > (*tb)->id) return 1;
    return 0;
}
