#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_TOKENS 1000
#define TOKEN_LENGTH 32

typedef struct {
    char tokens[MAX_TOKENS][TOKEN_LENGTH];
    int next_index;
} SessionManager;

SessionManager* create_session_manager() {
    SessionManager *manager = (SessionManager*)malloc(sizeof(SessionManager));
    if (manager == NULL) {
        fprintf(stderr, "Failed to allocate memory for session manager\n");
        exit(EXIT_FAILURE);
    }
    memset(manager->tokens, 0, sizeof(manager->tokens));
    manager->next_index = 0;
    return manager;
}

void destroy_session_manager(SessionManager *manager) {
    free(manager);
}

char* generate_token() {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *token = (char*)malloc(TOKEN_LENGTH + 1);
    if (token == NULL) {
        fprintf(stderr, "Failed to allocate memory for token\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < TOKEN_LENGTH; i++) {
        token[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    token[TOKEN_LENGTH] = '\0';
    return token;
}

void add_token(SessionManager *manager, const char *user_id) {
    if (manager->next_index >= MAX_TOKENS) {
        fprintf(stderr, "Session manager is full\n");
        return;
    }
    strcpy(manager->tokens[manager->next_index], user_id);
    manager->next_index++;
}

void remove_token(SessionManager *manager, const char *user_id) {
    for (int i = 0; i < manager->next_index; i++) {
        if (strcmp(manager->tokens[i], user_id) == 0) {
            manager->next_index--;
            strcpy(manager->tokens[i], manager->tokens[manager->next_index]);
            break;
        }
    }
}

void log_event(const char *user_id, const char *message) {
    // Log the event to an external logging service
    printf("User: %s - %s\n", user_id, message);
}

int main() {
    srand(time(NULL));

    SessionManager *manager = create_session_manager();

    add_token(manager, "user123");
    add_token(manager, "user456");

    log_event("user123", "Login successful");

    remove_token(manager, "user123");

    destroy_session_manager(manager);

    return 0;
}
