#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define TOKEN_LENGTH 32

typedef struct {
    char token[TOKEN_LENGTH];
    time_t expiration_time;
} SessionToken;

SessionToken *token_pool = NULL;
int pool_size = 0;
int current_index = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_token_pool(int size) {
    pthread_mutex_lock(&mutex);
    if (token_pool != NULL) {
        free(token_pool);
    }
    token_pool = (SessionToken *)malloc(size * sizeof(SessionToken));
    pool_size = size;
    current_index = 0;
    pthread_mutex_unlock(&mutex);
}

char *generate_unique_token() {
    pthread_mutex_lock(&mutex);
    if (current_index >= pool_size) {
        current_index = 0; // Wrap around for simplicity, adjust as needed
    }
    char *token = token_pool[current_index].token;
    time_t now = time(NULL);
    token_pool[current_index].expiration_time = now + 3600; // Example expiration time
    pthread_mutex_unlock(&mutex);
    return token;
}

void free_token(char *token) {
    for (int i = 0; i < pool_size; i++) {
        if (strcmp(token_pool[i].token, token) == 0) {
            pthread_mutex_lock(&mutex);
            token_pool[i].expiration_time = time(NULL); // Mark as expired
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
}

int validate_session_token(char *token) {
    for (int i = 0; i < pool_size; i++) {
        if (strcmp(token_pool[i].token, token) == 0 && token_pool[i].expiration_time > time(NULL)) {
            return 1; // Token is valid
        }
    }
    return 0; // Token is invalid or expired
}

void *session_cleanup_thread(void *arg) {
    while (1) {
        for (int i = 0; i < pool_size; i++) {
            if (token_pool[i].expiration_time > time(NULL)) {
                pthread_mutex_lock(&mutex);
                token_pool[i].expiration_time = time(NULL); // Mark as expired
                pthread_mutex_unlock(&mutex);
            }
        }
        sleep(60); // Cleanup interval, adjust as needed
    }
    return NULL;
}

int main() {
    initialize_token_pool(1000);

    // Example usage
    char *new_token = generate_unique_token();
    printf("New Token: %s\n", new_token);

    if (validate_session_token(new_token)) {
        printf("Session is valid.\n");
    } else {
        printf("Session is invalid or expired.\n");
    }

    free_token(new_token);

    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, session_cleanup_thread, NULL);
    pthread_join(cleanup_thread, NULL);

    return 0;
}
```

This code provides a basic implementation of a function to dynamically generate and manage unique session tokens for user login attempts. It includes mechanisms for concurrency control, token generation, validation, and expiration handling. The use of mutexes ensures safe concurrent access to the token pool. A separate thread is used for periodic cleanup of expired sessions, demonstrating how to integrate background tasks with your main application logic.

This example serves as a foundation that can be expanded and optimized further based on specific requirements, such as integrating with an external logging service, extending functionality for distributed environments, or fine-tuning performance parameters.']

