    static int initialized = 0;
    if (!initialized) {
        srand(time(NULL));
        initialized = 1;
    }
    return rand() % (max - min + 1) + min;
}

Transaction* createTransactions(int count, int seed, int *error) {
    if (count <= 0 || count > MAX_TRANSACTION_ID) {
        *error = -1; // Invalid input
        return NULL;
    }

    Transaction *transactions = malloc(count * sizeof(Transaction));
    if (!transactions) {
        *error = -2; // Memory allocation failed
        return NULL;
    }

    int ids[MAX_TRANSACTION_ID];
    for (int i = 0; i < count; ++i) {
        int id;
        do {
            id = generateRandomID(1, MAX_TRANSACTION_ID);
        } while (id >= count && !ids[id]); // Ensure uniqueness
        transactions[i].transactionID = id;
        transactions[i].amount = (double)rand() / RAND_MAX * 1000.0; // Random amount between 0 and 1000
        transactions[i].timestamp = time(NULL);
        ids[id] = 1;
    }

    return transactions;
}

int main() {
    int error;
    Transaction *transactions = createTransactions(10, 42, &error);
    if (!transactions) {
        printf("Error: %d\n", error);
        return 1;
    }

    // Process transactions

    free(transactions);
    return 0;
}
