#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long session_id;
    char* username;
    int status;
    time_t timestamp;
} Record;

typedef struct {
    Record** records;
    size_t count;
    size_t capacity;
} SessionManager;

SessionManager* init_session_manager(size_t initial_capacity) {
    SessionManager* manager = malloc(sizeof(SessionManager));
    if (manager == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    manager->records = malloc(initial_capacity * sizeof(Record*));
    if (manager->records == NULL) {
        free(manager);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    manager->count = 0;
    manager->capacity = initial_capacity;
    return manager;
}

void free_session_manager(SessionManager* manager) {
    for (size_t i = 0; i < manager->count; i++) {
        free(manager->records[i]->username);
        free(manager->records[i]);
    }
    free(manager->records);
    free(manager);
}

long generate_unique_session_id() {
    // Use a CSPRNG to generate a unique session ID
    return rand();  // Placeholder for actual CSPRNG implementation
}

Record* create_record(const char* username) {
    Record* record = malloc(sizeof(Record));
    if (record == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    record->session_id = generate_unique_session_id();
    record->username = strdup(username);
    record->status = 0;  // Assuming 0 means active session
    record->timestamp = time(NULL);
    return record;
}

int add_login_attempt(SessionManager* manager, const char* username) {
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Record** new_records = realloc(manager->records, new_capacity * sizeof(Record*));
        if (new_records == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return -1;  // Memory allocation error
        }
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    Record* record = create_record(username);
    if (record == NULL) {
        return -1;  // Memory allocation error
    }

    manager->records[manager->count++] = record;
    return 0;  // Success
}

int main() {
    srand(time(NULL));  // Seed the PRNG

    SessionManager* manager = init_session_manager(10);
    if (manager == NULL) {
        fprintf(stderr, "Failed to initialize session manager\n");
        return EXIT_FAILURE;
    }

    const char* usernames[] = {"user1", "user2", "user3"};
    size_t num_users = sizeof(usernames) / sizeof(usernames[0]);

    for (size_t i = 0; i < num_users; i++) {
        if (add_login_attempt(manager, usernames[i]) != 0) {
            fprintf(stderr, "Failed to add login attempt\n");
            free_session_manager(manager);
            return EXIT_FAILURE;
        }
    }

    // Print session records
    for (size_t i = 0; i < manager->count; i++) {
        printf("Session ID: %ld, Username: %s, Status: %d, Timestamp: %s\n",
               manager->records[i]->session_id,
               manager->records[i]->username,
               manager->records[i]->status,
               ctime(&manager->records[i]->timestamp));
    }

    free_session_manager(manager);
