session* create_sessions(int num_sessions, int seed_interval, int range_start, int range_end) {
    if (num_sessions <= 0 || seed_interval <= 0 || range_start < 0 || range_end < range_start) {
        fprintf(stderr, "Invalid input values\n");
        return NULL;
    }

    session* sessions = malloc(num_sessions * sizeof(session));
    if (!sessions) {
        perror("Failed to allocate memory");
        return NULL;
    }

    srand(time(NULL)); // Initialize random seed

    for (int i = 0; i < num_sessions; ) {
        unsigned int new_id = rand() % (range_end - range_start + 1) + range_start;

        // Check for duplicates
        int is_duplicate = 0;
        for (int j = 0; j < i; j++) {
            if (sessions[j].sessionID == new_id) {
                is_duplicate = 1;
                break;
            }
        }

        if (!is_duplicate) {
            sessions[i].sessionID = new_id;
            sessions[i].lastActiveTime = time(NULL);
            sessions[i].status = 'A';
            i++;
        } else {
            // Retry mechanism with exponential backoff
            usleep(seed_interval * 1000);
        }
    }

    return sessions;
}

void free_sessions(session* sessions, int num_sessions) {
    free(sessions);
}

int main() {
    int num_sessions = 10;
    int seed_interval = 500; // milliseconds
    int range_start = 1000;
    int range_end = 2000;

    session* sessions = create_sessions(num_sessions, seed_interval, range_start, range_end);
    if (sessions) {
        for (int i = 0; i < num_sessions; i++) {
            printf("Session %d: ID=%u, Last Active=%ld, Status=%c\n", i + 1, sessions[i].sessionID, sessions[i].lastActiveTime, sessions[i].status);
        }
        free_sessions(sessions, num_sessions);
    }

    return 0;
}
