typedef struct {
    int sessionID;
    time_t lastActiveTime;
    char status[20];
} Session;

Session* create_session_pool(int num_sessions, int id_range_start, int id_range_end) {
    if (num_sessions <= 0 || id_range_start >= id_range_end) {
        return NULL; // Invalid input
    }

    Session* sessions = malloc(num_sessions * sizeof(Session));
    if (!sessions) {
        return NULL; // Memory allocation failed
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    srand(time(NULL));

    int retries = 0;
    while (retries < num_sessions) {
        int unique_id = id_range_start + rand() % (id_range_end - id_range_start);
        int is_unique = 1;

        for (int i = 0; i < retries; i++) {
            if (sessions[i].sessionID == unique_id) {
                is_unique = 0;
                break;
            }
        }

        if (is_unique) {
            sessions[retries].sessionID = unique_id;
            sessions[retries].lastActiveTime = time(NULL);
            strcpy(sessions[retries].status, "active");
            retries++;
        } else {
            // Retry logic here
        }
    }

    pthread_mutex_destroy(&mutex);
    return sessions;
}

void destroy_session_pool(Session* sessions, int num_sessions) {
    if (sessions) {
        free(sessions);
    }
}
