    if (records == NULL) {
        perror("Failed to allocate memory for records");
        return NULL;
    }
    return records;
}

void initializeRecords(Record* records, int size, int min, int max) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % (max - min + 1) + min;
    }
}

void serializeRecords(Record* records, int size, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(records, sizeof(Record), size, file);
    fclose(file);
}

void deserializeRecords(Record** records, int* size, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        return;
    }
    *size = fread(*records, sizeof(Record), MAX_RECORDS, file);
    fclose(file);
}

int main() {
    int size = 1024;
    Record* records = allocateRecords(size);
    if (records == NULL) {
        return EXIT_FAILURE;
    }

    initializeRecords(records, size, 1, 100);

    serializeRecords(records, size, "records.dat");

    free(records);

    records = allocateRecords(MAX_RECORDS);
    if (records == NULL) {
        return EXIT_FAILURE;
    }

    deserializeRecords(&records, &size, "records.dat");

    for (int i = 0; i < size; i++) {
        printf("%d\n", records[i].value);
    }

    free(records);

    return EXIT_SUCCESS;
}
