    StorageSystem *system = (StorageSystem*)malloc(sizeof(StorageSystem));
    if (!system) return NULL;

    system->records = (Record*)calloc(CHUNK_SIZE, RECORD_SIZE);
    if (!system->records) {
        free(system);
        return NULL;
    }

    system->count = 0;
    system->capacity = CHUNK_SIZE;
    pthread_mutex_init(&system->lock, NULL);

    return system;
}

void destroy_storage_system(StorageSystem *system) {
    pthread_mutex_lock(&system->lock);
    free(system->records);
    pthread_mutex_unlock(&system->lock);
    free(system);
}

int add_record(StorageSystem *system, Record *record) {
    pthread_mutex_lock(&system->lock);
    if (system->count >= system->capacity) {
        Record *new_records = realloc(system->records, (system->capacity + CHUNK_SIZE) * RECORD_SIZE);
        if (!new_records) {
            pthread_mutex_unlock(&system->lock);
            return -1; // Allocation failure
        }
        system->records = new_records;
        system->capacity += CHUNK_SIZE;
    }

    system->records[system->count++] = *record;
    pthread_mutex_unlock(&system->lock);
    return 0; // Success
}

int load_state_from_db(StorageSystem *system, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1; // File open failure

    Record record;
    while (fread(&record, RECORD_SIZE, 1, file)) {
        add_record(system, &record);
    }

    fclose(file);
    return 0; // Success
}

int save_state_to_db(StorageSystem *system, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1; // File open failure

    for (size_t i = 0; i < system->count; ++i) {
        fwrite(&system->records[i], RECORD_SIZE, 1, file);
    }

    fclose(file);
    return 0; // Success
}

void* thread_function(void *arg) {
    StorageSystem *system = (StorageSystem*)arg;
    Record record = {0}; // Initialize your record here

    // Simulate adding a record in a thread-safe manner
    add_record(system, &record);

    return NULL;
}
```

