#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_RECORDS 1024
#define MIN_MEMORY_THRESHOLD 512 * 1024  // 512 KB

typedef struct {
    char name[32];
    long offset;
    int key;
    double value;
} record;

void initialize_arrays(long** offsets, int** keys, double** values, record** records) {
    *offsets = (long*)malloc(MAX_RECORDS * sizeof(long));
    *keys = (int*)malloc(MAX_RECORDS * sizeof(int));
    *values = (double*)malloc(MAX_RECORDS * sizeof(double));
    *records = (record*)malloc(MAX_RECORDS * sizeof(record));

    if (!*offsets || !*keys || !*values || !*records) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
}

void initialize_records(long* offsets, int* keys, double* values, record* records, size_t count) {
    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        snprintf(records[i].name, sizeof(records[i].name), "Record%zu", i);
        offsets[i] = rand() % 1000L;
        keys[i] = rand();
        values[i] = ((double)rand()) / RAND_MAX * 100.0;
    }
}

void serialize_records(record* records, size_t count, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    if (fwrite(records, sizeof(record), count, file) != count) {
        perror("Failed to write records to file");
    }

    fclose(file);
}

int deserialize_records(record* records, size_t* count, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return -1;
    }

    *count = fread(records, sizeof(record), MAX_RECORDS, file);
    fclose(file);

    return 0;
}

void free_resources(long* offsets, int* keys, double* values, record* records) {
    free(offsets);
    free(keys);
    free(values);
    free(records);
}

int main() {
    long* offsets;
    int* keys;
    double* values;
    record* records;

    initialize_arrays(&offsets, &keys, &values, &records);

    size_t count = 100;
    initialize_records(offsets, keys, values, records, count);

    serialize_records(records, count, "records.bin");

    size_t read_count;
    deserialize_records(records, &read_count, "records.bin");
    printf("Read %zu records from file\n", read_count);

    free_resources(offsets, keys, values, records);

    return 0;
}
```

