import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class SessionManager {

    private static final int MAX_SEEDS = 100; // Assuming a maximum number of seeds for demonstration
    private ConcurrentHashMap<String, Record> sessionRecords = new ConcurrentHashMap<>();
    private AtomicInteger seedIndex = new AtomicInteger(0);

    public void manageSessions(String[] sessionIdentifiers, int[] seedValues) {
        long startTime;

        // Initialize data structures
        int[] offsets = new int[MAX_SEEDS];
        int[] keys = new int[MAX_SEEDS];
        Record[] records = new Record[MAX_SEEDS];

        startTime = System.nanoTime();
        initializeDataStructures(offsets, keys, records, seedValues);
        long initTime = System.nanoTime() - startTime;
        System.out.println("Initialization time: " + initTime + " ns");

        // Populate session records
        startTime = System.nanoTime();
        for (String sessionId : sessionIdentifiers) {
            Record record = records[seedIndex.getAndIncrement() % MAX_SEEDS];
            if (!sessionRecords.putIfAbsent(sessionId, record)) {
                throw new IllegalStateException("Duplicate session ID");
            }
        }
        long populateTime = System.nanoTime() - startTime;
        System.out.println("Populate time: " + populateTime + " ns");
    }

    private void initializeDataStructures(int[] offsets, int[] keys, Record[] records, int[] seedValues) {
        java.security.SecureRandom random = new java.security.SecureRandom();

        for (int i = 0; i < MAX_SEEDS && i < seedValues.length; i++) {
            offsets[i] = seedValues[i];
            keys[i] = random.nextInt(Integer.MAX_VALUE);
            records[i] = new Record(offsets[i], keys[i]);
        }
    }

    static class Record {
        long offset;
        int key;

        public Record(long offset, int key) {
            this.offset = offset;
            this.key = key;
        }
    }
}
