    return ((float)rand() / RAND_MAX) * (max - min) + min;
}

record** allocate_records(int count) {
    record **records = malloc(sizeof(record*) * count);
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    float values[count];
    int keys[count];
    long offsets[count];

    srand(time(NULL)); // Seed the PRNG

    for (int i = 0; i < count; ++i) {
        values[i] = custom_prng(0.0f, 100.0f);
        values[i] = round(values[i] * 100) / 100; // Round to two decimal places
        keys[i] = rand() % 1000;
        offsets[i] = i;

        records[i] = malloc(sizeof(record));
        if (records[i] == NULL) {
            perror("Failed to allocate memory for record");
            exit(EXIT_FAILURE);
        }

        records[i]->value = values[i];
        records[i]->key = keys[i];
        records[i]->description = strdup("Sample Description"); // Assuming you have a way to get this
    }

    return records;
}

void free_records(record **records, int count) {
    for (int i = 0; i < count; ++i) {
        if (records[i] != NULL) {
            free(records[i]);
        }
    }
    free(records);
}

int main() {
    const int count = 1000;
    record **records = allocate_records(count);

    // Use records...

    free_records(records, count);
    return 0;
}
