#define MAX_RECORDS 1000
#define RANDOM_RANGE 1000

typedef struct {
    int value;
} record;

long* allocateOffsetArray(int size) {
    return (long*)malloc(size * sizeof(long));
}

int* allocateKeyArray(int size) {
    return (int*)malloc(size * sizeof(int));
}

record* allocateRecordArray(int size) {
    return (record*)calloc(size, sizeof(record));
}

void fillRecordsWithRandomValues(record* records, int size) {
    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        records[i].value = rand() % RANDOM_RANGE;
    }
}

void processInput(int batch_size) {
    int input[batch_size];
    while (1) {
        int count = read(STDIN_FILENO, input, sizeof(int) * batch_size);
        if (count == -1) {
            perror("Error reading from standard input");
            continue;
        }
        for (int i = 0; i < count / sizeof(int); ++i) {
            printf("Processing input: %d\n", input[i]);
        }
    }
}

void logMemoryOperations(const char* operation, size_t size) {
    FILE* log_file = fopen("memory_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s %zu bytes\n", operation, size);
        fclose(log_file);
    }
}

record findLargestRecord(record* records, int size) {
    record largest = records[0];
    for (int i = 1; i < size; ++i) {
        if (records[i].value > largest.value) {
            largest = records[i];
        }
    }
    return largest;
}

record findLargestInput(int* input, int batch_size) {
    record largest = {input[0]};
    for (int i = 1; i < batch_size; ++i) {
        if (input[i] > largest.value) {
            largest.value = input[i];
        }
    }
    return largest;
}

void allocateAndProcess(int array_size, int batch_size) {
    long* offsets = allocateOffsetArray(array_size);
    logMemoryOperations("Allocated offsets", array_size * sizeof(long));

    int* keys = allocateKeyArray(array_size);
    logMemoryOperations("Allocated keys", array_size * sizeof(int));

    record* records = allocateRecordArray(array_size);
    fillRecordsWithRandomValues(records, array_size);
    logMemoryOperations("Filled records with random values");

    processInput(batch_size);

    record largest_record = findLargestRecord(records, array_size);
    record largest_input = findLargestInput(input, batch_size);

    printf("Largest record value: %d\n", largest_record.value);
    printf("Largest input value: %d\n", largest_input.value);

    free(offsets);
    logMemoryOperations("Deallocated offsets", array_size * sizeof(long));

    free(keys);
    logMemoryOperations("Deallocated keys", array_size * sizeof(int));

    free(records);
    logMemoryOperations("Deallocated records", array_size * sizeof(record));
}
