    long* offsets = malloc(size * sizeof(long));
    if (!offsets) return NULL; // Handle memory allocation failure

    for (int i = 0; i < size; ++i) {
        offsets[i] = min_offset + rand() % (max_offset - min_offset + 1);
    }

    return offsets;
}

int* allocate_keys(int size, int min_key, int max_key) {
    // Validate key limits
    if (size <= 0 || min_key > max_key) return NULL;

    int* keys = malloc(size * sizeof(int));
    if (!keys) return NULL; // Handle memory allocation failure

    for (int i = 0; i < size; ++i) {
        keys[i] = min_key + rand() % (max_key - min_key + 1);
    }

    return keys;
}

record* allocate_records(int size, int seed, int min_value, int max_value) {
    // Validate record parameters
    if (size <= 0 || min_value > max_value) return NULL;

    srand(seed); // Initialize PRNG with the provided seed

    record* records = malloc(size * sizeof(record));
    if (!records) return NULL; // Handle memory allocation failure

    for (int i = 0; i < size; ++i) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
    }

    return records;
}

