#include <stdlib.h>
#include <time.h>
#include <stdio.h>

// Define the record structure
typedef struct {
    int value;
    struct timeval timestamp;
    unsigned long checksum;
} Record;

// Function to securely generate a random number within a specified range
int secureRandom(int min, int max) {
    static bool seeded = false;
    if (!seeded) {
        srand(time(NULL));
        seeded = true;
    }
    return min + rand() % (max - min + 1);
}

// Function to allocate and initialize memory for arrays
void allocateAndInitializeArrays(long **offsets, int **keys, Record **records, size_t size) {
    if (size == 0) {
        fprintf(stderr, "Error: Size must be greater than zero.\n");
        return;
    }

    // Allocate memory for each array
    *offsets = (long *)malloc(size * sizeof(long));
    *keys = (int *)malloc(size * sizeof(int));
    *records = (Record *)malloc(size * sizeof(Record));

    if (!(*offsets) || !(*keys) || !(*records)) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(*offsets);
        free(*keys);
        free(*records);
        return;
    }

    // Initialize arrays
    for (size_t i = 0; i < size; ++i) {
        (*offsets)[i] = secureRandom(0, 100); // Example initialization logic
        (*keys)[i] = secureRandom(-100, 100);
        (*records)[i].value = secureRandom(1, 1000);
        gettimeofday(&(*records)[i].timestamp, NULL);
        // Calculate checksum (example: simple XOR of value and timestamp)
        (*records)[i].checksum = (*records)[i].value ^ (*records)[i].timestamp.tv_sec;
    }

    printf("Arrays allocated and initialized successfully.\n");
}

// Example usage
int main() {
    size_t numRecords = 1000000; // 1 million records
    long *offsets = NULL;
    int *keys = NULL;
    Record *records = NULL;

    allocateAndInitializeArrays(&offsets, &keys, &records, numRecords);

    // Free allocated memory when done
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
