} audit_log;

int init_records(long* offsets, int* keys, record** records, audit_log** logs, long num_records, int min_val, int max_val) {
    if (num_records <= 0 || min_val > max_val) {
        return -1; // Invalid input parameters
    }

    offsets = (long*)malloc(num_records * sizeof(long));
    keys = (int*)malloc(num_records * sizeof(int));
    records = (record**)malloc(num_records * sizeof(record*));
    logs = (audit_log**)malloc(num_records * sizeof(audit_log*));

    if (!offsets || !keys || !records || !logs) {
        // Log memory allocation failure
        printf("Memory allocation failed. Requested size: %ld, Available memory: %ld\n", num_records, sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE));
        return -2; // Memory allocation failure
    }

    srand(time(NULL)); // Seed the PRNG for secure random numbers

    for (long i = 0; i < num_records; ++i) {
        offsets[i] = rand() % num_records;
        keys[i] = rand() % (max_val - min_val + 1) + min_val;

        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            // Log memory allocation failure
            printf("Memory allocation failed. Requested size: %ld, Available memory: %ld\n", num_records, sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE));
            return -2; // Memory allocation failure
        }

        logs[i] = (audit_log*)malloc(sizeof(audit_log));
        if (!logs[i]) {
            // Log memory allocation failure
            printf("Memory allocation failed. Requested size: %ld, Available memory: %ld\n", num_records, sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE));
            return -2; // Memory allocation failure
        }

        gettimeofday(&logs[i]->timestamp, NULL);

        size_t metadata_size = rand() % (MAX_METADATA_SIZE - 1) + 1;
        records[i]->metadata[metadata_size] = '\0'; // Null-terminate string
    }

    return 0; // Success
}

int main() {
    long num_records = 5000000; // Example: 5 million records
    int min_val = 1, max_val = 100;

    long* offsets;
    int* keys;
    record** records;
    audit_log** logs;

    if (init_records(offsets, keys, records, logs, num_records, min_val, max_val) != 0) {
        printf("Initialization failed.\n");
        return 1;
    }

    // Use the allocated arrays...

    // Free the allocated memory
    for (long i = 0; i < num_records; ++i) {
        free(records[i]);
        free(logs[i]);
    }
    free(offsets);
    free(keys);
    free(records);
    free(logs);

    return 0;
}
