#define MAX_SESSIONS 1000
#define TOKEN_CACHE_SIZE 100

typedef struct {
    int id;
    char username[50];
    int status;
    time_t timestamp;
    char token[100];
} SessionToken;

SessionToken sessionPool[MAX_SESSIONS];
int sessionCount = 0;
pthread_mutex_t poolMutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    char service_name[50];
    char api_key[50];
    // Other service-specific settings
} ServiceConfig;

ServiceConfig serviceConfigs[10];

// Function to generate a pseudo-random session ID
int generateSessionID() {
    static int lastID = 0;
    pthread_mutex_lock(&poolMutex);
    lastID++;
    if (lastID >= MAX_SESSIONS) {
        lastID = 0; // Reset for simplicity, in real-world use consider thread-local storage or a more robust solution
    }
    pthread_mutex_unlock(&poolMutex);
    return lastID;
}

// Function to allocate and initialize a session token
SessionToken* allocateSessionToken(const char* username, const char* token) {
    SessionToken* session = NULL;
    pthread_mutex_lock(&poolMutex);
    if (sessionCount < MAX_SESSIONS) {
        session = &sessionPool[sessionCount++];
        session->id = generateSessionID();
        strncpy(session->username, username, sizeof(session->username));
        strncpy(session->token, token, sizeof(session->token));
        time(&session->timestamp);
        session->status = 0; // Assuming 0 means success
    }
    pthread_mutex_unlock(&poolMutex);
    return session;
}

