void handleLogin(const char* username, const char* password) {
    pthread_mutex_lock(&poolMutex);
    // Check cache for existing token
    if (/* Token is in cache */) {
        printf("Login successful using cached token.\n");
        pthread_mutex_unlock(&poolMutex);
        return;
    }
    pthread_mutex_unlock(&poolMutex);

    // Simulate API call and get new token
    char* token = getAuthToken(username, password);
    if (token) {
        SessionToken* session = allocateSessionToken(username, token);
        if (session) {
            printf("Login successful. New session ID: %d\n", session->id);
        } else {
            printf("Failed to create new session.\n");
        }
    } else {
        printf("Authentication failed.\n");
    }
}

// Main function for batch processing
