['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000
#define MIN_KEY 1
#define MAX_KEY 1000

typedef struct {
    int value;
} record;

long* allocate_offset_array(int count) {
    return (long*)malloc(count * sizeof(long));
}

int* allocate_key_array(int count) {
    return (int*)malloc(count * sizeof(int));
}

record* allocate_record_array(int count) {
    return (record*)malloc(count * sizeof(record));
}

void read_config_file(const char* file_path, int* count, int* min_key, int* max_key) {
    FILE* file = fopen(file_path, "r");
    if (!file) {
        fprintf(stderr, "Failed to open config file: %s\n", file_path);
        exit(EXIT_FAILURE);
    }

    fscanf(file, "%d %d %d", count, min_key, max_key);

    fclose(file);
}

void validate_config(int count, int min_key, int max_key) {
    if (count <= 0 || min_key < MIN_KEY || max_key > MAX_KEY) {
        fprintf(stderr, "Invalid configuration values.\n");
        exit(EXIT_FAILURE);
    }
}

unsigned long custom_rand() {
    static unsigned long seed = 1;
    seed = seed * 1103515245 + 12345; // Simple linear congruential generator
    return seed % MAX_KEY;
}

void generate_records(int count, record* records) {
    for (int i = 0; i < count; ++i) {
        records[i].value = MIN_KEY + custom_rand() % (MAX_KEY - MIN_KEY + 1);
    }
}

void print_summary(int count, record* records) {
    printf("Total records: %d\n", count);
    printf("Sample record value: %d\n", records[0].value);
}

void cleanup(long* offsets, int* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
}

int main(int argc, char* argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <config_file> <min_key> <max_key>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int count, min_key, max_key;
    read_config_file(argv[1], &count, &min_key, &max_key);
    validate_config(count, min_key, max_key);

    long* offsets = allocate_offset_array(count);
    int* keys = allocate_key_array(count);
    record* records = allocate_record_array(count);

    generate_records(count, records);
    print_summary(count, records);

    cleanup(offsets, keys, records);

    return EXIT_SUCCESS;
}
